window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ZEC"]={"book":"ZEC","editions":{"hbo-source":[[1,1,"בַּ⁠חֹ֨דֶשׁ֙ הַ⁠שְּׁמִינִ֔י בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֑וֶשׁ הָיָ֣ה דְבַר־יְהוָ֗ה אֶל־זְכַרְיָה֙ בֶּן־בֶּ֣רֶכְיָ֔ה בֶּן־עִדּ֥וֹ הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bȧ⁠ẖò֨deş̌֙ ha⁠şĕ̇̌miyni֔y bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֑weş̌ háyá֣h dĕbar-yĕhwá֗h ʼel-zĕkarĕyáh֙ bėn-bė֣rekĕyá֔h bėn-ʻiḋ֥wò ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[1,2,"קָצַ֧ף יְהוָ֛ה עַל־אֲבֽוֹתֵי⁠כֶ֖ם קָֽצֶף׃","qáẕa֧p yĕhwá֛h ʻal-ʼàbֽwòţéy⁠ke֖m qáֽẕep׃"],[1,3,"וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֗ם כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת שׁ֣וּבוּ אֵלַ֔⁠י נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת וְ⁠אָשׁ֣וּב אֲלֵי⁠כֶ֔ם אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֗m kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ş֣̌ẇbẇ ʼéla֔⁠y nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠ʼáş֣̌ẇb ʼàléy⁠ke֔m ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[1,4,"אַל־תִּהְי֣וּ כַ⁠אֲבֹֽתֵי⁠כֶ֡ם אֲשֶׁ֣ר קָרְאֽוּ־אֲלֵי⁠הֶם֩ הַ⁠נְּבִיאִ֨ים הָ⁠רִֽאשֹׁנִ֜ים לֵ⁠אמֹ֗ר כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת שׁ֤וּבוּ נָא֙ מִ⁠דַּרְכֵי⁠כֶ֣ם הָ⁠רָעִ֔ים ו⁠מעלילי⁠כם הָֽ⁠רָעִ֑ים וְ⁠לֹ֥א שָׁמְע֛וּ וְ⁠לֹֽא־הִקְשִׁ֥יבוּ אֵלַ֖⁠י נְאֻם־יְהוָֽה׃","ʼal-ţi̇hĕy֣ẇ ka⁠ʼàbòֽţéy⁠ke֡m ʼàşě֣r qárĕʼֽẇ-ʼàléy⁠hem֩ ha⁠nĕ̇biyʼi֨ym há⁠riֽʼşò̌ni֜ym lé⁠ʼmò֗r kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ş֤̌ẇbẇ náʼ֙ mi⁠dȧrĕkéy⁠ke֣m há⁠ráʻi֔ym w⁠mʻlyly⁠km háֽ⁠ráʻi֑ym wĕ⁠lò֥ʼ şá̌mĕʻ֛ẇ wĕ⁠lòֽʼ-hiqĕşǐ֥ybẇ ʼéla֖⁠y nĕʼum-yĕhwáֽh׃"],[1,5,"אֲבֽוֹתֵי⁠כֶ֖ם אַיֵּה־הֵ֑ם וְ⁠הַ֨⁠נְּבִאִ֔ים הַ⁠לְ⁠עוֹלָ֖ם יִֽחְיֽוּ׃","ʼàbֽwòţéy⁠ke֖m ʼayé̇h-hé֑m wĕ⁠ha֨⁠nĕ̇biʼi֔ym ha⁠lĕ⁠ʻwòlá֖m yiֽẖĕyֽẇ׃"],[1,6,"אַ֣ךְ ׀ דְּבָרַ֣⁠י וְ⁠חֻקַּ֗⁠י אֲשֶׁ֤ר צִוִּ֨יתִי֙ אֶת־עֲבָדַ֣⁠י הַ⁠נְּבִיאִ֔ים הֲ⁠ל֥וֹא הִשִּׂ֖יגוּ אֲבֹתֵי⁠כֶ֑ם וַ⁠יָּשׁ֣וּבוּ וַ⁠יֹּאמְר֗וּ כַּ⁠אֲשֶׁ֨ר זָמַ֜ם יְהוָ֤ה צְבָאוֹת֙ לַ⁠עֲשׂ֣וֹת לָ֔⁠נוּ כִּ⁠דְרָכֵ֨י⁠נוּ֙ וּ⁠כְ⁠מַ֣עֲלָלֵ֔י⁠נוּ כֵּ֖ן עָשָׂ֥ה אִתָּֽ⁠נוּ׃ס","ʼa֣kĕ ׀ dĕ̇bára֣⁠y wĕ⁠ẖuqȧ֗⁠y ʼàşě֤r ẕiwi̇֨yţiy֙ ʼeţ-ʻàbáda֣⁠y ha⁠nĕ̇biyʼi֔ym hà⁠l֥wòʼ hişi֖̇̂ygẇ ʼàbòţéy⁠ke֑m wa⁠yá̇ş֣̌ẇbẇ wa⁠yò̇ʼmĕr֗ẇ kȧ⁠ʼàşě֨r záma֜m yĕhwá֤h ẕĕbáʼwòţ֙ la⁠ʻàş֣̂wòţ lá֔⁠nẇ ki̇⁠dĕráké֨y⁠nẇ֙ ẇ⁠kĕ⁠ma֣ʻàlálé֔y⁠nẇ ké֖̇n ʻáşá֥̂h ʼiţáֽ̇⁠nẇ׃s"],[1,7,"בְּ⁠יוֹם֩ עֶשְׂרִ֨ים וְ⁠אַרְבָּעָ֜ה לְ⁠עַשְׁתֵּֽי־עָשָׂ֥ר חֹ֨דֶשׁ֙ הוּא־חֹ֣דֶשׁ שְׁבָ֔ט בִּ⁠שְׁנַ֥ת שְׁתַּ֖יִם לְ⁠דָרְיָ֑וֶשׁ הָיָ֣ה דְבַר־יְהוָ֗ה אֶל־זְכַרְיָה֙ בֶּן־בֶּ֣רֶכְיָ֔הוּ בֶּן־עִדּ֥וֹא הַ⁠נָּבִ֖יא לֵ⁠אמֹֽר׃","bĕ̇⁠ywòm֩ ʻeşĕ̂ri֨ym wĕ⁠ʼarĕbá̇ʻá֜h lĕ⁠ʻaşĕ̌ţéֽ̇y-ʻáşá֥̂r ẖò֨deş̌֙ hẇʼ-ẖò֣deş̌ şĕ̌bá֔t bi̇⁠şĕ̌na֥ţ şĕ̌ţȧ֖yim lĕ⁠dárĕyá֑weş̌ háyá֣h dĕbar-yĕhwá֗h ʼel-zĕkarĕyáh֙ bėn-bė֣rekĕyá֔hẇ bėn-ʻiḋ֥wòʼ ha⁠ná̇bi֖yʼ lé⁠ʼmòֽr׃"],[1,8,"רָאִ֣יתִי ׀ הַ⁠לַּ֗יְלָה וְ⁠הִנֵּה־אִישׁ֙ רֹכֵב֙ עַל־ס֣וּס אָדֹ֔ם וְ⁠ה֣וּא עֹמֵ֔ד בֵּ֥ין הַ⁠הֲדַסִּ֖ים אֲשֶׁ֣ר בַּ⁠מְּצֻלָ֑ה וְ⁠אַחֲרָי⁠ו֙ סוּסִ֣ים אֲדֻמִּ֔ים שְׂרֻקִּ֖ים וּ⁠לְבָנִֽים׃","ráʼi֣yţiy ׀ ha⁠lȧ֗yĕláh wĕ⁠hiné̇h-ʼiyş̌֙ ròkéb֙ ʻal-s֣ẇs ʼádò֔m wĕ⁠h֣ẇʼ ʻòmé֔d bé֥̇yn ha⁠hàdasi֖̇ym ʼàşě֣r bȧ⁠mĕ̇ẕulá֑h wĕ⁠ʼaẖàráy⁠w֙ sẇsi֣ym ʼàdumi̇֔ym şĕ̂ruqi֖̇ym ẇ⁠lĕbániֽym׃"],[1,9,"וָ⁠אֹמַ֖ר מָה־אֵ֣לֶּה אֲדֹנִ֑⁠י וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הַ⁠מַּלְאָךְ֙ הַ⁠דֹּבֵ֣ר בִּ֔⁠י אֲנִ֥י אַרְאֶ֖⁠ךָּ מָה־הֵ֥מָּה אֵֽלֶּה׃","wá⁠ʼòma֖r máh-ʼé֣lėh ʼàdòni֑⁠y wa⁠yò֣̇ʼmer ʼéla֗⁠y ha⁠mȧlĕʼákĕ֙ ha⁠dò̇bé֣r bi̇֔⁠y ʼàni֥y ʼarĕʼe֖⁠ká̇ máh-hé֥má̇h ʼéֽlėh׃"],[1,10,"וַ⁠יַּ֗עַן הָ⁠אִ֛ישׁ הָ⁠עֹמֵ֥ד בֵּין־הַ⁠הַדַסִּ֖ים וַ⁠יֹּאמַ֑ר אֵ֚לֶּה אֲשֶׁ֣ר שָׁלַ֣ח יְהוָ֔ה לְ⁠הִתְהַלֵּ֖ךְ בָּ⁠אָֽרֶץ׃","wa⁠yȧ֗ʻan há⁠ʼi֛yş̌ há⁠ʻòmé֥d bé̇yn-ha⁠hadasi֖̇ym wa⁠yò̇ʼma֑r ʼé֚lėh ʼàşě֣r şá̌la֣ẖ yĕhwá֔h lĕ⁠hiţĕhalé֖̇kĕ bá̇⁠ʼáֽreẕ׃"],[1,11,"וַֽ⁠יַּעֲנ֞וּ אֶת־מַלְאַ֣ךְ יְהוָ֗ה הָֽ⁠עֹמֵד֙ בֵּ֣ין הַ⁠הֲדַסִּ֔ים וַ⁠יֹּאמְר֖וּ הִתְהַלַּ֣כְנוּ בָ⁠אָ֑רֶץ וְ⁠הִנֵּ֥ה כָל־הָ⁠אָ֖רֶץ יֹשֶׁ֥בֶת וְ⁠שֹׁקָֽטֶת׃","waֽ⁠yȧʻàn֞ẇ ʼeţ-malĕʼa֣kĕ yĕhwá֗h háֽ⁠ʻòméd֙ bé֣̇yn ha⁠hàdasi̇֔ym wa⁠yò̇ʼmĕr֖ẇ hiţĕhalȧ֣kĕnẇ bá⁠ʼá֑reẕ wĕ⁠hiné֥̇h kál-há⁠ʼá֖reẕ yòşě֥beţ wĕ⁠şò̌qáֽteţ׃"],[1,12,"וַ⁠יַּ֣עַן מַלְאַךְ־יְהוָה֮ וַ⁠יֹּאמַר֒ יְהוָ֣ה צְבָא֔וֹת עַד־מָתַ֗י אַתָּה֙ לֹֽא־תְרַחֵ֣ם אֶת־יְרוּשָׁלִַ֔ם וְ⁠אֵ֖ת עָרֵ֣י יְהוּדָ֑ה אֲשֶׁ֣ר זָעַ֔מְתָּה זֶ֖ה שִׁבְעִ֥ים שָׁנָֽה׃","wa⁠yȧ֣ʻan malĕʼakĕ-yĕhwáh֮ wa⁠yò̇ʼmar֒ yĕhwá֣h ẕĕbáʼ֔wòţ ʻad-máţa֗y ʼaţá̇h֙ lòֽʼ-ţĕraẖé֣m ʼeţ-yĕrẇşá̌lia֔m wĕ⁠ʼé֖ţ ʻáré֣y yĕhẇdá֑h ʼàşě֣r záʻa֔mĕţá̇h ze֖h şǐbĕʻi֥ym şá̌náֽh׃"],[1,13,"וַ⁠יַּ֣עַן יְהוָ֗ה אֶת־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י דְּבָרִ֣ים טוֹבִ֑ים דְּבָרִ֖ים נִחֻמִֽים׃","wa⁠yȧ֣ʻan yĕhwá֗h ʼeţ-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y dĕ̇bári֣ym twòbi֑ym dĕ̇bári֖ym niẖumiֽym׃"],[1,14,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הַ⁠מַּלְאָךְ֙ הַ⁠דֹּבֵ֣ר בִּ֔⁠י קְרָ֣א לֵ⁠אמֹ֔ר כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת קִנֵּ֧אתִי לִ⁠ירוּשָׁלִַ֛ם וּ⁠לְ⁠צִיּ֖וֹן קִנְאָ֥ה גְדוֹלָֽה׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y ha⁠mȧlĕʼákĕ֙ ha⁠dò̇bé֣r bi̇֔⁠y qĕrá֣ʼ lé⁠ʼmò֔r kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ qiné֧̇ʼţiy li⁠yrẇşá̌lia֛m ẇ⁠lĕ⁠ẕiẏ֖wòn qinĕʼá֥h gĕdwòláֽh׃"],[1,15,"וְ⁠קֶ֤צֶף גָּדוֹל֙ אֲנִ֣י קֹצֵ֔ף עַל־הַ⁠גּוֹיִ֖ם הַ⁠שַּֽׁאֲנַנִּ֑ים אֲשֶׁ֤ר אֲנִי֙ קָצַ֣פְתִּי מְּעָ֔ט וְ⁠הֵ֖מָּה עָזְר֥וּ לְ⁠רָעָֽה׃","wĕ⁠qe֤ẕep gá̇dwòl֙ ʼàni֣y qòẕé֔p ʻal-ha⁠ġwòyi֖m ha⁠şȧֽ̌ʼànani֑̇ym ʼàşě֤r ʼàniy֙ qáẕa֣pĕţi̇y mĕ̇ʻá֔t wĕ⁠hé֖má̇h ʻázĕr֥ẇ lĕ⁠ráʻáֽh׃"],[1,16,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר יְהוָ֗ה שַׁ֤בְתִּי לִ⁠ירוּשָׁלִַ֨ם֙ בְּֽ⁠רַחֲמִ֔ים בֵּיתִ⁠י֙ יִבָּ֣נֶה בָּ֔⁠הּ נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת ו⁠קוה יִנָּטֶ֖ה עַל־יְרוּשָׁלִָֽם׃","lá⁠ké֞n kòֽ̇h-ʼáma֣r yĕhwá֗h şǎ֤bĕţi̇y li⁠yrẇşá̌lia֨m֙ bĕֽ̇⁠raẖàmi֔ym bé̇yţi⁠y֙ yibá֣̇neh bá̇֔⁠ḣ nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ w⁠qwh yiná̇te֖h ʻal-yĕrẇşá̌liáֽm׃"],[1,17,"ע֣וֹד ׀ קְרָ֣א לֵ⁠אמֹ֗ר כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת ע֛וֹד תְּפוּצֶ֥ינָה עָרַ֖⁠י מִ⁠טּ֑וֹב וְ⁠נִחַ֨ם יְהוָ֥ה עוֹד֙ אֶת־צִיּ֔וֹן וּ⁠בָחַ֥ר ע֖וֹד בִּ⁠ירוּשָׁלִָֽם׃ס","ʻ֣wòd ׀ qĕrá֣ʼ lé⁠ʼmò֗r kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻ֛wòd ţĕ̇pẇẕe֥ynáh ʻára֖⁠y mi⁠ṫ֑wòb wĕ⁠niẖa֨m yĕhwá֥h ʻwòd֙ ʼeţ-ẕiẏ֔wòn ẇ⁠báẖa֥r ʻ֖wòd bi̇⁠yrẇşá̌liáֽm׃s"],[1,18,"וָ⁠אֶשָּׂ֥א אֶת־עֵינַ֖⁠י וָ⁠אֵ֑רֶא וְ⁠הִנֵּ֖ה אַרְבַּ֥ע קְרָנֽוֹת׃","wá⁠ʼeşá֥̇̂ʼ ʼeţ-ʻéyna֖⁠y wá⁠ʼé֑reʼ wĕ⁠hiné֖̇h ʼarĕbȧ֥ʻ qĕránֽwòţ׃"],[1,19,"וָ⁠אֹמַ֗ר אֶל־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י מָה־אֵ֑לֶּה וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י אֵ֤לֶּה הַ⁠קְּרָנוֹת֙ אֲשֶׁ֣ר זֵר֣וּ אֶת־יְהוּדָ֔ה אֶת־יִשְׂרָאֵ֖ל וִ⁠ירוּשָׁלָֽם׃ס","wá⁠ʼòma֗r ʼel-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y máh-ʼé֑lėh wa⁠yò֣̇ʼmer ʼéla֔⁠y ʼé֤lėh ha⁠qĕ̇ránwòţ֙ ʼàşě֣r zér֣ẇ ʼeţ-yĕhẇdá֔h ʼeţ-yişĕ̂ráʼé֖l wi⁠yrẇşá̌láֽm׃s"],[1,20,"וַ⁠יַּרְאֵ֣⁠נִי יְהוָ֔ה אַרְבָּעָ֖ה חָרָשִֽׁים׃","wa⁠yȧrĕʼé֣⁠niy yĕhwá֔h ʼarĕbá̇ʻá֖h ẖáráşǐֽym׃"],[1,21,"וָ⁠אֹמַ֕ר מָ֛ה אֵ֥לֶּה בָאִ֖ים לַֽ⁠עֲשׂ֑וֹת וַ⁠יֹּ֣אמֶר לֵ⁠אמֹ֗ר אֵ֣לֶּה הַ⁠קְּרָנ֞וֹת אֲשֶׁר־זֵ֣רוּ אֶת־יְהוּדָ֗ה כְּ⁠פִי־אִישׁ֙ לֹא־נָשָׂ֣א רֹאשׁ֔⁠וֹ וַ⁠יָּבֹ֤אוּ אֵ֨לֶּה֙ לְ⁠הַחֲרִ֣יד אֹתָ֔⁠ם לְ⁠יַדּ֞וֹת אֶת־קַרְנ֣וֹת הַ⁠גּוֹיִ֗ם הַ⁠נֹּשְׂאִ֥ים קֶ֛רֶן אֶל־אֶ֥רֶץ יְהוּדָ֖ה לְ⁠זָרוֹתָֽ⁠הּ׃ס","wá⁠ʼòma֕r má֛h ʼé֥lėh báʼi֖ym laֽ⁠ʻàş֑̂wòţ wa⁠yò֣̇ʼmer lé⁠ʼmò֗r ʼé֣lėh ha⁠qĕ̇rán֞wòţ ʼàşěr-zé֣rẇ ʼeţ-yĕhẇdá֗h kĕ̇⁠piy-ʼiyş̌֙ lòʼ-náşá֣̂ʼ ròʼş̌֔⁠wò wa⁠yá̇bò֤ʼẇ ʼé֨lėh֙ lĕ⁠haẖàri֣yd ʼòţá֔⁠m lĕ⁠yaḋ֞wòţ ʼeţ-qarĕn֣wòţ ha⁠ġwòyi֗m ha⁠nò̇şĕ̂ʼi֥ym qe֛ren ʼel-ʼe֥reẕ yĕhẇdá֖h lĕ⁠zárwòţáֽ⁠ḣ׃s"],[2,1,"וָ⁠אֶשָּׂ֥א עֵינַ֛⁠י וָ⁠אֵ֖רֶא וְ⁠הִנֵּה־אִ֑ישׁ וּ⁠בְ⁠יָד֖⁠וֹ חֶ֥בֶל מִדָּֽה׃","wá⁠ʼeşá֥̇̂ʼ ʻéyna֛⁠y wá⁠ʼé֖reʼ wĕ⁠hiné̇h-ʼi֑yş̌ ẇ⁠bĕ⁠yád֖⁠wò ẖe֥bel midáֽ̇h׃"],[2,2,"וָ⁠אֹמַ֕ר אָ֖נָה אַתָּ֣ה הֹלֵ֑ךְ וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י לָ⁠מֹד֙ אֶת־יְר֣וּשָׁלִַ֔ם לִ⁠רְא֥וֹת כַּ⁠מָּֽה־רָחְבָּ֖⁠הּ וְ⁠כַ⁠מָּ֥ה אָרְכָּֽ⁠הּ׃","wá⁠ʼòma֕r ʼá֖náh ʼaţá֣̇h hòlé֑kĕ wa⁠yò֣̇ʼmer ʼéla֗⁠y lá⁠mòd֙ ʼeţ-yĕr֣ẇşá̌lia֔m li⁠rĕʼ֥wòţ kȧ⁠máֽ̇h-ráẖĕbá֖̇⁠ḣ wĕ⁠ka⁠má֥̇h ʼárĕkáֽ̇⁠ḣ׃"],[2,3,"וְ⁠הִנֵּ֗ה הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י יֹצֵ֑א וּ⁠מַלְאָ֣ךְ אַחֵ֔ר יֹצֵ֖א לִ⁠קְרָאתֽ⁠וֹ׃","wĕ⁠hiné̇֗h ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y yòẕé֑ʼ ẇ⁠malĕʼá֣kĕ ʼaẖé֔r yòẕé֖ʼ li⁠qĕráʼţֽ⁠wò׃"],[2,4,"וַ⁠יֹּ֣אמֶר אֵלָ֔⁠ו רֻ֗ץ דַּבֵּ֛ר אֶל־הַ⁠נַּ֥עַר הַלָּ֖ז לֵ⁠אמֹ֑ר פְּרָזוֹת֙ תֵּשֵׁ֣ב יְרוּשָׁלִַ֔ם מֵ⁠רֹ֥ב אָדָ֛ם וּ⁠בְהֵמָ֖ה בְּ⁠תוֹכָֽ⁠הּ׃","wa⁠yò֣̇ʼmer ʼélá֔⁠w ru֗ẕ dȧbé֛̇r ʼel-ha⁠nȧ֥ʻar halá֖̇z lé⁠ʼmò֑r pĕ̇rázwòţ֙ ţé̇şé֣̌b yĕrẇşá̌lia֔m mé⁠rò֥b ʼádá֛m ẇ⁠bĕhémá֖h bĕ̇⁠ţwòkáֽ⁠ḣ׃"],[2,5,"וַ⁠אֲנִ֤י אֶֽהְיֶה־לָּ⁠הּ֙ נְאֻם־יְהוָ֔ה ח֥וֹמַת אֵ֖שׁ סָבִ֑יב וּ⁠לְ⁠כָב֖וֹד אֶֽהְיֶ֥ה בְ⁠תוֹכָֽ⁠הּ׃פ","wa⁠ʼàni֤y ʼeֽhĕyeh-lá̇⁠ḣ֙ nĕʼum-yĕhwá֔h ẖ֥wòmaţ ʼé֖ş̌ sábi֑yb ẇ⁠lĕ⁠káb֖wòd ʼeֽhĕye֥h bĕ⁠ţwòkáֽ⁠ḣ׃p"],[2,6,"ה֣וֹי ה֗וֹי וְ⁠נֻ֛סוּ מֵ⁠אֶ֥רֶץ צָפ֖וֹן נְאֻם־יְהוָ֑ה כִּ֠י כְּ⁠אַרְבַּ֞ע רוּח֧וֹת הַ⁠שָּׁמַ֛יִם פֵּרַ֥שְׂתִּי אֶתְ⁠כֶ֖ם נְאֻם־יְהוָֽה׃","h֣wòy h֗wòy wĕ⁠nu֛sẇ mé⁠ʼe֥reẕ ẕáp֖wòn nĕʼum-yĕhwá֑h ki̇֠y kĕ̇⁠ʼarĕbȧ֞ʻ rẇẖ֧wòţ ha⁠şá̇̌ma֛yim pé̇ra֥şĕ̂ţi̇y ʼeţĕ⁠ke֖m nĕʼum-yĕhwáֽh׃"],[2,7,"ה֥וֹי צִיּ֖וֹן הִמָּלְטִ֑י יוֹשֶׁ֖בֶת בַּת־בָּבֶֽל׃ס","h֥wòy ẕiẏ֖wòn himá̇lĕti֑y ywòşě֖beţ bȧţ-bá̇beֽl׃s"],[2,8,"כִּ֣י כֹ֣ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ אַחַ֣ר כָּב֔וֹד שְׁלָחַ֕⁠נִי אֶל־הַ⁠גּוֹיִ֖ם הַ⁠שֹּׁלְלִ֣ים אֶתְ⁠כֶ֑ם כִּ֚י הַ⁠נֹּגֵ֣עַ בָּ⁠כֶ֔ם נֹגֵ֖עַ בְּ⁠בָבַ֥ת עֵינֽ⁠וֹ׃","ki֣̇y kò֣h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ ʼaẖa֣r ká̇b֔wòd şĕ̌láẖa֕⁠niy ʼel-ha⁠ġwòyi֖m ha⁠şò̇̌lĕli֣ym ʼeţĕ⁠ke֑m ki֚̇y ha⁠nò̇gé֣ʻa bá̇⁠ke֔m nògé֖ʻa bĕ̇⁠bába֥ţ ʻéynֽ⁠wò׃"],[2,9,"כִּ֠י הִנְ⁠נִ֨י מֵנִ֤יף אֶת־יָדִ⁠י֙ עֲלֵי⁠הֶ֔ם וְ⁠הָי֥וּ שָׁלָ֖ל לְ⁠עַבְדֵי⁠הֶ֑ם וִֽ⁠ידַעְתֶּ֕ם כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחָֽ⁠נִי׃ס","ki̇֠y hinĕ⁠ni֨y méni֤yp ʼeţ-yádi⁠y֙ ʻàléy⁠he֔m wĕ⁠háy֥ẇ şá̌lá֖l lĕ⁠ʻabĕdéy⁠he֑m wiֽ⁠ydaʻĕţė֕m kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖáֽ⁠niy׃s"],[2,10,"רָנִּ֥י וְ⁠שִׂמְחִ֖י בַּת־צִיּ֑וֹן כִּ֧י הִנְ⁠נִי־בָ֛א וְ⁠שָׁכַנְתִּ֥י בְ⁠תוֹכֵ֖⁠ךְ נְאֻם־יְהוָֽה׃","ráni֥̇y wĕ⁠şîmĕẖi֖y bȧţ-ẕiẏ֑wòn ki֧̇y hinĕ⁠niy-bá֛ʼ wĕ⁠şá̌kanĕţi֥̇y bĕ⁠ţwòké֖⁠kĕ nĕʼum-yĕhwáֽh׃"],[2,11,"וְ⁠נִלְווּ֩ גוֹיִ֨ם רַבִּ֤ים אֶל־יְהוָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠הָ֥יוּ לִ֖⁠י לְ⁠עָ֑ם וְ⁠שָׁכַנְתִּ֣י בְ⁠תוֹכֵ֔⁠ךְ וְ⁠יָדַ֕עַתְּ כִּי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֥⁠נִי אֵלָֽיִ⁠ךְ׃","wĕ⁠nilĕwẇ֩ gwòyi֨m rabi֤̇ym ʼel-yĕhwáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠há֥yẇ li֖⁠y lĕ⁠ʻá֑m wĕ⁠şá̌kanĕţi֣̇y bĕ⁠ţwòké֔⁠kĕ wĕ⁠yáda֕ʻaţĕ̇ ki̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֥⁠niy ʼéláֽyi⁠kĕ׃"],[2,12,"וְ⁠נָחַ֨ל יְהוָ֤ה אֶת־יְהוּדָה֙ חֶלְק֔⁠וֹ עַ֖ל אַדְמַ֣ת הַ⁠קֹּ֑דֶשׁ וּ⁠בָחַ֥ר ע֖וֹד בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠náẖa֨l yĕhwá֤h ʼeţ-yĕhẇdáh֙ ẖelĕq֔⁠wò ʻa֖l ʼadĕma֣ţ ha⁠qò֑̇deş̌ ẇ⁠báẖa֥r ʻ֖wòd bi̇⁠yrẇşá̌liáֽm׃"],[2,13,"הַ֥ס כָּל־בָּשָׂ֖ר מִ⁠פְּנֵ֣י יְהוָ֑ה כִּ֥י נֵע֖וֹר מִ⁠מְּע֥וֹן קָדְשֽׁ⁠וֹ׃ס","ha֥s ká̇l-bá̇şá֖̂r mi⁠pĕ̇né֣y yĕhwá֑h ki֥̇y néʻ֖wòr mi⁠mĕ̇ʻ֥wòn qádĕşֽ̌⁠wò׃s"],[3,1,"וַ⁠יַּרְאֵ֗⁠נִי אֶת־יְהוֹשֻׁ֨עַ֙ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֔וֹל עֹמֵ֕ד לִ⁠פְנֵ֖י מַלְאַ֣ךְ יְהוָ֑ה וְ⁠הַ⁠שָּׂטָ֛ן עֹמֵ֥ד עַל־יְמִינ֖⁠וֹ לְ⁠שִׂטְנֽ⁠וֹ׃","wa⁠yȧrĕʼé֗⁠niy ʼeţ-yĕhwòşǔ֨ʻa֙ ha⁠kò̇hé֣n ha⁠gá̇d֔wòl ʻòmé֕d li⁠pĕné֖y malĕʼa֣kĕ yĕhwá֑h wĕ⁠ha⁠şá̇̂tá֛n ʻòmé֥d ʻal-yĕmiyn֖⁠wò lĕ⁠şîtĕnֽ⁠wò׃"],[3,2,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֶל־הַ⁠שָּׂטָ֗ן יִגְעַ֨ר יְהוָ֤ה בְּ⁠ךָ֙ הַ⁠שָּׂטָ֔ן וְ⁠יִגְעַ֤ר יְהוָה֙ בְּ⁠ךָ֔ הַ⁠בֹּחֵ֖ר בִּ⁠ירֽוּשָׁלִָ֑ם הֲ⁠ל֧וֹא זֶ֦ה א֖וּד מֻצָּ֥ל מֵ⁠אֵֽשׁ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼel-ha⁠şá̇̂tá֗n yigĕʻa֨r yĕhwá֤h bĕ̇⁠ká֙ ha⁠şá̇̂tá֔n wĕ⁠yigĕʻa֤r yĕhwáh֙ bĕ̇⁠ká֔ ha⁠bò̇ẖé֖r bi̇⁠yrֽẇşá̌liá֑m hà⁠l֧wòʼ ze֦h ʼ֖ẇd muẕá֥̇l mé⁠ʼéֽş̌׃"],[3,3,"וִ⁠יהוֹשֻׁ֕עַ הָיָ֥ה לָבֻ֖שׁ בְּגָדִ֣ים צוֹאִ֑ים וְ⁠עֹמֵ֖ד לִ⁠פְנֵ֥י הַ⁠מַּלְאָֽךְ׃","wi⁠yhwòşǔ֕ʻa háyá֥h lábu֖ş̌ bĕ̇gádi֣ym ẕwòʼi֑ym wĕ⁠ʻòmé֖d li⁠pĕné֥y ha⁠mȧlĕʼáֽkĕ׃"],[3,4,"וַ⁠יַּ֣עַן וַ⁠יֹּ֗אמֶר אֶל־הָ⁠עֹמְדִ֤ים לְ⁠פָנָי⁠ו֙ לֵ⁠אמֹ֔ר הָסִ֛ירוּ הַ⁠בְּגָדִ֥ים הַ⁠צֹּאִ֖ים מֵ⁠עָלָ֑י⁠ו וַ⁠יֹּ֣אמֶר אֵלָ֗י⁠ו רְאֵ֨ה הֶעֱבַ֤רְתִּי מֵ⁠עָלֶ֨י⁠ךָ֙ עֲוֺנֶ֔⁠ךָ וְ⁠הַלְבֵּ֥שׁ אֹתְ⁠ךָ֖ מַחֲלָצֽוֹת׃","wa⁠yȧ֣ʻan wa⁠yò̇֗ʼmer ʼel-há⁠ʻòmĕdi֤ym lĕ⁠pánáy⁠w֙ lé⁠ʼmò֔r hási֛yrẇ ha⁠bĕ̇gádi֥ym ha⁠ẕò̇ʼi֖ym mé⁠ʻálá֑y⁠w wa⁠yò֣̇ʼmer ʼélá֗y⁠w rĕʼé֨h heʻèba֤rĕţi̇y mé⁠ʻále֨y⁠ká֙ ʻàwֺne֔⁠ká wĕ⁠halĕbé֥̇ş̌ ʼòţĕ⁠ká֖ maẖàláẕֽwòţ׃"],[3,5,"וָ⁠אֹמַ֕ר יָשִׂ֛ימוּ צָנִ֥יף טָה֖וֹר עַל־רֹאשׁ֑⁠וֹ וַ⁠יָּשִׂימוּ֩ הַ⁠צָּנִ֨יף הַ⁠טָּה֜וֹר עַל־רֹאשׁ֗⁠וֹ וַ⁠יַּלְבִּשֻׁ֨⁠הוּ֙ בְּגָדִ֔ים וּ⁠מַלְאַ֥ךְ יְהוָ֖ה עֹמֵֽד׃","wá⁠ʼòma֕r yáşî֛ymẇ ẕáni֥yp táh֖wòr ʻal-ròʼş֑̌⁠wò wa⁠yá̇şîymẇ֩ ha⁠ẕá̇ni֨yp ha⁠tá̇h֜wòr ʻal-ròʼş̌֗⁠wò wa⁠yȧlĕbi̇şǔ֨⁠hẇ֙ bĕ̇gádi֔ym ẇ⁠malĕʼa֥kĕ yĕhwá֖h ʻòméֽd׃"],[3,6,"וַ⁠יָּ֨עַד֙ מַלְאַ֣ךְ יְהוָ֔ה בִּ⁠יהוֹשֻׁ֖עַ לֵ⁠אמֹֽר׃","wa⁠yá̇֨ʻad֙ malĕʼa֣kĕ yĕhwá֔h bi̇⁠yhwòşǔ֖ʻa lé⁠ʼmòֽr׃"],[3,7,"כֹּה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת אִם־בִּ⁠דְרָכַ֤⁠י תֵּלֵךְ֙ וְ⁠אִ֣ם אֶת־מִשְׁמַרְתִּ֣⁠י תִשְׁמֹ֔ר וְ⁠גַם־אַתָּה֙ תָּדִ֣ין אֶת־בֵּיתִ֔⁠י וְ⁠גַ֖ם תִּשְׁמֹ֣ר אֶת־חֲצֵרָ֑⁠י וְ⁠נָתַתִּ֤י לְ⁠ךָ֙ מַהְלְכִ֔ים בֵּ֥ין הָ⁠עֹמְדִ֖ים הָ⁠אֵֽלֶּה׃","kò̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ʼim-bi̇⁠dĕráka֤⁠y ţé̇lékĕ֙ wĕ⁠ʼi֣m ʼeţ-mişĕ̌marĕţi֣̇⁠y ţişĕ̌mò֔r wĕ⁠gam-ʼaţá̇h֙ ţá̇di֣yn ʼeţ-bé̇yţi֔⁠y wĕ⁠ga֖m ţi̇şĕ̌mò֣r ʼeţ-ẖàẕérá֑⁠y wĕ⁠náţaţi֤̇y lĕ⁠ká֙ mahĕlĕki֔ym bé֥̇yn há⁠ʻòmĕdi֖ym há⁠ʼéֽlėh׃"],[3,8,"שְֽׁמַֽע־נָ֞א יְהוֹשֻׁ֣עַ ׀ הַ⁠כֹּהֵ֣ן הַ⁠גָּד֗וֹל אַתָּה֙ וְ⁠רֵעֶ֨י⁠ךָ֙ הַ⁠יֹּשְׁבִ֣ים לְ⁠פָנֶ֔י⁠ךָ כִּֽי־אַנְשֵׁ֥י מוֹפֵ֖ת הֵ֑מָּה כִּֽי־הִנְ⁠נִ֥י מֵבִ֛יא אֶת־עַבְדִּ֖⁠י צֶֽמַח׃","şĕֽ̌maֽʻ-ná֞ʼ yĕhwòşǔ֣ʻa ׀ ha⁠kò̇hé֣n ha⁠gá̇d֗wòl ʼaţá̇h֙ wĕ⁠réʻe֨y⁠ká֙ ha⁠yò̇şĕ̌bi֣ym lĕ⁠páne֔y⁠ká kiֽ̇y-ʼanĕşé֥̌y mwòpé֖ţ hé֑má̇h kiֽ̇y-hinĕ⁠ni֥y mébi֛yʼ ʼeţ-ʻabĕdi֖̇⁠y ẕeֽmaẖ׃"],[3,9,"כִּ֣י ׀ הִנֵּ֣ה הָ⁠אֶ֗בֶן אֲשֶׁ֤ר נָתַ֨תִּי֙ לִ⁠פְנֵ֣י יְהוֹשֻׁ֔עַ עַל־אֶ֥בֶן אַחַ֖ת שִׁבְעָ֣ה עֵינָ֑יִם הִנְ⁠נִ֧י מְפַתֵּ֣חַ פִּתֻּחָ֗⁠הּ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠מַשְׁתִּ֛י אֶת־עֲוֺ֥ן הָ⁠אָֽרֶץ־הַ⁠הִ֖יא בְּ⁠י֥וֹם אֶחָֽד׃","ki֣̇y ׀ hiné֣̇h há⁠ʼe֗ben ʼàşě֤r náţa֨ţi̇y֙ li⁠pĕné֣y yĕhwòşǔ֔ʻa ʻal-ʼe֥ben ʼaẖa֖ţ şǐbĕʻá֣h ʻéyná֑yim hinĕ⁠ni֧y mĕpaţé֣̇ẖa pi̇ţu̇ẖá֗⁠ḣ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠maşĕ̌ţi֛̇y ʼeţ-ʻàwֺ֥n há⁠ʼáֽreẕ-ha⁠hi֖yʼ bĕ̇⁠y֥wòm ʼeẖáֽd׃"],[3,10,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת תִּקְרְא֖וּ אִ֣ישׁ לְ⁠רֵעֵ֑⁠הוּ אֶל־תַּ֥חַת גֶּ֖פֶן וְ⁠אֶל־תַּ֥חַת תְּאֵנָֽה׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ţi̇qĕrĕʼ֖ẇ ʼi֣yş̌ lĕ⁠réʻé֑⁠hẇ ʼel-ţȧ֥ẖaţ gė֖pen wĕ⁠ʼel-ţȧ֥ẖaţ ţĕ̇ʼénáֽh׃"],[4,1,"וַ⁠יָּ֕שָׁב הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י וַ⁠יְעִירֵ֕⁠נִי כְּ⁠אִ֖ישׁ אֲשֶׁר־יֵע֥וֹר מִ⁠שְּׁנָתֽ⁠וֹ׃","wa⁠yá̇֕şá̌b ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y wa⁠yĕʻiyré֕⁠niy kĕ̇⁠ʼi֖yş̌ ʼàşěr-yéʻ֥wòr mi⁠şĕ̇̌náţֽ⁠wò׃"],[4,2,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י מָ֥ה אַתָּ֖ה רֹאֶ֑ה ו⁠יאמר רָאִ֣יתִי ׀ וְ⁠הִנֵּ֣ה מְנוֹרַת֩ זָהָ֨ב כֻּלָּ֜⁠הּ וְ⁠גֻלָּ֣הּ עַל־רֹאשָׁ֗⁠הּ וְ⁠שִׁבְעָ֤ה נֵרֹתֶ֨י⁠הָ֙ עָלֶ֔י⁠הָ שִׁבְעָ֤ה וְ⁠שִׁבְעָה֙ מֽוּצָק֔וֹת לַ⁠נֵּר֖וֹת אֲשֶׁ֥ר עַל־רֹאשָֽׁ⁠הּ׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y má֥h ʼaţá֖̇h ròʼe֑h w⁠yʼmr ráʼi֣yţiy ׀ wĕ⁠hiné֣̇h mĕnwòraţ֩ záhá֨b ku̇lá̇֜⁠ḣ wĕ⁠gulá֣̇ḣ ʻal-ròʼşá̌֗⁠ḣ wĕ⁠şǐbĕʻá֤h néròţe֨y⁠há֙ ʻále֔y⁠há şǐbĕʻá֤h wĕ⁠şǐbĕʻáh֙ mֽẇẕáq֔wòţ la⁠né̇r֖wòţ ʼàşě֥r ʻal-ròʼşáֽ̌⁠ḣ׃"],[4,3,"וּ⁠שְׁנַ֥יִם זֵיתִ֖ים עָלֶ֑י⁠הָ אֶחָד֙ מִ⁠ימִ֣ין הַ⁠גֻּלָּ֔ה וְ⁠אֶחָ֖ד עַל־שְׂמֹאלָֽ⁠הּ׃","ẇ⁠şĕ̌na֥yim zéyţi֖ym ʻále֑y⁠há ʼeẖád֙ mi⁠ymi֣yn ha⁠gu̇lá̇֔h wĕ⁠ʼeẖá֖d ʻal-şĕ̂mòʼláֽ⁠ḣ׃"],[4,4,"וָ⁠אַ֨עַן֙ וָֽ⁠אֹמַ֔ר אֶל־הַ⁠מַּלְאָ֛ךְ הַ⁠דֹּבֵ֥ר בִּ֖⁠י לֵ⁠אמֹ֑ר מָה־אֵ֖לֶּה אֲדֹנִֽ⁠י׃","wá⁠ʼa֨ʻan֙ wáֽ⁠ʼòma֔r ʼel-ha⁠mȧlĕʼá֛kĕ ha⁠dò̇bé֥r bi֖̇⁠y lé⁠ʼmò֑r máh-ʼé֖lėh ʼàdòniֽ⁠y׃"],[4,5,"וַ֠⁠יַּעַן הַ⁠מַּלְאָ֞ךְ הַ⁠דֹּבֵ֥ר בִּ⁠י֙ וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י הֲ⁠ל֥וֹא יָדַ֖עְתָּ מָה־הֵ֣מָּה אֵ֑לֶּה וָ⁠אֹמַ֖ר לֹ֥א אֲדֹנִֽ⁠י׃","wa֠⁠yȧʻan ha⁠mȧlĕʼá֞kĕ ha⁠dò̇bé֥r bi̇⁠y֙ wa⁠yò֣̇ʼmer ʼéla֔⁠y hà⁠l֥wòʼ yáda֖ʻĕţá̇ máh-hé֣má̇h ʼé֑lėh wá⁠ʼòma֖r lò֥ʼ ʼàdòniֽ⁠y׃"],[4,6,"וַ⁠יַּ֜עַן וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ לֵ⁠אמֹ֔ר זֶ֚ה דְּבַר־יְהוָ֔ה אֶל־זְרֻבָּבֶ֖ל לֵ⁠אמֹ֑ר לֹ֤א בְ⁠חַ֨יִל֙ וְ⁠לֹ֣א בְ⁠כֹ֔חַ כִּ֣י אִם־בְּ⁠רוּחִ֔⁠י אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wa⁠yȧ֜ʻan wa⁠yò֤̇ʼmer ʼéla⁠y֙ lé⁠ʼmò֔r ze֚h dĕ̇bar-yĕhwá֔h ʼel-zĕrubá̇be֖l lé⁠ʼmò֑r lò֤ʼ bĕ⁠ẖa֨yil֙ wĕ⁠lò֣ʼ bĕ⁠kò֔ẖa ki֣̇y ʼim-bĕ̇⁠rẇẖi֔⁠y ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[4,7,"מִֽי־אַתָּ֧ה הַֽר־הַ⁠גָּד֛וֹל לִ⁠פְנֵ֥י זְרֻבָּבֶ֖ל לְ⁠מִישֹׁ֑ר וְ⁠הוֹצִיא֙ אֶת־הָ⁠אֶ֣בֶן הָ⁠רֹאשָׁ֔ה תְּשֻׁא֕וֹת חֵ֥ן חֵ֖ן לָֽ⁠הּ׃פ","miֽy-ʼaţá֧̇h haֽr-ha⁠gá̇d֛wòl li⁠pĕné֥y zĕrubá̇be֖l lĕ⁠miyşò֑̌r wĕ⁠hwòẕiyʼ֙ ʼeţ-há⁠ʼe֣ben há⁠ròʼşá̌֔h ţĕ̇şǔʼ֕wòţ ẖé֥n ẖé֖n láֽ⁠ḣ׃p"],[4,8,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[4,9,"יְדֵ֣י זְרֻבָּבֶ֗ל יִסְּד֛וּ הַ⁠בַּ֥יִת הַ⁠זֶּ֖ה וְ⁠יָדָ֣י⁠ו תְּבַצַּ֑עְנָה וְ⁠יָ֣דַעְתָּ֔ כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֥⁠נִי אֲלֵי⁠כֶֽם׃","yĕdé֣y zĕrubá̇be֗l yisĕ̇d֛ẇ ha⁠bȧ֥yiţ ha⁠zė֖h wĕ⁠yádá֣y⁠w ţĕ̇baẕȧ֑ʻĕnáh wĕ⁠yá֣daʻĕţá̇֔ kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֥⁠niy ʼàléy⁠keֽm׃"],[4,10,"כִּ֣י מִ֣י בַז֮ לְ⁠י֣וֹם קְטַנּוֹת֒ וְ⁠שָׂמְח֗וּ וְ⁠רָא֞וּ אֶת־הָ⁠אֶ֧בֶן הַ⁠בְּדִ֛יל בְּ⁠יַ֥ד זְרֻבָּבֶ֖ל שִׁבְעָה־אֵ֑לֶּה עֵינֵ֣י יְהוָ֔ה הֵ֥מָּה מְשׁוֹטְטִ֖ים בְּ⁠כָל־הָ⁠אָֽרֶץ׃","ki֣̇y mi֣y baz֮ lĕ⁠y֣wòm qĕtaṅwòţ֒ wĕ⁠şá̂mĕẖ֗ẇ wĕ⁠ráʼ֞ẇ ʼeţ-há⁠ʼe֧ben ha⁠bĕ̇di֛yl bĕ̇⁠ya֥d zĕrubá̇be֖l şǐbĕʻáh-ʼé֑lėh ʻéyné֣y yĕhwá֔h hé֥má̇h mĕş̌wòtĕti֖ym bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[4,11,"וָ⁠אַ֖עַן וָ⁠אֹמַ֣ר אֵלָ֑י⁠ו מַה־שְּׁנֵ֤י הַ⁠זֵּיתִים֙ הָ⁠אֵ֔לֶה עַל־יְמִ֥ין הַ⁠מְּנוֹרָ֖ה וְ⁠עַל־שְׂמֹאולָֽ⁠הּ׃","wá⁠ʼa֖ʻan wá⁠ʼòma֣r ʼélá֑y⁠w mah-şĕ̇̌né֤y ha⁠zé̇yţiym֙ há⁠ʼé֔leh ʻal-yĕmi֥yn ha⁠mĕ̇nwòrá֖h wĕ⁠ʻal-şĕ̂mòʼwláֽ⁠ḣ׃"],[4,12,"וָ⁠אַ֣עַן שֵׁנִ֔ית וָ⁠אֹמַ֖ר אֵלָ֑י⁠ו מַה־שְׁתֵּ֞י שִׁבֲּלֵ֣י הַ⁠זֵּיתִ֗ים אֲשֶׁר֙ בְּ⁠יַ֗ד שְׁנֵי֙ צַנְתְּר֣וֹת הַ⁠זָּהָ֔ב הַֽ⁠מְרִיקִ֥ים מֵ⁠עֲלֵי⁠הֶ֖ם הַ⁠זָּהָֽב׃","wá⁠ʼa֣ʻan şé̌ni֔yţ wá⁠ʼòma֖r ʼélá֑y⁠w mah-şĕ̌ţé̇֞y şǐbà̇lé֣y ha⁠zé̇yţi֗ym ʼàşěr֙ bĕ̇⁠ya֗d şĕ̌néy֙ ẕanĕţĕ̇r֣wòţ ha⁠zá̇há֔b haֽ⁠mĕriyqi֥ym mé⁠ʻàléy⁠he֖m ha⁠zá̇háֽb׃"],[4,13,"וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ לֵ⁠אמֹ֔ר הֲ⁠ל֥וֹא יָדַ֖עְתָּ מָה־אֵ֑לֶּה וָ⁠אֹמַ֖ר לֹ֥א אֲדֹנִֽ⁠י׃","wa⁠yò֤̇ʼmer ʼéla⁠y֙ lé⁠ʼmò֔r hà⁠l֥wòʼ yáda֖ʻĕţá̇ máh-ʼé֑lėh wá⁠ʼòma֖r lò֥ʼ ʼàdòniֽ⁠y׃"],[4,14,"וַ⁠יֹּ֕אמֶר אֵ֖לֶּה שְׁנֵ֣י בְנֵֽי־הַ⁠יִּצְהָ֑ר הָ⁠עֹמְדִ֖ים עַל־אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","wa⁠yò̇֕ʼmer ʼé֖lėh şĕ̌né֣y bĕnéֽy-ha⁠yi̇ẕĕhá֑r há⁠ʻòmĕdi֖ym ʻal-ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[5,1,"וָ⁠אָשׁ֕וּב וָ⁠אֶשָּׂ֥א עֵינַ֖⁠י וָֽ⁠אֶרְאֶ֑ה וְ⁠הִנֵּ֖ה מְגִלָּ֥ה עָפָֽה׃","wá⁠ʼáş̌֕ẇb wá⁠ʼeşá֥̇̂ʼ ʻéyna֖⁠y wáֽ⁠ʼerĕʼe֑h wĕ⁠hiné֖̇h mĕgilá֥̇h ʻápáֽh׃"],[5,2,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י מָ֥ה אַתָּ֖ה רֹאֶ֑ה וָ⁠אֹמַ֗ר אֲנִ֤י רֹאֶה֙ מְגִלָּ֣ה עָפָ֔ה אָרְכָּ⁠הּ֙ עֶשְׂרִ֣ים בָּֽ⁠אַמָּ֔ה וְ⁠רָחְבָּ֖⁠הּ עֶ֥שֶׂר בָּ⁠אַמָּֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y má֥h ʼaţá֖̇h ròʼe֑h wá⁠ʼòma֗r ʼàni֤y ròʼeh֙ mĕgilá֣̇h ʻápá֔h ʼárĕká̇⁠ḣ֙ ʻeşĕ̂ri֣ym báֽ̇⁠ʼamá̇֔h wĕ⁠ráẖĕbá֖̇⁠ḣ ʻe֥şêr bá̇⁠ʼamáֽ̇h׃"],[5,3,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י זֹ֚את הָֽ⁠אָלָ֔ה הַ⁠יּוֹצֵ֖את עַל־פְּנֵ֣י כָל־הָ⁠אָ֑רֶץ כִּ֣י כָל־הַ⁠גֹּנֵ֗ב מִ⁠זֶּה֙ כָּמ֣וֹ⁠הָ נִקָּ֔ה וְ⁠כָל־הַ⁠נִּ֨שְׁבָּ֔ע מִ⁠זֶּ֖ה כָּמ֥וֹ⁠הָ נִקָּֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y zò֚ʼţ háֽ⁠ʼálá֔h ha⁠ẏwòẕé֖ʼţ ʻal-pĕ̇né֣y kál-há⁠ʼá֑reẕ ki֣̇y kál-ha⁠gò̇né֗b mi⁠zėh֙ ká̇m֣wò⁠há niqá̇֔h wĕ⁠kál-ha⁠ni̇֨şĕ̌bá̇֔ʻ mi⁠zė֖h ká̇m֥wò⁠há niqáֽ̇h׃"],[5,4,"הוֹצֵאתִ֗י⁠הָ נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠בָ֨אָה֙ אֶל־בֵּ֣ית הַ⁠גַּנָּ֔ב וְ⁠אֶל־בֵּ֛ית הַ⁠נִּשְׁבָּ֥ע בִּ⁠שְׁמִ֖⁠י לַ⁠שָּׁ֑קֶר וְ⁠לָ֨נֶה֙ בְּ⁠ת֣וֹךְ בֵּית֔⁠וֹ וְ⁠כִלַּ֖תּ⁠וּ וְ⁠אֶת־עֵצָ֥י⁠ו וְ⁠אֶת־אֲבָנָֽי⁠ו׃","hwòẕéʼţi֗y⁠há nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠bá֨ʼáh֙ ʼel-bé֣̇yţ ha⁠gȧná̇֔b wĕ⁠ʼel-bé֛̇yţ ha⁠ni̇şĕ̌bá֥̇ʻ bi̇⁠şĕ̌mi֖⁠y la⁠şá֑̇̌qer wĕ⁠lá֨neh֙ bĕ̇⁠ţ֣wòkĕ bé̇yţ֔⁠wò wĕ⁠kilȧ֖ţ̇⁠ẇ wĕ⁠ʼeţ-ʻéẕá֥y⁠w wĕ⁠ʼeţ-ʼàbánáֽy⁠w׃"],[5,5,"וַ⁠יֵּצֵ֕א הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י שָׂ֣א נָ֤א עֵינֶ֨י⁠ךָ֙ וּ⁠רְאֵ֔ה מָ֖ה הַ⁠יּוֹצֵ֥את הַ⁠זֹּֽאת׃","wa⁠yé̇ẕé֕ʼ ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y wa⁠yò֣̇ʼmer ʼéla֔⁠y şá֣̂ʼ ná֤ʼ ʻéyne֨y⁠ká֙ ẇ⁠rĕʼé֔h má֖h ha⁠ẏwòẕé֥ʼţ ha⁠zòֽ̇ʼţ׃"],[5,6,"וָ⁠אֹמַ֖ר מַה־הִ֑יא וַ⁠יֹּ֗אמֶר זֹ֤את הָֽ⁠אֵיפָה֙ הַ⁠יּוֹצֵ֔את וַ⁠יֹּ֕אמֶר זֹ֥את עֵינָ֖⁠ם בְּ⁠כָל־הָ⁠אָֽרֶץ׃","wá⁠ʼòma֖r mah-hi֑yʼ wa⁠yò̇֗ʼmer zò֤ʼţ háֽ⁠ʼéypáh֙ ha⁠ẏwòẕé֔ʼţ wa⁠yò̇֕ʼmer zò֥ʼţ ʻéyná֖⁠m bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[5,7,"וְ⁠הִנֵּ֛ה כִּכַּ֥ר עֹפֶ֖רֶת נִשֵּׂ֑את וְ⁠זֹאת֙ אִשָּׁ֣ה אַחַ֔ת יוֹשֶׁ֖בֶת בְּ⁠ת֥וֹךְ הָ⁠אֵיפָֽה׃","wĕ⁠hiné֛̇h ki̇kȧ֥r ʻòpe֖reţ nişé֑̇̂ʼţ wĕ⁠zòʼţ֙ ʼişá֣̇̌h ʼaẖa֔ţ ywòşě֖beţ bĕ̇⁠ţ֥wòkĕ há⁠ʼéypáֽh׃"],[5,8,"וַ⁠יֹּ֨אמֶר֙ זֹ֣את הָ⁠רִשְׁעָ֔ה וַ⁠יַּשְׁלֵ֥ךְ אֹתָ֖⁠הּ אֶל־תּ֣וֹךְ הָֽ⁠אֵיפָ֑ה וַ⁠יַּשְׁלֵ֛ךְ אֶת־אֶ֥בֶן הָ⁠עֹפֶ֖רֶת אֶל־פִּֽי⁠הָ׃ס","wa⁠yò̇֨ʼmer֙ zò֣ʼţ há⁠rişĕ̌ʻá֔h wa⁠yȧşĕ̌lé֥kĕ ʼòţá֖⁠ḣ ʼel-ţ֣̇wòkĕ háֽ⁠ʼéypá֑h wa⁠yȧşĕ̌lé֛kĕ ʼeţ-ʼe֥ben há⁠ʻòpe֖reţ ʼel-piֽ̇y⁠há׃s"],[5,9,"וָ⁠אֶשָּׂ֨א עֵינַ֜⁠י וָ⁠אֵ֗רֶא וְ⁠הִנֵּה֩ שְׁתַּ֨יִם נָשִׁ֤ים יֽוֹצְאוֹת֙ וְ⁠ר֣וּחַ בְּ⁠כַנְפֵי⁠הֶ֔ם וְ⁠לָ⁠הֵ֥נָּה כְנָפַ֖יִם כְּ⁠כַנְפֵ֣י הַ⁠חֲסִידָ֑ה וַ⁠תִּשֶּׂ֨אנָה֙ אֶת־הָ֣⁠אֵיפָ֔ה בֵּ֥ין הָ⁠אָ֖רֶץ וּ⁠בֵ֥ין הַ⁠שָּׁמָֽיִם׃","wá⁠ʼeşá̇̂֨ʼ ʻéyna֜⁠y wá⁠ʼé֗reʼ wĕ⁠hiné̇h֩ şĕ̌ţȧ֨yim náşǐ֤ym yֽwòẕĕʼwòţ֙ wĕ⁠r֣ẇẖa bĕ̇⁠kanĕpéy⁠he֔m wĕ⁠lá⁠hé֥ná̇h kĕnápa֖yim kĕ̇⁠kanĕpé֣y ha⁠ẖàsiydá֑h wa⁠ţi̇şė̂֨ʼnáh֙ ʼeţ-há֣⁠ʼéypá֔h bé֥̇yn há⁠ʼá֖reẕ ẇ⁠bé֥yn ha⁠şá̇̌máֽyim׃"],[5,10,"וָ⁠אֹמַ֕ר אֶל־הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י אָ֛נָה הֵ֥מָּה מֽוֹלִכ֖וֹת אֶת־הָ⁠אֵיפָֽה׃","wá⁠ʼòma֕r ʼel-ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y ʼá֛náh hé֥má̇h mֽwòlik֖wòţ ʼeţ-há⁠ʼéypáֽh׃"],[5,11,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י לִ⁠בְנֽוֹת־לָ֥⁠הֿ בַ֖יִת בְּ⁠אֶ֣רֶץ שִׁנְעָ֑ר וְ⁠הוּכַ֛ן וְ⁠הֻנִּ֥יחָה שָּׁ֖ם עַל־מְכֻנָתָֽ⁠הּ׃ס","wa⁠yò֣̇ʼmer ʼéla֔⁠y li⁠bĕnֽwòţ-lá֥⁠h̄ ba֖yiţ bĕ̇⁠ʼe֣reẕ şǐnĕʻá֑r wĕ⁠hẇka֛n wĕ⁠huni֥̇yẖáh şá֖̇̌m ʻal-mĕkunáţáֽ⁠ḣ׃s"],[6,1,"וָ⁠אָשֻׁ֗ב וָ⁠אֶשָּׂ֤א עֵינַ⁠י֙ וָֽ⁠אֶרְאֶ֔ה וְ⁠הִנֵּ֨ה אַרְבַּ֤ע מַרְכָּבוֹת֙ יֹֽצְא֔וֹת מִ⁠בֵּ֖ין שְׁנֵ֣י הֶֽ⁠הָרִ֑ים וְ⁠הֶ⁠הָרִ֖ים הָרֵ֥י נְחֹֽשֶׁת׃","wá⁠ʼáşǔ֗b wá⁠ʼeşá֤̇̂ʼ ʻéyna⁠y֙ wáֽ⁠ʼerĕʼe֔h wĕ⁠hiné̇֨h ʼarĕbȧ֤ʻ marĕká̇bwòţ֙ yòֽẕĕʼ֔wòţ mi⁠bé֖̇yn şĕ̌né֣y heֽ⁠hári֑ym wĕ⁠he⁠hári֖ym háré֥y nĕẖòֽşěţ׃"],[6,2,"בַּ⁠מֶּרְכָּבָ֥ה הָ⁠רִֽאשֹׁנָ֖ה סוּסִ֣ים אֲדֻמִּ֑ים וּ⁠בַ⁠מֶּרְכָּבָ֥ה הַ⁠שֵּׁנִ֖ית סוּסִ֥ים שְׁחֹרִֽים׃","bȧ⁠mėrĕká̇bá֥h há⁠riֽʼşò̌ná֖h sẇsi֣ym ʼàdumi֑̇ym ẇ⁠ba⁠mėrĕká̇bá֥h ha⁠şé̇̌ni֖yţ sẇsi֥ym şĕ̌ẖòriֽym׃"],[6,3,"וּ⁠בַ⁠מֶּרְכָּבָ֥ה הַ⁠שְּׁלִשִׁ֖ית סוּסִ֣ים לְבָנִ֑ים וּ⁠בַ⁠מֶּרְכָּבָה֙ הָ⁠רְבִעִ֔ית סוּסִ֥ים בְּרֻדִּ֖ים אֲמֻצִּֽים׃","ẇ⁠ba⁠mėrĕká̇bá֥h ha⁠şĕ̇̌lişǐ֖yţ sẇsi֣ym lĕbáni֑ym ẇ⁠ba⁠mėrĕká̇báh֙ há⁠rĕbiʻi֔yţ sẇsi֥ym bĕ̇rudi֖̇ym ʼàmuẕiֽ̇ym׃"],[6,4,"וָ⁠אַ֨עַן֙ וָֽ⁠אֹמַ֔ר אֶל־הַ⁠מַּלְאָ֖ךְ הַ⁠דֹּבֵ֣ר בִּ֑⁠י מָה־אֵ֖לֶּה אֲדֹנִֽ⁠י׃","wá⁠ʼa֨ʻan֙ wáֽ⁠ʼòma֔r ʼel-ha⁠mȧlĕʼá֖kĕ ha⁠dò̇bé֣r bi֑̇⁠y máh-ʼé֖lėh ʼàdòniֽ⁠y׃"],[6,5,"וַ⁠יַּ֥עַן הַ⁠מַּלְאָ֖ךְ וַ⁠יֹּ֣אמֶר אֵלָ֑⁠י אֵ֗לֶּה אַרְבַּע֙ רֻח֣וֹת הַ⁠שָּׁמַ֔יִם יוֹצְא֕וֹת מֵֽ⁠הִתְיַצֵּ֖ב עַל־אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","wa⁠yȧ֥ʻan ha⁠mȧlĕʼá֖kĕ wa⁠yò֣̇ʼmer ʼélá֑⁠y ʼé֗lėh ʼarĕbȧʻ֙ ruẖ֣wòţ ha⁠şá̇̌ma֔yim ywòẕĕʼ֕wòţ méֽ⁠hiţĕyaẕé֖̇b ʻal-ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[6,6,"אֲשֶׁר־בָּ֞⁠הּ הַ⁠סּוּסִ֣ים הַ⁠שְּׁחֹרִ֗ים יֹֽצְאִים֙ אֶל־אֶ֣רֶץ צָפ֔וֹן וְ⁠הַ⁠לְּבָנִ֔ים יָצְא֖וּ אֶל־אַֽחֲרֵי⁠הֶ֑ם וְ⁠הַ֨⁠בְּרֻדִּ֔ים יָצְא֖וּ אֶל־אֶ֥רֶץ הַ⁠תֵּימָֽן׃","ʼàşěr-bá̇֞⁠ḣ ha⁠ṡẇsi֣ym ha⁠şĕ̇̌ẖòri֗ym yòֽẕĕʼiym֙ ʼel-ʼe֣reẕ ẕáp֔wòn wĕ⁠ha⁠lĕ̇báni֔ym yáẕĕʼ֖ẇ ʼel-ʼaֽẖàréy⁠he֑m wĕ⁠ha֨⁠bĕ̇rudi̇֔ym yáẕĕʼ֖ẇ ʼel-ʼe֥reẕ ha⁠ţé̇ymáֽn׃"],[6,7,"וְ⁠הָ⁠אֲמֻצִּ֣ים יָצְא֗וּ וַ⁠יְבַקְשׁוּ֙ לָ⁠לֶ֨כֶת֙ לְ⁠הִתְהַלֵּ֣ך בָּ⁠אָ֔רֶץ וַ⁠יֹּ֕אמֶר לְכ֖וּ הִתְהַלְּכ֣וּ בָ⁠אָ֑רֶץ וַ⁠תִּתְהַלַּ֖כְנָה בָּ⁠אָֽרֶץ׃","wĕ⁠há⁠ʼàmuẕi֣̇ym yáẕĕʼ֗ẇ wa⁠yĕbaqĕş̌ẇ֙ lá⁠le֨keţ֙ lĕ⁠hiţĕhalé֣̇k bá̇⁠ʼá֔reẕ wa⁠yò̇֕ʼmer lĕk֖ẇ hiţĕhalĕ̇k֣ẇ bá⁠ʼá֑reẕ wa⁠ţi̇ţĕhalȧ֖kĕnáh bá̇⁠ʼáֽreẕ׃"],[6,8,"וַ⁠יַּזְעֵ֣ק אֹתִ֔⁠י וַ⁠יְדַבֵּ֥ר אֵלַ֖⁠י לֵ⁠אמֹ֑ר רְאֵ֗ה הַ⁠יּֽוֹצְאִים֙ אֶל־אֶ֣רֶץ צָפ֔וֹן הֵנִ֥יחוּ אֶת־רוּחִ֖⁠י בְּ⁠אֶ֥רֶץ צָפֽוֹן׃ס","wa⁠yȧzĕʻé֣q ʼòţi֔⁠y wa⁠yĕdabé֥̇r ʼéla֖⁠y lé⁠ʼmò֑r rĕʼé֗h ha⁠ẏֽwòẕĕʼiym֙ ʼel-ʼe֣reẕ ẕáp֔wòn héni֥yẖẇ ʼeţ-rẇẖi֖⁠y bĕ̇⁠ʼe֥reẕ ẕápֽwòn׃s"],[6,9,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[6,10,"לָק֨וֹחַ֙ מֵ⁠אֵ֣ת הַ⁠גּוֹלָ֔ה מֵ⁠חֶלְדַּ֕י וּ⁠מֵ⁠אֵ֥ת טוֹבִיָּ֖ה וּ⁠מֵ⁠אֵ֣ת יְדַֽעְיָ֑ה וּ⁠בָאתָ֤ אַתָּה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וּ⁠בָ֗אתָ בֵּ֚ית יֹאשִׁיָּ֣ה בֶן־צְפַנְיָ֔ה אֲשֶׁר־בָּ֖אוּ מִ⁠בָּבֶֽל׃","láq֨wòẖa֙ mé⁠ʼé֣ţ ha⁠ġwòlá֔h mé⁠ẖelĕdȧ֕y ẇ⁠mé⁠ʼé֥ţ twòbiyá֖̇h ẇ⁠mé⁠ʼé֣ţ yĕdaֽʻĕyá֑h ẇ⁠báʼţá֤ ʼaţá̇h֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ẇ⁠bá֗ʼţá bé֚̇yţ yòʼşǐyá֣̇h ben-ẕĕpanĕyá֔h ʼàşěr-bá֖̇ʼẇ mi⁠bá̇beֽl׃"],[6,11,"וְ⁠לָקַחְתָּ֥ כֶֽסֶף־וְ⁠זָהָ֖ב וְ⁠עָשִׂ֣יתָ עֲטָר֑וֹת וְ⁠שַׂמְתָּ֗ בְּ⁠רֹ֛אשׁ יְהוֹשֻׁ֥עַ בֶּן־יְהוֹצָדָ֖ק הַ⁠כֹּהֵ֥ן הַ⁠גָּדֽוֹל׃","wĕ⁠láqaẖĕţá֥̇ keֽsep-wĕ⁠záhá֖b wĕ⁠ʻáşî֣yţá ʻàtár֑wòţ wĕ⁠şâmĕţá̇֗ bĕ̇⁠rò֛ʼş̌ yĕhwòşǔ֥ʻa bėn-yĕhwòẕádá֖q ha⁠kò̇hé֥n ha⁠gá̇dֽwòl׃"],[6,12,"וְ⁠אָמַרְתָּ֤ אֵלָי⁠ו֙ לֵ⁠אמֹ֔ר כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר הִנֵּה־אִ֞ישׁ צֶ֤מַח שְׁמ⁠וֹ֙ וּ⁠מִ⁠תַּחְתָּ֣י⁠ו יִצְמָ֔ח וּ⁠בָנָ֖ה אֶת־הֵיכַ֥ל יְהוָֽהּ׃","wĕ⁠ʼámarĕţá֤̇ ʼéláy⁠w֙ lé⁠ʼmò֔r kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r hiné̇h-ʼi֞yş̌ ẕe֤maẖ şĕ̌m⁠wò֙ ẇ⁠mi⁠ţȧẖĕţá֣̇y⁠w yiẕĕmá֔ẖ ẇ⁠báná֖h ʼeţ-héyka֥l yĕhwáֽḣ׃"],[6,13,"וְ֠⁠הוּא יִבְנֶ֞ה אֶת־הֵיכַ֤ל יְהוָה֙ וְ⁠הֽוּא־יִשָּׂ֣א ה֔וֹד וְ⁠יָשַׁ֥ב וּ⁠מָשַׁ֖ל עַל־כִּסְא֑⁠וֹ וְ⁠הָיָ֤ה כֹהֵן֙ עַל־כִּסְא֔⁠וֹ וַ⁠עֲצַ֣ת שָׁל֔וֹם תִּהְיֶ֖ה בֵּ֥ין שְׁנֵי⁠הֶֽם׃","wĕ֠⁠hẇʼ yibĕne֞h ʼeţ-héyka֤l yĕhwáh֙ wĕ⁠hֽẇʼ-yişá֣̇̂ʼ h֔wòd wĕ⁠yáşǎ֥b ẇ⁠máşǎ֖l ʻal-ki̇sĕʼ֑⁠wò wĕ⁠háyá֤h kòhén֙ ʻal-ki̇sĕʼ֔⁠wò wa⁠ʻàẕa֣ţ şá̌l֔wòm ţi̇hĕye֖h bé֥̇yn şĕ̌néy⁠heֽm׃"],[6,14,"וְ⁠הָ⁠עֲטָרֹ֗ת תִּֽהְיֶה֙ לְ⁠חֵ֨לֶם֙ וּ⁠לְ⁠טוֹבִיָּ֣ה וְ⁠לִ⁠ידַֽעְיָ֔ה וּ⁠לְ⁠חֵ֖ן בֶּן־צְפַנְיָ֑ה לְ⁠זִכָּר֖וֹן בְּ⁠הֵיכַ֥ל יְהוָֽה׃","wĕ⁠há⁠ʻàtárò֗ţ ţiֽ̇hĕyeh֙ lĕ⁠ẖé֨lem֙ ẇ⁠lĕ⁠twòbiyá֣̇h wĕ⁠li⁠ydaֽʻĕyá֔h ẇ⁠lĕ⁠ẖé֖n bėn-ẕĕpanĕyá֑h lĕ⁠ziká̇r֖wòn bĕ̇⁠héyka֥l yĕhwáֽh׃"],[6,15,"וּ⁠רְחוֹקִ֣ים ׀ יָבֹ֗אוּ וּ⁠בָנוּ֙ בְּ⁠הֵיכַ֣ל יְהוָ֔ה וִ⁠ידַעְתֶּ֕ם כִּֽי־יְהוָ֥ה צְבָא֖וֹת שְׁלָחַ֣⁠נִי אֲלֵי⁠כֶ֑ם וְ⁠הָיָה֙ אִם־שָׁמ֣וֹעַ תִּשְׁמְע֔וּ⁠ן בְּ⁠ק֖וֹל יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃ס","ẇ⁠rĕẖwòqi֣ym ׀ yábò֗ʼẇ ẇ⁠bánẇ֙ bĕ̇⁠héyka֣l yĕhwá֔h wi⁠ydaʻĕţė֕m kiֽ̇y-yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌láẖa֣⁠niy ʼàléy⁠ke֑m wĕ⁠háyáh֙ ʼim-şá̌m֣wòʻa ţi̇şĕ̌mĕʻ֔ẇ⁠n bĕ̇⁠q֖wòl yĕhwá֥h ʼèlòhéy⁠keֽm׃s"],[7,1,"וַֽ⁠יְהִי֙ בִּ⁠שְׁנַ֣ת אַרְבַּ֔ע לְ⁠דָרְיָ֖וֶשׁ הַ⁠מֶּ֑לֶךְ הָיָ֨ה דְבַר־יְהוָ֜ה אֶל־זְכַרְיָ֗ה בְּ⁠אַרְבָּעָ֛ה לַ⁠חֹ֥דֶשׁ הַ⁠תְּשִׁעִ֖י בְּ⁠כִסְלֵֽו׃","waֽ⁠yĕhiy֙ bi̇⁠şĕ̌na֣ţ ʼarĕbȧ֔ʻ lĕ⁠dárĕyá֖weş̌ ha⁠mė֑lekĕ háyá֨h dĕbar-yĕhwá֜h ʼel-zĕkarĕyá֗h bĕ̇⁠ʼarĕbá̇ʻá֛h la⁠ẖò֥deş̌ ha⁠ţĕ̇şǐʻi֖y bĕ̇⁠kisĕléֽw׃"],[7,2,"וַ⁠יִּשְׁלַח֙ בֵּֽית־אֵ֔ל שַׂר־אֶ֕צֶר וְ⁠רֶ֥גֶם מֶ֖לֶךְ וַֽ⁠אֲנָשָׁ֑י⁠ו לְ⁠חַלּ֖וֹת אֶת־פְּנֵ֥י יְהוָֽה׃","wa⁠yi̇şĕ̌laẖ֙ béֽ̇yţ-ʼé֔l şâr-ʼe֕ẕer wĕ⁠re֥gem me֖lekĕ waֽ⁠ʼànáşá֑̌y⁠w lĕ⁠ẖal֖̇wòţ ʼeţ-pĕ̇né֥y yĕhwáֽh׃"],[7,3,"לֵ⁠אמֹ֗ר אֶל־הַ⁠כֹּֽהֲנִים֙ אֲשֶׁר֙ לְ⁠בֵית־יְהוָ֣ה צְבָא֔וֹת וְ⁠אֶל־הַ⁠נְּבִיאִ֖ים לֵ⁠אמֹ֑ר הַֽ⁠אֶבְכֶּה֙ בַּ⁠חֹ֣דֶשׁ הַ⁠חֲמִשִׁ֔י הִנָּזֵ֕ר כַּ⁠אֲשֶׁ֣ר עָשִׂ֔יתִי זֶ֖ה כַּ⁠מֶּ֥ה שָׁנִֽים׃פ","lé⁠ʼmò֗r ʼel-ha⁠kòֽ̇hàniym֙ ʼàşěr֙ lĕ⁠béyţ-yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠ʼel-ha⁠nĕ̇biyʼi֖ym lé⁠ʼmò֑r haֽ⁠ʼebĕkėh֙ bȧ⁠ẖò֣deş̌ ha⁠ẖàmişǐ֔y hiná̇zé֕r kȧ⁠ʼàşě֣r ʻáşî֔yţiy ze֖h kȧ⁠mė֥h şá̌niֽym׃p"],[7,4,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ ʼéla֥⁠y lé⁠ʼmòֽr׃"],[7,5,"אֱמֹר֙ אֶל־כָּל־עַ֣ם הָ⁠אָ֔רֶץ וְ⁠אֶל־הַ⁠כֹּהֲנִ֖ים לֵ⁠אמֹ֑ר כִּֽי־צַמְתֶּ֨ם וְ⁠סָפ֜וֹד בַּ⁠חֲמִישִׁ֣י וּ⁠בַ⁠שְּׁבִיעִ֗י וְ⁠זֶה֙ שִׁבְעִ֣ים שָׁנָ֔ה הֲ⁠צ֥וֹם צַמְתֻּ֖⁠נִי אָֽנִי׃","ʼèmòr֙ ʼel-ká̇l-ʻa֣m há⁠ʼá֔reẕ wĕ⁠ʼel-ha⁠kò̇hàni֖ym lé⁠ʼmò֑r kiֽ̇y-ẕamĕţė֨m wĕ⁠sáp֜wòd bȧ⁠ẖàmiyşǐ֣y ẇ⁠ba⁠şĕ̇̌biyʻi֗y wĕ⁠zeh֙ şǐbĕʻi֣ym şá̌ná֔h hà⁠ẕ֥wòm ẕamĕţu֖̇⁠niy ʼáֽniy׃"],[7,6,"וְ⁠כִ֥י תֹאכְל֖וּ וְ⁠כִ֣י תִשְׁתּ֑וּ הֲ⁠ל֤וֹא אַתֶּם֙ הָ⁠אֹ֣כְלִ֔ים וְ⁠אַתֶּ֖ם הַ⁠שֹּׁתִֽים׃","wĕ⁠ki֥y ţòʼkĕl֖ẇ wĕ⁠ki֣y ţişĕ̌ţ֑̇ẇ hà⁠l֤wòʼ ʼaţėm֙ há⁠ʼò֣kĕli֔ym wĕ⁠ʼaţė֖m ha⁠şò̇̌ţiֽym׃"],[7,7,"הֲ⁠ל֣וֹא אֶת־הַ⁠דְּבָרִ֗ים אֲשֶׁ֨ר קָרָ֤א יְהוָה֙ בְּ⁠יַד֙ הַ⁠נְּבִיאִ֣ים הָ⁠רִֽאשֹׁנִ֔ים בִּ⁠הְי֤וֹת יְרוּשָׁלִַ֨ם֙ יֹשֶׁ֣בֶת וּ⁠שְׁלֵוָ֔ה וְ⁠עָרֶ֖י⁠הָ סְבִיבֹתֶ֑י⁠הָ וְ⁠הַ⁠נֶּ֥גֶב וְ⁠הַ⁠שְּׁפֵלָ֖ה יֹשֵֽׁב׃פ","hà⁠l֣wòʼ ʼeţ-ha⁠dĕ̇bári֗ym ʼàşě֨r qárá֤ʼ yĕhwáh֙ bĕ̇⁠yad֙ ha⁠nĕ̇biyʼi֣ym há⁠riֽʼşò̌ni֔ym bi̇⁠hĕy֤wòţ yĕrẇşá̌lia֨m֙ yòşě֣beţ ẇ⁠şĕ̌léwá֔h wĕ⁠ʻáre֖y⁠há sĕbiybòţe֑y⁠há wĕ⁠ha⁠nė֥geb wĕ⁠ha⁠şĕ̇̌pélá֖h yòşéֽ̌b׃p"],[7,8,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶל־זְכַרְיָ֖ה לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼel-zĕkarĕyá֖h lé⁠ʼmòֽr׃"],[7,9,"כֹּ֥ה אָמַ֛ר יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר מִשְׁפַּ֤ט אֱמֶת֙ שְׁפֹ֔טוּ וְ⁠חֶ֣סֶד וְ⁠רַֽחֲמִ֔ים עֲשׂ֖וּ אִ֥ישׁ אֶת־אָחִֽי⁠ו׃","kò֥̇h ʼáma֛r yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r mişĕ̌pȧ֤t ʼèmeţ֙ şĕ̌pò֔tẇ wĕ⁠ẖe֣sed wĕ⁠raֽẖàmi֔ym ʻàş֖̂ẇ ʼi֥yş̌ ʼeţ-ʼáẖiֽy⁠w׃"],[7,10,"וְ⁠אַלְמָנָ֧ה וְ⁠יָת֛וֹם גֵּ֥ר וְ⁠עָנִ֖י אַֽל־תַּעֲשֹׁ֑קוּ וְ⁠רָעַת֙ אִ֣ישׁ אָחִ֔י⁠ו אַֽל־תַּחְשְׁב֖וּ בִּ⁠לְבַבְ⁠כֶֽם׃","wĕ⁠ʼalĕmáná֧h wĕ⁠yáţ֛wòm gé֥̇r wĕ⁠ʻáni֖y ʼaֽl-ţȧʻàşò֑̌qẇ wĕ⁠ráʻaţ֙ ʼi֣yş̌ ʼáẖi֔y⁠w ʼaֽl-ţȧẖĕşĕ̌b֖ẇ bi̇⁠lĕbabĕ⁠keֽm׃"],[7,11,"וַ⁠יְמָאֲנ֣וּ לְ⁠הַקְשִׁ֔יב וַ⁠יִּתְּנ֥וּ כָתֵ֖ף סֹרָ֑רֶת וְ⁠אָזְנֵי⁠הֶ֖ם הִכְבִּ֥ידוּ מִ⁠שְּׁמֽוֹעַ׃","wa⁠yĕmáʼàn֣ẇ lĕ⁠haqĕşǐ֔yb wa⁠yi̇ţĕ̇n֥ẇ káţé֖p sòrá֑reţ wĕ⁠ʼázĕnéy⁠he֖m hikĕbi֥̇ydẇ mi⁠şĕ̇̌mֽwòʻa׃"],[7,12,"וְ⁠לִבָּ֞⁠ם שָׂ֣מוּ שָׁמִ֗יר מִ֠⁠שְּׁמוֹעַ אֶת־הַ⁠תּוֹרָ֤ה וְ⁠אֶת־הַ⁠דְּבָרִים֙ אֲשֶׁ֨ר שָׁלַ֜ח יְהוָ֤ה צְבָאוֹת֙ בְּ⁠רוּח֔⁠וֹ בְּ⁠יַ֖ד הַ⁠נְּבִיאִ֣ים הָ⁠רִֽאשֹׁנִ֑ים וַֽ⁠יְהִי֙ קֶ֣צֶף גָּד֔וֹל מֵ⁠אֵ֖ת יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠libá̇֞⁠m şá֣̂mẇ şá̌mi֗yr mi֠⁠şĕ̇̌mwòʻa ʼeţ-ha⁠ţ̇wòrá֤h wĕ⁠ʼeţ-ha⁠dĕ̇báriym֙ ʼàşě֨r şá̌la֜ẖ yĕhwá֤h ẕĕbáʼwòţ֙ bĕ̇⁠rẇẖ֔⁠wò bĕ̇⁠ya֖d ha⁠nĕ̇biyʼi֣ym há⁠riֽʼşò̌ni֑ym waֽ⁠yĕhiy֙ qe֣ẕep gá̇d֔wòl mé⁠ʼé֖ţ yĕhwá֥h ẕĕbáʼֽwòţ׃"],[7,13,"וַ⁠יְהִ֥י כַ⁠אֲשֶׁר־קָרָ֖א וְ⁠לֹ֣א שָׁמֵ֑עוּ כֵּ֤ן יִקְרְאוּ֙ וְ⁠לֹ֣א אֶשְׁמָ֔ע אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃","wa⁠yĕhi֥y ka⁠ʼàşěr-qárá֖ʼ wĕ⁠lò֣ʼ şá̌mé֑ʻẇ ké֤̇n yiqĕrĕʼẇ֙ wĕ⁠lò֣ʼ ʼeşĕ̌má֔ʻ ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃"],[7,14,"וְ⁠אֵ֣סָעֲרֵ֗⁠ם עַ֤ל כָּל־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר לֹֽא־יְדָע֔וּ⁠ם וְ⁠הָ⁠אָ֨רֶץ֙ נָשַׁ֣מָּה אַֽחֲרֵי⁠הֶ֔ם מֵֽ⁠עֹבֵ֖ר וּ⁠מִ⁠שָּׁ֑ב וַ⁠יָּשִׂ֥ימוּ אֶֽרֶץ־חֶמְדָּ֖ה לְ⁠שַׁמָּֽה׃פ","wĕ⁠ʼé֣sáʻàré֗⁠m ʻa֤l ká̇l-ha⁠ġwòyim֙ ʼàşě֣r lòֽʼ-yĕdáʻ֔ẇ⁠m wĕ⁠há⁠ʼá֨reẕ֙ náşǎ֣má̇h ʼaֽẖàréy⁠he֔m méֽ⁠ʻòbé֖r ẇ⁠mi⁠şá֑̇̌b wa⁠yá̇şî֥ymẇ ʼeֽreẕ-ẖemĕdá֖̇h lĕ⁠şǎmáֽ̇h׃p"],[8,1,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmòֽr׃"],[8,2,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת קִנֵּ֥אתִי לְ⁠צִיּ֖וֹן קִנְאָ֣ה גְדוֹלָ֑ה וְ⁠חֵמָ֥ה גְדוֹלָ֖ה קִנֵּ֥אתִי לָֽ⁠הּ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ qiné֥̇ʼţiy lĕ⁠ẕiẏ֖wòn qinĕʼá֣h gĕdwòlá֑h wĕ⁠ẖémá֥h gĕdwòlá֖h qiné֥̇ʼţiy láֽ⁠ḣ׃"],[8,3,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה שַׁ֚בְתִּי אֶל־צִיּ֔וֹן וְ⁠שָׁכַנְתִּ֖י בְּ⁠ת֣וֹךְ יְרֽוּשָׁלִָ֑ם וְ⁠נִקְרְאָ֤ה יְרוּשָׁלִַ֨ם֙ עִ֣יר־הָֽ⁠אֱמֶ֔ת וְ⁠הַר־יְהוָ֥ה צְבָא֖וֹת הַ֥ר הַ⁠קֹּֽדֶשׁ׃ס","kò֚̇h ʼáma֣r yĕhwá֔h şǎ֚bĕţi̇y ʼel-ẕiẏ֔wòn wĕ⁠şá̌kanĕţi֖̇y bĕ̇⁠ţ֣wòkĕ yĕrֽẇşá̌liá֑m wĕ⁠niqĕrĕʼá֤h yĕrẇşá̌lia֨m֙ ʻi֣yr-háֽ⁠ʼème֔ţ wĕ⁠har-yĕhwá֥h ẕĕbáʼ֖wòţ ha֥r ha⁠qòֽ̇deş̌׃s"],[8,4,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת עֹ֤ד יֵֽשְׁבוּ֙ זְקֵנִ֣ים וּ⁠זְקֵנ֔וֹת בִּ⁠רְחֹב֖וֹת יְרוּשָׁלִָ֑ם וְ⁠אִ֧ישׁ מִשְׁעַנְתּ֛⁠וֹ בְּ⁠יָד֖⁠וֹ מֵ⁠רֹ֥ב יָמִֽים׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʻò֤d yéֽşĕ̌bẇ֙ zĕqéni֣ym ẇ⁠zĕqén֔wòţ bi̇⁠rĕẖòb֖wòţ yĕrẇşá̌liá֑m wĕ⁠ʼi֧yş̌ mişĕ̌ʻanĕţ֛̇⁠wò bĕ̇⁠yád֖⁠wò mé⁠rò֥b yámiֽym׃"],[8,5,"וּ⁠רְחֹב֤וֹת הָ⁠עִיר֙ יִמָּ֣לְא֔וּ יְלָדִ֖ים וִֽ⁠ילָד֑וֹת מְשַׂחֲקִ֖ים בִּ⁠רְחֹֽבֹתֶֽי⁠הָ׃ס","ẇ⁠rĕẖòb֤wòţ há⁠ʻiyr֙ yimá֣̇lĕʼ֔ẇ yĕládi֖ym wiֽ⁠ylád֑wòţ mĕşâẖàqi֖ym bi̇⁠rĕẖòֽbòţeֽy⁠há׃s"],[8,6,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת כִּ֣י יִפָּלֵ֗א בְּ⁠עֵינֵי֙ שְׁאֵרִית֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה בַּ⁠יָּמִ֖ים הָ⁠הֵ֑ם גַּם־בְּ⁠עֵינַ⁠י֙ יִפָּלֵ֔א נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃פ","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ki֣̇y yipá̇lé֗ʼ bĕ̇⁠ʻéynéy֙ şĕ̌ʼériyţ֙ há⁠ʻá֣m ha⁠zė֔h bȧ⁠yá̇mi֖ym há⁠hé֑m gȧm-bĕ̇⁠ʻéyna⁠y֙ yipá̇lé֔ʼ nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[8,7,"כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת הִנְ⁠נִ֥י מוֹשִׁ֛יעַ אֶת־עַמִּ֖⁠י מֵ⁠אֶ֣רֶץ מִזְרָ֑ח וּ⁠מֵ⁠אֶ֖רֶץ מְב֥וֹא הַ⁠שָּֽׁמֶשׁ׃","kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ hinĕ⁠ni֥y mwòşǐ֛yʻa ʼeţ-ʻami֖̇⁠y mé⁠ʼe֣reẕ mizĕrá֑ẖ ẇ⁠mé⁠ʼe֖reẕ mĕb֥wòʼ ha⁠şáֽ̇̌meş̌׃"],[8,8,"וְ⁠הֵבֵאתִ֣י אֹתָ֔⁠ם וְ⁠שָׁכְנ֖וּ בְּ⁠ת֣וֹךְ יְרוּשָׁלִָ֑ם וְ⁠הָיוּ־לִ֣⁠י לְ⁠עָ֗ם וַֽ⁠אֲנִי֙ אֶהְיֶ֤ה לָ⁠הֶם֙ לֵֽ⁠אלֹהִ֔ים בֶּ⁠אֱמֶ֖ת וּ⁠בִ⁠צְדָקָֽה׃ס","wĕ⁠hébéʼţi֣y ʼòţá֔⁠m wĕ⁠şá̌kĕn֖ẇ bĕ̇⁠ţ֣wòkĕ yĕrẇşá̌liá֑m wĕ⁠háyẇ-li֣⁠y lĕ⁠ʻá֗m waֽ⁠ʼàniy֙ ʼehĕye֤h lá⁠hem֙ léֽ⁠ʼlòhi֔ym bė⁠ʼème֖ţ ẇ⁠bi⁠ẕĕdáqáֽh׃s"],[8,9,"כֹּֽה־אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ תֶּחֱזַ֣קְנָה יְדֵי⁠כֶ֔ם הַ⁠שֹּֽׁמְעִים֙ בַּ⁠יָּמִ֣ים הָ⁠אֵ֔לֶּה אֵ֖ת הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה מִ⁠פִּי֙ הַ⁠נְּבִיאִ֔ים אֲ֠שֶׁר בְּ⁠י֞וֹם יֻסַּ֨ד בֵּית־יְהוָ֧ה צְבָא֛וֹת הַ⁠הֵיכָ֖ל לְ⁠הִבָּנֽוֹת׃","kòֽ̇h-ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ ţėẖèza֣qĕnáh yĕdéy⁠ke֔m ha⁠şòֽ̇̌mĕʻiym֙ bȧ⁠yá̇mi֣ym há⁠ʼé֔lėh ʼé֖ţ ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh mi⁠pi̇y֙ ha⁠nĕ̇biyʼi֔ym ʼà֠şěr bĕ̇⁠y֞wòm yusȧ֨d bé̇yţ-yĕhwá֧h ẕĕbáʼ֛wòţ ha⁠héyká֖l lĕ⁠hibá̇nֽwòţ׃"],[8,10,"כִּ֗י לִ⁠פְנֵי֙ הַ⁠יָּמִ֣ים הָ⁠הֵ֔ם שְׂכַ֤ר הָֽ⁠אָדָם֙ לֹ֣א נִֽהְיָ֔ה וּ⁠שְׂכַ֥ר הַ⁠בְּהֵמָ֖ה אֵינֶ֑⁠נָּה וְ⁠לַ⁠יּוֹצֵ֨א וְ⁠לַ⁠בָּ֤א אֵין־שָׁלוֹם֙ מִן־הַ⁠צָּ֔ר וַ⁠אֲשַׁלַּ֥ח אֶת־כָּל־הָ⁠אָדָ֖ם אִ֥ישׁ בְּ⁠רֵעֵֽ⁠הוּ׃","ki̇֗y li⁠pĕnéy֙ ha⁠yá̇mi֣ym há⁠hé֔m şĕ̂ka֤r háֽ⁠ʼádám֙ lò֣ʼ niֽhĕyá֔h ẇ⁠şĕ̂ka֥r ha⁠bĕ̇hémá֖h ʼéyne֑⁠ná̇h wĕ⁠la⁠ẏwòẕé֨ʼ wĕ⁠la⁠bá֤̇ʼ ʼéyn-şá̌lwòm֙ min-ha⁠ẕá̇֔r wa⁠ʼàşǎlȧ֥ẖ ʼeţ-ká̇l-há⁠ʼádá֖m ʼi֥yş̌ bĕ̇⁠réʻéֽ⁠hẇ׃"],[8,11,"וְ⁠עַתָּ֗ה לֹ֣א כַ⁠יָּמִ֤ים הָ⁠רִֽאשֹׁנִים֙ אֲנִ֔י לִ⁠שְׁאֵרִ֖ית הָ⁠עָ֣ם הַ⁠זֶּ֑ה נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠ʻaţá̇֗h lò֣ʼ ka⁠yá̇mi֤ym há⁠riֽʼşò̌niym֙ ʼàni֔y li⁠şĕ̌ʼéri֖yţ há⁠ʻá֣m ha⁠zė֑h nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃"],[8,12,"כִּֽי־זֶ֣רַע הַ⁠שָּׁל֗וֹם הַ⁠גֶּ֜פֶן תִּתֵּ֤ן פִּרְיָ⁠הּ֙ וְ⁠הָ⁠אָ֨רֶץ֙ תִּתֵּ֣ן אֶת־יְבוּלָ֔⁠הּ וְ⁠הַ⁠שָּׁמַ֖יִם יִתְּנ֣וּ טַלָּ֑⁠ם וְ⁠הִנְחַלְתִּ֗י אֶת־שְׁאֵרִ֛ית הָ⁠עָ֥ם הַ⁠זֶּ֖ה אֶת־כָּל־אֵֽלֶּה׃","kiֽ̇y-ze֣raʻ ha⁠şá̇̌l֗wòm ha⁠gė֜pen ţi̇ţé֤̇n pi̇rĕyá⁠ḣ֙ wĕ⁠há⁠ʼá֨reẕ֙ ţi̇ţé֣̇n ʼeţ-yĕbẇlá֔⁠ḣ wĕ⁠ha⁠şá̇̌ma֖yim yiţĕ̇n֣ẇ talá֑̇⁠m wĕ⁠hinĕẖalĕţi̇֗y ʼeţ-şĕ̌ʼéri֛yţ há⁠ʻá֥m ha⁠zė֖h ʼeţ-ká̇l-ʼéֽlėh׃"],[8,13,"וְ⁠הָיָ֡ה כַּ⁠אֲשֶׁר֩ הֱיִיתֶ֨ם קְלָלָ֜ה בַּ⁠גּוֹיִ֗ם בֵּ֤ית יְהוּדָה֙ וּ⁠בֵ֣ית יִשְׂרָאֵ֔ל כֵּ֚ן אוֹשִׁ֣יעַ אֶתְ⁠כֶ֔ם וִ⁠הְיִיתֶ֖ם בְּרָכָ֑ה אַל־תִּירָ֖אוּ תֶּחֱזַ֥קְנָה יְדֵי⁠כֶֽם׃ס","wĕ⁠háyá֡h kȧ⁠ʼàşěr֩ hèyiyţe֨m qĕlálá֜h bȧ⁠ġwòyi֗m bé֤̇yţ yĕhẇdáh֙ ẇ⁠bé֣yţ yişĕ̂ráʼé֔l ké֚̇n ʼwòşǐ֣yʻa ʼeţĕ⁠ke֔m wi⁠hĕyiyţe֖m bĕ̇ráká֑h ʼal-ţi̇yrá֖ʼẇ ţėẖèza֥qĕnáh yĕdéy⁠keֽm׃s"],[8,14,"כִּ֣י כֹ֣ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ כַּ⁠אֲשֶׁ֨ר זָמַמְ֜תִּי לְ⁠הָרַ֣ע לָ⁠כֶ֗ם בְּ⁠הַקְצִ֤יף אֲבֹֽתֵי⁠כֶם֙ אֹתִ֔⁠י אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת וְ⁠לֹ֖א נִחָֽמְתִּי׃","ki֣̇y kò֣h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ kȧ⁠ʼàşě֨r zámamĕ֜ţi̇y lĕ⁠hára֣ʻ lá⁠ke֗m bĕ̇⁠haqĕẕi֤yp ʼàbòֽţéy⁠kem֙ ʼòţi֔⁠y ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠lò֖ʼ niẖáֽmĕţi̇y׃"],[8,15,"כֵּ֣ן שַׁ֤בְתִּי זָמַ֨מְתִּי֙ בַּ⁠יָּמִ֣ים הָ⁠אֵ֔לֶּה לְ⁠הֵיטִ֥יב אֶת־יְרוּשָׁלִַ֖ם וְ⁠אֶת־בֵּ֣ית יְהוּדָ֑ה אַל־תִּירָֽאוּ׃","ké֣̇n şǎ֤bĕţi̇y záma֨mĕţi̇y֙ bȧ⁠yá̇mi֣ym há⁠ʼé֔lėh lĕ⁠héyti֥yb ʼeţ-yĕrẇşá̌lia֖m wĕ⁠ʼeţ-bé֣̇yţ yĕhẇdá֑h ʼal-ţi̇yráֽʼẇ׃"],[8,16,"אֵ֥לֶּה הַ⁠דְּבָרִ֖ים אֲשֶׁ֣ר תַּֽעֲשׂ֑וּ דַּבְּר֤וּ אֱמֶת֙ אִ֣ישׁ אֶת־רֵעֵ֔⁠הוּ אֱמֶת֙ וּ⁠מִשְׁפַּ֣ט שָׁל֔וֹם שִׁפְט֖וּ בְּ⁠שַׁעֲרֵי⁠כֶֽם׃","ʼé֥lėh ha⁠dĕ̇bári֖ym ʼàşě֣r ţȧֽʻàş֑̂ẇ dȧbĕ̇r֤ẇ ʼèmeţ֙ ʼi֣yş̌ ʼeţ-réʻé֔⁠hẇ ʼèmeţ֙ ẇ⁠mişĕ̌pȧ֣t şá̌l֔wòm şǐpĕt֖ẇ bĕ̇⁠şǎʻàréy⁠keֽm׃"],[8,17,"וְ⁠אִ֣ישׁ ׀ אֶת־רָעַ֣ת רֵעֵ֗⁠הוּ אַֽל־תַּחְשְׁבוּ֙ בִּ⁠לְבַבְ⁠כֶ֔ם וּ⁠שְׁבֻ֥עַת שֶׁ֖קֶר אַֽל־תֶּאֱהָ֑בוּ כִּ֧י אֶת־כָּל־אֵ֛לֶּה אֲשֶׁ֥ר שָׂנֵ֖אתִי נְאֻם־יְהוָֽה׃ס","wĕ⁠ʼi֣yş̌ ׀ ʼeţ-ráʻa֣ţ réʻé֗⁠hẇ ʼaֽl-ţȧẖĕşĕ̌bẇ֙ bi̇⁠lĕbabĕ⁠ke֔m ẇ⁠şĕ̌bu֥ʻaţ şě֖qer ʼaֽl-ţėʼèhá֑bẇ ki֧̇y ʼeţ-ká̇l-ʼé֛lėh ʼàşě֥r şá̂né֖ʼţiy nĕʼum-yĕhwáֽh׃s"],[8,18,"וַ⁠יְהִ֛י דְּבַר־יְהוָ֥ה צְבָא֖וֹת אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y dĕ̇bar-yĕhwá֥h ẕĕbáʼ֖wòţ ʼéla֥⁠y lé⁠ʼmòֽr׃"],[8,19,"כֹּֽה־אָמַ֞ר יְהוָ֣ה צְבָא֗וֹת צ֣וֹם הָ⁠רְבִיעִ֡י וְ⁠צ֣וֹם הַ⁠חֲמִישִׁי֩ וְ⁠צ֨וֹם הַ⁠שְּׁבִיעִ֜י וְ⁠צ֣וֹם הָ⁠עֲשִׂירִ֗י יִהְיֶ֤ה לְ⁠בֵית־יְהוּדָה֙ לְ⁠שָׂשׂ֣וֹן וּ⁠לְ⁠שִׂמְחָ֔ה וּֽ⁠לְ⁠מֹעֲדִ֖ים טוֹבִ֑ים וְ⁠הָ⁠אֱמֶ֥ת וְ⁠הַ⁠שָּׁל֖וֹם אֱהָֽבוּ׃פ","kòֽ̇h-ʼáma֞r yĕhwá֣h ẕĕbáʼ֗wòţ ẕ֣wòm há⁠rĕbiyʻi֡y wĕ⁠ẕ֣wòm ha⁠ẖàmiyşǐy֩ wĕ⁠ẕ֨wòm ha⁠şĕ̇̌biyʻi֜y wĕ⁠ẕ֣wòm há⁠ʻàşîyri֗y yihĕye֤h lĕ⁠béyţ-yĕhẇdáh֙ lĕ⁠şá̂ş֣̂wòn ẇ⁠lĕ⁠şîmĕẖá֔h ẇֽ⁠lĕ⁠mòʻàdi֖ym twòbi֑ym wĕ⁠há⁠ʼème֥ţ wĕ⁠ha⁠şá̇̌l֖wòm ʼèháֽbẇ׃p"],[8,20,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה צְבָא֑וֹת עֹ֚ד אֲשֶׁ֣ר יָבֹ֣אוּ עַמִּ֔ים וְ⁠יֹשְׁבֵ֖י עָרִ֥ים רַבּֽוֹת׃","kò֥̇h ʼáma֖r yĕhwá֣h ẕĕbáʼ֑wòţ ʻò֚d ʼàşě֣r yábò֣ʼẇ ʻami̇֔ym wĕ⁠yòşĕ̌bé֖y ʻári֥ym raḃֽwòţ׃"],[8,21,"וְֽ⁠הָלְכ֡וּ יֹשְׁבֵי֩ אַחַ֨ת אֶל־אַחַ֜ת לֵ⁠אמֹ֗ר נֵלְכָ֤ה הָלוֹךְ֙ לְ⁠חַלּוֹת֙ אֶת־פְּנֵ֣י יְהוָ֔ה וּ⁠לְ⁠בַקֵּ֖שׁ אֶת־יְהוָ֣ה צְבָא֑וֹת אֵלְכָ֖ה גַּם־אָֽנִי׃","wĕֽ⁠hálĕk֡ẇ yòşĕ̌béy֩ ʼaẖa֨ţ ʼel-ʼaẖa֜ţ lé⁠ʼmò֗r nélĕká֤h hálwòkĕ֙ lĕ⁠ẖal̇wòţ֙ ʼeţ-pĕ̇né֣y yĕhwá֔h ẇ⁠lĕ⁠baqé֖̇ş̌ ʼeţ-yĕhwá֣h ẕĕbáʼ֑wòţ ʼélĕká֖h gȧm-ʼáֽniy׃"],[8,22,"וּ⁠בָ֨אוּ עַמִּ֤ים רַבִּים֙ וְ⁠גוֹיִ֣ם עֲצוּמִ֔ים לְ⁠בַקֵּ֛שׁ אֶת־יְהוָ֥ה צְבָא֖וֹת בִּ⁠ירוּשָׁלִָ֑ם וּ⁠לְ⁠חַלּ֖וֹת אֶת־פְּנֵ֥י יְהוָֽה׃ס","ẇ⁠bá֨ʼẇ ʻami֤̇ym rabi̇ym֙ wĕ⁠gwòyi֣m ʻàẕẇmi֔ym lĕ⁠baqé֛̇ş̌ ʼeţ-yĕhwá֥h ẕĕbáʼ֖wòţ bi̇⁠yrẇşá̌liá֑m ẇ⁠lĕ⁠ẖal֖̇wòţ ʼeţ-pĕ̇né֥y yĕhwáֽh׃s"],[8,23,"כֹּ֥ה אָמַר֮ יְהוָ֣ה צְבָאוֹת֒ בַּ⁠יָּמִ֣ים הָ⁠הֵ֔מָּה אֲשֶׁ֤ר יַחֲזִ֨יקוּ֙ עֲשָׂרָ֣ה אֲנָשִׁ֔ים מִ⁠כֹּ֖ל לְשֹׁנ֣וֹת הַ⁠גּוֹיִ֑ם וְֽ⁠הֶחֱזִ֡יקוּ בִּ⁠כְנַף֩ אִ֨ישׁ יְהוּדִ֜י לֵ⁠אמֹ֗ר נֵֽלְכָה֙ עִמָּ⁠כֶ֔ם כִּ֥י שָׁמַ֖עְנוּ אֱלֹהִ֥ים עִמָּ⁠כֶֽם׃ס","kò֥̇h ʼámar֮ yĕhwá֣h ẕĕbáʼwòţ֒ bȧ⁠yá̇mi֣ym há⁠hé֔má̇h ʼàşě֤r yaẖàzi֨yqẇ֙ ʻàşá̂rá֣h ʼànáşǐ֔ym mi⁠kò֖̇l lĕşò̌n֣wòţ ha⁠ġwòyi֑m wĕֽ⁠heẖèzi֡yqẇ bi̇⁠kĕnap֩ ʼi֨yş̌ yĕhẇdi֜y lé⁠ʼmò֗r néֽlĕkáh֙ ʻimá̇⁠ke֔m ki֥̇y şá̌ma֖ʻĕnẇ ʼèlòhi֥ym ʻimá̇⁠keֽm׃s"],[9,1,"מַשָּׂ֤א דְבַר־יְהוָה֙ בְּ⁠אֶ֣רֶץ חַדְרָ֔ךְ וְ⁠דַמֶּ֖שֶׂק מְנֻחָת֑⁠וֹ כִּ֤י לַֽ⁠יהוָה֙ עֵ֣ין אָדָ֔ם וְ⁠כֹ֖ל שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","maşá֤̇̂ʼ dĕbar-yĕhwáh֙ bĕ̇⁠ʼe֣reẕ ẖadĕrá֔kĕ wĕ⁠damė֖şêq mĕnuẖáţ֑⁠wò ki֤̇y laֽ⁠yhwáh֙ ʻé֣yn ʼádá֔m wĕ⁠kò֖l şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[9,2,"וְ⁠גַם־חֲמָ֖ת תִּגְבָּל־בָּ֑⁠הּ צֹ֣ר וְ⁠צִיד֔וֹן כִּ֥י חָֽכְמָ֖ה מְאֹֽד׃","wĕ⁠gam-ẖàmá֖ţ ţi̇gĕbá̇l-bá֑̇⁠ḣ ẕò֣r wĕ⁠ẕiyd֔wòn ki֥̇y ẖáֽkĕmá֖h mĕʼòֽd׃"],[9,3,"וַ⁠תִּ֥בֶן צֹ֛ר מָצ֖וֹר לָ֑⁠הּ וַ⁠תִּצְבָּר־כֶּ֨סֶף֙ כֶּֽ⁠עָפָ֔ר וְ⁠חָר֖וּץ כְּ⁠טִ֥יט חוּצֽוֹת׃","wa⁠ţi֥̇ben ẕò֛r máẕ֖wòr lá֑⁠ḣ wa⁠ţi̇ẕĕbá̇r-kė֨sep֙ kėֽ⁠ʻápá֔r wĕ⁠ẖár֖ẇẕ kĕ̇⁠ti֥yt ẖẇẕֽwòţ׃"],[9,4,"הִנֵּ֤ה אֲדֹנָ⁠י֙ יֽוֹרִשֶׁ֔⁠נָּה וְ⁠הִכָּ֥ה בַ⁠יָּ֖ם חֵילָ֑⁠הּ וְ⁠הִ֖יא בָּ⁠אֵ֥שׁ תֵּאָכֵֽל׃","hiné֤̇h ʼàdòná⁠y֙ yֽwòrişě֔⁠ná̇h wĕ⁠hiká֥̇h ba⁠yá֖̇m ẖéylá֑⁠ḣ wĕ⁠hi֖yʼ bá̇⁠ʼé֥ş̌ ţé̇ʼákéֽl׃"],[9,5,"תֵּרֶ֨א אַשְׁקְל֜וֹן וְ⁠תִירָ֗א וְ⁠עַזָּה֙ וְ⁠תָחִ֣יל מְאֹ֔ד וְ⁠עֶקְר֖וֹן כִּֽי־הֹבִ֣ישׁ מֶבָּטָ֑⁠הּ וְ⁠אָ֤בַד מֶ֨לֶךְ֙ מֵֽ⁠עַזָּ֔ה וְ⁠אַשְׁקְל֖וֹן לֹ֥א תֵשֵֽׁב׃","ţé̇re֨ʼ ʼaşĕ̌qĕl֜wòn wĕ⁠ţiyrá֗ʼ wĕ⁠ʻazá̇h֙ wĕ⁠ţáẖi֣yl mĕʼò֔d wĕ⁠ʻeqĕr֖wòn kiֽ̇y-hòbi֣yş̌ mebá̇tá֑⁠ḣ wĕ⁠ʼá֤bad me֨lekĕ֙ méֽ⁠ʻazá̇֔h wĕ⁠ʼaşĕ̌qĕl֖wòn lò֥ʼ ţéşéֽ̌b׃"],[9,6,"וְ⁠יָשַׁ֥ב מַמְזֵ֖ר בְּ⁠אַשְׁדּ֑וֹד וְ⁠הִכְרַתִּ֖י גְּא֥וֹן פְּלִשְׁתִּֽים׃","wĕ⁠yáşǎ֥b mamĕzé֖r bĕ̇⁠ʼaşĕ̌ḋ֑wòd wĕ⁠hikĕraţi֖̇y gĕ̇ʼ֥wòn pĕ̇lişĕ̌ţiֽ̇ym׃"],[9,7,"וַ⁠הֲסִרֹתִ֨י דָמָ֜י⁠ו מִ⁠פִּ֗י⁠ו וְ⁠שִׁקֻּצָי⁠ו֙ מִ⁠בֵּ֣ין שִׁנָּ֔י⁠ו וְ⁠נִשְׁאַ֥ר גַּם־ה֖וּא לֵֽ⁠אלֹהֵ֑י⁠נוּ וְ⁠הָיָה֙ כְּ⁠אַלֻּ֣ף בִּֽ⁠יהוּדָ֔ה וְ⁠עֶקְר֖וֹן כִּ⁠יבוּסִֽי׃","wa⁠hàsiròţi֨y dámá֜y⁠w mi⁠pi̇֗y⁠w wĕ⁠şǐqu̇ẕáy⁠w֙ mi⁠bé֣̇yn şǐná̇֔y⁠w wĕ⁠nişĕ̌ʼa֥r gȧm-h֖ẇʼ léֽ⁠ʼlòhé֑y⁠nẇ wĕ⁠háyáh֙ kĕ̇⁠ʼalu֣̇p biֽ̇⁠yhẇdá֔h wĕ⁠ʻeqĕr֖wòn ki̇⁠ybẇsiֽy׃"],[9,8,"וְ⁠חָנִ֨יתִי לְ⁠בֵיתִ֤⁠י מִצָּבָה֙ מֵ⁠עֹבֵ֣ר וּ⁠מִ⁠שָּׁ֔ב וְ⁠לֹֽא־יַעֲבֹ֧ר עֲלֵי⁠הֶ֛ם ע֖וֹד נֹגֵ֑שׂ כִּ֥י עַתָּ֖ה רָאִ֥יתִי בְ⁠עֵינָֽ⁠י׃ס","wĕ⁠ẖáni֨yţiy lĕ⁠béyţi֤⁠y miẕá̇báh֙ mé⁠ʻòbé֣r ẇ⁠mi⁠şá̇̌֔b wĕ⁠lòֽʼ-yaʻàbò֧r ʻàléy⁠he֛m ʻ֖wòd nògé֑ş̂ ki֥̇y ʻaţá֖̇h ráʼi֥yţiy bĕ⁠ʻéynáֽ⁠y׃s"],[9,9,"גִּילִ֨י מְאֹ֜ד בַּת־צִיּ֗וֹן הָרִ֨יעִי֙ בַּ֣ת יְרוּשָׁלִַ֔ם הִנֵּ֤ה מַלְכֵּ⁠ךְ֙ יָ֣בוֹא לָ֔⁠ךְ צַדִּ֥יק וְ⁠נוֹשָׁ֖ע ה֑וּא עָנִי֙ וְ⁠רֹכֵ֣ב עַל־חֲמ֔וֹר וְ⁠עַל־עַ֖יִר בֶּן־אֲתֹנֽוֹת׃","gi̇yli֨y mĕʼò֜d bȧţ-ẕiẏ֗wòn hári֨yʻiy֙ bȧ֣ţ yĕrẇşá̌lia֔m hiné֤̇h malĕké̇⁠kĕ֙ yá֣bwòʼ lá֔⁠kĕ ẕadi֥̇yq wĕ⁠nwòşá֖̌ʻ h֑ẇʼ ʻániy֙ wĕ⁠ròké֣b ʻal-ẖàm֔wòr wĕ⁠ʻal-ʻa֖yir bėn-ʼàţònֽwòţ׃"],[9,10,"וְ⁠הִכְרַתִּי־רֶ֣כֶב מֵ⁠אֶפְרַ֗יִם וְ⁠סוּס֙ מִ⁠יר֣וּשָׁלִַ֔ם וְ⁠נִכְרְתָה֙ קֶ֣שֶׁת מִלְחָמָ֔ה וְ⁠דִבֶּ֥ר שָׁל֖וֹם לַ⁠גּוֹיִ֑ם וּ⁠מָשְׁל⁠וֹ֙ מִ⁠יָּ֣ם עַד־יָ֔ם וּ⁠מִ⁠נָּהָ֖ר עַד־אַפְסֵי־אָֽרֶץ׃","wĕ⁠hikĕraţi̇y-re֣keb mé⁠ʼepĕra֗yim wĕ⁠sẇs֙ mi⁠yr֣ẇşá̌lia֔m wĕ⁠nikĕrĕţáh֙ qe֣şěţ milĕẖámá֔h wĕ⁠dibė֥r şá̌l֖wòm la⁠ġwòyi֑m ẇ⁠máşĕ̌l⁠wò֙ mi⁠yá֣̇m ʻad-yá֔m ẇ⁠mi⁠ná̇há֖r ʻad-ʼapĕséy-ʼáֽreẕ׃"],[9,11,"גַּם־אַ֣תְּ בְּ⁠דַם־בְּרִיתֵ֗⁠ךְ שִׁלַּ֤חְתִּי אֲסִירַ֨יִ⁠ךְ֙ מִ⁠בּ֔וֹר אֵ֥ין מַ֖יִם בּֽ⁠וֹ׃","gȧm-ʼa֣ţĕ̇ bĕ̇⁠dam-bĕ̇riyţé֗⁠kĕ şǐlȧ֤ẖĕţi̇y ʼàsiyra֨yi⁠kĕ֙ mi⁠ḃ֔wòr ʼé֥yn ma֖yim ḃֽ⁠wò׃"],[9,12,"שׁ֚וּבוּ לְ⁠בִצָּר֔וֹן אֲסִירֵ֖י הַ⁠תִּקְוָ֑ה גַּם־הַ⁠יּ֕וֹם מַגִּ֥יד מִשְׁנֶ֖ה אָשִׁ֥יב לָֽ⁠ךְ׃","ş֚̌ẇbẇ lĕ⁠biẕá̇r֔wòn ʼàsiyré֖y ha⁠ţi̇qĕwá֑h gȧm-ha⁠ẏ֕wòm magi֥̇yd mişĕ̌ne֖h ʼáşǐ֥yb láֽ⁠kĕ׃"],[9,13,"כִּֽי־דָרַ֨כְתִּי לִ֜⁠י יְהוּדָ֗ה קֶ֚שֶׁת מִלֵּ֣אתִי אֶפְרַ֔יִם וְ⁠עוֹרַרְתִּ֤י בָנַ֨יִ⁠ךְ֙ צִיּ֔וֹן עַל־בָּנַ֖יִ⁠ךְ יָוָ֑ן וְ⁠שַׂמְתִּ֖י⁠ךְ כְּ⁠חֶ֥רֶב גִּבּֽוֹר׃","kiֽ̇y-dára֨kĕţi̇y li֜⁠y yĕhẇdá֗h qe֚şěţ milé֣̇ʼţiy ʼepĕra֔yim wĕ⁠ʻwòrarĕţi֤̇y bána֨yi⁠kĕ֙ ẕiẏ֔wòn ʻal-bá̇na֖yi⁠kĕ yáwá֑n wĕ⁠şâmĕţi֖̇y⁠kĕ kĕ̇⁠ẖe֥reb gi̇ḃֽwòr׃"],[9,14,"וַֽ⁠יהוָה֙ עֲלֵי⁠הֶ֣ם יֵֽרָאֶ֔ה וְ⁠יָצָ֥א כַ⁠בָּרָ֖ק חִצּ֑⁠וֹ וַֽ⁠אדֹנָ֤⁠י יְהֹוִה֙ בַּ⁠שּׁוֹפָ֣ר יִתְקָ֔ע וְ⁠הָלַ֖ךְ בְּ⁠סַעֲר֥וֹת תֵּימָֽן׃","waֽ⁠yhwáh֙ ʻàléy⁠he֣m yéֽráʼe֔h wĕ⁠yáẕá֥ʼ ka⁠bá̇rá֖q ẖiẕ֑̇⁠wò waֽ⁠ʼdòná֤⁠y yĕhòwih֙ bȧ⁠ş̇̌wòpá֣r yiţĕqá֔ʻ wĕ⁠hála֖kĕ bĕ̇⁠saʻàr֥wòţ ţé̇ymáֽn׃"],[9,15,"יְהוָ֣ה צְבָאוֹת֮ יָגֵ֣ן עֲלֵי⁠הֶם֒ וְ⁠אָכְל֗וּ וְ⁠כָֽבְשׁוּ֙ אַבְנֵי־קֶ֔לַע וְ⁠שָׁת֥וּ הָמ֖וּ כְּמוֹ־יָ֑יִן וּ⁠מָֽלְאוּ֙ כַּ⁠מִּזְרָ֔ק כְּ⁠זָוִיּ֖וֹת מִזְבֵּֽחַ׃","yĕhwá֣h ẕĕbáʼwòţ֮ yágé֣n ʻàléy⁠hem֒ wĕ⁠ʼákĕl֗ẇ wĕ⁠káֽbĕş̌ẇ֙ ʼabĕnéy-qe֔laʻ wĕ⁠şá̌ţ֥ẇ hám֖ẇ kĕ̇mwò-yá֑yin ẇ⁠máֽlĕʼẇ֙ kȧ⁠mi̇zĕrá֔q kĕ̇⁠záwiẏ֖wòţ mizĕbéֽ̇ẖa׃"],[9,16,"וְֽ⁠הוֹשִׁיעָ֞⁠ם יְהוָ֧ה אֱלֹהֵי⁠הֶ֛ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כְּ⁠צֹ֣אן עַמּ֑⁠וֹ כִּ֚י אַבְנֵי־נֵ֔זֶר מִֽתְנוֹסְס֖וֹת עַל־אַדְמָתֽ⁠וֹ׃","wĕֽ⁠hwòşǐyʻá֞⁠m yĕhwá֧h ʼèlòhéy⁠he֛m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kĕ̇⁠ẕò֣ʼn ʻaṁ֑⁠wò ki֚̇y ʼabĕnéy-né֔zer miֽţĕnwòsĕs֖wòţ ʻal-ʼadĕmáţֽ⁠wò׃"],[9,17,"כִּ֥י מַה־טּוּב֖⁠וֹ וּ⁠מַה־יָפְי֑⁠וֹ דָּגָן֙ בַּֽחוּרִ֔ים וְ⁠תִיר֖וֹשׁ יְנוֹבֵ֥ב בְּתֻלֽוֹת׃","ki֥̇y mah-ṫẇb֖⁠wò ẇ⁠mah-yápĕy֑⁠wò dá̇gán֙ bȧֽẖẇri֔ym wĕ⁠ţiyr֖wòş̌ yĕnwòbé֥b bĕ̇ţulֽwòţ׃"],[10,1,"שַׁאֲל֨וּ מֵ⁠יְהוָ֤ה מָטָר֙ בְּ⁠עֵ֣ת מַלְק֔וֹשׁ יְהוָ֖ה עֹשֶׂ֣ה חֲזִיזִ֑ים וּ⁠מְטַר־גֶּ֨שֶׁם֙ יִתֵּ֣ן לָ⁠הֶ֔ם לְ⁠אִ֖ישׁ עֵ֥שֶׂב בַּ⁠שָּׂדֶֽה׃","şǎʼàl֨ẇ mé⁠yĕhwá֤h mátár֙ bĕ̇⁠ʻé֣ţ malĕq֔wòş̌ yĕhwá֖h ʻòşê֣h ẖàziyzi֑ym ẇ⁠mĕtar-gė֨şěm֙ yiţé֣̇n lá⁠he֔m lĕ⁠ʼi֖yş̌ ʻé֥şêb bȧ⁠şá̇̂deֽh׃"],[10,2,"כִּ֧י הַ⁠תְּרָפִ֣ים דִּבְּרוּ־אָ֗וֶן וְ⁠הַ⁠קּֽוֹסְמִים֙ חָ֣זוּ שֶׁ֔קֶר וַֽ⁠חֲלֹמוֹת֙ הַ⁠שָּׁ֣וא יְדַבֵּ֔רוּ הֶ֖בֶל יְנַֽחֵמ֑וּ⁠ן עַל־כֵּן֙ נָסְע֣וּ כְמוֹ־צֹ֔אן יַעֲנ֖וּ כִּֽי־אֵ֥ין רֹעֶֽה׃פ","ki֧̇y ha⁠ţĕ̇rápi֣ym di̇bĕ̇rẇ-ʼá֗wen wĕ⁠ha⁠qֽ̇wòsĕmiym֙ ẖá֣zẇ şě֔qer waֽ⁠ẖàlòmwòţ֙ ha⁠şá֣̇̌wʼ yĕdabé̇֔rẇ he֖bel yĕnaֽẖém֑ẇ⁠n ʻal-ké̇n֙ násĕʻ֣ẇ kĕmwò-ẕò֔ʼn yaʻàn֖ẇ kiֽ̇y-ʼé֥yn ròʻeֽh׃p"],[10,3,"עַל־הָֽ⁠רֹעִים֙ חָרָ֣ה אַפִּ֔⁠י וְ⁠עַל־הָ⁠עַתּוּדִ֖ים אֶפְק֑וֹד כִּֽי־פָקַד֩ יְהוָ֨ה צְבָא֤וֹת אֶת־עֶדְר⁠וֹ֙ אֶת־בֵּ֣ית יְהוּדָ֔ה וְ⁠שָׂ֣ם אוֹתָ֔⁠ם כְּ⁠ס֥וּס הוֹד֖⁠וֹ בַּ⁠מִּלְחָמָֽה׃","ʻal-háֽ⁠ròʻiym֙ ẖárá֣h ʼapi̇֔⁠y wĕ⁠ʻal-há⁠ʻaţ̇ẇdi֖ym ʼepĕq֑wòd kiֽ̇y-páqad֩ yĕhwá֨h ẕĕbáʼ֤wòţ ʼeţ-ʻedĕr⁠wò֙ ʼeţ-bé֣̇yţ yĕhẇdá֔h wĕ⁠şá֣̂m ʼwòţá֔⁠m kĕ̇⁠s֥ẇs hwòd֖⁠wò bȧ⁠mi̇lĕẖámáֽh׃"],[10,4,"מִמֶּ֤⁠נּוּ פִנָּה֙ מִמֶּ֣⁠נּוּ יָתֵ֔ד מִמֶּ֖⁠נּוּ קֶ֣שֶׁת מִלְחָמָ֑ה מִמֶּ֛⁠נּוּ יֵצֵ֥א כָל־נוֹגֵ֖שׂ יַחְדָּֽו׃","mimė֤⁠ṅẇ piná̇h֙ mimė֣⁠ṅẇ yáţé֔d mimė֖⁠ṅẇ qe֣şěţ milĕẖámá֑h mimė֛⁠ṅẇ yéẕé֥ʼ kál-nwògé֖ş̂ yaẖĕdáֽ̇w׃"],[10,5,"וְ⁠הָי֨וּ כְ⁠גִבֹּרִ֜ים בּוֹסִ֨ים בְּ⁠טִ֤יט חוּצוֹת֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠נִ֨לְחֲמ֔וּ כִּ֥י יְהוָ֖ה עִמָּ֑⁠ם וְ⁠הֹבִ֖ישׁוּ רֹכְבֵ֥י סוּסִֽים׃","wĕ⁠háy֨ẇ kĕ⁠gibò̇ri֜ym ḃwòsi֨ym bĕ̇⁠ti֤yt ẖẇẕwòţ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠ni֨lĕẖàm֔ẇ ki֥̇y yĕhwá֖h ʻimá֑̇⁠m wĕ⁠hòbi֖yş̌ẇ ròkĕbé֥y sẇsiֽym׃"],[10,6,"וְ⁠גִבַּרְתִּ֣י ׀ אֶת־בֵּ֣ית יְהוּדָ֗ה וְ⁠אֶת־בֵּ֤ית יוֹסֵף֙ אוֹשִׁ֔יעַ וְ⁠הֽוֹשְׁבוֹתִי⁠ם֙ כִּ֣י רִֽחַמְתִּ֔י⁠ם וְ⁠הָי֖וּ כַּ⁠אֲשֶׁ֣ר לֹֽא־זְנַחְתִּ֑י⁠ם כִּ֗י אֲנִ֛י יְהוָ֥ה אֱלֹהֵי⁠הֶ֖ם וְ⁠אֶעֱנֵֽ⁠ם׃","wĕ⁠gibȧrĕţi֣̇y ׀ ʼeţ-bé֣̇yţ yĕhẇdá֗h wĕ⁠ʼeţ-bé֤̇yţ ywòsép֙ ʼwòşǐ֔yʻa wĕ⁠hֽwòşĕ̌bwòţiy⁠m֙ ki֣̇y riֽẖamĕţi̇֔y⁠m wĕ⁠háy֖ẇ kȧ⁠ʼàşě֣r lòֽʼ-zĕnaẖĕţi֑̇y⁠m ki̇֗y ʼàni֛y yĕhwá֥h ʼèlòhéy⁠he֖m wĕ⁠ʼeʻènéֽ⁠m׃"],[10,7,"וְ⁠הָי֤וּ כְ⁠גִבּוֹר֙ אֶפְרַ֔יִם וְ⁠שָׂמַ֥ח לִבָּ֖⁠ם כְּמוֹ־יָ֑יִן וּ⁠בְנֵי⁠הֶם֙ יִרְא֣וּ וְ⁠שָׂמֵ֔חוּ יָגֵ֥ל לִבָּ֖⁠ם בַּ⁠יהוָֽה׃","wĕ⁠háy֤ẇ kĕ⁠giḃwòr֙ ʼepĕra֔yim wĕ⁠şá̂ma֥ẖ libá֖̇⁠m kĕ̇mwò-yá֑yin ẇ⁠bĕnéy⁠hem֙ yirĕʼ֣ẇ wĕ⁠şá̂mé֔ẖẇ yágé֥l libá֖̇⁠m bȧ⁠yhwáֽh׃"],[10,8,"אֶשְׁרְקָ֥ה לָ⁠הֶ֛ם וַ⁠אֲקַבְּצֵ֖⁠ם כִּ֣י פְדִיתִ֑י⁠ם וְ⁠רָב֖וּ כְּמ֥וֹ רָבֽוּ׃","ʼeşĕ̌rĕqá֥h lá⁠he֛m wa⁠ʼàqabĕ̇ẕé֖⁠m ki֣̇y pĕdiyţi֑y⁠m wĕ⁠ráb֖ẇ kĕ̇m֥wò rábֽẇ׃"],[10,9,"וְ⁠אֶזְרָעֵ⁠ם֙ בָּֽ⁠עַמִּ֔ים וּ⁠בַ⁠מֶּרְחַקִּ֖ים יִזְכְּר֑וּ⁠נִי וְ⁠חָי֥וּ אֶת־בְּנֵי⁠הֶ֖ם וָ⁠שָֽׁבוּ׃","wĕ⁠ʼezĕráʻé⁠m֙ báֽ̇⁠ʻami̇֔ym ẇ⁠ba⁠mėrĕẖaqi֖̇ym yizĕkĕ̇r֑ẇ⁠niy wĕ⁠ẖáy֥ẇ ʼeţ-bĕ̇néy⁠he֖m wá⁠şáֽ̌bẇ׃"],[10,10,"וַ⁠הֲשִֽׁיבוֹתִי⁠ם֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם וּ⁠מֵֽ⁠אַשּׁ֖וּר אֲקַבְּצֵ֑⁠ם וְ⁠אֶל־אֶ֨רֶץ גִּלְעָ֤ד וּ⁠לְבָנוֹן֙ אֲבִיאֵ֔⁠ם וְ⁠לֹ֥א יִמָּצֵ֖א לָ⁠הֶֽם׃","wa⁠hàşǐֽybwòţiy⁠m֙ mé⁠ʼe֣reẕ miẕĕra֔yim ẇ⁠méֽ⁠ʼaş֖̇̌ẇr ʼàqabĕ̇ẕé֑⁠m wĕ⁠ʼel-ʼe֨reẕ gi̇lĕʻá֤d ẇ⁠lĕbánwòn֙ ʼàbiyʼé֔⁠m wĕ⁠lò֥ʼ yimá̇ẕé֖ʼ lá⁠heֽm׃"],[10,11,"וְ⁠עָבַ֨ר בַּ⁠יָּ֜ם צָרָ֗ה וְ⁠הִכָּ֤ה בַ⁠יָּם֙ גַּלִּ֔ים וְ⁠הֹבִ֕ישׁוּ כֹּ֖ל מְצוּל֣וֹת יְאֹ֑ר וְ⁠הוּרַד֙ גְּא֣וֹן אַשּׁ֔וּר וְ⁠שֵׁ֥בֶט מִצְרַ֖יִם יָסֽוּר׃","wĕ⁠ʻába֨r bȧ⁠yá̇֜m ẕárá֗h wĕ⁠hiká֤̇h ba⁠yá̇m֙ gȧli̇֔ym wĕ⁠hòbi֕yş̌ẇ kò֖̇l mĕẕẇl֣wòţ yĕʼò֑r wĕ⁠hẇrad֙ gĕ̇ʼ֣wòn ʼaş̇̌֔ẇr wĕ⁠şé֥̌bet miẕĕra֖yim yásֽẇr׃"],[10,12,"וְ⁠גִבַּרְתִּי⁠ם֙ בַּֽ⁠יהוָ֔ה וּ⁠בִ⁠שְׁמ֖⁠וֹ יִתְהַלָּ֑כוּ נְאֻ֖ם יְהוָֽה׃ס","wĕ⁠gibȧrĕţi̇y⁠m֙ bȧֽ⁠yhwá֔h ẇ⁠bi⁠şĕ̌m֖⁠wò yiţĕhalá֑̇kẇ nĕʼu֖m yĕhwáֽh׃s"],[11,1,"פְּתַ֥ח לְבָנ֖וֹן דְּלָתֶ֑י⁠ךָ וְ⁠תֹאכַ֥ל אֵ֖שׁ בַּ⁠אֲרָזֶֽי⁠ךָ׃","pĕ̇ţa֥ẖ lĕbán֖wòn dĕ̇láţe֑y⁠ká wĕ⁠ţòʼka֥l ʼé֖ş̌ bȧ⁠ʼàrázeֽy⁠ká׃"],[11,2,"הֵילֵ֤ל בְּרוֹשׁ֙ כִּֽי־נָ֣פַל אֶ֔רֶז אֲשֶׁ֥ר אַדִּרִ֖ים שֻׁדָּ֑דוּ הֵילִ֨ילוּ֙ אַלּוֹנֵ֣י בָשָׁ֔ן כִּ֥י יָרַ֖ד יַ֥עַר ה⁠בצור׃","héylé֤l bĕ̇rwòş̌֙ kiֽ̇y-ná֣pal ʼe֔rez ʼàşě֥r ʼadi̇ri֖ym şǔdá֑̇dẇ héyli֨ylẇ֙ ʼal̇wòné֣y báşá̌֔n ki֥̇y yára֖d ya֥ʻar h⁠bẕwr׃"],[11,3,"ק֚וֹל יִֽלְלַ֣ת הָ⁠רֹעִ֔ים כִּ֥י שֻׁדְּדָ֖ה אַדַּרְתָּ֑⁠ם ק֚וֹל שַׁאֲגַ֣ת כְּפִירִ֔ים כִּ֥י שֻׁדַּ֖ד גְּא֥וֹן הַ⁠יַּרְדֵּֽן׃ס","q֚wòl yiֽlĕla֣ţ há⁠ròʻi֔ym ki֥̇y şǔdĕ̇dá֖h ʼadȧrĕţá֑̇⁠m q֚wòl şǎʼàga֣ţ kĕ̇piyri֔ym ki֥̇y şǔdȧ֖d gĕ̇ʼ֥wòn ha⁠yȧrĕdéֽ̇n׃s"],[11,4,"כֹּ֥ה אָמַ֖ר יְהוָ֣ה אֱלֹהָ֑⁠י רְעֵ֖ה אֶת־צֹ֥אן הַ⁠הֲרֵגָֽה׃","kò֥̇h ʼáma֖r yĕhwá֣h ʼèlòhá֑⁠y rĕʻé֖h ʼeţ-ẕò֥ʼn ha⁠hàrégáֽh׃"],[11,5,"אֲשֶׁ֨ר קֹנֵי⁠הֶ֤ן יַֽהֲרְגֻ⁠ן֙ וְ⁠לֹ֣א יֶאְשָׁ֔מוּ וּ⁠מֹכְרֵי⁠הֶ֣ן יֹאמַ֔ר בָּר֥וּךְ יְהוָ֖ה וַ⁠אעְשִׁ֑ר וְ⁠רֹ֣עֵי⁠הֶ֔ם לֹ֥א יַחְמ֖וֹל עֲלֵי⁠הֶֽן׃","ʼàşě֨r qònéy⁠he֤n yaֽhàrĕgu⁠n֙ wĕ⁠lò֣ʼ yeʼĕşá̌֔mẇ ẇ⁠mòkĕréy⁠he֣n yòʼma֔r bá̇r֥ẇkĕ yĕhwá֖h wa⁠ʼʻĕşǐ֑r wĕ⁠rò֣ʻéy⁠he֔m lò֥ʼ yaẖĕm֖wòl ʻàléy⁠heֽn׃"],[11,6,"כִּ֠י לֹ֣א אֶחְמ֥וֹל ע֛וֹד עַל־יֹשְׁבֵ֥י הָ⁠אָ֖רֶץ נְאֻם־יְהוָ֑ה וְ⁠הִנֵּ֨ה אָנֹכִ֜י מַמְצִ֣יא אֶת־הָ⁠אָדָ֗ם אִ֤ישׁ בְּ⁠יַד־רֵעֵ֨⁠הוּ֙ וּ⁠בְ⁠יַ֣ד מַלְכּ֔⁠וֹ וְ⁠כִתְּתוּ֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠לֹ֥א אַצִּ֖יל מִ⁠יָּדָֽ⁠ם׃","ki̇֠y lò֣ʼ ʼeẖĕm֥wòl ʻ֛wòd ʻal-yòşĕ̌bé֥y há⁠ʼá֖reẕ nĕʼum-yĕhwá֑h wĕ⁠hiné̇֨h ʼánòki֜y mamĕẕi֣yʼ ʼeţ-há⁠ʼádá֗m ʼi֤yş̌ bĕ̇⁠yad-réʻé֨⁠hẇ֙ ẇ⁠bĕ⁠ya֣d malĕk̇֔⁠wò wĕ⁠kiţĕ̇ţẇ֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠lò֥ʼ ʼaẕi֖̇yl mi⁠yá̇dáֽ⁠m׃"],[11,7,"וָֽ⁠אֶרְעֶה֙ אֶת־צֹ֣אן הַֽ⁠הֲרֵגָ֔ה לָ⁠כֵ֖ן עֲנִיֵּ֣י הַ⁠צֹּ֑אן וָ⁠אֶקַּֽח־לִ֞⁠י שְׁנֵ֣י מַקְל֗וֹת לְ⁠אַחַ֞ד קָרָ֤אתִי נֹ֨עַם֙ וּ⁠לְ⁠אַחַד֙ קָרָ֣אתִי חֹֽבְלִ֔ים וָ⁠אֶרְעֶ֖ה אֶת־הַ⁠צֹּֽאן׃","wáֽ⁠ʼerĕʻeh֙ ʼeţ-ẕò֣ʼn haֽ⁠hàrégá֔h lá⁠ké֖n ʻàniyé֣̇y ha⁠ẕò֑̇ʼn wá⁠ʼeqȧֽẖ-li֞⁠y şĕ̌né֣y maqĕl֗wòţ lĕ⁠ʼaẖa֞d qárá֤ʼţiy nò֨ʻam֙ ẇ⁠lĕ⁠ʼaẖad֙ qárá֣ʼţiy ẖòֽbĕli֔ym wá⁠ʼerĕʻe֖h ʼeţ-ha⁠ẕòֽ̇ʼn׃"],[11,8,"וָ⁠אַכְחִ֛ד אֶת־שְׁלֹ֥שֶׁת הָ⁠רֹעִ֖ים בְּ⁠יֶ֣רַח אֶחָ֑ד וַ⁠תִּקְצַ֤ר נַפְשִׁ⁠י֙ בָּ⁠הֶ֔ם וְ⁠גַם־נַפְשָׁ֖⁠ם בָּחֲלָ֥ה בִֽ⁠י׃","wá⁠ʼakĕẖi֛d ʼeţ-şĕ̌lò֥şěţ há⁠ròʻi֖ym bĕ̇⁠ye֣raẖ ʼeẖá֑d wa⁠ţi̇qĕẕa֤r napĕşǐ⁠y֙ bá̇⁠he֔m wĕ⁠gam-napĕşá֖̌⁠m bá̇ẖàlá֥h biֽ⁠y׃"],[11,9,"וָ⁠אֹמַ֕ר לֹ֥א אֶרְעֶ֖ה אֶתְ⁠כֶ֑ם הַ⁠מֵּתָ֣ה תָמ֗וּת וְ⁠הַ⁠נִּכְחֶ֨דֶת֙ תִּכָּחֵ֔ד וְ⁠הַ֨⁠נִּשְׁאָר֔וֹת תֹּאכַ֕לְנָה אִשָּׁ֖ה אֶת־בְּשַׂ֥ר רְעוּתָֽ⁠הּ׃","wá⁠ʼòma֕r lò֥ʼ ʼerĕʻe֖h ʼeţĕ⁠ke֑m ha⁠mé̇ţá֣h ţám֗ẇţ wĕ⁠ha⁠ni̇kĕẖe֨deţ֙ ţi̇ká̇ẖé֔d wĕ⁠ha֨⁠ni̇şĕ̌ʼár֔wòţ ţò̇ʼka֕lĕnáh ʼişá֖̇̌h ʼeţ-bĕ̇şâ֥r rĕʻẇţáֽ⁠ḣ׃"],[11,10,"וָ⁠אֶקַּ֤ח אֶת־מַקְלִ⁠י֙ אֶת־נֹ֔עַם וָ⁠אֶגְדַּ֖ע אֹת֑⁠וֹ לְ⁠הָפֵיר֙ אֶת־בְּרִיתִ֔⁠י אֲשֶׁ֥ר כָּרַ֖תִּי אֶת־כָּל־הָ⁠עַמִּֽים׃","wá⁠ʼeqȧ֤ẖ ʼeţ-maqĕli⁠y֙ ʼeţ-nò֔ʻam wá⁠ʼegĕdȧ֖ʻ ʼòţ֑⁠wò lĕ⁠hápéyr֙ ʼeţ-bĕ̇riyţi֔⁠y ʼàşě֥r ká̇ra֖ţi̇y ʼeţ-ká̇l-há⁠ʻamiֽ̇ym׃"],[11,11,"וַ⁠תֻּפַ֖ר בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וַ⁠יֵּדְע֨וּ כֵ֜ן עֲנִיֵּ֤י הַ⁠צֹּאן֙ הַ⁠שֹּׁמְרִ֣ים אֹתִ֔⁠י כִּ֥י דְבַר־יְהוָ֖ה הֽוּא׃","wa⁠ţu̇pa֖r bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wa⁠yé̇dĕʻ֨ẇ ké֜n ʻàniyé֤̇y ha⁠ẕò̇ʼn֙ ha⁠şò̇̌mĕri֣ym ʼòţi֔⁠y ki֥̇y dĕbar-yĕhwá֖h hֽẇʼ׃"],[11,12,"וָ⁠אֹמַ֣ר אֲלֵי⁠הֶ֗ם אִם־ט֧וֹב בְּ⁠עֵינֵי⁠כֶ֛ם הָב֥וּ שְׂכָרִ֖⁠י וְ⁠אִם־לֹ֣א ׀ חֲדָ֑לוּ וַ⁠יִּשְׁקְל֥וּ אֶת־שְׂכָרִ֖⁠י שְׁלֹשִׁ֥ים כָּֽסֶף׃","wá⁠ʼòma֣r ʼàléy⁠he֗m ʼim-t֧wòb bĕ̇⁠ʻéynéy⁠ke֛m háb֥ẇ şĕ̂kári֖⁠y wĕ⁠ʼim-lò֣ʼ ׀ ẖàdá֑lẇ wa⁠yi̇şĕ̌qĕl֥ẇ ʼeţ-şĕ̂kári֖⁠y şĕ̌lòşǐ֥ym káֽ̇sep׃"],[11,13,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י הַשְׁלִיכֵ֨⁠הוּ֙ אֶל־הַ⁠יּוֹצֵ֔ר אֶ֣דֶר הַ⁠יְקָ֔ר אֲשֶׁ֥ר יָקַ֖רְתִּי מֵֽ⁠עֲלֵי⁠הֶ֑ם וָֽ⁠אֶקְחָ⁠ה֙ שְׁלֹשִׁ֣ים הַ⁠כֶּ֔סֶף וָ⁠אַשְׁלִ֥יךְ אֹת֛⁠וֹ בֵּ֥ית יְהוָ֖ה אֶל־הַ⁠יּוֹצֵֽר׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y haşĕ̌liyké֨⁠hẇ֙ ʼel-ha⁠ẏwòẕé֔r ʼe֣der ha⁠yĕqá֔r ʼàşě֥r yáqa֖rĕţi̇y méֽ⁠ʻàléy⁠he֑m wáֽ⁠ʼeqĕẖá⁠h֙ şĕ̌lòşǐ֣ym ha⁠kė֔sep wá⁠ʼaşĕ̌li֥ykĕ ʼòţ֛⁠wò bé֥̇yţ yĕhwá֖h ʼel-ha⁠ẏwòẕéֽr׃"],[11,14,"וָֽ⁠אֶגְדַּע֙ אֶת־מַקְלִ֣⁠י הַ⁠שֵּׁנִ֔י אֵ֖ת הַ⁠חֹֽבְלִ֑ים לְ⁠הָפֵר֙ אֶת־הָֽ⁠אַחֲוָ֔ה בֵּ֥ין יְהוּדָ֖ה וּ⁠בֵ֥ין יִשְׂרָאֵֽל׃ס","wáֽ⁠ʼegĕdȧʻ֙ ʼeţ-maqĕli֣⁠y ha⁠şé̇̌ni֔y ʼé֖ţ ha⁠ẖòֽbĕli֑ym lĕ⁠hápér֙ ʼeţ-háֽ⁠ʼaẖàwá֔h bé֥̇yn yĕhẇdá֖h ẇ⁠bé֥yn yişĕ̂ráʼéֽl׃s"],[11,15,"וַ⁠יֹּ֥אמֶר יְהוָ֖ה אֵלָ֑⁠י ע֣וֹד קַח־לְ⁠ךָ֔ כְּלִ֖י רֹעֶ֥ה אֱוִלִֽי׃","wa⁠yò֥̇ʼmer yĕhwá֖h ʼélá֑⁠y ʻ֣wòd qaẖ-lĕ⁠ká֔ kĕ̇li֖y ròʻe֥h ʼèwiliֽy׃"],[11,16,"כִּ֣י הִנֵּֽה־אָנֹכִי֩ מֵקִ֨ים רֹעֶ֜ה בָּ⁠אָ֗רֶץ הַ⁠נִּכְחָד֤וֹת לֹֽא־יִפְקֹד֙ הַ⁠נַּ֣עַר לֹֽא־יְבַקֵּ֔שׁ וְ⁠הַ⁠נִּשְׁבֶּ֖רֶת לֹ֣א יְרַפֵּ֑א הַ⁠נִּצָּבָה֙ לֹ֣א יְכַלְכֵּ֔ל וּ⁠בְשַׂ֤ר הַ⁠בְּרִיאָה֙ יֹאכַ֔ל וּ⁠פַרְסֵי⁠הֶ֖ן יְפָרֵֽק׃ס","ki֣̇y hinéֽ̇h-ʼánòkiy֩ méqi֨ym ròʻe֜h bá̇⁠ʼá֗reẕ ha⁠ni̇kĕẖád֤wòţ lòֽʼ-yipĕqòd֙ ha⁠nȧ֣ʻar lòֽʼ-yĕbaqé̇֔ş̌ wĕ⁠ha⁠ni̇şĕ̌bė֖reţ lò֣ʼ yĕrapé֑̇ʼ ha⁠ni̇ẕá̇báh֙ lò֣ʼ yĕkalĕké̇֔l ẇ⁠bĕşâ֤r ha⁠bĕ̇riyʼáh֙ yòʼka֔l ẇ⁠parĕséy⁠he֖n yĕpáréֽq׃s"],[11,17,"ה֣וֹי רֹעִ֤י הָֽ⁠אֱלִיל֙ עֹזְבִ֣י הַ⁠צֹּ֔אן חֶ֥רֶב עַל־זְרוֹע֖⁠וֹ וְ⁠עַל־עֵ֣ין יְמִינ֑⁠וֹ זְרֹע⁠וֹ֙ יָב֣וֹשׁ תִּיבָ֔שׁ וְ⁠עֵ֥ין יְמִינ֖⁠וֹ כָּהֹ֥ה תִכְהֶֽה׃ס","h֣wòy ròʻi֤y háֽ⁠ʼèliyl֙ ʻòzĕbi֣y ha⁠ẕò̇֔ʼn ẖe֥reb ʻal-zĕrwòʻ֖⁠wò wĕ⁠ʻal-ʻé֣yn yĕmiyn֑⁠wò zĕròʻ⁠wò֙ yáb֣wòş̌ ţi̇ybá֔ş̌ wĕ⁠ʻé֥yn yĕmiyn֖⁠wò ká̇hò֥h ţikĕheֽh׃s"],[12,1,"מַשָּׂ֥א דְבַר־יְהוָ֖ה עַל־יִשְׂרָאֵ֑ל נְאֻם־יְהוָ֗ה נֹטֶ֤ה שָׁמַ֨יִם֙ וְ⁠יֹסֵ֣ד אָ֔רֶץ וְ⁠יֹצֵ֥ר רֽוּחַ־אָדָ֖ם בְּ⁠קִרְבּֽ⁠וֹ׃פ","maşá֥̇̂ʼ dĕbar-yĕhwá֖h ʻal-yişĕ̂ráʼé֑l nĕʼum-yĕhwá֗h nòte֤h şá̌ma֨yim֙ wĕ⁠yòsé֣d ʼá֔reẕ wĕ⁠yòẕé֥r rֽẇẖa-ʼádá֖m bĕ̇⁠qirĕḃֽ⁠wò׃p"],[12,2,"הִנֵּ֣ה אָ֠נֹכִי שָׂ֣ם אֶת־יְרוּשָׁלִַ֧ם סַף־רַ֛עַל לְ⁠כָל־הָ⁠עַמִּ֖ים סָבִ֑יב וְ⁠גַ֧ם עַל־יְהוּדָ֛ה יִֽהְיֶ֥ה בַ⁠מָּצ֖וֹר עַל־יְרוּשָׁלִָֽם׃","hiné֣̇h ʼá֠nòkiy şá֣̂m ʼeţ-yĕrẇşá̌lia֧m sap-ra֛ʻal lĕ⁠kál-há⁠ʻami֖̇ym sábi֑yb wĕ⁠ga֧m ʻal-yĕhẇdá֛h yiֽhĕye֥h ba⁠má̇ẕ֖wòr ʻal-yĕrẇşá̌liáֽm׃"],[12,3,"וְ⁠הָיָ֣ה בַ⁠יּוֹם־הַ֠⁠הוּא אָשִׂ֨ים אֶת־יְרוּשָׁלִַ֜ם אֶ֤בֶן מַֽעֲמָסָה֙ לְ⁠כָל־הָ֣⁠עַמִּ֔ים כָּל־עֹמְסֶ֖י⁠הָ שָׂר֣וֹט יִשָּׂרֵ֑טוּ וְ⁠נֶאֶסְפ֣וּ עָלֶ֔י⁠הָ כֹּ֖ל גּוֹיֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠háyá֣h ba⁠ẏwòm-ha֠⁠hẇʼ ʼáşî֨ym ʼeţ-yĕrẇşá̌lia֜m ʼe֤ben maֽʻàmásáh֙ lĕ⁠kál-há֣⁠ʻami̇֔ym ká̇l-ʻòmĕse֖y⁠há şá̂r֣wòt yişá̇̂ré֑tẇ wĕ⁠neʼesĕp֣ẇ ʻále֔y⁠há kò֖̇l ġwòyé֥y há⁠ʼáֽreẕ׃"],[12,4,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻם־יְהוָ֗ה אַכֶּ֤ה כָל־סוּס֙ בַּ⁠תִּמָּה֔וֹן וְ⁠רֹכְב֖⁠וֹ בַּ⁠שִּׁגָּע֑וֹן וְ⁠עַל־בֵּ֤ית יְהוּדָה֙ אֶפְקַ֣ח אֶת־עֵינַ֔⁠י וְ⁠כֹל֙ ס֣וּס הָֽ⁠עַמִּ֔ים אַכֶּ֖ה בַּֽ⁠עִוָּרֽוֹן׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼum-yĕhwá֗h ʼakė֤h kál-sẇs֙ bȧ⁠ţi̇má̇h֔wòn wĕ⁠ròkĕb֖⁠wò bȧ⁠şi̇̌gá̇ʻ֑wòn wĕ⁠ʻal-bé֤̇yţ yĕhẇdáh֙ ʼepĕqa֣ẖ ʼeţ-ʻéyna֔⁠y wĕ⁠kòl֙ s֣ẇs háֽ⁠ʻami̇֔ym ʼakė֖h bȧֽ⁠ʻiwá̇rֽwòn׃"],[12,5,"וְ⁠אָֽמְר֛וּ אַלֻּפֵ֥י יְהוּדָ֖ה בְּ⁠לִבָּ֑⁠ם אַמְצָ֥ה לִ⁠י֙ יֹשְׁבֵ֣י יְרוּשָׁלִַ֔ם בַּ⁠יהוָ֥ה צְבָא֖וֹת אֱלֹהֵי⁠הֶֽם׃","wĕ⁠ʼáֽmĕr֛ẇ ʼalu̇pé֥y yĕhẇdá֖h bĕ̇⁠libá֑̇⁠m ʼamĕẕá֥h li⁠y֙ yòşĕ̌bé֣y yĕrẇşá̌lia֔m bȧ⁠yhwá֥h ẕĕbáʼ֖wòţ ʼèlòhéy⁠heֽm׃"],[12,6,"בַּ⁠יּ֣וֹם הַ⁠ה֡וּא אָשִׂים֩ אֶת־אַלֻּפֵ֨י יְהוּדָ֜ה כְּֽ⁠כִיּ֧וֹר אֵ֣שׁ בְּ⁠עֵצִ֗ים וּ⁠כְ⁠לַפִּ֥יד אֵשׁ֙ בְּ⁠עָמִ֔יר וְ⁠אָ֨כְל֜וּ עַל־יָמִ֧ין וְ⁠עַל־שְׂמֹ֛אול אֶת־כָּל־הָ⁠עַמִּ֖ים סָבִ֑יב וְ⁠יָשְׁבָ֨ה יְרוּשָׁלִַ֥ם ע֛וֹד תַּחְתֶּ֖י⁠הָ בִּ⁠ירוּשָׁלִָֽם׃פ","bȧ⁠ẏ֣wòm ha⁠h֡ẇʼ ʼáşîym֩ ʼeţ-ʼalu̇pé֨y yĕhẇdá֜h kĕֽ̇⁠kiẏ֧wòr ʼé֣ş̌ bĕ̇⁠ʻéẕi֗ym ẇ⁠kĕ⁠lapi֥̇yd ʼéş̌֙ bĕ̇⁠ʻámi֔yr wĕ⁠ʼá֨kĕl֜ẇ ʻal-yámi֧yn wĕ⁠ʻal-şĕ̂mò֛ʼwl ʼeţ-ká̇l-há⁠ʻami֖̇ym sábi֑yb wĕ⁠yáşĕ̌bá֨h yĕrẇşá̌lia֥m ʻ֛wòd ţȧẖĕţė֖y⁠há bi̇⁠yrẇşá̌liáֽm׃p"],[12,7,"וְ⁠הוֹשִׁ֧יעַ יְהוָ֛ה אֶת־אָהֳלֵ֥י יְהוּדָ֖ה בָּ⁠רִֽאשֹׁנָ֑ה לְמַ֨עַן לֹֽא־תִגְדַּ֜ל תִּפְאֶ֣רֶת בֵּית־דָּוִ֗יד וְ⁠תִפְאֶ֛רֶת יֹשֵׁ֥ב יְרוּשָׁלִַ֖ם עַל־יְהוּדָֽה׃","wĕ⁠hwòşǐ֧yʻa yĕhwá֛h ʼeţ-ʼáholé֥y yĕhẇdá֖h bá̇⁠riֽʼşò̌ná֑h lĕma֨ʻan lòֽʼ-ţigĕdȧ֜l ţi̇pĕʼe֣reţ bé̇yţ-dá̇wi֗yd wĕ⁠ţipĕʼe֛reţ yòşé֥̌b yĕrẇşá̌lia֖m ʻal-yĕhẇdáֽh׃"],[12,8,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יָגֵ֤ן יְהוָה֙ בְּעַד֙ יוֹשֵׁ֣ב יְרוּשָׁלִַ֔ם וְ⁠הָיָ֞ה הַ⁠נִּכְשָׁ֥ל בָּ⁠הֶ֛ם בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כְּ⁠דָוִ֑יד וּ⁠בֵ֤ית דָּוִיד֙ כֵּֽ⁠אלֹהִ֔ים כְּ⁠מַלְאַ֥ךְ יְהוָ֖ה לִ⁠פְנֵי⁠הֶֽם׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yágé֤n yĕhwáh֙ bĕ̇ʻad֙ ywòşé֣̌b yĕrẇşá̌lia֔m wĕ⁠háyá֞h ha⁠ni̇kĕşá֥̌l bá̇⁠he֛m bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kĕ̇⁠dáwi֑yd ẇ⁠bé֤yţ dá̇wiyd֙ kéֽ̇⁠ʼlòhi֔ym kĕ̇⁠malĕʼa֥kĕ yĕhwá֖h li⁠pĕnéy⁠heֽm׃"],[12,9,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא אֲבַקֵּ֗שׁ לְ⁠הַשְׁמִיד֙ אֶת־כָּל־הַ⁠גּוֹיִ֔ם הַ⁠בָּאִ֖ים עַל־יְרוּשָׁלִָֽם׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ ʼàbaqé̇֗ş̌ lĕ⁠haşĕ̌miyd֙ ʼeţ-ká̇l-ha⁠ġwòyi֔m ha⁠bá̇ʼi֖ym ʻal-yĕrẇşá̌liáֽm׃"],[12,10,"וְ⁠שָׁפַכְתִּי֩ עַל־בֵּ֨ית דָּוִ֜יד וְ⁠עַ֣ל ׀ יוֹשֵׁ֣ב יְרוּשָׁלִַ֗ם ר֤וּחַ חֵן֙ וְ⁠תַ֣חֲנוּנִ֔ים וְ⁠הִבִּ֥יטוּ אֵלַ֖⁠י אֵ֣ת אֲשֶׁר־דָּקָ֑רוּ וְ⁠סָפְד֣וּ עָלָ֗י⁠ו כְּ⁠מִסְפֵּד֙ עַל־הַ⁠יָּחִ֔יד וְ⁠הָמֵ֥ר עָלָ֖י⁠ו כְּ⁠הָמֵ֥ר עַֽל־הַ⁠בְּכֽוֹר׃","wĕ⁠şá̌pakĕţi̇y֩ ʻal-bé̇֨yţ dá̇wi֜yd wĕ⁠ʻa֣l ׀ ywòşé֣̌b yĕrẇşá̌lia֗m r֤ẇẖa ẖén֙ wĕ⁠ţa֣ẖànẇni֔ym wĕ⁠hibi֥̇ytẇ ʼéla֖⁠y ʼé֣ţ ʼàşěr-dá̇qá֑rẇ wĕ⁠sápĕd֣ẇ ʻálá֗y⁠w kĕ̇⁠misĕpé̇d֙ ʻal-ha⁠yá̇ẖi֔yd wĕ⁠hámé֥r ʻálá֖y⁠w kĕ̇⁠hámé֥r ʻaֽl-ha⁠bĕ̇kֽwòr׃"],[12,11,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִגְדַּ֤ל הַ⁠מִּסְפֵּד֙ בִּ⁠יר֣וּשָׁלִַ֔ם כְּ⁠מִסְפַּ֥ד הֲדַדְ־רִמּ֖וֹן בְּ⁠בִקְעַ֥ת מְגִדּֽוֹן׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yigĕdȧ֤l ha⁠mi̇sĕpé̇d֙ bi̇⁠yr֣ẇşá̌lia֔m kĕ̇⁠misĕpȧ֥d hàdadĕ-riṁ֖wòn bĕ̇⁠biqĕʻa֥ţ mĕgiḋֽwòn׃"],[12,12,"וְ⁠סָפְדָ֣ה הָ⁠אָ֔רֶץ מִשְׁפָּח֥וֹת מִשְׁפָּח֖וֹת לְ⁠בָ֑ד מִשְׁפַּ֨חַת בֵּית־דָּוִ֤יד לְ⁠בָד֙ וּ⁠נְשֵׁי⁠הֶ֣ם לְ⁠בָ֔ד מִשְׁפַּ֤חַת בֵּית־נָתָן֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃","wĕ⁠sápĕdá֣h há⁠ʼá֔reẕ mişĕ̌pá̇ẖ֥wòţ mişĕ̌pá̇ẖ֖wòţ lĕ⁠bá֑d mişĕ̌pȧ֨ẖaţ bé̇yţ-dá̇wi֤yd lĕ⁠bád֙ ẇ⁠nĕşé̌y⁠he֣m lĕ⁠bá֔d mişĕ̌pȧ֤ẖaţ bé̇yţ-náţán֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃"],[12,13,"מִשְׁפַּ֤חַת בֵּית־לֵוִי֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָ֑ד מִשְׁפַּ֤חַת הַ⁠שִּׁמְעִי֙ לְ⁠בָ֔ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃","mişĕ̌pȧ֤ẖaţ bé̇yţ-léwiy֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠bá֑d mişĕ̌pȧ֤ẖaţ ha⁠şi̇̌mĕʻiy֙ lĕ⁠bá֔d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃"],[12,14,"כֹּ֗ל הַ⁠מִּשְׁפָּחוֹת֙ הַ⁠נִּשְׁאָר֔וֹת מִשְׁפָּחֹ֥ת מִשְׁפָּחֹ֖ת לְ⁠בָ֑ד וּ⁠נְשֵׁי⁠הֶ֖ם לְ⁠בָֽד׃ס","kò̇֗l ha⁠mi̇şĕ̌pá̇ẖwòţ֙ ha⁠ni̇şĕ̌ʼár֔wòţ mişĕ̌pá̇ẖò֥ţ mişĕ̌pá̇ẖò֖ţ lĕ⁠bá֑d ẇ⁠nĕşé̌y⁠he֖m lĕ⁠báֽd׃s"],[13,1,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ מָק֣וֹר נִפְתָּ֔ח לְ⁠בֵ֥ית דָּוִ֖יד וּ⁠לְ⁠יֹשְׁבֵ֣י יְרֽוּשָׁלִָ֑ם לְ⁠חַטַּ֖את וּ⁠לְ⁠נִדָּֽה׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ máq֣wòr nipĕţá̇֔ẖ lĕ⁠bé֥yţ dá̇wi֖yd ẇ⁠lĕ⁠yòşĕ̌bé֣y yĕrֽẇşá̌liá֑m lĕ⁠ẖatȧ֖ʼţ ẇ⁠lĕ⁠nidáֽ̇h׃"],[13,2,"וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻ֣ם ׀ יְהוָ֣ה צְבָא֗וֹת אַכְרִ֞ית אֶת־שְׁמ֤וֹת הָֽ⁠עֲצַבִּים֙ מִן־הָ⁠אָ֔רֶץ וְ⁠לֹ֥א יִזָּכְר֖וּ ע֑וֹד וְ⁠גַ֧ם אֶת־הַ⁠נְּבִיאִ֛ים וְ⁠אֶת־ר֥וּחַ הַ⁠טֻּמְאָ֖ה אַעֲבִ֥יר מִן־הָ⁠אָֽרֶץ׃","wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼu֣m ׀ yĕhwá֣h ẕĕbáʼ֗wòţ ʼakĕri֞yţ ʼeţ-şĕ̌m֤wòţ háֽ⁠ʻàẕabi̇ym֙ min-há⁠ʼá֔reẕ wĕ⁠lò֥ʼ yizá̇kĕr֖ẇ ʻ֑wòd wĕ⁠ga֧m ʼeţ-ha⁠nĕ̇biyʼi֛ym wĕ⁠ʼeţ-r֥ẇẖa ha⁠tu̇mĕʼá֖h ʼaʻàbi֥yr min-há⁠ʼáֽreẕ׃"],[13,3,"וְ⁠הָיָ֗ה כִּֽי־יִנָּבֵ֣א אִישׁ֮ עוֹד֒ וְ⁠אָמְר֣וּ אֵ֠לָי⁠ו אָבִ֨י⁠ו וְ⁠אִמּ֤⁠וֹ יֹֽלְדָי⁠ו֙ לֹ֣א תִֽחְיֶ֔ה כִּ֛י שֶׁ֥קֶר דִּבַּ֖רְתָּ בְּ⁠שֵׁ֣ם יְהוָ֑ה וּ⁠דְקָרֻ֜⁠הוּ אָבִ֧י⁠הוּ וְ⁠אִמּ֛⁠וֹ יֹלְדָ֖י⁠ו בְּ⁠הִנָּבְאֽ⁠וֹ׃","wĕ⁠háyá֗h kiֽ̇y-yiná̇bé֣ʼ ʼiyş֮̌ ʻwòd֒ wĕ⁠ʼámĕr֣ẇ ʼé֠láy⁠w ʼábi֨y⁠w wĕ⁠ʼiṁ֤⁠wò yòֽlĕdáy⁠w֙ lò֣ʼ ţiֽẖĕye֔h ki֛̇y şě֥qer di̇bȧ֖rĕţá̇ bĕ̇⁠şé֣̌m yĕhwá֑h ẇ⁠dĕqáru֜⁠hẇ ʼábi֧y⁠hẇ wĕ⁠ʼiṁ֛⁠wò yòlĕdá֖y⁠w bĕ̇⁠hiná̇bĕʼֽ⁠wò׃"],[13,4,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יֵבֹ֧שׁוּ הַ⁠נְּבִיאִ֛ים אִ֥ישׁ מֵ⁠חֶזְיֹנ֖⁠וֹ בְּ⁠הִנָּֽבְאֹת֑⁠וֹ וְ⁠לֹ֧א יִלְבְּשׁ֛וּ אַדֶּ֥רֶת שֵׂעָ֖ר לְמַ֥עַן כַּחֵֽשׁ׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yébò֧ş̌ẇ ha⁠nĕ̇biyʼi֛ym ʼi֥yş̌ mé⁠ẖezĕyòn֖⁠wò bĕ̇⁠hináֽ̇bĕʼòţ֑⁠wò wĕ⁠lò֧ʼ yilĕbĕ̇ş֛̌ẇ ʼadė֥reţ şé̂ʻá֖r lĕma֥ʻan kȧẖéֽş̌׃"],[13,5,"וְ⁠אָמַ֕ר לֹ֥א נָבִ֖יא אָנֹ֑כִי אִישׁ־עֹבֵ֤ד אֲדָמָה֙ אָנֹ֔כִי כִּ֥י אָדָ֖ם הִקְנַ֥⁠נִי מִ⁠נְּעוּרָֽ⁠י׃","wĕ⁠ʼáma֕r lò֥ʼ nábi֖yʼ ʼánò֑kiy ʼiyş̌-ʻòbé֤d ʼàdámáh֙ ʼánò֔kiy ki֥̇y ʼádá֖m hiqĕna֥⁠niy mi⁠nĕ̇ʻẇráֽ⁠y׃"],[13,6,"וְ⁠אָמַ֣ר אֵלָ֔י⁠ו מָ֧ה הַ⁠מַּכּ֛וֹת הָ⁠אֵ֖לֶּה בֵּ֣ין יָדֶ֑י⁠ךָ וְ⁠אָמַ֕ר אֲשֶׁ֥ר הֻכֵּ֖יתִי בֵּ֥ית מְאַהֲבָֽ⁠י׃ס","wĕ⁠ʼáma֣r ʼélá֔y⁠w má֧h ha⁠mȧk֛̇wòţ há⁠ʼé֖lėh bé֣̇yn yáde֑y⁠ká wĕ⁠ʼáma֕r ʼàşě֥r huké֖̇yţiy bé֥̇yţ mĕʼahàbáֽ⁠y׃s"],[13,7,"חֶ֗רֶב עוּרִ֤י עַל־רֹעִ⁠י֙ וְ⁠עַל־גֶּ֣בֶר עֲמִיתִ֔⁠י נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת הַ֤ךְ אֶת־הָֽ⁠רֹעֶה֙ וּ⁠תְפוּצֶ֣יןָ הַ⁠צֹּ֔אן וַ⁠הֲשִׁבֹתִ֥י יָדִ֖⁠י עַל־הַ⁠צֹּעֲרִֽים׃","ẖe֗reb ʻẇri֤y ʻal-ròʻi⁠y֙ wĕ⁠ʻal-gė֣ber ʻàmiyţi֔⁠y nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ ha֤kĕ ʼeţ-háֽ⁠ròʻeh֙ ẇ⁠ţĕpẇẕe֣yná ha⁠ẕò̇֔ʼn wa⁠hàşǐbòţi֥y yádi֖⁠y ʻal-ha⁠ẕò̇ʻàriֽym׃"],[13,8,"וְ⁠הָיָ֤ה בְ⁠כָל־הָ⁠אָ֨רֶץ֙ נְאֻם־יְהוָ֔ה פִּֽי־שְׁנַ֣יִם בָּ֔⁠הּ יִכָּרְת֖וּ יִגְוָ֑עוּ וְ⁠הַ⁠שְּׁלִשִׁ֖ית יִוָּ֥תֶר בָּֽ⁠הּ׃","wĕ⁠háyá֤h bĕ⁠kál-há⁠ʼá֨reẕ֙ nĕʼum-yĕhwá֔h piֽ̇y-şĕ̌na֣yim bá̇֔⁠ḣ yiká̇rĕţ֖ẇ yigĕwá֑ʻẇ wĕ⁠ha⁠şĕ̇̌lişǐ֖yţ yiwá֥̇ţer báֽ̇⁠ḣ׃"],[13,9,"וְ⁠הֵבֵאתִ֤י אֶת־הַ⁠שְּׁלִשִׁית֙ בָּ⁠אֵ֔שׁ וּ⁠צְרַפְתִּי⁠ם֙ כִּ⁠צְרֹ֣ף אֶת־הַ⁠כֶּ֔סֶף וּ⁠בְחַנְתִּ֖י⁠ם כִּ⁠בְחֹ֣ן אֶת־הַ⁠זָּהָ֑ב ה֣וּא ׀ יִקְרָ֣א בִ⁠שְׁמִ֗⁠י וַֽ⁠אֲנִי֙ אֶעֱנֶ֣ה אֹת֔⁠וֹ אָמַ֨רְתִּי֙ עַמִּ֣⁠י ה֔וּא וְ⁠ה֥וּא יֹאמַ֖ר יְהוָ֥ה אֱלֹהָֽ⁠י׃ס","wĕ⁠hébéʼţi֤y ʼeţ-ha⁠şĕ̇̌lişǐyţ֙ bá̇⁠ʼé֔ş̌ ẇ⁠ẕĕrapĕţi̇y⁠m֙ ki̇⁠ẕĕrò֣p ʼeţ-ha⁠kė֔sep ẇ⁠bĕẖanĕţi֖̇y⁠m ki̇⁠bĕẖò֣n ʼeţ-ha⁠zá̇há֑b h֣ẇʼ ׀ yiqĕrá֣ʼ bi⁠şĕ̌mi֗⁠y waֽ⁠ʼàniy֙ ʼeʻène֣h ʼòţ֔⁠wò ʼáma֨rĕţi̇y֙ ʻami֣̇⁠y h֔ẇʼ wĕ⁠h֥ẇʼ yòʼma֖r yĕhwá֥h ʼèlòháֽ⁠y׃s"],[14,1,"הִנֵּ֥ה יֽוֹם־בָּ֖א לַֽ⁠יהוָ֑ה וְ⁠חֻלַּ֥ק שְׁלָלֵ֖⁠ךְ בְּ⁠קִרְבֵּֽ⁠ךְ׃","hiné֥̇h yֽwòm-bá֖̇ʼ laֽ⁠yhwá֑h wĕ⁠ẖulȧ֥q şĕ̌lálé֖⁠kĕ bĕ̇⁠qirĕbéֽ̇⁠kĕ׃"],[14,2,"וְ⁠אָסַפְתִּ֨י אֶת־כָּל־הַ⁠גּוֹיִ֥ם ׀ אֶֽל־יְרוּשָׁלִַם֮ לַ⁠מִּלְחָמָה֒ וְ⁠נִלְכְּדָ֣ה הָ⁠עִ֗יר וְ⁠נָשַׁ֨סּוּ֙ הַ⁠בָּ֣תִּ֔ים וְ⁠הַ⁠נָּשִׁ֖ים תשגלנה וְ⁠יָצָ֞א חֲצִ֤י הָ⁠עִיר֙ בַּ⁠גּוֹלָ֔ה וְ⁠יֶ֣תֶר הָ⁠עָ֔ם לֹ֥א יִכָּרֵ֖ת מִן־הָ⁠עִֽיר׃","wĕ⁠ʼásapĕţi̇֨y ʼeţ-ká̇l-ha⁠ġwòyi֥m ׀ ʼeֽl-yĕrẇşá̌liam֮ la⁠mi̇lĕẖámáh֒ wĕ⁠nilĕkĕ̇dá֣h há⁠ʻi֗yr wĕ⁠náşǎ֨ṡẇ֙ ha⁠bá֣̇ţi̇֔ym wĕ⁠ha⁠ná̇şǐ֖ym ţşglnh wĕ⁠yáẕá֞ʼ ẖàẕi֤y há⁠ʻiyr֙ bȧ⁠ġwòlá֔h wĕ⁠ye֣ţer há⁠ʻá֔m lò֥ʼ yiká̇ré֖ţ min-há⁠ʻiֽyr׃"],[14,3,"וְ⁠יָצָ֣א יְהוָ֔ה וְ⁠נִלְחַ֖ם בַּ⁠גּוֹיִ֣ם הָ⁠הֵ֑ם כְּ⁠י֥וֹם הִֽלָּחֲמ֖⁠ו בְּ⁠י֥וֹם קְרָֽב׃","wĕ⁠yáẕá֣ʼ yĕhwá֔h wĕ⁠nilĕẖa֖m bȧ⁠ġwòyi֣m há⁠hé֑m kĕ̇⁠y֥wòm hiֽlá̇ẖàm֖⁠w bĕ̇⁠y֥wòm qĕráֽb׃"],[14,4,"וְ⁠עָמְד֣וּ רַגְלָ֣י⁠ו בַּ⁠יּוֹם־הַ֠⁠הוּא עַל־הַ֨ר הַ⁠זֵּתִ֜ים אֲשֶׁ֨ר עַל־פְּנֵ֥י יְרוּשָׁלִַם֮ מִ⁠קֶּדֶם֒ וְ⁠נִבְקַע֩ הַ֨ר הַ⁠זֵּיתִ֤ים מֵֽ⁠חֶצְי⁠וֹ֙ מִזְרָ֣חָ⁠ה וָ⁠יָ֔מָּ⁠ה גֵּ֖יא גְּדוֹלָ֣ה מְאֹ֑ד וּ⁠מָ֨שׁ חֲצִ֥י הָ⁠הָ֛ר צָפ֖וֹנָ⁠ה וְ⁠חֶצְי⁠וֹ־נֶֽגְבָּ⁠ה׃","wĕ⁠ʻámĕd֣ẇ ragĕlá֣y⁠w bȧ⁠ẏwòm-ha֠⁠hẇʼ ʻal-ha֨r ha⁠zé̇ţi֜ym ʼàşě֨r ʻal-pĕ̇né֥y yĕrẇşá̌liam֮ mi⁠qėdem֒ wĕ⁠nibĕqaʻ֩ ha֨r ha⁠zé̇yţi֤ym méֽ⁠ẖeẕĕy⁠wò֙ mizĕrá֣ẖá⁠h wá⁠yá֔má̇⁠h gé֖̇yʼ gĕ̇dwòlá֣h mĕʼò֑d ẇ⁠má֨ş̌ ẖàẕi֥y há⁠há֛r ẕáp֖wòná⁠h wĕ⁠ẖeẕĕy⁠wò-neֽgĕbá̇⁠h׃"],[14,5,"וְ⁠נַסְתֶּ֣ם גֵּֽיא־הָרַ֗⁠י כִּֽי־יַגִּ֣יעַ גֵּי־הָרִים֮ אֶל־אָצַל֒ וְ⁠נַסְתֶּ֗ם כַּ⁠אֲשֶׁ֤ר נַסְתֶּם֙ מִ⁠פְּנֵ֣י הָ⁠רַ֔עַשׁ בִּ⁠ימֵ֖י עֻזִּיָּ֣ה מֶֽלֶךְ־יְהוּדָ֑ה וּ⁠בָא֙ יְהוָ֣ה אֱלֹהַ֔⁠י כָּל־קְדֹשִׁ֖ים עִמָּֽ⁠ךְ׃","wĕ⁠nasĕţė֣m géֽ̇yʼ-hára֗⁠y kiֽ̇y-yagi֣̇yʻa gé̇y-háriym֮ ʼel-ʼáẕal֒ wĕ⁠nasĕţė֗m kȧ⁠ʼàşě֤r nasĕţėm֙ mi⁠pĕ̇né֣y há⁠ra֔ʻaş̌ bi̇⁠ymé֖y ʻuzi̇yá֣̇h meֽlekĕ-yĕhẇdá֑h ẇ⁠báʼ֙ yĕhwá֣h ʼèlòha֔⁠y ká̇l-qĕdòşǐ֖ym ʻimáֽ̇⁠kĕ׃"],[14,6,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא לֹֽא־יִהְיֶ֣ה א֔וֹר יְקָר֖וֹת יקפאו⁠ן׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ lòֽʼ-yihĕye֣h ʼ֔wòr yĕqár֖wòţ yqpʼw⁠n׃"],[14,7,"וְ⁠הָיָ֣ה יוֹם־אֶחָ֗ד ה֛וּא יִוָּדַ֥ע לַֽ⁠יהוָ֖ה לֹא־י֣וֹם וְ⁠לֹא־לָ֑יְלָה וְ⁠הָיָ֥ה לְ⁠עֵֽת־עֶ֖רֶב יִֽהְיֶה־אֽוֹר׃","wĕ⁠háyá֣h ywòm-ʼeẖá֗d h֛ẇʼ yiwá̇da֥ʻ laֽ⁠yhwá֖h lòʼ-y֣wòm wĕ⁠lòʼ-lá֑yĕláh wĕ⁠háyá֥h lĕ⁠ʻéֽţ-ʻe֖reb yiֽhĕyeh-ʼֽwòr׃"],[14,8,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יֵצְא֤וּ מַֽיִם־חַיִּים֙ מִ⁠יר֣וּשָׁלִַ֔ם חֶצְיָ֗⁠ם אֶל־הַ⁠יָּם֙ הַ⁠קַּדְמוֹנִ֔י וְ⁠חֶצְיָ֖⁠ם אֶל־הַ⁠יָּ֣ם הָ⁠אַחֲר֑וֹן בַּ⁠קַּ֥יִץ וּ⁠בָ⁠חֹ֖רֶף יִֽהְיֶֽה׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yéẕĕʼ֤ẇ maֽyim-ẖayi̇ym֙ mi⁠yr֣ẇşá̌lia֔m ẖeẕĕyá֗⁠m ʼel-ha⁠yá̇m֙ ha⁠qȧdĕmwòni֔y wĕ⁠ẖeẕĕyá֖⁠m ʼel-ha⁠yá֣̇m há⁠ʼaẖàr֑wòn bȧ⁠qȧ֥yiẕ ẇ⁠bá⁠ẖò֖rep yiֽhĕyeֽh׃"],[14,9,"וְ⁠הָיָ֧ה יְהוָ֛ה לְ⁠מֶ֖לֶךְ עַל־כָּל־הָ⁠אָ֑רֶץ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִהְיֶ֧ה יְהוָ֛ה אֶחָ֖ד וּ⁠שְׁמ֥⁠וֹ אֶחָֽד׃","wĕ⁠háyá֧h yĕhwá֛h lĕ⁠me֖lekĕ ʻal-ká̇l-há⁠ʼá֑reẕ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yihĕye֧h yĕhwá֛h ʼeẖá֖d ẇ⁠şĕ̌m֥⁠wò ʼeẖáֽd׃"],[14,10,"יִסּ֨וֹב כָּל־הָ⁠אָ֤רֶץ כָּ⁠עֲרָבָה֙ מִ⁠גֶּ֣בַע לְ⁠רִמּ֔וֹן נֶ֖גֶב יְרֽוּשָׁלִָ֑ם וְֽ⁠רָאֲמָה֩ וְ⁠יָשְׁבָ֨ה תַחְתֶּ֜י⁠הָ לְ⁠מִ⁠שַּׁ֣עַר בִּנְיָמִ֗ן עַד־מְק֞וֹם שַׁ֤עַר הָֽ⁠רִאשׁוֹן֙ עַד־שַׁ֣עַר הַ⁠פִּנִּ֔ים וּ⁠מִגְדַּ֣ל חֲנַנְאֵ֔ל עַ֖ד יִקְבֵ֥י הַ⁠מֶּֽלֶךְ׃","yiṡ֨wòb ká̇l-há⁠ʼá֤reẕ ká̇⁠ʻàrábáh֙ mi⁠gė֣baʻ lĕ⁠riṁ֔wòn ne֖geb yĕrֽẇşá̌liá֑m wĕֽ⁠ráʼàmáh֩ wĕ⁠yáşĕ̌bá֨h ţaẖĕţė֜y⁠há lĕ⁠mi⁠şȧ֣̌ʻar bi̇nĕyámi֗n ʻad-mĕq֞wòm şǎ֤ʻar háֽ⁠riʼş̌wòn֙ ʻad-şǎ֣ʻar ha⁠pi̇ni̇֔ym ẇ⁠migĕdȧ֣l ẖànanĕʼé֔l ʻa֖d yiqĕbé֥y ha⁠mėֽlekĕ׃"],[14,11,"וְ⁠יָ֣שְׁבוּ בָ֔⁠הּ וְ⁠חֵ֖רֶם לֹ֣א יִֽהְיֶה־ע֑וֹד וְ⁠יָשְׁבָ֥ה יְרוּשָׁלִַ֖ם לָ⁠בֶֽטַח׃","wĕ⁠yá֣şĕ̌bẇ bá֔⁠ḣ wĕ⁠ẖé֖rem lò֣ʼ yiֽhĕyeh-ʻ֑wòd wĕ⁠yáşĕ̌bá֥h yĕrẇşá̌lia֖m lá⁠beֽtaẖ׃"],[14,12,"וְ⁠זֹ֣את ׀ תִּֽהְיֶ֣ה הַ⁠מַּגֵּפָ֗ה אֲשֶׁ֨ר יִגֹּ֤ף יְהוָה֙ אֶת־כָּל־הָ֣⁠עַמִּ֔ים אֲשֶׁ֥ר צָבְא֖וּ עַל־יְרוּשָׁלִָ֑ם הָמֵ֣ק ׀ בְּשָׂר֗⁠וֹ וְ⁠הוּא֙ עֹמֵ֣ד עַל־רַגְלָ֔י⁠ו וְ⁠עֵינָי⁠ו֙ תִּמַּ֣קְנָה בְ⁠חֹֽרֵי⁠הֶ֔ן וּ⁠לְשׁוֹנ֖⁠וֹ תִּמַּ֥ק בְּ⁠פִי⁠הֶֽם׃","wĕ⁠zò֣ʼţ ׀ ţiֽ̇hĕye֣h ha⁠mȧgé̇pá֗h ʼàşě֨r yigò֤̇p yĕhwáh֙ ʼeţ-ká̇l-há֣⁠ʻami̇֔ym ʼàşě֥r ẕábĕʼ֖ẇ ʻal-yĕrẇşá̌liá֑m hámé֣q ׀ bĕ̇şá̂r֗⁠wò wĕ⁠hẇʼ֙ ʻòmé֣d ʻal-ragĕlá֔y⁠w wĕ⁠ʻéynáy⁠w֙ ţi̇mȧ֣qĕnáh bĕ⁠ẖòֽréy⁠he֔n ẇ⁠lĕş̌wòn֖⁠wò ţi̇mȧ֥q bĕ̇⁠piy⁠heֽm׃"],[14,13,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא תִּֽהְיֶ֧ה מְהֽוּמַת־יְהוָ֛ה רַבָּ֖ה בָּ⁠הֶ֑ם וְ⁠הֶחֱזִ֗יקוּ אִ֚ישׁ יַ֣ד רֵעֵ֔⁠הוּ וְ⁠עָלְתָ֥ה יָד֖⁠וֹ עַל־יַ֥ד רֵעֵֽ⁠הוּ׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ţiֽ̇hĕye֧h mĕhֽẇmaţ-yĕhwá֛h rabá֖̇h bá̇⁠he֑m wĕ⁠heẖèzi֗yqẇ ʼi֚yş̌ ya֣d réʻé֔⁠hẇ wĕ⁠ʻálĕţá֥h yád֖⁠wò ʻal-ya֥d réʻéֽ⁠hẇ׃"],[14,14,"וְ⁠גַ֨ם־יְהוּדָ֔ה תִּלָּחֵ֖ם בִּ⁠ירֽוּשָׁלִָ֑ם וְ⁠אֻסַּף֩ חֵ֨יל כָּל־הַ⁠גּוֹיִ֜ם סָבִ֗יב זָהָ֥ב וָ⁠כֶ֛סֶף וּ⁠בְגָדִ֖ים לָ⁠רֹ֥ב מְאֹֽד׃","wĕ⁠ga֨m-yĕhẇdá֔h ţi̇lá̇ẖé֖m bi̇⁠yrֽẇşá̌liá֑m wĕ⁠ʼusȧp֩ ẖé֨yl ká̇l-ha⁠ġwòyi֜m sábi֗yb záhá֥b wá⁠ke֛sep ẇ⁠bĕgádi֖ym lá⁠rò֥b mĕʼòֽd׃"],[14,15,"וְ⁠כֵ֨ן תִּֽהְיֶ֜ה מַגֵּפַ֣ת הַ⁠סּ֗וּס הַ⁠פֶּ֨רֶד֙ הַ⁠גָּמָ֣ל וְ⁠הַ⁠חֲמ֔וֹר וְ⁠כָ֨ל־הַ⁠בְּהֵמָ֔ה אֲשֶׁ֥ר יִהְיֶ֖ה בַּ⁠מַּחֲנ֣וֹת הָ⁠הֵ֑מָּה כַּ⁠מַּגֵּפָ֖ה הַ⁠זֹּֽאת׃","wĕ⁠ké֨n ţiֽ̇hĕye֜h magé̇pa֣ţ ha⁠ṡ֗ẇs ha⁠pė֨red֙ ha⁠gá̇má֣l wĕ⁠ha⁠ẖàm֔wòr wĕ⁠ká֨l-ha⁠bĕ̇hémá֔h ʼàşě֥r yihĕye֖h bȧ⁠mȧẖàn֣wòţ há⁠hé֑má̇h kȧ⁠mȧgé̇pá֖h ha⁠zòֽ̇ʼţ׃"],[14,16,"וְ⁠הָיָ֗ה כָּל־הַ⁠נּוֹתָר֙ מִ⁠כָּל־הַ⁠גּוֹיִ֔ם הַ⁠בָּאִ֖ים עַל־יְרֽוּשָׁלִָ֑ם וְ⁠עָל֞וּ מִ⁠דֵּ֧י שָׁנָ֣ה בְ⁠שָׁנָ֗ה לְ⁠הִֽשְׁתַּחֲוֺת֙ לְ⁠מֶ֨לֶךְ֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","wĕ⁠háyá֗h ká̇l-ha⁠ṅwòţár֙ mi⁠ká̇l-ha⁠ġwòyi֔m ha⁠bá̇ʼi֖ym ʻal-yĕrֽẇşá̌liá֑m wĕ⁠ʻál֞ẇ mi⁠dé֧̇y şá̌ná֣h bĕ⁠şá̌ná֗h lĕ⁠hiֽşĕ̌ţȧẖàwֺţ֙ lĕ⁠me֨lekĕ֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,17,"וְ֠⁠הָיָה אֲשֶׁ֨ר לֹֽא־יַעֲלֶ֜ה מֵ⁠אֵ֨ת מִשְׁפְּח֤וֹת הָ⁠אָ֨רֶץ֙ אֶל־יְר֣וּשָׁלִַ֔ם לְ⁠הִֽשְׁתַּחֲוֺ֔ת לְ⁠מֶ֖לֶךְ יְהוָ֣ה צְבָא֑וֹת וְ⁠לֹ֥א עֲלֵי⁠הֶ֖ם יִהְיֶ֥ה הַ⁠גָּֽשֶׁם׃","wĕ֠⁠háyáh ʼàşě֨r lòֽʼ-yaʻàle֜h mé⁠ʼé֨ţ mişĕ̌pĕ̇ẖ֤wòţ há⁠ʼá֨reẕ֙ ʼel-yĕr֣ẇşá̌lia֔m lĕ⁠hiֽşĕ̌ţȧẖàwֺ֔ţ lĕ⁠me֖lekĕ yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠lò֥ʼ ʻàléy⁠he֖m yihĕye֥h ha⁠gáֽ̇şěm׃"],[14,18,"וְ⁠אִם־מִשְׁפַּ֨חַת מִצְרַ֧יִם לֹֽא־תַעֲלֶ֛ה וְ⁠לֹ֥א בָאָ֖ה וְ⁠לֹ֣א עֲלֵי⁠הֶ֑ם תִּֽהְיֶ֣ה הַ⁠מַּגֵּפָ֗ה אֲשֶׁ֨ר יִגֹּ֤ף יְהוָה֙ אֶת־הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ לֹ֣א יַֽעֲל֔וּ לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","wĕ⁠ʼim-mişĕ̌pȧ֨ẖaţ miẕĕra֧yim lòֽʼ-ţaʻàle֛h wĕ⁠lò֥ʼ báʼá֖h wĕ⁠lò֣ʼ ʻàléy⁠he֑m ţiֽ̇hĕye֣h ha⁠mȧgé̇pá֗h ʼàşě֨r yigò֤̇p yĕhwáh֙ ʼeţ-ha⁠ġwòyi֔m ʼàşěr֙ lò֣ʼ yaֽʻàl֔ẇ lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,19,"זֹ֥את תִּהְיֶ֖ה חַטַּ֣את מִצְרָ֑יִם וְ⁠חַטַּאת֙ כָּל־הַ⁠גּוֹיִ֔ם אֲשֶׁר֙ לֹ֣א יַֽעֲל֔וּ לָ⁠חֹ֖ג אֶת־חַ֥ג הַ⁠סֻּכּֽוֹת׃","zò֥ʼţ ţi̇hĕye֖h ẖatȧ֣ʼţ miẕĕrá֑yim wĕ⁠ẖatȧʼţ֙ ká̇l-ha⁠ġwòyi֔m ʼàşěr֙ lò֣ʼ yaֽʻàl֔ẇ lá⁠ẖò֖g ʼeţ-ẖa֥g ha⁠su̇kֽ̇wòţ׃"],[14,20,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ עַל־מְצִלּ֣וֹת הַ⁠סּ֔וּס קֹ֖דֶשׁ לַֽ⁠יהוָ֑ה וְ⁠הָיָ֤ה הַ⁠סִּירוֹת֙ בְּ⁠בֵ֣ית יְהוָ֔ה כַּ⁠מִּזְרָקִ֖ים לִ⁠פְנֵ֥י הַ⁠מִּזְבֵּֽחַ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ ʻal-mĕẕil֣̇wòţ ha⁠ṡ֔ẇs qò֖deş̌ laֽ⁠yhwá֑h wĕ⁠háyá֤h ha⁠si̇yrwòţ֙ bĕ̇⁠bé֣yţ yĕhwá֔h kȧ⁠mi̇zĕráqi֖ym li⁠pĕné֥y ha⁠mi̇zĕbéֽ̇ẖa׃"],[14,21,"וְ֠⁠הָיָה כָּל־סִ֨יר בִּ⁠ירוּשָׁלִַ֜ם וּ⁠בִֽ⁠יהוּדָ֗ה קֹ֚דֶשׁ לַ⁠יהוָ֣ה צְבָא֔וֹת וּ⁠בָ֨אוּ֙ כָּל־הַ⁠זֹּ֣בְחִ֔ים וְ⁠לָקְח֥וּ מֵ⁠הֶ֖ם וּ⁠בִשְּׁל֣וּ בָ⁠הֶ֑ם וְ⁠לֹא־יִהְיֶ֨ה כְנַעֲנִ֥י ע֛וֹד בְּ⁠בֵית־יְהוָ֥ה צְבָא֖וֹת בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","wĕ֠⁠háyáh ká̇l-si֨yr bi̇⁠yrẇşá̌lia֜m ẇ⁠biֽ⁠yhẇdá֗h qò֚deş̌ la⁠yhwá֣h ẕĕbáʼ֔wòţ ẇ⁠bá֨ʼẇ֙ ká̇l-ha⁠zò֣̇bĕẖi֔ym wĕ⁠láqĕẖ֥ẇ mé⁠he֖m ẇ⁠bişĕ̇̌l֣ẇ bá⁠he֑m wĕ⁠lòʼ-yihĕye֨h kĕnaʻàni֥y ʻ֛wòd bĕ̇⁠béyţ-yĕhwá֥h ẕĕbáʼ֖wòţ bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"]],"fra-lsg1910":[[1,1,"Le huitième mois, la seconde année de Darius, la parole de l'Éternel fut adressée à Zacharie, fils de Bérékia, fils d'Iddo, le prophète, en ces mots:","Le huitième mois, la seconde année de Darius, la parole de l'Éternel fut adressée à Zacharie, fils de Bérékia, fils d'Iddo, le prophète, en ces mots:"],[1,2,"L'Éternel a été très irrité contre vos pères.","L'Éternel a été très irrité contre vos pères."],[1,3,"Dis-leur donc: Ainsi parle l'Éternel des armées: Revenez à moi, dit l'Éternel des armées, et je reviendrai à vous, dit l'Éternel des armées.","Dis-leur donc: Ainsi parle l'Éternel des armées: Revenez à moi, dit l'Éternel des armées, et je reviendrai à vous, dit l'Éternel des armées."],[1,4,"Ne soyez pas comme vos pères, auxquels s'adressaient les premiers prophètes, en disant: Ainsi parle l'Éternel des armées: Détournez-vous de vos mauvaises voies, de vos mauvaises actions! Mais ils n'écoutèrent pas, ils ne firent pas attention à moi, dit l'Éternel.","Ne soyez pas comme vos pères, auxquels s'adressaient les premiers prophètes, en disant: Ainsi parle l'Éternel des armées: Détournez-vous de vos mauvaises voies, de vos mauvaises actions! Mais ils n'écoutèrent pas, ils ne firent pas attention à moi, dit l'Éternel."],[1,5,"Vos pères, où sont-ils? et les prophètes pouvaient-ils vivre éternellement?","Vos pères, où sont-ils? et les prophètes pouvaient-ils vivre éternellement?"],[1,6,"Cependant mes paroles et les ordres que j'avais donnés à mes serviteurs, les prophètes, n'ont-ils pas atteint vos pères? Ils se sont retournés, et ils ont dit: L'Éternel des armées nous a traités comme il avait résolu de le faire selon nos voies et nos actions.","Cependant mes paroles et les ordres que j'avais donnés à mes serviteurs, les prophètes, n'ont-ils pas atteint vos pères? Ils se sont retournés, et ils ont dit: L'Éternel des armées nous a traités comme il avait résolu de le faire selon nos voies et nos actions."],[1,7,"Le vingt-quatrième jour du onzième mois, qui est le mois de Schebat, la seconde année de Darius, la parole de l'Éternel fut adressée à Zacharie, fils de Bérékia, fils d'Iddo, le prophète, en ces mots:","Le vingt-quatrième jour du onzième mois, qui est le mois de Schebat, la seconde année de Darius, la parole de l'Éternel fut adressée à Zacharie, fils de Bérékia, fils d'Iddo, le prophète, en ces mots:"],[1,8,"Je regardai pendant la nuit, et voici, un homme était monté sur un cheval roux, et se tenait parmi des myrtes dans un lieu ombragé; il y avait derrière lui des chevaux roux, fauves, et blancs.","Je regardai pendant la nuit, et voici, un homme était monté sur un cheval roux, et se tenait parmi des myrtes dans un lieu ombragé; il y avait derrière lui des chevaux roux, fauves, et blancs."],[1,9,"Je dis: Qui sont ces chevaux, mon seigneur? Et l'ange qui parlait avec moi me dit: Je te ferai voir qui sont ces chevaux.","Je dis: Qui sont ces chevaux, mon seigneur? Et l'ange qui parlait avec moi me dit: Je te ferai voir qui sont ces chevaux."],[1,10,"L'homme qui se tenait parmi les myrtes prit la parole et dit: Ce sont ceux que l'Éternel a envoyés pour parcourir la terre.","L'homme qui se tenait parmi les myrtes prit la parole et dit: Ce sont ceux que l'Éternel a envoyés pour parcourir la terre."],[1,11,"Et ils s'adressèrent à l'ange de l'Éternel, qui se tenait parmi les myrtes, et ils dirent: Nous avons parcouru la terre, et voici, toute la terre est en repos et tranquille.","Et ils s'adressèrent à l'ange de l'Éternel, qui se tenait parmi les myrtes, et ils dirent: Nous avons parcouru la terre, et voici, toute la terre est en repos et tranquille."],[1,12,"Alors l'ange de l'Éternel prit la parole et dit: Éternel des armées, jusques à quand n'auras-tu pas compassion de Jérusalem et des villes de Juda, contre lesquelles tu es irrité depuis soixante-dix ans?","Alors l'ange de l'Éternel prit la parole et dit: Éternel des armées, jusques à quand n'auras-tu pas compassion de Jérusalem et des villes de Juda, contre lesquelles tu es irrité depuis soixante-dix ans?"],[1,13,"L'Éternel répondit par de bonnes paroles, par des paroles de consolation, à l'ange qui parlait avec moi.","L'Éternel répondit par de bonnes paroles, par des paroles de consolation, à l'ange qui parlait avec moi."],[1,14,"Et l'ange qui parlait avec moi me dit: Crie, et dis: Ainsi parle l'Éternel des armées: Je suis ému d'une grande jalousie pour Jérusalem et pour Sion,","Et l'ange qui parlait avec moi me dit: Crie, et dis: Ainsi parle l'Éternel des armées: Je suis ému d'une grande jalousie pour Jérusalem et pour Sion,"],[1,15,"et je suis saisi d'une grande irritation contre les nations orgueilleuses; car je n'étais que peu irrité, mais elles ont contribué au mal.","et je suis saisi d'une grande irritation contre les nations orgueilleuses; car je n'étais que peu irrité, mais elles ont contribué au mal."],[1,16,"C'est pourquoi ainsi parle l'Éternel: Je reviens à Jérusalem avec compassion; ma maison y sera rebâtie, et le cordeau sera étendu sur Jérusalem.","C'est pourquoi ainsi parle l'Éternel: Je reviens à Jérusalem avec compassion; ma maison y sera rebâtie, et le cordeau sera étendu sur Jérusalem."],[1,17,"Crie de nouveau, et dis: Ainsi parle l'Éternel des armées: Mes villes auront encore des biens en abondance; l'Éternel consolera encore Sion, il choisira encore Jérusalem.","Crie de nouveau, et dis: Ainsi parle l'Éternel des armées: Mes villes auront encore des biens en abondance; l'Éternel consolera encore Sion, il choisira encore Jérusalem."],[1,18,"Je levai les yeux et je regardai, et voici, il y avait quatre cornes.","Je levai les yeux et je regardai, et voici, il y avait quatre cornes."],[1,19,"Je dis à l'ange qui parlait avec moi: Qu'est-ce que ces cornes? Et il me dit: Ce sont les cornes qui ont dispersé Juda, Israël et Jérusalem.","Je dis à l'ange qui parlait avec moi: Qu'est-ce que ces cornes? Et il me dit: Ce sont les cornes qui ont dispersé Juda, Israël et Jérusalem."],[1,20,"L'Éternel me fit voir quatre forgerons.","L'Éternel me fit voir quatre forgerons."],[1,21,"Je dis: Que viennent-ils faire? Et il dit: Ce sont les cornes qui ont dispersé Juda, tellement que nul ne lève la tête; et ces forgerons sont venus pour les effrayer, et pour abattre les cornes des nations qui ont levé la corne contre le pays de Juda, afin d'en disperser les habitants.","Je dis: Que viennent-ils faire? Et il dit: Ce sont les cornes qui ont dispersé Juda, tellement que nul ne lève la tête; et ces forgerons sont venus pour les effrayer, et pour abattre les cornes des nations qui ont levé la corne contre le pays de Juda, afin d'en disperser les habitants."],[2,1,"Je levai les yeux et je regardai, et voici, il y avait un homme tenant dans la main un cordeau pour mesurer.","Je levai les yeux et je regardai, et voici, il y avait un homme tenant dans la main un cordeau pour mesurer."],[2,2,"Je dis: Où vas-tu? Et il me dit: Je vais mesurer Jérusalem, pour voir de quelle largeur et de quelle longueur elle doit être.","Je dis: Où vas-tu? Et il me dit: Je vais mesurer Jérusalem, pour voir de quelle largeur et de quelle longueur elle doit être."],[2,3,"Et voici, l'ange qui parlait avec moi s'avança, et un autre ange vint à sa rencontre.","Et voici, l'ange qui parlait avec moi s'avança, et un autre ange vint à sa rencontre."],[2,4,"Il lui dit: Cours, parle à ce jeune homme, et dis: Jérusalem sera une ville ouverte, à cause de la multitude d'hommes et de bêtes qui seront au milieu d'elle;","Il lui dit: Cours, parle à ce jeune homme, et dis: Jérusalem sera une ville ouverte, à cause de la multitude d'hommes et de bêtes qui seront au milieu d'elle;"],[2,5,"je serai pour elle, dit l'Éternel, une muraille de feu tout autour, et je serai sa gloire au milieu d'elle.","je serai pour elle, dit l'Éternel, une muraille de feu tout autour, et je serai sa gloire au milieu d'elle."],[2,6,"Fuyez, fuyez du pays du septentrion! Dit l'Éternel. Car je vous ai dispersés aux quatre vents des cieux, Dit l'Éternel.","Fuyez, fuyez du pays du septentrion! Dit l'Éternel. Car je vous ai dispersés aux quatre vents des cieux, Dit l'Éternel."],[2,7,"Sauve-toi, Sion, Toi qui habites chez la fille de Babylone!","Sauve-toi, Sion, Toi qui habites chez la fille de Babylone!"],[2,8,"Car ainsi parle l'Éternel des armées: Après cela, viendra la gloire! Il m'a envoyé vers les nations qui vous ont dépouillés; Car celui qui vous touche touche la prunelle de son oeil.","Car ainsi parle l'Éternel des armées: Après cela, viendra la gloire! Il m'a envoyé vers les nations qui vous ont dépouillés; Car celui qui vous touche touche la prunelle de son oeil."],[2,9,"Voici, je lève ma main contre elles, Et elles seront la proie de ceux qui leur étaient asservis. Et vous saurez que l'Éternel des armées m'a envoyé.","Voici, je lève ma main contre elles, Et elles seront la proie de ceux qui leur étaient asservis. Et vous saurez que l'Éternel des armées m'a envoyé."],[2,10,"Pousse des cris d'allégresse et réjouis-toi, Fille de Sion! Car voici, je viens, et j'habiterai au milieu de toi, Dit l'Éternel.","Pousse des cris d'allégresse et réjouis-toi, Fille de Sion! Car voici, je viens, et j'habiterai au milieu de toi, Dit l'Éternel."],[2,11,"Beaucoup de nations s'attacheront à l'Éternel en ce jour-là, Et deviendront mon peuple; J'habiterai au milieu de toi, Et tu sauras que l'Éternel des armées m'a envoyé vers toi.","Beaucoup de nations s'attacheront à l'Éternel en ce jour-là, Et deviendront mon peuple; J'habiterai au milieu de toi, Et tu sauras que l'Éternel des armées m'a envoyé vers toi."],[2,12,"L'Éternel possédera Juda comme sa part Dans la terre sainte, Et il choisira encore Jérusalem.","L'Éternel possédera Juda comme sa part Dans la terre sainte, Et il choisira encore Jérusalem."],[2,13,"Que toute chair fasse silence devant l'Éternel! Car il s'est réveillé de sa demeure sainte.","Que toute chair fasse silence devant l'Éternel! Car il s'est réveillé de sa demeure sainte."],[3,1,"Il me fit voir Josué, le souverain sacrificateur, debout devant l'ange de l'Éternel, et Satan qui se tenait à sa droite pour l'accuser.","Il me fit voir Josué, le souverain sacrificateur, debout devant l'ange de l'Éternel, et Satan qui se tenait à sa droite pour l'accuser."],[3,2,"L'Éternel dit à Satan: Que l'Éternel te réprime, Satan! que l'Éternel te réprime, lui qui a choisi Jérusalem! N'est-ce pas là un tison arraché du feu?","L'Éternel dit à Satan: Que l'Éternel te réprime, Satan! que l'Éternel te réprime, lui qui a choisi Jérusalem! N'est-ce pas là un tison arraché du feu?"],[3,3,"Or Josué était couvert de vêtements sales, et il se tenait debout devant l'ange.","Or Josué était couvert de vêtements sales, et il se tenait debout devant l'ange."],[3,4,"L'ange, prenant la parole, dit à ceux qui étaient devant lui: Otez-lui les vêtements sales! Puis il dit à Josué: Vois, je t'enlève ton iniquité, et je te revêts d'habits de fête.","L'ange, prenant la parole, dit à ceux qui étaient devant lui: Otez-lui les vêtements sales! Puis il dit à Josué: Vois, je t'enlève ton iniquité, et je te revêts d'habits de fête."],[3,5,"Je dis: Qu'on mette sur sa tête un turban pur! Et ils mirent un turban pur sur sa tête, et ils lui mirent des vêtements. L'ange de l'Éternel était là.","Je dis: Qu'on mette sur sa tête un turban pur! Et ils mirent un turban pur sur sa tête, et ils lui mirent des vêtements. L'ange de l'Éternel était là."],[3,6,"L'ange de l'Éternel fit à Josué cette déclaration:","L'ange de l'Éternel fit à Josué cette déclaration:"],[3,7,"Ainsi parle l'Éternel des armées: Si tu marches dans mes voies et si tu observes mes ordres, tu jugeras ma maison et tu garderas mes parvis, et je te donnerai libre accès parmi ceux qui sont ici.","Ainsi parle l'Éternel des armées: Si tu marches dans mes voies et si tu observes mes ordres, tu jugeras ma maison et tu garderas mes parvis, et je te donnerai libre accès parmi ceux qui sont ici."],[3,8,"Écoute donc, Josué, souverain sacrificateur, toi et tes compagnons qui sont assis devant toi! car ce sont des hommes qui serviront de signes. Voici, je ferai venir mon serviteur, le germe.","Écoute donc, Josué, souverain sacrificateur, toi et tes compagnons qui sont assis devant toi! car ce sont des hommes qui serviront de signes. Voici, je ferai venir mon serviteur, le germe."],[3,9,"Car voici, pour ce qui est de la pierre que j'ai placée devant Josué, il y a sept yeux sur cette seule pierre; voici, je graverai moi-même ce qui doit y être gravé, dit l'Éternel des armées; et j'enlèverai l'iniquité de ce pays, en un jour.","Car voici, pour ce qui est de la pierre que j'ai placée devant Josué, il y a sept yeux sur cette seule pierre; voici, je graverai moi-même ce qui doit y être gravé, dit l'Éternel des armées; et j'enlèverai l'iniquité de ce pays, en un jour."],[3,10,"En ce jour-là, dit l'Éternel des armées, vous vous inviterez les uns les autres sous la vigne et sous le figuier.","En ce jour-là, dit l'Éternel des armées, vous vous inviterez les uns les autres sous la vigne et sous le figuier."],[4,1,"L'ange qui parlait avec moi revint, et il me réveilla comme un homme que l'on réveille de son sommeil.","L'ange qui parlait avec moi revint, et il me réveilla comme un homme que l'on réveille de son sommeil."],[4,2,"Il me dit: Que vois-tu? Je répondis: Je regarde, et voici, il y a un chandelier tout d'or, surmonté d'un vase et portant sept lampes, avec sept conduits pour les lampes qui sont au sommet du chandelier;","Il me dit: Que vois-tu? Je répondis: Je regarde, et voici, il y a un chandelier tout d'or, surmonté d'un vase et portant sept lampes, avec sept conduits pour les lampes qui sont au sommet du chandelier;"],[4,3,"et il y a près de lui deux oliviers, l'un à la droite du vase, et l'autre à sa gauche.","et il y a près de lui deux oliviers, l'un à la droite du vase, et l'autre à sa gauche."],[4,4,"Et reprenant la parole, je dis à l'ange qui parlait avec moi: Que signifient ces choses, mon seigneur?","Et reprenant la parole, je dis à l'ange qui parlait avec moi: Que signifient ces choses, mon seigneur?"],[4,5,"L'ange qui parlait avec moi me répondit: Ne sais-tu pas ce que signifient ces choses? Je dis: Non, mon seigneur.","L'ange qui parlait avec moi me répondit: Ne sais-tu pas ce que signifient ces choses? Je dis: Non, mon seigneur."],[4,6,"Alors il reprit et me dit: C'est ici la parole que l'Éternel adresse à Zorobabel: Ce n'est ni par la puissance ni par la force, mais c'est par mon esprit, dit l'Éternel des armées.","Alors il reprit et me dit: C'est ici la parole que l'Éternel adresse à Zorobabel: Ce n'est ni par la puissance ni par la force, mais c'est par mon esprit, dit l'Éternel des armées."],[4,7,"Qui es-tu, grande montagne, devant Zorobabel? Tu seras aplanie. Il posera la pierre principale au milieu des acclamations: Grâce, grâce pour elle!","Qui es-tu, grande montagne, devant Zorobabel? Tu seras aplanie. Il posera la pierre principale au milieu des acclamations: Grâce, grâce pour elle!"],[4,8,"La parole de l'Éternel me fut adressée, en ces mots:","La parole de l'Éternel me fut adressée, en ces mots:"],[4,9,"Les mains de Zorobabel ont fondé cette maison, et ses mains l'achèveront; et tu sauras que l'Éternel des armées m'a envoyé vers vous.","Les mains de Zorobabel ont fondé cette maison, et ses mains l'achèveront; et tu sauras que l'Éternel des armées m'a envoyé vers vous."],[4,10,"Car ceux qui méprisaient le jour des faibles commencements se réjouiront en voyant le niveau dans la main de Zorobabel. Ces sept sont les yeux de l'Éternel, qui parcourent toute la terre.","Car ceux qui méprisaient le jour des faibles commencements se réjouiront en voyant le niveau dans la main de Zorobabel. Ces sept sont les yeux de l'Éternel, qui parcourent toute la terre."],[4,11,"Je pris la parole et je lui dis: Que signifient ces deux oliviers, à la droite du chandelier et à sa gauche?","Je pris la parole et je lui dis: Que signifient ces deux oliviers, à la droite du chandelier et à sa gauche?"],[4,12,"Je pris une seconde fois la parole, et je lui dis: Que signifient les deux rameaux d'olivier, qui sont près des deux conduits d'or d'où découle l'or?","Je pris une seconde fois la parole, et je lui dis: Que signifient les deux rameaux d'olivier, qui sont près des deux conduits d'or d'où découle l'or?"],[4,13,"Il me répondit: Ne sais-tu pas ce qu'ils signifient? Je dis: Non, mon seigneur.","Il me répondit: Ne sais-tu pas ce qu'ils signifient? Je dis: Non, mon seigneur."],[4,14,"Et il dit: Ce sont les deux oints qui se tiennent devant le Seigneur de toute la terre.","Et il dit: Ce sont les deux oints qui se tiennent devant le Seigneur de toute la terre."],[5,1,"Je levai de nouveau les yeux et je regardai, et voici, il y avait un rouleau qui volait.","Je levai de nouveau les yeux et je regardai, et voici, il y avait un rouleau qui volait."],[5,2,"Il me dit: Que vois-tu? Je répondis: Je vois un rouleau qui vole; il a vingt coudées de longueur, et dix coudées de largeur.","Il me dit: Que vois-tu? Je répondis: Je vois un rouleau qui vole; il a vingt coudées de longueur, et dix coudées de largeur."],[5,3,"Et il me dit: C'est la malédiction qui se répand sur tout le pays; car selon elle tout voleur sera chassé d'ici, et selon elle tout parjure sera chassé d'ici.","Et il me dit: C'est la malédiction qui se répand sur tout le pays; car selon elle tout voleur sera chassé d'ici, et selon elle tout parjure sera chassé d'ici."],[5,4,"Je la répands, dit l'Éternel des armées, afin qu'elle entre dans la maison du voleur et de celui qui jure faussement en mon nom, afin qu'elle y établisse sa demeure, et qu'elle la consume avec le bois et les pierres.","Je la répands, dit l'Éternel des armées, afin qu'elle entre dans la maison du voleur et de celui qui jure faussement en mon nom, afin qu'elle y établisse sa demeure, et qu'elle la consume avec le bois et les pierres."],[5,5,"L'ange qui parlait avec moi s'avança, et il me dit: Lève les yeux, et regarde ce qui sort là.","L'ange qui parlait avec moi s'avança, et il me dit: Lève les yeux, et regarde ce qui sort là."],[5,6,"Je répondis: Qu'est-ce? Et il dit: C'est l'épha qui sort. Il ajouta: C'est leur iniquité dans tout le pays.","Je répondis: Qu'est-ce? Et il dit: C'est l'épha qui sort. Il ajouta: C'est leur iniquité dans tout le pays."],[5,7,"Et voici, une masse de plomb s'éleva, et il y avait une femme assise au milieu de l'épha.","Et voici, une masse de plomb s'éleva, et il y avait une femme assise au milieu de l'épha."],[5,8,"Il dit: C'est l'iniquité. Et il la repoussa dans l'épha, et il jeta sur l'ouverture la masse de plomb.","Il dit: C'est l'iniquité. Et il la repoussa dans l'épha, et il jeta sur l'ouverture la masse de plomb."],[5,9,"Je levai les yeux et je regardai, et voici, deux femmes parurent. Le vent soufflait dans leurs ailes; elles avaient des ailes comme celles de la cigogne. Elles enlevèrent l'épha entre la terre et le ciel.","Je levai les yeux et je regardai, et voici, deux femmes parurent. Le vent soufflait dans leurs ailes; elles avaient des ailes comme celles de la cigogne. Elles enlevèrent l'épha entre la terre et le ciel."],[5,10,"Je dis à l'ange qui parlait avec moi: Où emportent-elles l'épha?","Je dis à l'ange qui parlait avec moi: Où emportent-elles l'épha?"],[5,11,"Il me répondit: Elles vont lui bâtir une maison dans le pays de Schinear; et quand elle sera prête, il sera déposé là dans son lieu.","Il me répondit: Elles vont lui bâtir une maison dans le pays de Schinear; et quand elle sera prête, il sera déposé là dans son lieu."],[6,1,"Je levai de nouveau les yeux et je regardai, et voici, quatre chars sortaient d'entre deux montagnes; et les montagnes étaient des montagnes d'airain.","Je levai de nouveau les yeux et je regardai, et voici, quatre chars sortaient d'entre deux montagnes; et les montagnes étaient des montagnes d'airain."],[6,2,"Au premier char il y avait des chevaux roux, au second char des chevaux noirs,","Au premier char il y avait des chevaux roux, au second char des chevaux noirs,"],[6,3,"au troisième char des chevaux blancs, et au quatrième char des chevaux tachetés, rouges.","au troisième char des chevaux blancs, et au quatrième char des chevaux tachetés, rouges."],[6,4,"Je pris la parole et je dis à l'ange qui parlait avec moi: Qu'est-ce, mon seigneur?","Je pris la parole et je dis à l'ange qui parlait avec moi: Qu'est-ce, mon seigneur?"],[6,5,"L'ange me répondit: Ce sont les quatre vents des cieux, qui sortent du lieu où ils se tenaient devant le Seigneur de toute la terre.","L'ange me répondit: Ce sont les quatre vents des cieux, qui sortent du lieu où ils se tenaient devant le Seigneur de toute la terre."],[6,6,"Les chevaux noirs attelés à l'un des chars se dirigent vers le pays du septentrion, et les blancs vont après eux; les tachetés se dirigent vers le pays du midi.","Les chevaux noirs attelés à l'un des chars se dirigent vers le pays du septentrion, et les blancs vont après eux; les tachetés se dirigent vers le pays du midi."],[6,7,"Les rouges sortent et demandent à aller parcourir la terre. L'ange leur dit: Allez, parcourez la terre! Et ils parcoururent la terre.","Les rouges sortent et demandent à aller parcourir la terre. L'ange leur dit: Allez, parcourez la terre! Et ils parcoururent la terre."],[6,8,"Il m'appela, et il me dit: Vois, ceux qui se dirigent vers le pays du septentrion font reposer ma colère sur le pays du septentrion.","Il m'appela, et il me dit: Vois, ceux qui se dirigent vers le pays du septentrion font reposer ma colère sur le pays du septentrion."],[6,9,"La parole de l'Éternel me fut adressée, en ces mots:","La parole de l'Éternel me fut adressée, en ces mots:"],[6,10,"Tu recevras les dons des captifs, Heldaï, Tobija et Jedaeja, et tu iras toi-même ce jour-là, tu iras dans la maison de Josias, fils de Sophonie, où ils se sont rendus en arrivant de Babylone.","Tu recevras les dons des captifs, Heldaï, Tobija et Jedaeja, et tu iras toi-même ce jour-là, tu iras dans la maison de Josias, fils de Sophonie, où ils se sont rendus en arrivant de Babylone."],[6,11,"Tu prendras de l'argent et de l'or, et tu en feras des couronnes, que tu mettras sur la tête de Josué, fils de Jotsadak, le souverain sacrificateur.","Tu prendras de l'argent et de l'or, et tu en feras des couronnes, que tu mettras sur la tête de Josué, fils de Jotsadak, le souverain sacrificateur."],[6,12,"Tu lui diras: Ainsi parle l'Éternel des armées: Voici, un homme, dont le nom est germe, germera dans son lieu, et bâtira le temple de l'Éternel.","Tu lui diras: Ainsi parle l'Éternel des armées: Voici, un homme, dont le nom est germe, germera dans son lieu, et bâtira le temple de l'Éternel."],[6,13,"Il bâtira le temple de l'Éternel; il portera les insignes de la majesté; il s'assiéra et dominera sur son trône, il sera sacrificateur sur son trône, et une parfaite union régnera entre l'un et l'autre.","Il bâtira le temple de l'Éternel; il portera les insignes de la majesté; il s'assiéra et dominera sur son trône, il sera sacrificateur sur son trône, et une parfaite union régnera entre l'un et l'autre."],[6,14,"Les couronnes seront pour Hélem, Tobija et Jedaeja, et pour Hen, fils de Sophonie, un souvenir dans le temple de l'Éternel.","Les couronnes seront pour Hélem, Tobija et Jedaeja, et pour Hen, fils de Sophonie, un souvenir dans le temple de l'Éternel."],[6,15,"Ceux qui sont éloignés viendront et travailleront au temple de l'Éternel; et vous saurez que l'Éternel des armées m'a envoyé vers vous. Cela arrivera, si vous écoutez la voix de l'Éternel, votre Dieu.","Ceux qui sont éloignés viendront et travailleront au temple de l'Éternel; et vous saurez que l'Éternel des armées m'a envoyé vers vous. Cela arrivera, si vous écoutez la voix de l'Éternel, votre Dieu."],[7,1,"La quatrième année du roi Darius, la parole de l'Éternel fut adressée à Zacharie, le quatrième jour du neuvième mois, qui est le mois de Kisleu.","La quatrième année du roi Darius, la parole de l'Éternel fut adressée à Zacharie, le quatrième jour du neuvième mois, qui est le mois de Kisleu."],[7,2,"On avait envoyé de Béthel Scharetser et Réguem-Mélec avec ses gens pour implorer l'Éternel,","On avait envoyé de Béthel Scharetser et Réguem-Mélec avec ses gens pour implorer l'Éternel,"],[7,3,"et pour dire aux sacrificateurs de la maison de l'Éternel des armées et aux prophètes: Faut-il que je pleure au cinquième mois et que je fasse abstinence, comme je l'ai fait tant d'années?","et pour dire aux sacrificateurs de la maison de l'Éternel des armées et aux prophètes: Faut-il que je pleure au cinquième mois et que je fasse abstinence, comme je l'ai fait tant d'années?"],[7,4,"La parole de l'Éternel des armées me fut adressée, en ces mots:","La parole de l'Éternel des armées me fut adressée, en ces mots:"],[7,5,"Dis à tout le peuple du pays et aux sacrificateurs: Quand vous avez jeûné et pleuré au cinquième et au septième mois, et cela depuis soixante-dix ans, est-ce pour moi que vous avez jeûné?","Dis à tout le peuple du pays et aux sacrificateurs: Quand vous avez jeûné et pleuré au cinquième et au septième mois, et cela depuis soixante-dix ans, est-ce pour moi que vous avez jeûné?"],[7,6,"Et quand vous mangez et buvez, n'est-ce pas vous qui mangez et vous qui buvez?","Et quand vous mangez et buvez, n'est-ce pas vous qui mangez et vous qui buvez?"],[7,7,"Ne connaissez-vous pas les paroles qu'a proclamées l'Éternel par les premiers prophètes, lorsque Jérusalem était habitée et tranquille avec ses villes à l'entour, et que le midi et la plaine étaient habités?","Ne connaissez-vous pas les paroles qu'a proclamées l'Éternel par les premiers prophètes, lorsque Jérusalem était habitée et tranquille avec ses villes à l'entour, et que le midi et la plaine étaient habités?"],[7,8,"La parole de l'Éternel fut adressée à Zacharie, en ces mots:","La parole de l'Éternel fut adressée à Zacharie, en ces mots:"],[7,9,"Ainsi parlait l'Éternel des armées: Rendez véritablement la justice, Et ayez l'un pour l'autre de la bonté et de la miséricorde.","Ainsi parlait l'Éternel des armées: Rendez véritablement la justice, Et ayez l'un pour l'autre de la bonté et de la miséricorde."],[7,10,"N'opprimez pas la veuve et l'orphelin, l'étranger et le pauvre, Et ne méditez pas l'un contre l'autre le mal dans vos coeurs.","N'opprimez pas la veuve et l'orphelin, l'étranger et le pauvre, Et ne méditez pas l'un contre l'autre le mal dans vos coeurs."],[7,11,"Mais ils refusèrent d'être attentifs, ils eurent l'épaule rebelle, et ils endurcirent leurs oreilles pour ne pas entendre.","Mais ils refusèrent d'être attentifs, ils eurent l'épaule rebelle, et ils endurcirent leurs oreilles pour ne pas entendre."],[7,12,"Ils rendirent leur coeur dur comme le diamant, pour ne pas écouter la loi et les paroles que l'Éternel des armées leur adressait par son esprit, par les premiers prophètes. Ainsi l'Éternel des armées s'enflamma d'une grande colère.","Ils rendirent leur coeur dur comme le diamant, pour ne pas écouter la loi et les paroles que l'Éternel des armées leur adressait par son esprit, par les premiers prophètes. Ainsi l'Éternel des armées s'enflamma d'une grande colère."],[7,13,"Quand il appelait, ils n'ont pas écouté: aussi n'ai-je pas écouté, quand ils ont appelé, dit l'Éternel des armées.","Quand il appelait, ils n'ont pas écouté: aussi n'ai-je pas écouté, quand ils ont appelé, dit l'Éternel des armées."],[7,14,"Je les ai dispersés parmi toutes les nations qu'ils ne connaissaient pas; le pays a été dévasté derrière eux, il n'y a plus eu ni allants ni venants; et d'un pays de délices ils ont fait un désert.","Je les ai dispersés parmi toutes les nations qu'ils ne connaissaient pas; le pays a été dévasté derrière eux, il n'y a plus eu ni allants ni venants; et d'un pays de délices ils ont fait un désert."],[8,1,"La parole de l'Éternel des armées se révéla, en ces mots:","La parole de l'Éternel des armées se révéla, en ces mots:"],[8,2,"Ainsi parle l'Éternel des armées: Je suis ému pour Sion d'une grande jalousie, et je suis saisi pour elle d'une grande fureur.","Ainsi parle l'Éternel des armées: Je suis ému pour Sion d'une grande jalousie, et je suis saisi pour elle d'une grande fureur."],[8,3,"Ainsi parle l'Éternel: Je retourne à Sion, et je veux habiter au milieu de Jérusalem. Jérusalem sera appelée ville fidèle, et la montagne de l'Éternel des armées montagne sainte.","Ainsi parle l'Éternel: Je retourne à Sion, et je veux habiter au milieu de Jérusalem. Jérusalem sera appelée ville fidèle, et la montagne de l'Éternel des armées montagne sainte."],[8,4,"Ainsi parle l'Éternel des armées: Des vieillards et des femmes âgées s'assiéront encore dans les rues de Jérusalem, chacun le bâton à la main, à cause du grand nombre de leurs jours.","Ainsi parle l'Éternel des armées: Des vieillards et des femmes âgées s'assiéront encore dans les rues de Jérusalem, chacun le bâton à la main, à cause du grand nombre de leurs jours."],[8,5,"Les rues de la ville seront remplies de jeunes garçons et de jeunes filles, jouant dans les rues.","Les rues de la ville seront remplies de jeunes garçons et de jeunes filles, jouant dans les rues."],[8,6,"Ainsi parle l'Éternel des armées: Si la chose paraît étonnante aux yeux du reste de ce peuple en ces jours-là, sera-t-elle de même étonnante à mes yeux? dit l'Éternel des armées.","Ainsi parle l'Éternel des armées: Si la chose paraît étonnante aux yeux du reste de ce peuple en ces jours-là, sera-t-elle de même étonnante à mes yeux? dit l'Éternel des armées."],[8,7,"Ainsi parle l'Éternel des armées: Voici, je délivre mon peuple du pays de l'orient et du pays du soleil couchant.","Ainsi parle l'Éternel des armées: Voici, je délivre mon peuple du pays de l'orient et du pays du soleil couchant."],[8,8,"Je les ramènerai, et ils habiteront au milieu de Jérusalem; ils seront mon peuple, et je serai leur Dieu avec vérité et droiture.","Je les ramènerai, et ils habiteront au milieu de Jérusalem; ils seront mon peuple, et je serai leur Dieu avec vérité et droiture."],[8,9,"Ainsi parle l'Éternel des armées: Fortifiez vos mains, vous qui entendez aujourd'hui ces paroles de la bouche des prophètes qui parurent au temps où fut fondée la maison de l'Éternel des armées, où le temple allait être bâti.","Ainsi parle l'Éternel des armées: Fortifiez vos mains, vous qui entendez aujourd'hui ces paroles de la bouche des prophètes qui parurent au temps où fut fondée la maison de l'Éternel des armées, où le temple allait être bâti."],[8,10,"Car avant ce temps, le travail de l'homme ne recevait pas sa récompense, et le salaire des bêtes était nul; il n'y avait point de paix pour ceux qui entraient et sortaient, à cause de l'ennemi, et je lâchais tous les hommes les uns contre les autres.","Car avant ce temps, le travail de l'homme ne recevait pas sa récompense, et le salaire des bêtes était nul; il n'y avait point de paix pour ceux qui entraient et sortaient, à cause de l'ennemi, et je lâchais tous les hommes les uns contre les autres."],[8,11,"Maintenant je ne suis pas pour le reste de ce peuple comme j'étais dans le temps passé, dit l'Éternel des armées.","Maintenant je ne suis pas pour le reste de ce peuple comme j'étais dans le temps passé, dit l'Éternel des armées."],[8,12,"Car les semailles prospéreront, la vigne rendra son fruit, la terre donnera ses produits, et les cieux enverront leur rosée; je ferai jouir de toutes ces choses le reste de ce peuple.","Car les semailles prospéreront, la vigne rendra son fruit, la terre donnera ses produits, et les cieux enverront leur rosée; je ferai jouir de toutes ces choses le reste de ce peuple."],[8,13,"De même que vous avez été en malédiction parmi les nations, maison de Juda et maison d'Israël, de même je vous sauverai, et vous serez en bénédiction. Ne craignez pas, et que vos mains se fortifient!","De même que vous avez été en malédiction parmi les nations, maison de Juda et maison d'Israël, de même je vous sauverai, et vous serez en bénédiction. Ne craignez pas, et que vos mains se fortifient!"],[8,14,"Car ainsi parle l'Éternel des armées: Comme j'ai eu la pensée de vous faire du mal lorsque vos pères m'irritaient, dit l'Éternel des armées, et que je ne m'en suis point repenti,","Car ainsi parle l'Éternel des armées: Comme j'ai eu la pensée de vous faire du mal lorsque vos pères m'irritaient, dit l'Éternel des armées, et que je ne m'en suis point repenti,"],[8,15,"ainsi je reviens en arrière et j'ai résolu en ces jours de faire du bien à Jérusalem et à la maison de Juda. Ne craignez pas!","ainsi je reviens en arrière et j'ai résolu en ces jours de faire du bien à Jérusalem et à la maison de Juda. Ne craignez pas!"],[8,16,"Voici ce que vous devez faire: dites la vérité chacun à son prochain; jugez dans vos portes selon la vérité et en vue de la paix;","Voici ce que vous devez faire: dites la vérité chacun à son prochain; jugez dans vos portes selon la vérité et en vue de la paix;"],[8,17,"que nul en son coeur ne pense le mal contre son prochain, et n'aimez pas le faux serment, car ce sont là toutes choses que je hais, dit l'Éternel.","que nul en son coeur ne pense le mal contre son prochain, et n'aimez pas le faux serment, car ce sont là toutes choses que je hais, dit l'Éternel."],[8,18,"La parole de l'Éternel des armées me fut adressée, en ces mots:","La parole de l'Éternel des armées me fut adressée, en ces mots:"],[8,19,"Ainsi parle l'Éternel des armées: Le jeûne du quatrième mois, le jeûne du cinquième, le jeûne du septième et le jeûne du dixième se changeront pour la maison de Juda en jours d'allégresse et de joie, en fêtes de réjouissance. Mais aimez la vérité et la paix.","Ainsi parle l'Éternel des armées: Le jeûne du quatrième mois, le jeûne du cinquième, le jeûne du septième et le jeûne du dixième se changeront pour la maison de Juda en jours d'allégresse et de joie, en fêtes de réjouissance. Mais aimez la vérité et la paix."],[8,20,"Ainsi parle l'Éternel des armées: Il viendra encore des peuples et des habitants d'un grand nombre de villes.","Ainsi parle l'Éternel des armées: Il viendra encore des peuples et des habitants d'un grand nombre de villes."],[8,21,"Les habitants d'une ville iront à l'autre, en disant: Allons implorer l'Éternel et chercher l'Éternel des armées! Nous irons aussi!","Les habitants d'une ville iront à l'autre, en disant: Allons implorer l'Éternel et chercher l'Éternel des armées! Nous irons aussi!"],[8,22,"Et beaucoup de peuples et de nombreuses nations viendront chercher l'Éternel des armées à Jérusalem et implorer l'Éternel.","Et beaucoup de peuples et de nombreuses nations viendront chercher l'Éternel des armées à Jérusalem et implorer l'Éternel."],[8,23,"Ainsi parle l'Éternel des armées: En ces jours-là, dix hommes de toutes les langues des nations saisiront un Juif par le pan de son vêtement et diront: Nous irons avec vous, car nous avons appris que Dieu est avec vous.","Ainsi parle l'Éternel des armées: En ces jours-là, dix hommes de toutes les langues des nations saisiront un Juif par le pan de son vêtement et diront: Nous irons avec vous, car nous avons appris que Dieu est avec vous."],[9,1,"Oracle, parole de l'Éternel sur le pays de Hadrac. Elle s'arrête sur Damas, Car l'Éternel a l'oeil sur les hommes Comme sur toutes les tribus d'Israël;","Oracle, parole de l'Éternel sur le pays de Hadrac. Elle s'arrête sur Damas, Car l'Éternel a l'oeil sur les hommes Comme sur toutes les tribus d'Israël;"],[9,2,"Elle s'arrête aussi sur Hamath, à la frontière de Damas, Sur Tyr et Sidon, malgré toute leur sagesse.","Elle s'arrête aussi sur Hamath, à la frontière de Damas, Sur Tyr et Sidon, malgré toute leur sagesse."],[9,3,"Tyr s'est bâti une forteresse; Elle a amassé l'argent comme la poussière, Et l'or comme la boue des rues.","Tyr s'est bâti une forteresse; Elle a amassé l'argent comme la poussière, Et l'or comme la boue des rues."],[9,4,"Voici, le Seigneur s'en emparera, Il précipitera sa puissance dans la mer, Et elle sera consumée par le feu.","Voici, le Seigneur s'en emparera, Il précipitera sa puissance dans la mer, Et elle sera consumée par le feu."],[9,5,"Askalon le verra, et elle sera dans la crainte; Gaza aussi, et un violent tremblement la saisira; Ékron aussi, car son espoir sera confondu. Le roi disparaîtra de Gaza, Et Askalon ne sera plus habitée.","Askalon le verra, et elle sera dans la crainte; Gaza aussi, et un violent tremblement la saisira; Ékron aussi, car son espoir sera confondu. Le roi disparaîtra de Gaza, Et Askalon ne sera plus habitée."],[9,6,"L'étranger s'établira dans Asdod, Et j'abattrai l'orgueil des Philistins.","L'étranger s'établira dans Asdod, Et j'abattrai l'orgueil des Philistins."],[9,7,"J'ôterai le sang de sa bouche, Et les abominations d'entre ses dents; Lui aussi restera pour notre Dieu; Il sera comme un chef en Juda, Et Ékron sera comme les Jébusiens.","J'ôterai le sang de sa bouche, Et les abominations d'entre ses dents; Lui aussi restera pour notre Dieu; Il sera comme un chef en Juda, Et Ékron sera comme les Jébusiens."],[9,8,"Je camperai autour de ma maison pour la défendre contre une armée, Contre les allants et les venants, Et l'oppresseur ne passera plus près d'eux; Car maintenant mes yeux sont fixés sur elle.","Je camperai autour de ma maison pour la défendre contre une armée, Contre les allants et les venants, Et l'oppresseur ne passera plus près d'eux; Car maintenant mes yeux sont fixés sur elle."],[9,9,"Sois transportée d'allégresse, fille de Sion! Pousse des cris de joie, fille de Jérusalem! Voici, ton roi vient à toi; Il est juste et victorieux, Il est humble et monté sur un âne, Sur un âne, le petit d'une ânesse.","Sois transportée d'allégresse, fille de Sion! Pousse des cris de joie, fille de Jérusalem! Voici, ton roi vient à toi; Il est juste et victorieux, Il est humble et monté sur un âne, Sur un âne, le petit d'une ânesse."],[9,10,"Je détruirai les chars d'Éphraïm, Et les chevaux de Jérusalem; Et les arcs de guerre seront anéantis. Il annoncera la paix aux nations, Et il dominera d'une mer à l'autre, Depuis le fleuve jusqu'aux extrémités de la terre.","Je détruirai les chars d'Éphraïm, Et les chevaux de Jérusalem; Et les arcs de guerre seront anéantis. Il annoncera la paix aux nations, Et il dominera d'une mer à l'autre, Depuis le fleuve jusqu'aux extrémités de la terre."],[9,11,"Et pour toi, à cause de ton alliance scellée par le sang, Je retirerai tes captifs de la fosse où il n'y a pas d'eau.","Et pour toi, à cause de ton alliance scellée par le sang, Je retirerai tes captifs de la fosse où il n'y a pas d'eau."],[9,12,"Retournez à la forteresse, captifs pleins d'espérance! Aujourd'hui encore je le déclare, Je te rendrai le double.","Retournez à la forteresse, captifs pleins d'espérance! Aujourd'hui encore je le déclare, Je te rendrai le double."],[9,13,"Car je bande Juda comme un arc, Je m'arme d'Éphraïm comme d'un arc, Et je soulèverai tes enfants, ô Sion, Contre tes enfants, ô Javan! Je te rendrai pareille à l'épée d'un vaillant homme.","Car je bande Juda comme un arc, Je m'arme d'Éphraïm comme d'un arc, Et je soulèverai tes enfants, ô Sion, Contre tes enfants, ô Javan! Je te rendrai pareille à l'épée d'un vaillant homme."],[9,14,"L'Éternel au-dessus d'eux apparaîtra, Et sa flèche partira comme l'éclair; Le Seigneur, l'Éternel, sonnera de la trompette, Il s'avancera dans l'ouragan du midi.","L'Éternel au-dessus d'eux apparaîtra, Et sa flèche partira comme l'éclair; Le Seigneur, l'Éternel, sonnera de la trompette, Il s'avancera dans l'ouragan du midi."],[9,15,"L'Éternel des armées les protégera; Ils dévoreront, ils vaincront les pierres de la fronde; Ils boiront, ils seront bruyants comme pris de vin; Ils seront pleins comme une coupe, Comme les coins de l'autel.","L'Éternel des armées les protégera; Ils dévoreront, ils vaincront les pierres de la fronde; Ils boiront, ils seront bruyants comme pris de vin; Ils seront pleins comme une coupe, Comme les coins de l'autel."],[9,16,"L'Éternel, leur Dieu, les sauvera en ce jour-là, Comme le troupeau de son peuple; Car ils sont les pierres d'un diadème, Qui brilleront dans son pays.","L'Éternel, leur Dieu, les sauvera en ce jour-là, Comme le troupeau de son peuple; Car ils sont les pierres d'un diadème, Qui brilleront dans son pays."],[9,17,"Oh! quelle prospérité pour eux! quelle beauté! Le froment fera croître les jeunes hommes, Et le moût les jeunes filles.","Oh! quelle prospérité pour eux! quelle beauté! Le froment fera croître les jeunes hommes, Et le moût les jeunes filles."],[10,1,"Demandez à l'Éternel la pluie, la pluie du printemps! L'Éternel produira des éclairs, Et il vous enverra une abondante pluie, Il donnera à chacun de l'herbe dans son champ.","Demandez à l'Éternel la pluie, la pluie du printemps! L'Éternel produira des éclairs, Et il vous enverra une abondante pluie, Il donnera à chacun de l'herbe dans son champ."],[10,2,"Car les théraphim ont des paroles de néant, Les devins prophétisent des faussetés, Les songes mentent et consolent par la vanité. C'est pourquoi ils sont errants comme un troupeau, Ils sont malheureux parce qu'il n'y a point de pasteur.","Car les théraphim ont des paroles de néant, Les devins prophétisent des faussetés, Les songes mentent et consolent par la vanité. C'est pourquoi ils sont errants comme un troupeau, Ils sont malheureux parce qu'il n'y a point de pasteur."],[10,3,"Ma colère s'est enflammée contre les pasteurs, Et je châtierai les boucs; Car l'Éternel des armées visite son troupeau, la maison de Juda, Et il en fera comme son cheval de gloire dans la bataille;","Ma colère s'est enflammée contre les pasteurs, Et je châtierai les boucs; Car l'Éternel des armées visite son troupeau, la maison de Juda, Et il en fera comme son cheval de gloire dans la bataille;"],[10,4,"De lui sortira l'angle, de lui le clou, de lui l'arc de guerre; De lui sortiront tous les chefs ensemble.","De lui sortira l'angle, de lui le clou, de lui l'arc de guerre; De lui sortiront tous les chefs ensemble."],[10,5,"Ils seront comme des héros foulant dans la bataille la boue des rues; Ils combattront, parce que l'Éternel sera avec eux; Et ceux qui seront montés sur des chevaux seront couverts de honte.","Ils seront comme des héros foulant dans la bataille la boue des rues; Ils combattront, parce que l'Éternel sera avec eux; Et ceux qui seront montés sur des chevaux seront couverts de honte."],[10,6,"Je fortifierai la maison de Juda, Et je délivrerai la maison de Joseph; Je les ramènerai, car j'ai compassion d'eux, Et ils seront comme si je ne les avais pas rejetés; Car je suis l'Éternel, leur Dieu, et je les exaucerai.","Je fortifierai la maison de Juda, Et je délivrerai la maison de Joseph; Je les ramènerai, car j'ai compassion d'eux, Et ils seront comme si je ne les avais pas rejetés; Car je suis l'Éternel, leur Dieu, et je les exaucerai."],[10,7,"Éphraïm sera comme un héros; Leur coeur aura la joie que donne le vin; Leurs fils le verront et seront dans l'allégresse, Leur coeur se réjouira en l'Éternel.","Éphraïm sera comme un héros; Leur coeur aura la joie que donne le vin; Leurs fils le verront et seront dans l'allégresse, Leur coeur se réjouira en l'Éternel."],[10,8,"Je les sifflerai et les rassemblerai, car je les rachète, Et ils multiplieront comme ils multipliaient.","Je les sifflerai et les rassemblerai, car je les rachète, Et ils multiplieront comme ils multipliaient."],[10,9,"Je les disperserai parmi les peuples, Et au loin ils se souviendront de moi; Ils vivront avec leurs enfants, et ils reviendront.","Je les disperserai parmi les peuples, Et au loin ils se souviendront de moi; Ils vivront avec leurs enfants, et ils reviendront."],[10,10,"Je les ramènerai du pays d'Égypte, Et je les rassemblerai de l'Assyrie; Je les ferai venir au pays de Galaad et au Liban, Et l'espace ne leur suffira pas.","Je les ramènerai du pays d'Égypte, Et je les rassemblerai de l'Assyrie; Je les ferai venir au pays de Galaad et au Liban, Et l'espace ne leur suffira pas."],[10,11,"Il passera la mer de détresse, il frappera les flots de la mer, Et toutes les profondeurs du fleuve seront desséchées; L'orgueil de l'Assyrie sera abattu, Et le sceptre de l'Égypte disparaîtra.","Il passera la mer de détresse, il frappera les flots de la mer, Et toutes les profondeurs du fleuve seront desséchées; L'orgueil de l'Assyrie sera abattu, Et le sceptre de l'Égypte disparaîtra."],[10,12,"Je les fortifierai par l'Éternel, Et ils marcheront en son nom, Dit l'Éternel.","Je les fortifierai par l'Éternel, Et ils marcheront en son nom, Dit l'Éternel."],[11,1,"Liban, ouvre tes portes, Et que le feu dévore tes cèdres!","Liban, ouvre tes portes, Et que le feu dévore tes cèdres!"],[11,2,"Gémis, cyprès, car le cèdre est tombé, Ceux qui s'élevaient sont détruits! Gémissez, chênes de Basan, Car la forêt inaccessible est renversée!","Gémis, cyprès, car le cèdre est tombé, Ceux qui s'élevaient sont détruits! Gémissez, chênes de Basan, Car la forêt inaccessible est renversée!"],[11,3,"Les bergers poussent des cris lamentables, Parce que leur magnificence est détruite; Les lionceaux rugissent, Parce que l'orgueil du Jourdain est abattu.","Les bergers poussent des cris lamentables, Parce que leur magnificence est détruite; Les lionceaux rugissent, Parce que l'orgueil du Jourdain est abattu."],[11,4,"Ainsi parle l'Éternel, mon Dieu: Pais les brebis destinées à la boucherie!","Ainsi parle l'Éternel, mon Dieu: Pais les brebis destinées à la boucherie!"],[11,5,"Ceux qui les achètent les égorgent impunément; Celui qui les vend dit: Béni soit l'Éternel, car je m'enrichis! Et leurs pasteurs ne les épargnent pas.","Ceux qui les achètent les égorgent impunément; Celui qui les vend dit: Béni soit l'Éternel, car je m'enrichis! Et leurs pasteurs ne les épargnent pas."],[11,6,"Car je n'ai plus de pitié pour les habitants du pays, Dit l'Éternel; Et voici, je livre les hommes Aux mains les uns des autres et aux mains de leur roi; Ils ravageront le pays, Et je ne délivrerai pas de leurs mains.","Car je n'ai plus de pitié pour les habitants du pays, Dit l'Éternel; Et voici, je livre les hommes Aux mains les uns des autres et aux mains de leur roi; Ils ravageront le pays, Et je ne délivrerai pas de leurs mains."],[11,7,"Alors je me mis à paître les brebis destinées à la boucherie, assurément les plus misérables du troupeau. Je pris deux houlettes: j'appelai l'une Grâce, et j'appelai l'autre Union. Et je fis paître les brebis.","Alors je me mis à paître les brebis destinées à la boucherie, assurément les plus misérables du troupeau. Je pris deux houlettes: j'appelai l'une Grâce, et j'appelai l'autre Union. Et je fis paître les brebis."],[11,8,"J'exterminai les trois pasteurs en un mois; mon âme était impatiente à leur sujet, et leur âme avait aussi pour moi du dégoût.","J'exterminai les trois pasteurs en un mois; mon âme était impatiente à leur sujet, et leur âme avait aussi pour moi du dégoût."],[11,9,"Et je dis: Je ne vous paîtrai plus! Que celle qui va mourir meure, que celle qui va périr périsse, et que celles qui restent se dévorent les unes les autres!","Et je dis: Je ne vous paîtrai plus! Que celle qui va mourir meure, que celle qui va périr périsse, et que celles qui restent se dévorent les unes les autres!"],[11,10,"Je pris ma houlette Grâce, et je la brisai, pour rompre mon alliance que j'avais traitée avec tous les peuples.","Je pris ma houlette Grâce, et je la brisai, pour rompre mon alliance que j'avais traitée avec tous les peuples."],[11,11,"Elle fut rompue ce jour-là; et les malheureuses brebis, qui prirent garde à moi, reconnurent ainsi que c'était la parole de l'Éternel.","Elle fut rompue ce jour-là; et les malheureuses brebis, qui prirent garde à moi, reconnurent ainsi que c'était la parole de l'Éternel."],[11,12,"Je leur dis: Si vous le trouvez bon, donnez-moi mon salaire; sinon, ne le donnez pas. Et ils pesèrent pour mon salaire trente sicles d'argent.","Je leur dis: Si vous le trouvez bon, donnez-moi mon salaire; sinon, ne le donnez pas. Et ils pesèrent pour mon salaire trente sicles d'argent."],[11,13,"L'Éternel me dit: Jette-le au potier, ce prix magnifique auquel ils m'ont estimé! Et je pris les trente sicles d'argent, et je les jetai dans la maison de l'Éternel, pour le potier.","L'Éternel me dit: Jette-le au potier, ce prix magnifique auquel ils m'ont estimé! Et je pris les trente sicles d'argent, et je les jetai dans la maison de l'Éternel, pour le potier."],[11,14,"Puis je brisai ma seconde houlette Union, pour rompre la fraternité entre Juda et Israël.","Puis je brisai ma seconde houlette Union, pour rompre la fraternité entre Juda et Israël."],[11,15,"L'Éternel me dit: Prends encore l'équipage d'un pasteur insensé!","L'Éternel me dit: Prends encore l'équipage d'un pasteur insensé!"],[11,16,"Car voici, je susciterai dans le pays un pasteur qui n'aura pas souci des brebis qui périssent; il n'ira pas à la recherche des plus jeunes, il ne guérira pas les blessées, il ne soignera pas les saines; mais il dévorera la chair des plus grasses, et il déchirera jusqu'aux cornes de leurs pieds.","Car voici, je susciterai dans le pays un pasteur qui n'aura pas souci des brebis qui périssent; il n'ira pas à la recherche des plus jeunes, il ne guérira pas les blessées, il ne soignera pas les saines; mais il dévorera la chair des plus grasses, et il déchirera jusqu'aux cornes de leurs pieds."],[11,17,"Malheur au pasteur de néant, qui abandonne ses brebis! Que l'épée fonde sur son bras et sur son oeil droit! Que son bras se dessèche, Et que son oeil droit s'éteigne!","Malheur au pasteur de néant, qui abandonne ses brebis! Que l'épée fonde sur son bras et sur son oeil droit! Que son bras se dessèche, Et que son oeil droit s'éteigne!"],[12,1,"Oracle, parole de l'Éternel sur Israël. Ainsi parle l'Éternel, qui a étendu les cieux et fondé la terre, Et qui a formé l'esprit de l'homme au dedans de lui:","Oracle, parole de l'Éternel sur Israël. Ainsi parle l'Éternel, qui a étendu les cieux et fondé la terre, Et qui a formé l'esprit de l'homme au dedans de lui:"],[12,2,"Voici, je ferai de Jérusalem une coupe d'étourdissement Pour tous les peuples d'alentour, Et aussi pour Juda dans le siège de Jérusalem.","Voici, je ferai de Jérusalem une coupe d'étourdissement Pour tous les peuples d'alentour, Et aussi pour Juda dans le siège de Jérusalem."],[12,3,"En ce jour-là, je ferai de Jérusalem une pierre pesante pour tous les peuples; Tous ceux qui la soulèveront seront meurtris; Et toutes les nations de la terre s'assembleront contre elle.","En ce jour-là, je ferai de Jérusalem une pierre pesante pour tous les peuples; Tous ceux qui la soulèveront seront meurtris; Et toutes les nations de la terre s'assembleront contre elle."],[12,4,"En ce jour-là, dit l'Éternel, Je frapperai d'étourdissement tous les chevaux, Et de délire ceux qui les monteront; Mais j'aurai les yeux ouverts sur la maison de Juda, Quand je frapperai d'aveuglement tous les chevaux des peuples.","En ce jour-là, dit l'Éternel, Je frapperai d'étourdissement tous les chevaux, Et de délire ceux qui les monteront; Mais j'aurai les yeux ouverts sur la maison de Juda, Quand je frapperai d'aveuglement tous les chevaux des peuples."],[12,5,"Les chefs de Juda diront en leur coeur: Les habitants de Jérusalem sont notre force, Par l'Éternel des armées, leur Dieu.","Les chefs de Juda diront en leur coeur: Les habitants de Jérusalem sont notre force, Par l'Éternel des armées, leur Dieu."],[12,6,"En ce jour-là, je ferai des chefs de Juda Comme un foyer ardent parmi du bois, Comme une torche enflammée parmi des gerbes; Ils dévoreront à droite et à gauche tous les peuples d'alentour, Et Jérusalem restera à sa place, à Jérusalem.","En ce jour-là, je ferai des chefs de Juda Comme un foyer ardent parmi du bois, Comme une torche enflammée parmi des gerbes; Ils dévoreront à droite et à gauche tous les peuples d'alentour, Et Jérusalem restera à sa place, à Jérusalem."],[12,7,"L'Éternel sauvera d'abord les tentes de Juda, Afin que la gloire de la maison de David, La gloire des habitants de Jérusalem ne s'élève pas au-dessus de Juda.","L'Éternel sauvera d'abord les tentes de Juda, Afin que la gloire de la maison de David, La gloire des habitants de Jérusalem ne s'élève pas au-dessus de Juda."],[12,8,"En ce jour-là, l'Éternel protégera les habitants de Jérusalem, Et le faible parmi eux sera dans ce jour comme David; La maison de David sera comme Dieu, Comme l'ange de l'Éternel devant eux.","En ce jour-là, l'Éternel protégera les habitants de Jérusalem, Et le faible parmi eux sera dans ce jour comme David; La maison de David sera comme Dieu, Comme l'ange de l'Éternel devant eux."],[12,9,"En ce jour-là, Je m'efforcerai de détruire toutes les nations Qui viendront contre Jérusalem.","En ce jour-là, Je m'efforcerai de détruire toutes les nations Qui viendront contre Jérusalem."],[12,10,"Alors je répandrai sur la maison de David et sur les habitants de Jérusalem Un esprit de grâce et de supplication, Et ils tourneront les regards vers moi, celui qu'ils ont percé. Ils pleureront sur lui comme on pleure sur un fils unique, Ils pleureront amèrement sur lui comme on pleure sur un premier-né.","Alors je répandrai sur la maison de David et sur les habitants de Jérusalem Un esprit de grâce et de supplication, Et ils tourneront les regards vers moi, celui qu'ils ont percé. Ils pleureront sur lui comme on pleure sur un fils unique, Ils pleureront amèrement sur lui comme on pleure sur un premier-né."],[12,11,"En ce jour-là, le deuil sera grand à Jérusalem, Comme le deuil d'Hadadrimmon dans la vallée de Meguiddon.","En ce jour-là, le deuil sera grand à Jérusalem, Comme le deuil d'Hadadrimmon dans la vallée de Meguiddon."],[12,12,"Le pays sera dans le deuil, chaque famille séparément: La famille de la maison de David séparément, et les femmes à part; La famille de la maison de Nathan séparément, et les femmes à part;","Le pays sera dans le deuil, chaque famille séparément: La famille de la maison de David séparément, et les femmes à part; La famille de la maison de Nathan séparément, et les femmes à part;"],[12,13,"La famille de la maison de Lévi séparément, et les femmes à part; La famille de Schimeï séparément, et les femmes à part;","La famille de la maison de Lévi séparément, et les femmes à part; La famille de Schimeï séparément, et les femmes à part;"],[12,14,"Toutes les autres familles, chaque famille séparément, Et les femmes à part.","Toutes les autres familles, chaque famille séparément, Et les femmes à part."],[13,1,"En ce jour-là, une source sera ouverte Pour la maison de David et les habitants de Jérusalem, Pour le péché et pour l'impureté.","En ce jour-là, une source sera ouverte Pour la maison de David et les habitants de Jérusalem, Pour le péché et pour l'impureté."],[13,2,"En ce jour-là, dit l'Éternel des armées, J'exterminerai du pays les noms des idoles, Afin qu'on ne s'en souvienne plus; J'ôterai aussi du pays les prophètes et l'esprit d'impureté.","En ce jour-là, dit l'Éternel des armées, J'exterminerai du pays les noms des idoles, Afin qu'on ne s'en souvienne plus; J'ôterai aussi du pays les prophètes et l'esprit d'impureté."],[13,3,"Si quelqu'un prophétise encore, Son père et sa mère, qui l'ont engendré, lui diront: Tu ne vivras pas, car tu dis des mensonges au nom de l'Éternel! Et son père et sa mère, qui l'ont engendré, le transperceront Quand il prophétisera.","Si quelqu'un prophétise encore, Son père et sa mère, qui l'ont engendré, lui diront: Tu ne vivras pas, car tu dis des mensonges au nom de l'Éternel! Et son père et sa mère, qui l'ont engendré, le transperceront Quand il prophétisera."],[13,4,"En ce jour-là, les prophètes rougiront de leurs visions Quand ils prophétiseront, Et ils ne revêtiront plus un manteau de poil pour mentir.","En ce jour-là, les prophètes rougiront de leurs visions Quand ils prophétiseront, Et ils ne revêtiront plus un manteau de poil pour mentir."],[13,5,"Chacun d'eux dira: Je ne suis pas prophète, Je suis laboureur, Car on m'a acheté dès ma jeunesse.","Chacun d'eux dira: Je ne suis pas prophète, Je suis laboureur, Car on m'a acheté dès ma jeunesse."],[13,6,"Et si on lui demande: D'où viennent ces blessures que tu as aux mains? Il répondra: C'est dans la maison de ceux qui m'aimaient que je les ai reçues.","Et si on lui demande: D'où viennent ces blessures que tu as aux mains? Il répondra: C'est dans la maison de ceux qui m'aimaient que je les ai reçues."],[13,7,"Épée, lève-toi sur mon pasteur Et sur l'homme qui est mon compagnon! Dit l'Éternel des armées. Frappe le pasteur, et que les brebis se dispersent! Et je tournerai ma main vers les faibles.","Épée, lève-toi sur mon pasteur Et sur l'homme qui est mon compagnon! Dit l'Éternel des armées. Frappe le pasteur, et que les brebis se dispersent! Et je tournerai ma main vers les faibles."],[13,8,"Dans tout le pays, dit l'Éternel, Les deux tiers seront exterminés, périront, Et l'autre tiers restera.","Dans tout le pays, dit l'Éternel, Les deux tiers seront exterminés, périront, Et l'autre tiers restera."],[13,9,"Je mettrai ce tiers dans le feu, Et je le purifierai comme on purifie l'argent, Je l'éprouverai comme on éprouve l'or. Il invoquera mon nom, et je l'exaucerai; Je dirai: C'est mon peuple! Et il dira: L'Éternel est mon Dieu!","Je mettrai ce tiers dans le feu, Et je le purifierai comme on purifie l'argent, Je l'éprouverai comme on éprouve l'or. Il invoquera mon nom, et je l'exaucerai; Je dirai: C'est mon peuple! Et il dira: L'Éternel est mon Dieu!"],[14,1,"Voici, le jour de l'Éternel arrive, Et tes dépouilles seront partagées au milieu de toi.","Voici, le jour de l'Éternel arrive, Et tes dépouilles seront partagées au milieu de toi."],[14,2,"Je rassemblerai toutes les nations pour qu'elles attaquent Jérusalem; La ville sera prise, les maisons seront pillées, et les femmes violées; La moitié de la ville ira en captivité, Mais le reste du peuple ne sera pas exterminé de la ville.","Je rassemblerai toutes les nations pour qu'elles attaquent Jérusalem; La ville sera prise, les maisons seront pillées, et les femmes violées; La moitié de la ville ira en captivité, Mais le reste du peuple ne sera pas exterminé de la ville."],[14,3,"L'Éternel paraîtra, et il combattra ces nations, Comme il combat au jour de la bataille.","L'Éternel paraîtra, et il combattra ces nations, Comme il combat au jour de la bataille."],[14,4,"Ses pieds se poseront en ce jour sur la montagne des oliviers, Qui est vis-à-vis de Jérusalem, du côté de l'orient; La montagne des oliviers se fendra par le milieu, à l'orient et à l'occident, Et il se formera une très grande vallée: Une moitié de la montagne reculera vers le septentrion, Et une moitié vers le midi.","Ses pieds se poseront en ce jour sur la montagne des oliviers, Qui est vis-à-vis de Jérusalem, du côté de l'orient; La montagne des oliviers se fendra par le milieu, à l'orient et à l'occident, Et il se formera une très grande vallée: Une moitié de la montagne reculera vers le septentrion, Et une moitié vers le midi."],[14,5,"Vous fuirez alors dans la vallée de mes montagnes, Car la vallée des montagnes s'étendra jusqu'à Atzel; Vous fuirez comme vous avez fui devant le tremblement de terre, Au temps d'Ozias, roi de Juda. Et l'Éternel, mon Dieu, viendra, et tous ses saints avec lui.","Vous fuirez alors dans la vallée de mes montagnes, Car la vallée des montagnes s'étendra jusqu'à Atzel; Vous fuirez comme vous avez fui devant le tremblement de terre, Au temps d'Ozias, roi de Juda. Et l'Éternel, mon Dieu, viendra, et tous ses saints avec lui."],[14,6,"En ce jour-là, il n'y aura point de lumière; Il y aura du froid et de la glace.","En ce jour-là, il n'y aura point de lumière; Il y aura du froid et de la glace."],[14,7,"Ce sera un jour unique, connu de l'Éternel, Et qui ne sera ni jour ni nuit; Mais vers le soir la lumière paraîtra.","Ce sera un jour unique, connu de l'Éternel, Et qui ne sera ni jour ni nuit; Mais vers le soir la lumière paraîtra."],[14,8,"En ce jour-là, des eaux vives sortiront de Jérusalem, Et couleront moitié vers la mer orientale, Moitié vers la mer occidentale; Il en sera ainsi été et hiver.","En ce jour-là, des eaux vives sortiront de Jérusalem, Et couleront moitié vers la mer orientale, Moitié vers la mer occidentale; Il en sera ainsi été et hiver."],[14,9,"L'Éternel sera roi de toute la terre; En ce jour-là, l'Éternel sera le seul Éternel, Et son nom sera le seul nom.","L'Éternel sera roi de toute la terre; En ce jour-là, l'Éternel sera le seul Éternel, Et son nom sera le seul nom."],[14,10,"Tout le pays deviendra comme la plaine, de Guéba à Rimmon, Au midi de Jérusalem; Et Jérusalem sera élevée et restera à sa place, Depuis la porte de Benjamin jusqu'au lieu de la première porte, Jusqu'à la porte des angles, Et depuis la tour de Hananeel jusqu'aux pressoirs du roi.","Tout le pays deviendra comme la plaine, de Guéba à Rimmon, Au midi de Jérusalem; Et Jérusalem sera élevée et restera à sa place, Depuis la porte de Benjamin jusqu'au lieu de la première porte, Jusqu'à la porte des angles, Et depuis la tour de Hananeel jusqu'aux pressoirs du roi."],[14,11,"On habitera dans son sein, et il n'y aura plus d'interdit; Jérusalem sera en sécurité.","On habitera dans son sein, et il n'y aura plus d'interdit; Jérusalem sera en sécurité."],[14,12,"Voici la plaie dont l'Éternel frappera tous les peuples Qui auront combattu contre Jérusalem: Leur chair tombera en pourriture tandis qu'ils seront sur leurs pieds, Leurs yeux tomberont en pourriture dans leurs orbites, Et leur langue tombera en pourriture dans leur bouche.","Voici la plaie dont l'Éternel frappera tous les peuples Qui auront combattu contre Jérusalem: Leur chair tombera en pourriture tandis qu'ils seront sur leurs pieds, Leurs yeux tomberont en pourriture dans leurs orbites, Et leur langue tombera en pourriture dans leur bouche."],[14,13,"En ce jour-là, l'Éternel produira un grand trouble parmi eux; L'un saisira la main de l'autre, Et ils lèveront la main les uns sur les autres.","En ce jour-là, l'Éternel produira un grand trouble parmi eux; L'un saisira la main de l'autre, Et ils lèveront la main les uns sur les autres."],[14,14,"Juda combattra aussi dans Jérusalem, Et l'on amassera les richesses de toutes les nations d'alentour, L'or, l'argent, et des vêtements en très grand nombre.","Juda combattra aussi dans Jérusalem, Et l'on amassera les richesses de toutes les nations d'alentour, L'or, l'argent, et des vêtements en très grand nombre."],[14,15,"La plaie frappera de même les chevaux, Les mulets, les chameaux, les ânes, Et toutes les bêtes qui seront dans ces camps: Cette plaie sera semblable à l'autre.","La plaie frappera de même les chevaux, Les mulets, les chameaux, les ânes, Et toutes les bêtes qui seront dans ces camps: Cette plaie sera semblable à l'autre."],[14,16,"Tous ceux qui resteront de toutes les nations Venues contre Jérusalem Monteront chaque année Pour se prosterner devant le roi, l'Éternel des armées, Et pour célébrer la fête des tabernacles.","Tous ceux qui resteront de toutes les nations Venues contre Jérusalem Monteront chaque année Pour se prosterner devant le roi, l'Éternel des armées, Et pour célébrer la fête des tabernacles."],[14,17,"S'il y a des familles de la terre qui ne montent pas à Jérusalem Pour se prosterner devant le roi, l'Éternel des armées, La pluie ne tombera pas sur elles.","S'il y a des familles de la terre qui ne montent pas à Jérusalem Pour se prosterner devant le roi, l'Éternel des armées, La pluie ne tombera pas sur elles."],[14,18,"Si la famille d'Égypte ne monte pas, si elle ne vient pas, La pluie ne tombera pas sur elle; Elle sera frappée de la plaie dont l'Éternel frappera les nations Qui ne monteront pas pour célébrer la fête des tabernacles.","Si la famille d'Égypte ne monte pas, si elle ne vient pas, La pluie ne tombera pas sur elle; Elle sera frappée de la plaie dont l'Éternel frappera les nations Qui ne monteront pas pour célébrer la fête des tabernacles."],[14,19,"Ce sera le châtiment de l'Égypte, Le châtiment de toutes les nations Qui ne monteront pas pour célébrer la fête des tabernacles.","Ce sera le châtiment de l'Égypte, Le châtiment de toutes les nations Qui ne monteront pas pour célébrer la fête des tabernacles."],[14,20,"En ce jour-là, il sera écrit sur les clochettes des chevaux: Sainteté à L'Éternel! Et les chaudières dans la maison de l'Éternel Seront comme les coupes devant l'autel.","En ce jour-là, il sera écrit sur les clochettes des chevaux: Sainteté à L'Éternel! Et les chaudières dans la maison de l'Éternel Seront comme les coupes devant l'autel."],[14,21,"Toute chaudière à Jérusalem et dans Juda Sera consacrée à l'Éternel des armées; Tous ceux qui offriront des sacrifices viendront Et s'en serviront pour cuire les viandes; Et il n'y aura plus de marchands dans la maison de l'Éternel des armées, En ce jour-là.","Toute chaudière à Jérusalem et dans Juda Sera consacrée à l'Éternel des armées; Tous ceux qui offriront des sacrifices viendront Et s'en serviront pour cuire les viandes; Et il n'y aura plus de marchands dans la maison de l'Éternel des armées, En ce jour-là."]],"spa-rv1909":[[1,1,"EN el mesoctavo, en el añosegundode Darío, fuépalabrade Jehováá Zacaríasprofeta, hijode Berechîas, hijode Iddo, diciendo:","EN el mesoctavo, en el añosegundode Darío, fuépalabrade Jehováá Zacaríasprofeta, hijode Berechîas, hijode Iddo, diciendo:"],[1,2,"EnojóseJehovácon iracontravuestros padres.","EnojóseJehovácon iracontravuestros padres."],[1,3,"Les dirás pues: Asíha dichoJehováde los ejércitos: Volveosá mí, diceJehováde los ejércitos, y yo me volveréávosotros, ha dichoJehováde los ejércitos.","Les dirás pues: Asíha dichoJehováde los ejércitos: Volveosá mí, diceJehováde los ejércitos, y yo me volveréávosotros, ha dichoJehováde los ejércitos."],[1,4,"Noseáiscomo vuestros padres, álos cuales dieron voceslos primerosprofetas, diciendo: Asíha dichoJehováde los ejércitos: Volveosahorade vuestros maloscaminos, y de vuestras malasobras: y noatendieron, nimeescucharon, diceJehová.","Noseáiscomo vuestros padres, álos cuales dieron voceslos primerosprofetas, diciendo: Asíha dichoJehováde los ejércitos: Volveosahorade vuestros maloscaminos, y de vuestras malasobras: y noatendieron, nimeescucharon, diceJehová."],[1,5,"Vuestros padres, ¿dóndeestán? y los profetas¿han de vivirpara siempre?","Vuestros padres, ¿dóndeestán? y los profetas¿han de vivirpara siempre?"],[1,6,"Empero mis palabrasy mis ordenanzasquemandéá mis siervoslos profetas, ¿noalcanzaroná vuestros padres? Por eso se volvieronellos y dijeron: Como Jehováde los ejércitospensótratarnos conforme á nuestroscaminos, y conforme á nuestrasobras, asílo hizoconnosotros.","Empero mis palabrasy mis ordenanzasquemandéá mis siervoslos profetas, ¿noalcanzaroná vuestros padres? Por eso se volvieronellos y dijeron: Como Jehováde los ejércitospensótratarnos conforme á nuestroscaminos, y conforme á nuestrasobras, asílo hizoconnosotros."],[1,7,"A los veinticuatrodel mesundécimo, quees el mesde Sebath, en el añosegundode Darío, fuépalabrade Jehováá Zacaríasprofeta, hijode Berechîas, hijode Iddo, diciendo:","A los veinticuatrodel mesundécimo, quees el mesde Sebath, en el añosegundode Darío, fuépalabrade Jehováá Zacaríasprofeta, hijode Berechîas, hijode Iddo, diciendo:"],[1,8,"Vide noche, y he aquíun varónque cabalgabasobreun caballobermejo, el cualestabaentrelos mirtosquehabía en la hondura; y detrásde élhabía caballosbermejos, overos, y blancos.","Vide noche, y he aquíun varónque cabalgabasobreun caballobermejo, el cualestabaentrelos mirtosquehabía en la hondura; y detrásde élhabía caballosbermejos, overos, y blancos."],[1,9,"Entonces dije: ¿Quéson éstos, señormío? Y díjomeel ángelque hablabaconmigo: Yote enseñaréquéson éstos.","Entonces dije: ¿Quéson éstos, señormío? Y díjomeel ángelque hablabaconmigo: Yote enseñaréquéson éstos."],[1,10,"Y aquel varónque estabaentrelos mirtosrespondió, y dijo: Estosson los queJehováha enviadoá recorrerla tierra.","Y aquel varónque estabaentrelos mirtosrespondió, y dijo: Estosson los queJehováha enviadoá recorrerla tierra."],[1,11,"Y ellos hablaroná aquel ángelde Jehováque estabaentrelos mirtos, y dijeron: Hemos recorridola tierra, y he aquí, todala tierraestá reposaday quieta.","Y ellos hablaroná aquel ángelde Jehováque estabaentrelos mirtos, y dijeron: Hemos recorridola tierra, y he aquí, todala tierraestá reposaday quieta."],[1,12,"Y respondióel ángelde Jehová, y dijo: Oh Jehováde los ejércitos, ¿hastacuándonotendrás piedadde Jerusalem, y de las ciudadesde Judá, con las cualeshas estado airadoporespacio de setentaaños?","Y respondióel ángelde Jehová, y dijo: Oh Jehováde los ejércitos, ¿hastacuándonotendrás piedadde Jerusalem, y de las ciudadesde Judá, con las cualeshas estado airadoporespacio de setentaaños?"],[1,13,"Y Jehovárespondióbuenaspalabras, palabrasconsolatorias á aquel ángelque hablabaconmigo.","Y Jehovárespondióbuenaspalabras, palabrasconsolatorias á aquel ángelque hablabaconmigo."],[1,14,"Y díjomeel ángelque hablabaconmigo: Clamadiciendo: Asíha dichoJehováde los ejércitos: Celéá Jerusalemy á Sióncon grancelo:","Y díjomeel ángelque hablabaconmigo: Clamadiciendo: Asíha dichoJehováde los ejércitos: Celéá Jerusalemy á Sióncon grancelo:"],[1,15,"Y con grande enojo estoy airadocontralas gentesque están reposadas; porqueyoestaba enojadoun poco, y ellosayudaron para el mal.","Y con grande enojo estoy airadocontralas gentesque están reposadas; porqueyoestaba enojadoun poco, y ellosayudaron para el mal."],[1,16,"Por tanto, asíha dichoJehová: Yo me he tornado á Jerusalemcon miseraciones; en ella será edificadami casa, diceJehováde los ejércitos, y la plomadaserá tendidasobreJerusalem.","Por tanto, asíha dichoJehová: Yo me he tornado á Jerusalemcon miseraciones; en ella será edificadami casa, diceJehováde los ejércitos, y la plomadaserá tendidasobreJerusalem."],[1,17,"Clamaaún, diciendo: AsídiceJehováde los ejércitos: Aunserán ensanchadasmis ciudadespor la abundancia del bien; y aunconsolaráJehováá Sión, y escogerátodavíaá Jerusalem.","Clamaaún, diciendo: AsídiceJehováde los ejércitos: Aunserán ensanchadasmis ciudadespor la abundancia del bien; y aunconsolaráJehováá Sión, y escogerátodavíaá Jerusalem."],[1,18,"Después alcémis ojos, y miré, y he aquícuatrocuernos.","Después alcémis ojos, y miré, y he aquícuatrocuernos."],[1,19,"Y dijealángelque hablabaconmigo: ¿Quéson éstos? Y respondióme: Estosson los cuernosqueaventaron á Judá, á Israel, y á Jerusalem.","Y dijealángelque hablabaconmigo: ¿Quéson éstos? Y respondióme: Estosson los cuernosqueaventaron á Judá, á Israel, y á Jerusalem."],[1,20,"Mostrómeluego Jehovácuatrocarpinteros.","Mostrómeluego Jehovácuatrocarpinteros."],[1,21,"Y yo dije: ¿Quévienenéstosá hacer? Y respondióme, diciendo: Estos son los cuernosqueaventaron á Judá, tanto queningunoalzósu cabeza; mas éstoshan venidopara hacerlos temblar, para derribarlos cuernosde las gentes, quealzaronel cuernosobrela tierrade Judápara aventarla.","Y yo dije: ¿Quévienenéstosá hacer? Y respondióme, diciendo: Estos son los cuernosqueaventaron á Judá, tanto queningunoalzósu cabeza; mas éstoshan venidopara hacerlos temblar, para derribarlos cuernosde las gentes, quealzaronel cuernosobrela tierrade Judápara aventarla."],[2,1,"ALCÉdespués mis ojos, y miréy he aquíun varónque tenía en su manoun cordelde medir.","ALCÉdespués mis ojos, y miréy he aquíun varónque tenía en su manoun cordelde medir."],[2,2,"Y díjele: ¿A dóndevas? Y él merespondió: A medirá Jerusalem, para vercuánta es su anchura, y cuánta su longitud.","Y díjele: ¿A dóndevas? Y él merespondió: A medirá Jerusalem, para vercuánta es su anchura, y cuánta su longitud."],[2,3,"Y he aquí, salíaaquel ángelque hablabaconmigo, y otroángelle salióal encuentro,","Y he aquí, salíaaquel ángelque hablabaconmigo, y otroángelle salióal encuentro,"],[2,4,"Y díjole: Corre, hablaá este mozo, diciendo: Sin murosserá habitadaJerusalemá causa de la multitudde los hombres, y de las bestiasen mediode ella.","Y díjole: Corre, hablaá este mozo, diciendo: Sin murosserá habitadaJerusalemá causa de la multitudde los hombres, y de las bestiasen mediode ella."],[2,5,"Yoserépara ella, diceJehová, murode fuegoen derredor, y serépor gloriaen mediode ella.","Yoserépara ella, diceJehová, murode fuegoen derredor, y serépor gloriaen mediode ella."],[2,6,"Eh, eh, huidde la tierradel aquilón, diceJehová, puespor los cuatrovientosde los cielosos esparcí, diceJehová.","Eh, eh, huidde la tierradel aquilón, diceJehová, puespor los cuatrovientosde los cielosos esparcí, diceJehová."],[2,7,"OhSión, la que morascon la hijade Babilonia, escápate.","OhSión, la que morascon la hijade Babilonia, escápate."],[2,8,"Porqueasíha dichoJehováde los ejércitos: Después de la gloriame enviaráél á las gentesque os despojaron: porqueel que os toca, tocaá la niñade su ojo.","Porqueasíha dichoJehováde los ejércitos: Después de la gloriame enviaráél á las gentesque os despojaron: porqueel que os toca, tocaá la niñade su ojo."],[2,9,"Porquehe aquí yo alzomi manosobreellos, y serándespojoá sus siervos, y sabréisqueJehováde los ejércitosme envió.","Porquehe aquí yo alzomi manosobreellos, y serándespojoá sus siervos, y sabréisqueJehováde los ejércitosme envió."],[2,10,"Cantay alégrate, hijade Sión: porquehe aquí vengo, y moraréen mediode tí, ha dichoJehová.","Cantay alégrate, hijade Sión: porquehe aquí vengo, y moraréen mediode tí, ha dichoJehová."],[2,11,"Y uniránsemuchasgentesá Jehováen aquel día, y me seránpor pueblo, y moraréen mediode ti; y entonces conocerásqueJehováde los ejércitosme ha enviadoáti.","Y uniránsemuchasgentesá Jehováen aquel día, y me seránpor pueblo, y moraréen mediode ti; y entonces conocerásqueJehováde los ejércitosme ha enviadoáti."],[2,12,"Y Jehováposeeráá Judásu heredadenla tierrasanta, y escogeráaúná Jerusalem.","Y Jehováposeeráá Judásu heredadenla tierrasanta, y escogeráaúná Jerusalem."],[2,13,"Calletodacarnedelantede Jehová; porqueél se ha despertadode su santa morada.","Calletodacarnedelantede Jehová; porqueél se ha despertadode su santa morada."],[3,1,"Y MOSTRÓMEá Josué, el gransacerdote, el cual estabadelantedel ángelde Jehová; y Satánestabaásu mano derechapara serle adversario.","Y MOSTRÓMEá Josué, el gransacerdote, el cual estabadelantedel ángelde Jehová; y Satánestabaásu mano derechapara serle adversario."],[3,2,"Y dijoJehováá Satán: Jehováte reprenda, oh Satán; Jehová, que ha escogidoá Jerusalem, te reprenda. ¿Noes éstetizónarrebatadodel incendio?","Y dijoJehováá Satán: Jehováte reprenda, oh Satán; Jehová, que ha escogidoá Jerusalem, te reprenda. ¿Noes éstetizónarrebatadodel incendio?"],[3,3,"Y Josuéestabavestidode vestimentasviles, y estabadelantedel ángel.","Y Josuéestabavestidode vestimentasviles, y estabadelantedel ángel."],[3,4,"Y hablóel ángel, é intimó á los que estabandelantede sí, diciendo: Quitadleesas vestimentasviles. Y áél dijo: Miraque he hecho pasartu pecadodeti, y te he hecho vestirderopas degala.","Y hablóel ángel, é intimó á los que estabandelantede sí, diciendo: Quitadleesas vestimentasviles. Y áél dijo: Miraque he hecho pasartu pecadodeti, y te he hecho vestirderopas degala."],[3,5,"Después dijo: Ponganmitralimpiasobresu cabeza. Y pusieronuna mitralimpiasobresu cabeza, y vistiéronlede ropas. Y el ángelde Jehováestaba en pie.","Después dijo: Ponganmitralimpiasobresu cabeza. Y pusieronuna mitralimpiasobresu cabeza, y vistiéronlede ropas. Y el ángelde Jehováestaba en pie."],[3,6,"Y el ángelde Jehováprotestó al mismo Josué, diciendo:","Y el ángelde Jehováprotestó al mismo Josué, diciendo:"],[3,7,"AsídiceJehováde los ejércitos: Sianduvierespor mis caminos, y siguardaresmi ordenanza, tambiéntú gobernarásmi casa, tambiéntú guardarásmis atrios, y entreestos que aquí están te daréplaza.","AsídiceJehováde los ejércitos: Sianduvierespor mis caminos, y siguardaresmi ordenanza, tambiéntú gobernarásmi casa, tambiéntú guardarásmis atrios, y entreestos que aquí están te daréplaza."],[3,8,"Escuchapues ahora, Josuégransacerdote, tú, y tusamigosque se sientandelantede ti; porqueson varonessimbólicos: He aquí, yo traigoá mi siervo, el Pimpollo.","Escuchapues ahora, Josuégransacerdote, tú, y tusamigosque se sientandelantede ti; porqueson varonessimbólicos: He aquí, yo traigoá mi siervo, el Pimpollo."],[3,9,"Porquehe aquíaquella piedraquepusedelantede Josué; sobreesta únicapiedrahay sieteojos: he aquí, yo grabarésuescultura, diceJehováde los ejércitos, y quitaréel pecadode la tierraen undía.","Porquehe aquíaquella piedraquepusedelantede Josué; sobreesta únicapiedrahay sieteojos: he aquí, yo grabarésuescultura, diceJehováde los ejércitos, y quitaréel pecadode la tierraen undía."],[3,10,"En aquel día, diceJehováde los ejércitos, cada unode vosotros llamaráá sucompañerodebajode la vid, y debajode la higuera.","En aquel día, diceJehováde los ejércitos, cada unode vosotros llamaráá sucompañerodebajode la vid, y debajode la higuera."],[4,1,"Y VOLVIÓel ángelque hablabaconmigo, y despertómecomo un hombrequees despertadode su sueño.","Y VOLVIÓel ángelque hablabaconmigo, y despertómecomo un hombrequees despertadode su sueño."],[4,2,"Y díjome: ¿Quéves? Y respondí: He mirado, y he aquíun candelerotodode oro, con su vaso sobre su cabeza, y sus sietelámparasencimadel candelero; y sietecanales para las lámparasqueestán encimade él;","Y díjome: ¿Quéves? Y respondí: He mirado, y he aquíun candelerotodode oro, con su vaso sobre su cabeza, y sus sietelámparasencimadel candelero; y sietecanales para las lámparasqueestán encimade él;"],[4,3,"Y sobreél dosolivas, la unaá la derechadel vaso, y la otraásu izquierda.","Y sobreél dosolivas, la unaá la derechadel vaso, y la otraásu izquierda."],[4,4,"Proseguí, y habléáaquel ángelque hablabaconmigo, diciendo: ¿Quées esto, señormío?","Proseguí, y habléáaquel ángelque hablabaconmigo, diciendo: ¿Quées esto, señormío?"],[4,5,"Y el ángelque hablabaconmigo respondió, y díjome: ¿Nosabesquées esto? Y dije: No, señormío.","Y el ángelque hablabaconmigo respondió, y díjome: ¿Nosabesquées esto? Y dije: No, señormío."],[4,6,"Entonces respondióy hablóme, diciendo: Estaes palabrade JehovááZorobabel, en que se dice: Nocon ejército, nicon fuerza, sino con mi espíritu, ha dichoJehováde los ejércitos.","Entonces respondióy hablóme, diciendo: Estaes palabrade JehovááZorobabel, en que se dice: Nocon ejército, nicon fuerza, sino con mi espíritu, ha dichoJehováde los ejércitos."],[4,7,"¿Quiéneres tú, oh granmonte? Delantede Zorobabelserás reducidoá llanura: él sacarála primerapiedracon aclamacionesde Gracia, graciaá ella.","¿Quiéneres tú, oh granmonte? Delantede Zorobabelserás reducidoá llanura: él sacarála primerapiedracon aclamacionesde Gracia, graciaá ella."],[4,8,"Y fuépalabrade Jehováámí, diciendo:","Y fuépalabrade Jehováámí, diciendo:"],[4,9,"Las manosde Zorobabelecharán el fundamentoá esta casa, y sus manosla acabarán; y conocerásqueJehováde los ejércitosme envióávosotros.","Las manosde Zorobabelecharán el fundamentoá esta casa, y sus manosla acabarán; y conocerásqueJehováde los ejércitosme envióávosotros."],[4,10,"Porquelos quemenospreciaronel díade las pequeñecesse alegrarán, y veránla plomadaen la manode Zorobabel. Aquellas sietesonlos ojosde Jehováquerecorrenpor todala tierra.","Porquelos quemenospreciaronel díade las pequeñecesse alegrarán, y veránla plomadaen la manode Zorobabel. Aquellas sietesonlos ojosde Jehováquerecorrenpor todala tierra."],[4,11,"Hablémás, y díjele: ¿Quésignificanestas dosolivas á la derechadel candelero, y ásu izquierda?","Hablémás, y díjele: ¿Quésignificanestas dosolivas á la derechadel candelero, y ásu izquierda?"],[4,12,"Habléaún de nuevo, y díjele: ¿Quésignificanlas dosramasde olivasquepor mediode dostubosde oroviertendesí aceite comooro?","Habléaún de nuevo, y díjele: ¿Quésignificanlas dosramasde olivasquepor mediode dostubosde oroviertendesí aceite comooro?"],[4,13,"Y respondióme, diciendo: ¿Nosabesquées esto? Y dije: Señormío, no.","Y respondióme, diciendo: ¿Nosabesquées esto? Y dije: Señormío, no."],[4,14,"Y él dijo: Estosdoshijos de aceite son los que estándelantedel Señorde todala tierra.","Y él dijo: Estosdoshijos de aceite son los que estándelantedel Señorde todala tierra."],[5,1,"Y TORNÉME, y alcémis ojos, y miré, y he aquíun rolloque volaba.","Y TORNÉME, y alcémis ojos, y miré, y he aquíun rolloque volaba."],[5,2,"Y díjome: ¿Quéves? Y respondí: Veoun rolloque vuela, de veintecodosde largo, y diezcodosde ancho.","Y díjome: ¿Quéves? Y respondí: Veoun rolloque vuela, de veintecodosde largo, y diezcodosde ancho."],[5,3,"Díjomeentonces: Estaes la maldiciónque salesobrela hazde todala tierra; porquetodoaquel que hurta, (comoestáde la una parte del rollo) será destruído; y todoaquel que jura, (comoestáde la otraparte del rollo) será destruído.","Díjomeentonces: Estaes la maldiciónque salesobrela hazde todala tierra; porquetodoaquel que hurta, (comoestáde la una parte del rollo) será destruído; y todoaquel que jura, (comoestáde la otraparte del rollo) será destruído."],[5,4,"Yo la saqué, diceJehováde los ejércitos, y vendráá la casadel ladrón, y ála casadel que jurafalsamenteen mi nombre; y permanecerá en mediode su casa, y consumirála, con sus enmaderamientosy sus piedras.","Yo la saqué, diceJehováde los ejércitos, y vendráá la casadel ladrón, y ála casadel que jurafalsamenteen mi nombre; y permanecerá en mediode su casa, y consumirála, con sus enmaderamientosy sus piedras."],[5,5,"Y salióaquel ángelque hablabaconmigo, y díjome: Alzaahoratus ojos, y miraquées esto que sale.","Y salióaquel ángelque hablabaconmigo, y díjome: Alzaahoratus ojos, y miraquées esto que sale."],[5,6,"Y dije: ¿Quées? Y él dijo: Estees un ephaque sale. Además dijo: Estees el ojo de ellos en todala tierra.","Y dije: ¿Quées? Y él dijo: Estees un ephaque sale. Además dijo: Estees el ojo de ellos en todala tierra."],[5,7,"Y he aquí, traíanun talentode plomo, y unamujerestaba asentadaen mediode aquel epha.","Y he aquí, traíanun talentode plomo, y unamujerestaba asentadaen mediode aquel epha."],[5,8,"Y él dijo: Estaes la Maldad; y echóladentrodel epha, y echóla masade plomoensu boca.","Y él dijo: Estaes la Maldad; y echóladentrodel epha, y echóla masade plomoensu boca."],[5,9,"Alcéluego mis ojos, y miré, y he aquídosmujeresque salían, y traían vientoen sus alas, y tenían alascomo de cigüeña, y alzaronel ephaentrela tierray los cielos.","Alcéluego mis ojos, y miré, y he aquídosmujeresque salían, y traían vientoen sus alas, y tenían alascomo de cigüeña, y alzaronel ephaentrela tierray los cielos."],[5,10,"Y dijealángelque hablabaconmigo: ¿A dóndellevanel epha?","Y dijealángelque hablabaconmigo: ¿A dóndellevanel epha?"],[5,11,"Y él merespondió: Para que le sea edificadacasaen tierrade Shinar: y será asentadoy puestoallá sobresu asiento.","Y él merespondió: Para que le sea edificadacasaen tierrade Shinar: y será asentadoy puestoallá sobresu asiento."],[6,1,"Y TORNÉME, y alcémis ojosy miré, y he aquícuatrocarrosque salíande entredos montes; y aquellos monteseran de metal.","Y TORNÉME, y alcémis ojosy miré, y he aquícuatrocarrosque salíande entredos montes; y aquellos monteseran de metal."],[6,2,"En el primercarrohabía caballosbermejos, y en el segundocarrocaballosnegros,","En el primercarrohabía caballosbermejos, y en el segundocarrocaballosnegros,"],[6,3,"Y en el tercercarrocaballosblancos, y en el cuartocarrocaballosoverosruciorodados.","Y en el tercercarrocaballosblancos, y en el cuartocarrocaballosoverosruciorodados."],[6,4,"Respondíentonces, y dijealángelque conmigo hablaba: Señormío, ¿quées esto?","Respondíentonces, y dijealángelque conmigo hablaba: Señormío, ¿quées esto?"],[6,5,"Y el ángelme respondió, y díjome: Estosson los cuatrovientosde los cielos, que salende donde están delante delSeñorde todala tierra.","Y el ángelme respondió, y díjome: Estosson los cuatrovientosde los cielos, que salende donde están delante delSeñorde todala tierra."],[6,6,"En el que estaban los caballosnegros, salieronhaciala tierradel aquilón; y los blancossalierontrasellos; y lo overossalieronhaciala tierradel mediodía.","En el que estaban los caballosnegros, salieronhaciala tierradel aquilón; y los blancossalierontrasellos; y lo overossalieronhaciala tierradel mediodía."],[6,7,"Y los rucios salieron, y se afanaronpor irá recorrerla tierra. Y dijo: Id, recorredla tierra. Y recorrieronla tierra.","Y los rucios salieron, y se afanaronpor irá recorrerla tierra. Y dijo: Id, recorredla tierra. Y recorrieronla tierra."],[6,8,"Luego mellamó, y hablómediciendo: Mira, los que salieronhaciala tierradel aquilónhicieron reposarmi espírituen la tierradel aquilón.","Luego mellamó, y hablómediciendo: Mira, los que salieronhaciala tierradel aquilónhicieron reposarmi espírituen la tierradel aquilón."],[6,9,"Y fuéámí palabrade Jehová, diciendo:","Y fuéámí palabrade Jehová, diciendo:"],[6,10,"Tomade los del cautiverio, de Heldai, y de Tobías, y de Jedaía, los cualesvolvieronde Babilonia; y vendrás túen aquel día, y entrarásen casade Josíashijode Sefanías;","Tomade los del cautiverio, de Heldai, y de Tobías, y de Jedaía, los cualesvolvieronde Babilonia; y vendrás túen aquel día, y entrarásen casade Josíashijode Sefanías;"],[6,11,"Tomaráspues platay oro, y haráscoronas, y las pondrásen la cabezadel gransacerdoteJosué, hijode Josadac;","Tomaráspues platay oro, y haráscoronas, y las pondrásen la cabezadel gransacerdoteJosué, hijode Josadac;"],[6,12,"Y lehablarás, diciendo: Asíha habladoJehováde los ejércitos, diciendo: He aquíel varóncuyo nombrees Pimpollo, el cual germinaráde su lugar, y edificaráel templode Jehová:","Y lehablarás, diciendo: Asíha habladoJehováde los ejércitos, diciendo: He aquíel varóncuyo nombrees Pimpollo, el cual germinaráde su lugar, y edificaráel templode Jehová:"],[6,13,"Eledificaráeltemplode Jehová, y élllevarágloria, y se sentaráy dominaráensutrono, y será sacerdoteensusolio; y consejode pazseráentreambosá dos.","Eledificaráeltemplode Jehová, y élllevarágloria, y se sentaráy dominaráensutrono, y será sacerdoteensusolio; y consejode pazseráentreambosá dos."],[6,14,"Y Helem, y Tobías, y Jedaía, y Hen, hijode Sefanías, tendráncoronaspor memorialen el templode Jehová.","Y Helem, y Tobías, y Jedaía, y Hen, hijode Sefanías, tendráncoronaspor memorialen el templode Jehová."],[6,15,"Y los que están lejosvendrány edificaránen el templode Jehová, y conoceréisqueJehováde los ejércitosme ha enviadoávosotros. Y seráesto, sioyereisobedientesla vozde Jehovávuestro Dios.","Y los que están lejosvendrány edificaránen el templode Jehová, y conoceréisqueJehováde los ejércitosme ha enviadoávosotros. Y seráesto, sioyereisobedientesla vozde Jehovávuestro Dios."],[7,1,"Y ACONTECIÓen el añocuartodel reyDarío, que fuépalabrade JehovááZacaríasá los cuatrodel mesnoveno, que es Chisleu;","Y ACONTECIÓen el añocuartodel reyDarío, que fuépalabrade JehovááZacaríasá los cuatrodel mesnoveno, que es Chisleu;"],[7,2,"Cuando fué enviadoá la casa de Dios, Saraser, con Regem-melechy sus hombres, á implorarel favorde Jehová,","Cuando fué enviadoá la casa de Dios, Saraser, con Regem-melechy sus hombres, á implorarel favorde Jehová,"],[7,3,"Y á hablará los sacerdotesqueestaban en la casade Jehováde los ejércitos, y álos profetas, diciendo: ¿Lloraremosen el mesquinto? ¿haremos abstinenciacomo hemos hechoya algunosaños?","Y á hablará los sacerdotesqueestaban en la casade Jehováde los ejércitos, y álos profetas, diciendo: ¿Lloraremosen el mesquinto? ¿haremos abstinenciacomo hemos hechoya algunosaños?"],[7,4,"Fuépues ámí palabrade Jehováde los ejércitos, diciendo:","Fuépues ámí palabrade Jehováde los ejércitos, diciendo:"],[7,5,"Hablaá todoel pueblodel país, y álos sacerdotes, diciendo: Cuandoayunasteisy llorasteisen el quintoy en el séptimomesestossetentaaños, ¿habéis ayunadopara mí?","Hablaá todoel pueblodel país, y álos sacerdotes, diciendo: Cuandoayunasteisy llorasteisen el quintoy en el séptimomesestossetentaaños, ¿habéis ayunadopara mí?"],[7,6,"Y cuandocoméisy bebéis, ¿nocoméisy bebéispara vosotros?","Y cuandocoméisy bebéis, ¿nocoméisy bebéispara vosotros?"],[7,7,"¿Noson estaslas palabrasquepublicó Jehovápor manode los profetasprimeros, cuando Jerusalemestabahabitaday quieta, y sus ciudadesen sus alrededores, y el mediodíay la campiñase habitaban?","¿Noson estaslas palabrasquepublicó Jehovápor manode los profetasprimeros, cuando Jerusalemestabahabitaday quieta, y sus ciudadesen sus alrededores, y el mediodíay la campiñase habitaban?"],[7,8,"Y fuépalabrade JehovááZacarías, diciendo:","Y fuépalabrade JehovááZacarías, diciendo:"],[7,9,"AsíhablóJehováde los ejércitos, diciendo: Juzgadjuicio verdadero, y hacedmisericordiay piedadcada cualconsu hermano:","AsíhablóJehováde los ejércitos, diciendo: Juzgadjuicio verdadero, y hacedmisericordiay piedadcada cualconsu hermano:"],[7,10,"Noagraviéisá la viuda, ni al huérfano, ni al extranjero, ni al pobre; niningunopiensemalen su corazóncontra su hermano.","Noagraviéisá la viuda, ni al huérfano, ni al extranjero, ni al pobre; niningunopiensemalen su corazóncontra su hermano."],[7,11,"Empero no quisieronescuchar, antes dieronhombro rebelado, y agravaronsus oídospara no oir:","Empero no quisieronescuchar, antes dieronhombro rebelado, y agravaronsus oídospara no oir:"],[7,12,"Y pusieronsu corazóncomo diamante, para no oirla leyni las palabrasqueJehováde los ejércitosenviabapor su espíritu, por manode los profetasprimeros: fué, por tanto, hecho grandecastigoporJehováde los ejércitos.","Y pusieronsu corazóncomo diamante, para no oirla leyni las palabrasqueJehováde los ejércitosenviabapor su espíritu, por manode los profetasprimeros: fué, por tanto, hecho grandecastigoporJehováde los ejércitos."],[7,13,"Y acontecióque como él clamó, y noescucharon, así ellos clamaron, y yo noescuché, diceJehováde los ejércitos;","Y acontecióque como él clamó, y noescucharon, así ellos clamaron, y yo noescuché, diceJehováde los ejércitos;"],[7,14,"Antes los esparcí con torbellinoportodaslas gentesque ellos noconocían, y la tierrafué desoladatrasde ellos, sin quedar quien fueseni viniese; pues tornaronen asolamientoel paísdeseable.","Antes los esparcí con torbellinoportodaslas gentesque ellos noconocían, y la tierrafué desoladatrasde ellos, sin quedar quien fueseni viniese; pues tornaronen asolamientoel paísdeseable."],[8,1,"Y FUÉá mípalabrade Jehováde los ejércitos, diciendo:","Y FUÉá mípalabrade Jehováde los ejércitos, diciendo:"],[8,2,"Asíha dichoJehováde los ejércitos: Yo he celadoá Sióncon grandecelo, y con grandeirala celé.","Asíha dichoJehováde los ejércitos: Yo he celadoá Sióncon grandecelo, y con grandeirala celé."],[8,3,"AsídiceJehová: Yo he restituídoáSión, y moraréen mediode Jerusalem: y Jerusalemse llamaráCiudadde Verdad, y el montede Jehováde los ejércitos, Montede Santidad.","AsídiceJehová: Yo he restituídoáSión, y moraréen mediode Jerusalem: y Jerusalemse llamaráCiudadde Verdad, y el montede Jehováde los ejércitos, Montede Santidad."],[8,4,"Asíha dichoJehováde los ejércitos: Aunhan de morarviejosy viejasen las plazasde Jerusalem, y cadacual con bordónen su manopor la multitudde los días.","Asíha dichoJehováde los ejércitos: Aunhan de morarviejosy viejasen las plazasde Jerusalem, y cadacual con bordónen su manopor la multitudde los días."],[8,5,"Y las callesde la ciudadserán llenasde muchachosy muchachas, que jugaránen las calles.","Y las callesde la ciudadserán llenasde muchachosy muchachas, que jugaránen las calles."],[8,6,"AsídiceJehováde los ejércitos: Siesto parecerá dificultoso á los ojosdel resto de este puebloen aquellos días, ¿tambiénserá dificultoso delante de mis ojos? diceJehováde los ejércitos.","AsídiceJehováde los ejércitos: Siesto parecerá dificultoso á los ojosdel resto de este puebloen aquellos días, ¿tambiénserá dificultoso delante de mis ojos? diceJehováde los ejércitos."],[8,7,"Asíha dichoJehováde los ejércitos: He aquí, yo salvomi pueblode la tierradel oriente, y de la tierradonde se poneel sol;","Asíha dichoJehováde los ejércitos: He aquí, yo salvomi pueblode la tierradel oriente, y de la tierradonde se poneel sol;"],[8,8,"Y traerélos, y habitaránen mediode Jerusalem; y me seránpor pueblo, y yoseréá ellos por Dioscon verdady con justicia.","Y traerélos, y habitaránen mediode Jerusalem; y me seránpor pueblo, y yoseréá ellos por Dioscon verdady con justicia."],[8,9,"Asíha dichoJehováde los ejércitos: Esfuércensevuestras manos, de vosotros los que oísen estos díasestas palabrasde la bocade los profetas, desdeel díaque se echó el cimientoá la casade Jehováde los ejércitos, para edificarel templo.","Asíha dichoJehováde los ejércitos: Esfuércensevuestras manos, de vosotros los que oísen estos díasestas palabrasde la bocade los profetas, desdeel díaque se echó el cimientoá la casade Jehováde los ejércitos, para edificarel templo."],[8,10,"Porqueantesde estos díasnoha habidopagade hombre, ni pagade bestia, ni hubopazalguna para entrante ni para saliente, á causa delenemigo: y yo dejétodoslos hombres, cada cualcontra su compañero.","Porqueantesde estos díasnoha habidopagade hombre, ni pagade bestia, ni hubopazalguna para entrante ni para saliente, á causa delenemigo: y yo dejétodoslos hombres, cada cualcontra su compañero."],[8,11,"Mas ahoranolo harécon el resto de este pueblocomo en aquellos díaspasados, diceJehováde los ejércitos.","Mas ahoranolo harécon el resto de este pueblocomo en aquellos díaspasados, diceJehováde los ejércitos."],[8,12,"Porquehabrásimientede paz; la viddarásu fruto, y darásu productola tierra, y los cielosdaránsu rocío; y haré que el resto de este puebloposeatodoesto.","Porquehabrásimientede paz; la viddarásu fruto, y darásu productola tierra, y los cielosdaránsu rocío; y haré que el resto de este puebloposeatodoesto."],[8,13,"Y seráque como fuisteismaldiciónentre las gentes, oh casade Judáy casade Israel, asíos salvaré, y seréisbendición. Notemáis, mas esfuércensevuestras manos.","Y seráque como fuisteismaldiciónentre las gentes, oh casade Judáy casade Israel, asíos salvaré, y seréisbendición. Notemáis, mas esfuércensevuestras manos."],[8,14,"Porqueasíha dichoJehováde los ejércitos: Como penséhaceros malcuando vuestros padresme provocaron á ira, diceJehováde los ejércitos, y nome arrepentí;","Porqueasíha dichoJehováde los ejércitos: Como penséhaceros malcuando vuestros padresme provocaron á ira, diceJehováde los ejércitos, y nome arrepentí;"],[8,15,"Asítornando he pensadode hacer biená Jerusalemy á la casade Judáen estos días: notemáis.","Asítornando he pensadode hacer biená Jerusalemy á la casade Judáen estos días: notemáis."],[8,16,"Estasson las cosasquehabéis de hacer: Habladverdadcada cualconsu prójimo; juzgaden vuestras puertasverdady juicio de paz:","Estasson las cosasquehabéis de hacer: Habladverdadcada cualconsu prójimo; juzgaden vuestras puertasverdady juicio de paz:"],[8,17,"Y ningunode vosotros piensemalen su corazóncontra su prójimo, niaméisjuramentofalso: porquetodasestasson cosas queaborrezco, diceJehová.","Y ningunode vosotros piensemalen su corazóncontra su prójimo, niaméisjuramentofalso: porquetodasestasson cosas queaborrezco, diceJehová."],[8,18,"Y fuéámí palabrade Jehováde los ejércitos, diciendo:","Y fuéámí palabrade Jehováde los ejércitos, diciendo:"],[8,19,"Asíha dichoJehováde los ejércitos: El ayunodel cuartomes, y el ayunodel quinto, y el ayunodel séptimo, y el ayunodel décimo, se tornaráná la casade Judáen gozoy alegría, y en festivassolemnidades. Amadpues verdady paz.","Asíha dichoJehováde los ejércitos: El ayunodel cuartomes, y el ayunodel quinto, y el ayunodel séptimo, y el ayunodel décimo, se tornaráná la casade Judáen gozoy alegría, y en festivassolemnidades. Amadpues verdady paz."],[8,20,"Asíha dichoJehováde los ejércitos: Aunvendránpueblos, y moradoresde muchasciudades;","Asíha dichoJehováde los ejércitos: Aunvendránpueblos, y moradoresde muchasciudades;"],[8,21,"Y vendránlos moradoresde la unaá la otra, y dirán: Vamosá implorarel favorde Jehová, y á buscará Jehováde los ejércitos. Yotambiéniré.","Y vendránlos moradoresde la unaá la otra, y dirán: Vamosá implorarel favorde Jehová, y á buscará Jehováde los ejércitos. Yotambiéniré."],[8,22,"Y vendránmuchospueblosy fuertesnacionesá buscará Jehováde los ejércitosen Jerusalem, y á implorarel favorde Jehová.","Y vendránmuchospueblosy fuertesnacionesá buscará Jehováde los ejércitosen Jerusalem, y á implorarel favorde Jehová."],[8,23,"Asíha dichoJehováde los ejércitos: En aquellos díasaconteceráquediezhombresde todas las lenguas de las gentes, trabaránde la faldade un Judío, diciendo: Iremosconvosotros, porquehemos oídoqueDiosestá convosotros.","Asíha dichoJehováde los ejércitos: En aquellos díasaconteceráquediezhombresde todas las lenguas de las gentes, trabaránde la faldade un Judío, diciendo: Iremosconvosotros, porquehemos oídoqueDiosestá convosotros."],[9,1,"CARGAde la palabrade Jehovácontra tierrade Hadrach, y de Damascosu reposo: porqueá Jehováestán vueltos los ojosde los hombres, y de todaslas tribusde Israel.","CARGAde la palabrade Jehovácontra tierrade Hadrach, y de Damascosu reposo: porqueá Jehováestán vueltos los ojosde los hombres, y de todaslas tribusde Israel."],[9,2,"Y tambiénHamathtendrá término en ella; Tiroy Sidón, aunquemuysabia sea.","Y tambiénHamathtendrá término en ella; Tiroy Sidón, aunquemuysabia sea."],[9,3,"Bien que Tirose edificófortaleza, y amontonóplatacomo polvo, y orocomo lodode las calles,","Bien que Tirose edificófortaleza, y amontonóplatacomo polvo, y orocomo lodode las calles,"],[9,4,"He aquí, el Señorlaempobrecerá, y heriráen lamarsufortaleza, y ellaserá consumidade fuego.","He aquí, el Señorlaempobrecerá, y heriráen lamarsufortaleza, y ellaserá consumidade fuego."],[9,5,"Ascalónverá, y temerá; Gazatambién, y se doleráen granmanera: asimismo Ecrón, porquesu esperanzaserá confundida; y de Gazapereceráel rey, y Ascalónnoserá habitada.","Ascalónverá, y temerá; Gazatambién, y se doleráen granmanera: asimismo Ecrón, porquesu esperanzaserá confundida; y de Gazapereceráel rey, y Ascalónnoserá habitada."],[9,6,"Y habitaráen Asdodun extranjero, y yo talaré la soberbiade los Palestinos;","Y habitaráen Asdodun extranjero, y yo talaré la soberbiade los Palestinos;"],[9,7,"Y quitarésussangresde suboca, y susabominacionesde susdientes, y quedarán ellos tambiénpara nuestroDios, y seráncomo capitanesen Judá, y Ecróncomo el Jebuseo.","Y quitarésussangresde suboca, y susabominacionesde susdientes, y quedarán ellos tambiénpara nuestroDios, y seráncomo capitanesen Judá, y Ecróncomo el Jebuseo."],[9,8,"Y seré realde ejército á mi casa, á causa del que vay del que viene: y nopasarámássobreellos angustiador; porqueahoramiré con mis ojos.","Y seré realde ejército á mi casa, á causa del que vay del que viene: y nopasarámássobreellos angustiador; porqueahoramiré con mis ojos."],[9,9,"Alégratemucho, hijade Sión; da voces de júbilo, hijade Jerusalem: he aquí, tu reyvendráá ti, justoy salvador, humilde, y cabalgandosobreun asno, así sobreun pollinohijode asna.","Alégratemucho, hijade Sión; da voces de júbilo, hijade Jerusalem: he aquí, tu reyvendráá ti, justoy salvador, humilde, y cabalgandosobreun asno, así sobreun pollinohijode asna."],[9,10,"Y de Ephraimdestruirélos carros, y los caballosde Jerusalem; y los arcosde guerraserán quebrados: y hablarápazá las gentes; y su señoríoserá de marámar, y desde el ríohastalos finesde la tierra.","Y de Ephraimdestruirélos carros, y los caballosde Jerusalem; y los arcosde guerraserán quebrados: y hablarápazá las gentes; y su señoríoserá de marámar, y desde el ríohastalos finesde la tierra."],[9,11,"Y tútambiénpor la sangrede tupactoserás salva; yo he sacadotuspresosdel aljibe en que nohay agua.","Y tútambiénpor la sangrede tupactoserás salva; yo he sacadotuspresosdel aljibe en que nohay agua."],[9,12,"Tornaos á la fortaleza, oh presos de esperanza: hoytambiénos anuncioque os daré doblado.","Tornaos á la fortaleza, oh presos de esperanza: hoytambiénos anuncioque os daré doblado."],[9,13,"Porqueentesadohe para mí á Judácomoarco, henchí á Ephraim; y despertarétus hijos, oh Sión, contratus hijos, oh Grecia, y te pondrécomo espadade valiente.","Porqueentesadohe para mí á Judácomoarco, henchí á Ephraim; y despertarétus hijos, oh Sión, contratus hijos, oh Grecia, y te pondrécomo espadade valiente."],[9,14,"Y Jehováserá vistosobreellos, y su dardosaldrácomo relámpago: y el SeñorJehovátocarátrompeta, é irácomo torbellinosdel austro.","Y Jehováserá vistosobreellos, y su dardosaldrácomo relámpago: y el SeñorJehovátocarátrompeta, é irácomo torbellinosdel austro."],[9,15,"Jehováde los ejércitoslos amparará, y ellos devorarán, y sujetaráná las piedrasde la honda, y beberán, y harán estrépitocomo tomadosdel vino; y se llenaráncomo cuenco, ó como los lados del altar.","Jehováde los ejércitoslos amparará, y ellos devorarán, y sujetaráná las piedrasde la honda, y beberán, y harán estrépitocomo tomadosdel vino; y se llenaráncomo cuenco, ó como los lados del altar."],[9,16,"Y los salvaráen aquel díaJehovásu Dioscomo á rebañode supueblo: porqueserán engrandecidos ensutierracomo piedrasde corona.","Y los salvaráen aquel díaJehovásu Dioscomo á rebañode supueblo: porqueserán engrandecidos ensutierracomo piedrasde corona."],[9,17,"Porque¡cuántaes su bondad, y cuántasu hermosura! El trigoalegraráá los mancebos, y el vinoá las doncellas.","Porque¡cuántaes su bondad, y cuántasu hermosura! El trigoalegraráá los mancebos, y el vinoá las doncellas."],[10,1,"PEDIDá Jehoválluviaen la sazóntardía: Jehováharárelámpagos, y os darálluviaabundante, y hierbaen el campoá cada uno.","PEDIDá Jehoválluviaen la sazóntardía: Jehováharárelámpagos, y os darálluviaabundante, y hierbaen el campoá cada uno."],[10,2,"Porquelas imágeneshan habladovanidad, y los adivinoshan vistomentira, y han habladosueñosvanos, en vanoconsuelan: porlo cualse fueronellos como ovejas, fueron humilladosporquenotuvieronpastor.","Porquelas imágeneshan habladovanidad, y los adivinoshan vistomentira, y han habladosueñosvanos, en vanoconsuelan: porlo cualse fueronellos como ovejas, fueron humilladosporquenotuvieronpastor."],[10,3,"Contralos pastoresse ha encendidomi enojo, y castigarélos machos de cabrío: masJehováde los ejércitosvisitarásu rebaño, la casade Judá, y tornarálos como su caballode honoren la guerra.","Contralos pastoresse ha encendidomi enojo, y castigarélos machos de cabrío: masJehováde los ejércitosvisitarásu rebaño, la casade Judá, y tornarálos como su caballode honoren la guerra."],[10,4,"Deél saldráel ángulo, deél la clavija, deél el arcodela guerra, deél también todoapremiador.","Deél saldráel ángulo, deél la clavija, deél el arcodela guerra, deél también todoapremiador."],[10,5,"Y seráncomo valientes, que en la batallapisanal enemigoen el lodode las calles; y pelearán, porqueJehováserácon ellos; y los que cabalganen caballosseránavergonzados.","Y seráncomo valientes, que en la batallapisanal enemigoen el lodode las calles; y pelearán, porqueJehováserácon ellos; y los que cabalganen caballosseránavergonzados."],[10,6,"Porque yo fortificaréla casade Judá, y guardaréla casade José; y harélos volver, porquede ellos tendré piedad; y seráncomo si nolos hubiera desechado; porqueyosoy Jehovásu Dios, que los oiré.","Porque yo fortificaréla casade Judá, y guardaréla casade José; y harélos volver, porquede ellos tendré piedad; y seráncomo si nolos hubiera desechado; porqueyosoy Jehovásu Dios, que los oiré."],[10,7,"Y seráEphraimcomo valiente, y alegrarásesu corazóncomo de vino: sus hijostambién verány se alegrarán; su corazónse gozaráen Jehová.","Y seráEphraimcomo valiente, y alegrarásesu corazóncomo de vino: sus hijostambién verány se alegrarán; su corazónse gozaráen Jehová."],[10,8,"Yo les silbaréy los juntaré, porquelos he redimido; y serán multiplicadoscomo fueron multiplicados.","Yo les silbaréy los juntaré, porquelos he redimido; y serán multiplicadoscomo fueron multiplicados."],[10,9,"Bien que los sembraréentre los pueblos, aun en lejanospaíses se acordaránde mí; y viviránconsus hijos, y tornarán.","Bien que los sembraréentre los pueblos, aun en lejanospaíses se acordaránde mí; y viviránconsus hijos, y tornarán."],[10,10,"Porque yo los tornaréde la tierrade Egipto, y los recogeréde la Asiria; y traerélosála tierrade Galaady del Líbano, y noles bastará.","Porque yo los tornaréde la tierrade Egipto, y los recogeréde la Asiria; y traerélosála tierrade Galaady del Líbano, y noles bastará."],[10,11,"Y la tribulaciónpasarápor la mar, y en la marherirálas ondas, y se secarántodaslas honduras del río: y la soberbiadel Assurserá derribada, y se perderáel cetrode Egipto.","Y la tribulaciónpasarápor la mar, y en la marherirálas ondas, y se secarántodaslas honduras del río: y la soberbiadel Assurserá derribada, y se perderáel cetrode Egipto."],[10,12,"Y yo los fortificaréen Jehová, y caminaránen su nombre, diceJehová.","Y yo los fortificaréen Jehová, y caminaránen su nombre, diceJehová."],[11,1,"OH Líbano, abretus puertas, y queme fuegotus cedros.","OH Líbano, abretus puertas, y queme fuegotus cedros."],[11,2,"Aulla, oh haya, porqueel cedrocayó, porquelos magníficosson talados. Aullad, alcornoques de Basán, porqueel fuertemontees derribado.","Aulla, oh haya, porqueel cedrocayó, porquelos magníficosson talados. Aullad, alcornoques de Basán, porqueel fuertemontees derribado."],[11,3,"Vozde aullido de pastores, porquesu magnificenciaes asolada; estruendode bramidosde cachorrosde leones, porquela soberbia del Jordánes destruída.","Vozde aullido de pastores, porquesu magnificenciaes asolada; estruendode bramidosde cachorrosde leones, porquela soberbia del Jordánes destruída."],[11,4,"Asíha dichoJehovámi Dios: Apacientalas ovejasde la matanza;","Asíha dichoJehovámi Dios: Apacientalas ovejasde la matanza;"],[11,5,"A las cualesmataban sus compradores, y nose tenían por culpables; y el que las vendía, decía: Benditosea Jehová, que he enriquecido; nisus pastorestenían piedadde ellas.","A las cualesmataban sus compradores, y nose tenían por culpables; y el que las vendía, decía: Benditosea Jehová, que he enriquecido; nisus pastorestenían piedadde ellas."],[11,6,"Portanto, nomástendré piedaddelos moradoresdela tierra, diceJehová: porque he aquí, yoentregarélos hombres, cada cualen manodesu compañero, y en manodesu rey; y quebrantaránla tierra, y yonolibrarédesus manos.","Portanto, nomástendré piedaddelos moradoresdela tierra, diceJehová: porque he aquí, yoentregarélos hombres, cada cualen manodesu compañero, y en manodesu rey; y quebrantaránla tierra, y yonolibrarédesus manos."],[11,7,"Apacentépues las ovejasde la matanza, es á saber, los pobresdel rebaño. Y me tomédoscayados; al unopusepor nombre Suavidad, y al otroAtaduras; y apacentélas ovejas.","Apacentépues las ovejasde la matanza, es á saber, los pobresdel rebaño. Y me tomédoscayados; al unopusepor nombre Suavidad, y al otroAtaduras; y apacentélas ovejas."],[11,8,"E hice matar trespastoresen unmes, y mi almase angustiópor ellos, y tambiénel almade ellos me aborrecióá mí.","E hice matar trespastoresen unmes, y mi almase angustiópor ellos, y tambiénel almade ellos me aborrecióá mí."],[11,9,"Y dije: Noos apacentaré; la que muriere, muera; y la que se perdiere, se pierda; y las que quedaren, que cada unacomala carnede su compañera.","Y dije: Noos apacentaré; la que muriere, muera; y la que se perdiere, se pierda; y las que quedaren, que cada unacomala carnede su compañera."],[11,10,"Toméluego mi cayadoSuavidad, y quebrélo, para deshacer mi pactoqueconcertécontodoslos pueblos.","Toméluego mi cayadoSuavidad, y quebrélo, para deshacer mi pactoqueconcertécontodoslos pueblos."],[11,11,"Y fué deshechoen ese día, y asíconocieronlos pobresdel rebañoque miran á mí, queera palabrade Jehová.","Y fué deshechoen ese día, y asíconocieronlos pobresdel rebañoque miran á mí, queera palabrade Jehová."],[11,12,"Y díjeles: Sios parecebien, dadmemi salario; y sino, dejadlo. Y pesaronpara mi salariotreintapiezasde plata.","Y díjeles: Sios parecebien, dadmemi salario; y sino, dejadlo. Y pesaronpara mi salariotreintapiezasde plata."],[11,13,"Y díjomeJehová: Echaloaltesorero, hermosopreciocon queme han apreciado. Y tomélas treintapiezasde plata, y echélasen la casade Jehováaltesorero.","Y díjomeJehová: Echaloaltesorero, hermosopreciocon queme han apreciado. Y tomélas treintapiezasde plata, y echélasen la casade Jehováaltesorero."],[11,14,"Quebréluego el otromi cayadoAtaduras, para romperla hermandadentreJudáé Israel.","Quebréluego el otromi cayadoAtaduras, para romperla hermandadentreJudáé Israel."],[11,15,"Y díjomeJehová: Tomaaúnel hato de un pastorinsensato;","Y díjomeJehová: Tomaaúnel hato de un pastorinsensato;"],[11,16,"Porquehe aquí, yolevantopastoren la tierra, que novisitarálas perdidas, nobuscarála pequeña, nocurarála perniquebrada, nillevará la cansadaá cuestas; sino que se comerála carnede la gruesa, y romperásus uñas.","Porquehe aquí, yolevantopastoren la tierra, que novisitarálas perdidas, nobuscarála pequeña, nocurarála perniquebrada, nillevará la cansadaá cuestas; sino que se comerála carnede la gruesa, y romperásus uñas."],[11,17,"Mal haya el pastorde nada, que deja el ganado. Espadasobre su brazo, y sobre su ojoderecho: del todose secarásu brazo, y enteramenteserá su ojoderechooscurecido.","Mal haya el pastorde nada, que deja el ganado. Espadasobre su brazo, y sobre su ojoderecho: del todose secarásu brazo, y enteramenteserá su ojoderechooscurecido."],[12,1,"CARGAde la palabrade Jehováacerca deIsrael. Jehová, que extiendelos cielos, y fundala tierra, y formael espíritudel hombredentrodeél, ha dicho:","CARGAde la palabrade Jehováacerca deIsrael. Jehová, que extiendelos cielos, y fundala tierra, y formael espíritudel hombredentrodeél, ha dicho:"],[12,2,"He aquí, yo pongoá Jerusalempor vasode temblorá todoslos pueblosde alrededorcuando estén en el sitiocontraJudáy contraJerusalem.","He aquí, yo pongoá Jerusalempor vasode temblorá todoslos pueblosde alrededorcuando estén en el sitiocontraJudáy contraJerusalem."],[12,3,"Y será en aquel día, que yo pondréá Jerusalempor piedrapesadaá todoslos pueblos: todoslos que se la cargaren, serándespedazados, bien que todaslas gentesde la tierrase juntaráncontraella.","Y será en aquel día, que yo pondréá Jerusalempor piedrapesadaá todoslos pueblos: todoslos que se la cargaren, serándespedazados, bien que todaslas gentesde la tierrase juntaráncontraella."],[12,4,"En aquel día, diceJehová, herirécon aturdimientoá todocaballo, y con locuraal que en él sube; mas sobrela casade Judáabrirémis ojos, y á todocaballode los pueblosherirécon ceguera.","En aquel día, diceJehová, herirécon aturdimientoá todocaballo, y con locuraal que en él sube; mas sobrela casade Judáabrirémis ojos, y á todocaballode los pueblosherirécon ceguera."],[12,5,"Y los capitanesde Judádiránen su corazón: Mi fuerzason los moradoresde Jerusalemen Jehováde los ejércitossu Dios.","Y los capitanesde Judádiránen su corazón: Mi fuerzason los moradoresde Jerusalemen Jehováde los ejércitossu Dios."],[12,6,"En aquel díapondrélos capitanesde Judácomo un braserode fuegoen leña, y como una hachade fuegoen gavillas; y consumiráná diestray ásiniestratodoslos pueblosalrededor: y Jerusalemserá otra vez habitadaensulugar, en Jerusalem.","En aquel díapondrélos capitanesde Judácomo un braserode fuegoen leña, y como una hachade fuegoen gavillas; y consumiráná diestray ásiniestratodoslos pueblosalrededor: y Jerusalemserá otra vez habitadaensulugar, en Jerusalem."],[12,7,"Y libraráJehoválas tiendasde Judáprimero, porque la gloriade la casade Davidy del morador de Jerusalemnose engrandezcasobreJudá.","Y libraráJehoválas tiendasde Judáprimero, porque la gloriade la casade Davidy del morador de Jerusalemnose engrandezcasobreJudá."],[12,8,"En aquel díaJehovádefenderáalmoradorde Jerusalem: y el que entre ellos fuere flaco, en aquel tiemposerá como David; y la casade Davidcomo ángeles, como el ángelde Jehovádelantede ellos.","En aquel díaJehovádefenderáalmoradorde Jerusalem: y el que entre ellos fuere flaco, en aquel tiemposerá como David; y la casade Davidcomo ángeles, como el ángelde Jehovádelantede ellos."],[12,9,"Y será que en aquel díayo procuraréquebrantar todaslas gentesque vinierencontraJerusalem.","Y será que en aquel díayo procuraréquebrantar todaslas gentesque vinierencontraJerusalem."],[12,10,"Y derramarésobrela casade David, y sobrelos moradoresde Jerusalem, espíritude graciay de oración; y miraránámí, á quientraspasaron, y harán llantosobreél, como llantosobreunigénito, afligiéndosesobreél como quiense afligesobreprimogénito.","Y derramarésobrela casade David, y sobrelos moradoresde Jerusalem, espíritude graciay de oración; y miraránámí, á quientraspasaron, y harán llantosobreél, como llantosobreunigénito, afligiéndosesobreél como quiense afligesobreprimogénito."],[12,11,"En aquel díahabrá granllantoen Jerusalem, como el llantode Adadrimónen el vallede Megiddo.","En aquel díahabrá granllantoen Jerusalem, como el llantode Adadrimónen el vallede Megiddo."],[12,12,"Y la tierralamentará, cada linaje de por sí; el linaje de la casade Davidpor sí, y sus mujerespor sí; el linaje de la casade Nathánpor sí, y sus mujerespor sí;","Y la tierralamentará, cada linaje de por sí; el linaje de la casade Davidpor sí, y sus mujerespor sí; el linaje de la casade Nathánpor sí, y sus mujerespor sí;"],[12,13,"El linaje de la casade Levípor sí, y sus mujerespor sí; el linaje de Simeipor sí, y sus mujerespor sí;","El linaje de la casade Levípor sí, y sus mujerespor sí; el linaje de Simeipor sí, y sus mujerespor sí;"],[12,14,"Todoslos otroslinajes, los linajespor sí, y sus mujerespor sí.","Todoslos otroslinajes, los linajespor sí, y sus mujerespor sí."],[13,1,"EN aquel tiempohabrámanantialabiertopara la casade Davidy para los moradoresde Jerusalem, para el pecadoy la inmundicia.","EN aquel tiempohabrámanantialabiertopara la casade Davidy para los moradoresde Jerusalem, para el pecadoy la inmundicia."],[13,2,"Y será en aquel día, diceJehováde los ejércitos, que talarédela tierralos nombresdelas imágenes, y nuncamásvendrán en memoria: y tambiénharé talardela tierralos profetas, y espíritudeinmundicia.","Y será en aquel día, diceJehováde los ejércitos, que talarédela tierralos nombresdelas imágenes, y nuncamásvendrán en memoria: y tambiénharé talardela tierralos profetas, y espíritudeinmundicia."],[13,3,"Y seráque cuandoalgunomás profetizare, diránlesu padrey su madreque lo engendraron: Novivirás, porquehas habladomentiraen el nombrede Jehová: y su padrey su madreque lo engendraron, le alancearáncuandoprofetizare.","Y seráque cuandoalgunomás profetizare, diránlesu padrey su madreque lo engendraron: Novivirás, porquehas habladomentiraen el nombrede Jehová: y su padrey su madreque lo engendraron, le alancearáncuandoprofetizare."],[13,4,"Y seráen aquel tiempo, que todos los profetasse avergonzaránde suvisióncuando profetizaren; ninunca más se vestiránde mantovellosopara mentir.","Y seráen aquel tiempo, que todos los profetasse avergonzaránde suvisióncuando profetizaren; ninunca más se vestiránde mantovellosopara mentir."],[13,5,"Y dirá: Nosoy profeta; labradorsoy de la tierra: porque estoaprendí del hombre desde mi juventud.","Y dirá: Nosoy profeta; labradorsoy de la tierra: porque estoaprendí del hombre desde mi juventud."],[13,6,"Y lepreguntarán: ¿Quéheridasson éstas en tus manos? Y él responderá: Conellas fuí heridoen casade mis amigos.","Y lepreguntarán: ¿Quéheridasson éstas en tus manos? Y él responderá: Conellas fuí heridoen casade mis amigos."],[13,7,"Levántate, oh espada, sobre el pastor, y sobre el hombrecompañeromío, diceJehováde los ejércitos. Hiereal pastor, y se derramaránlas ovejas: mas tornarémi manosobrelos chiquitos.","Levántate, oh espada, sobre el pastor, y sobre el hombrecompañeromío, diceJehováde los ejércitos. Hiereal pastor, y se derramaránlas ovejas: mas tornarémi manosobrelos chiquitos."],[13,8,"Y aconteceráen todala tierra, diceJehová, que las dospartesserán taladasen ella, y se perderán; mas la terceraquedaráen ella.","Y aconteceráen todala tierra, diceJehová, que las dospartesserán taladasen ella, y se perderán; mas la terceraquedaráen ella."],[13,9,"Y meteréen el fuegola terceraparte, y los fundirécomo se fundela plata, y probaréloscomo se pruebael oro. Elinvocaráminombre, y yole oiré, y diré: Pueblomío; y éldirá: Jehováes miDios.","Y meteréen el fuegola terceraparte, y los fundirécomo se fundela plata, y probaréloscomo se pruebael oro. Elinvocaráminombre, y yole oiré, y diré: Pueblomío; y éldirá: Jehováes miDios."],[14,1,"HE aquí, el díade Jehováviene, y tus despojosserán repartidosen mediode ti.","HE aquí, el díade Jehováviene, y tus despojosserán repartidosen mediode ti."],[14,2,"Porque yo reunirétodaslas gentesen batalla contraJerusalem; y la ciudadserá tomada, y saqueadasserán las casas, y forzadaslas mujeres: y la mitadde la ciudadiráen cautiverio, mas el restodel pueblonoserá taladodela ciudad.","Porque yo reunirétodaslas gentesen batalla contraJerusalem; y la ciudadserá tomada, y saqueadasserán las casas, y forzadaslas mujeres: y la mitadde la ciudadiráen cautiverio, mas el restodel pueblonoserá taladodela ciudad."],[14,3,"Después saldráJehová, y pelearácon aquellas gentes, como peleóel díade la batalla.","Después saldráJehová, y pelearácon aquellas gentes, como peleóel díade la batalla."],[14,4,"Y afirmaránsesuspiesen aquel díasobreel montede las Olivas, queestá enfrente de Jerusalemá la parte de oriente: y el montede las Olivas, se partirápor mediode sí hacia el orientey hacia el occidente, haciendoun muygrandevalle; y la mitaddel montese apartaráhacia el norte, y la otra mitadhacia el mediodía.","Y afirmaránsesuspiesen aquel díasobreel montede las Olivas, queestá enfrente de Jerusalemá la parte de oriente: y el montede las Olivas, se partirápor mediode sí hacia el orientey hacia el occidente, haciendoun muygrandevalle; y la mitaddel montese apartaráhacia el norte, y la otra mitadhacia el mediodía."],[14,5,"Y huiréisal vallede los montes; porqueel vallede los montesllegaráhastaHasal; y huiréisde la manera quehuisteispor causa del terremotoen los díasde Uzzías, reyde Judá: y vendráJehovámi Dios, y conél todoslos santos.","Y huiréisal vallede los montes; porqueel vallede los montesllegaráhastaHasal; y huiréisde la manera quehuisteispor causa del terremotoen los díasde Uzzías, reyde Judá: y vendráJehovámi Dios, y conél todoslos santos."],[14,6,"Y aconteceráque en ese díanohabráluzclara, ni oscura.","Y aconteceráque en ese díanohabráluzclara, ni oscura."],[14,7,"Y seráundía, el cuales conocidode Jehová, que ni serádíaninoche; mas aconteceráque al tiempo de la tardehabráluz.","Y seráundía, el cuales conocidode Jehová, que ni serádíaninoche; mas aconteceráque al tiempo de la tardehabráluz."],[14,8,"Acontecerátambién en aquel día, que saldránde Jerusalemaguasvivas; la mitadde ellas haciala maroriental, y la otra mitadhaciala maroccidental, en veranoy en invierno.","Acontecerátambién en aquel día, que saldránde Jerusalemaguasvivas; la mitadde ellas haciala maroriental, y la otra mitadhaciala maroccidental, en veranoy en invierno."],[14,9,"Y Jehováseráreysobretodala tierra. En aquel díaJehováseráuno, y unosunombre.","Y Jehováseráreysobretodala tierra. En aquel díaJehováseráuno, y unosunombre."],[14,10,"Y todala tierrase tornará como llanuradesde Gabaahasta Rimmónal mediodíade Jerusalem: y ésta será enaltecida, y habitarseha en su lugardesde la puertade Benjamínhastael lugarde la puertaprimera, hastala puertade los rincones; y desde la torrede Hananeelhastalos lagaresdel rey.","Y todala tierrase tornará como llanuradesde Gabaahasta Rimmónal mediodíade Jerusalem: y ésta será enaltecida, y habitarseha en su lugardesde la puertade Benjamínhastael lugarde la puertaprimera, hastala puertade los rincones; y desde la torrede Hananeelhastalos lagaresdel rey."],[14,11,"Y moraránen ella, y nunca másserá anatema; sino que será Jerusalemhabitadaconfiadamente.","Y moraránen ella, y nunca másserá anatema; sino que será Jerusalemhabitadaconfiadamente."],[14,12,"Y estaserála plagacon queheriráJehováá todoslos pueblosquepelearoncontraJerusalem: la carnede ellosse disolveráestandoellossobresuspies, y se consumiránsusojosen suscuencas, y su lenguase les desharáen su boca.","Y estaserála plagacon queheriráJehováá todoslos pueblosquepelearoncontraJerusalem: la carnede ellosse disolveráestandoellossobresuspies, y se consumiránsusojosen suscuencas, y su lenguase les desharáen su boca."],[14,13,"Y aconteceráen aquel díaque habráen ellos granquebrantamientode Jehová; porque trabarácada unode la manode sucompañero, y sumanoecharácontrala manode sucompañero.","Y aconteceráen aquel díaque habráen ellos granquebrantamientode Jehová; porque trabarácada unode la manode sucompañero, y sumanoecharácontrala manode sucompañero."],[14,14,"Y Judátambiénpelearáen Jerusalem. Y serán reunidaslas riquezasde todaslas gentesde alrededor: oro, y plata, y ropasde vestir, en grandeabundancia.","Y Judátambiénpelearáen Jerusalem. Y serán reunidaslas riquezasde todaslas gentesde alrededor: oro, y plata, y ropasde vestir, en grandeabundancia."],[14,15,"Y tal como esto serála plagade los caballos, de los mulos, de los camellos, de los asnos, y de todaslas bestiasqueestuvierenen aquelloscampamentos.","Y tal como esto serála plagade los caballos, de los mulos, de los camellos, de los asnos, y de todaslas bestiasqueestuvierenen aquelloscampamentos."],[14,16,"Y todoslos que quedaren de las gentesque vinieroncontraJerusalem, subiránde añoen añoá adoraral Rey, Jehováde los ejércitos, y á celebrarla fiestade las Cabañas.","Y todoslos que quedaren de las gentesque vinieroncontraJerusalem, subiránde añoen añoá adoraral Rey, Jehováde los ejércitos, y á celebrarla fiestade las Cabañas."],[14,17,"Y acontecerá, quelos de las familiasde la tierraquenosubierená Jerusalemá adoraral Rey, Jehováde los ejércitos, novendrásobreellos lluvia.","Y acontecerá, quelos de las familiasde la tierraquenosubierená Jerusalemá adoraral Rey, Jehováde los ejércitos, novendrásobreellos lluvia."],[14,18,"Y sila familiade Egiptonosubiere, y noviniere, sobreellos nohabrá lluvia; vendrála plagacon queJehováherirálas gentesquenosubierená celebrarla fiestade las Cabañas.","Y sila familiade Egiptonosubiere, y noviniere, sobreellos nohabrá lluvia; vendrála plagacon queJehováherirálas gentesquenosubierená celebrarla fiestade las Cabañas."],[14,19,"Estaserála penadel pecadode Egipto, y del pecadode todaslas gentesquenosubierená celebrar la fiestade las Cabañas.","Estaserála penadel pecadode Egipto, y del pecadode todaslas gentesquenosubierená celebrar la fiestade las Cabañas."],[14,20,"En aquel tiempoestarásobrelas campanillasde los caballos: SANTIDADÁ JEHOVÁ; y las ollasen la casade Jehováseráncomo los tazonesdelante del altar.","En aquel tiempoestarásobrelas campanillasde los caballos: SANTIDADÁ JEHOVÁ; y las ollasen la casade Jehováseráncomo los tazonesdelante del altar."],[14,21,"Y serátodaollaen Jerusalemy en Judásantidadá Jehováde los ejércitos: y todoslos que sacrificaren, vendrány tomaránde ellas, y coceránen ellas: y nohabrámásCananeo alguno en la casade Jehováde los ejércitosen aquel tiempo.","Y serátodaollaen Jerusalemy en Judásantidadá Jehováde los ejércitos: y todoslos que sacrificaren, vendrány tomaránde ellas, y coceránen ellas: y nohabrámásCananeo alguno en la casade Jehováde los ejércitosen aquel tiempo."]],"rus-synodal":[[1,1,"В восьмом месяце, во второй год Дария, было слово Господне к Захарии, сыну Варахиину, сыну Аддову, пророку:","V vosʹmom mesâce, vo vtoroj god Dariâ, bylo slovo Gospodne k Zaharii, synu Varahiinu, synu Addovu, proroku:"],[1,2,"прогневался Господь на отцов ваших великим гневом,","prognevalsâ Gospodʹ na otcov vaših velikim gnevom,"],[1,3,"и ты скажи им: так говорит Господь Саваоф: обратитесь ко Мне, говорит Господь Саваоф, и Я обращусь к вам, говорит Господь Саваоф.","i ty skaži im: tak govorit Gospodʹ Savaof: obratitesʹ ko Mne, govorit Gospodʹ Savaof, i Â obraŝusʹ k vam, govorit Gospodʹ Savaof."],[1,4,"Не будьте такими, как отцы ваши, к которым взывали прежде бывшие пророки, говоря: «так говорит Господь Саваоф: обратитесь от злых путей ваших и от злых дел ваших»; но они не слушались и не внимали Мне, говорит Господь.","Ne budʹte takimi, kak otcy vaši, k kotorym vzyvali prežde byvšie proroki, govorâ: «tak govorit Gospodʹ Savaof: obratitesʹ ot zlyh putej vaših i ot zlyh del vaših»; no oni ne slušalisʹ i ne vnimali Mne, govorit Gospodʹ."],[1,5,"Отцы ваши – где они? да и пророки, будут ли они вечно жить?","Otcy vaši – gde oni? da i proroki, budut li oni večno žitʹ?"],[1,6,"Но слова Мои и определения Мои, которые заповедал Я рабам Моим, пророкам, разве не постигли отцов ваших? и они обращались и говорили: «как определил Господь Саваоф поступить с нами по нашим путям и по нашим делам, так и поступил с нами».","No slova Moi i opredeleniâ Moi, kotorye zapovedal Â rabam Moim, prorokam, razve ne postigli otcov vaših? i oni obraŝalisʹ i govorili: «kak opredelil Gospodʹ Savaof postupitʹ s nami po našim putâm i po našim delam, tak i postupil s nami»."],[1,7,"В двадцать четвертый день одиннадцатого месяца, – это месяц Шеват, – во второй год Дария, было слово Господне к Захарии, сыну Варахиину, сыну Аддову, пророку:","V dvadcatʹ četvertyj denʹ odinnadcatogo mesâca, – éto mesâc Ševat, – vo vtoroj god Dariâ, bylo slovo Gospodne k Zaharii, synu Varahiinu, synu Addovu, proroku:"],[1,8,"видел я ночью: вот, муж на рыжем коне стоит между миртами, которые в углублении, а позади него кони рыжие, пегие и белые, –","videl â nočʹû: vot, muž na ryžem kone stoit meždu mirtami, kotorye v uglublenii, a pozadi nego koni ryžie, pegie i belye, –"],[1,9,"и сказал я: кто они, господин мой? И сказал мне Ангел, говоривший со мною: я покажу тебе, кто они.","i skazal â: kto oni, gospodin moj? I skazal mne Angel, govorivšij so mnoû: â pokažu tebe, kto oni."],[1,10,"И отвечал муж, который стоял между миртами, и сказал: это те, которых Господь послал обойти землю.","I otvečal muž, kotoryj stoâl meždu mirtami, i skazal: éto te, kotoryh Gospodʹ poslal obojti zemlû."],[1,11,"И они отвечали Ангелу Господню, стоявшему между миртами, и сказали: обошли мы землю, и вот, вся земля населена и спокойна.","I oni otvečali Angelu Gospodnû, stoâvšemu meždu mirtami, i skazali: obošli my zemlû, i vot, vsâ zemlâ naselena i spokojna."],[1,12,"И отвечал Ангел Господень и сказал: Господи Вседержителю! Доколе Ты не умилосердишься над Иерусалимом и над городами Иуды, на которые Ты гневаешься вот уже семьдесят лет?","I otvečal Angel Gospodenʹ i skazal: Gospodi Vsederžitelû! Dokole Ty ne umiloserdišʹsâ nad Ierusalimom i nad gorodami Iudy, na kotorye Ty gnevaešʹsâ vot uže semʹdesât let?"],[1,13,"Тогда в ответ Ангелу, говорившему со мною, изрек Господь слова благие, слова утешительные.","Togda v otvet Angelu, govorivšemu so mnoû, izrek Gospodʹ slova blagie, slova utešitelʹnye."],[1,14,"И сказал мне Ангел, говоривший со мною: провозгласи и скажи: так говорит Господь Саваоф: возревновал Я о Иерусалиме и о Сионе ревностью великою;","I skazal mne Angel, govorivšij so mnoû: provozglasi i skaži: tak govorit Gospodʹ Savaof: vozrevnoval Â o Ierusalime i o Sione revnostʹû velikoû;"],[1,15,"и великим негодованием негодую на народы, живущие в покое; ибо, когда Я мало прогневался, они усилили зло.","i velikim negodovaniem negoduû na narody, živuŝie v pokoe; ibo, kogda Â malo prognevalsâ, oni usilili zlo."],[1,16,"Посему так говорит Господь: Я обращаюсь к Иерусалиму с милосердием; в нем соорудится дом Мой, говорит Господь Саваоф, и землемерная вервь протянется по Иерусалиму.","Posemu tak govorit Gospodʹ: Â obraŝaûsʹ k Ierusalimu s miloserdiem; v nem sooruditsâ dom Moj, govorit Gospodʹ Savaof, i zemlemernaâ vervʹ protânetsâ po Ierusalimu."],[1,17,"Еще провозгласи и скажи: так говорит Господь Саваоф: снова переполнятся города Мои добром, и утешит Господь Сион, и снова изберет Иерусалим.","Eŝe provozglasi i skaži: tak govorit Gospodʹ Savaof: snova perepolnâtsâ goroda Moi dobrom, i utešit Gospodʹ Sion, i snova izberet Ierusalim."],[1,18,"И поднял я глаза мои и увидел: вот четыре рога.","I podnâl â glaza moi i uvidel: vot četyre roga."],[1,19,"И сказал я Ангелу, говорившему со мною: что это? И он ответил мне: это роги, которые разбросали Иуду, Израиля и Иерусалим.","I skazal â Angelu, govorivšemu so mnoû: čto éto? I on otvetil mne: éto rogi, kotorye razbrosali Iudu, Izrailâ i Ierusalim."],[1,20,"Потом показал мне Господь четырех рабочих.","Potom pokazal mne Gospodʹ četyreh rabočih."],[1,21,"И сказал я: что они идут делать? Он сказал мне так: эти роги разбросали Иуду, так что никто не может поднять головы своей; а сии пришли устрашить их, сбить роги народов, поднявших рог свой против земли Иуды, чтобы рассеять ее.","I skazal â: čto oni idut delatʹ? On skazal mne tak: éti rogi razbrosali Iudu, tak čto nikto ne možet podnâtʹ golovy svoej; a sii prišli ustrašitʹ ih, sbitʹ rogi narodov, podnâvših rog svoj protiv zemli Iudy, čtoby rasseâtʹ ee."],[2,1,"И снова я поднял глаза мои и увидел: вот муж, у которого в руке землемерная вервь.","I snova â podnâl glaza moi i uvidel: vot muž, u kotorogo v ruke zemlemernaâ vervʹ."],[2,2,"Я спросил: куда ты идешь? и он сказал мне: измерять Иерусалим, чтобы видеть, какая широта его и какая длина его.","Â sprosil: kuda ty idešʹ? i on skazal mne: izmerâtʹ Ierusalim, čtoby videtʹ, kakaâ širota ego i kakaâ dlina ego."],[2,3,"И вот Ангел, говоривший со мною, выходит, а другой Ангел идет навстречу ему,","I vot Angel, govorivšij so mnoû, vyhodit, a drugoj Angel idet navstreču emu,"],[2,4,"и сказал он этому: иди скорее, скажи этому юноше: Иерусалим заселит окрестности по причине множества людей и скота в нем.","i skazal on étomu: idi skoree, skaži étomu ûnoše: Ierusalim zaselit okrestnosti po pričine množestva lûdej i skota v nem."],[2,5,"И Я буду для него, говорит Господь, огненною стеною вокруг него и прославлюсь посреди него.","I Â budu dlâ nego, govorit Gospodʹ, ognennoû stenoû vokrug nego i proslavlûsʹ posredi nego."],[2,6,"Эй, эй! бегите из северной страны, говорит Господь: ибо по четырем ветрам небесным Я рассеял вас, говорит Господь.","Éj, éj! begite iz severnoj strany, govorit Gospodʹ: ibo po četyrem vetram nebesnym Â rasseâl vas, govorit Gospodʹ."],[2,7,"Спасайся, Сион, обитающий у дочери Вавилона.","Spasajsâ, Sion, obitaûŝij u dočeri Vavilona."],[2,8,"Ибо так говорит Господь Саваоф: для славы Он послал Меня к народам, грабившим вас, ибо касающийся вас касается зеницы ока Его.","Ibo tak govorit Gospodʹ Savaof: dlâ slavy On poslal Menâ k narodam, grabivšim vas, ibo kasaûŝijsâ vas kasaetsâ zenicy oka Ego."],[2,9,"И вот, Я подниму руку Мою на них, и они сделаются добычею рабов своих, и тогда узнаете, что Господь Саваоф послал Меня.","I vot, Â podnimu ruku Moû na nih, i oni sdelaûtsâ dobyčeû rabov svoih, i togda uznaete, čto Gospodʹ Savaof poslal Menâ."],[2,10,"Ликуй и веселись, дщерь Сиона! Ибо вот, Я приду и поселюсь посреди тебя, говорит Господь.","Likuj i veselisʹ, dŝerʹ Siona! Ibo vot, Â pridu i poselûsʹ posredi tebâ, govorit Gospodʹ."],[2,11,"И прибегнут к Господу многие народы в тот день, и будут Моим народом; и Я поселюсь посреди тебя, и узнаешь, что Господь Саваоф послал Меня к тебе.","I pribegnut k Gospodu mnogie narody v tot denʹ, i budut Moim narodom; i Â poselûsʹ posredi tebâ, i uznaešʹ, čto Gospodʹ Savaof poslal Menâ k tebe."],[2,12,"Тогда Господь возьмет во владение Иуду, Свой удел на святой земле, и снова изберет Иерусалим.","Togda Gospodʹ vozʹmet vo vladenie Iudu, Svoj udel na svâtoj zemle, i snova izberet Ierusalim."],[2,13,"Да молчит всякая плоть пред лицом Господа! Ибо Он поднимается от святого жилища Своего.","Da molčit vsâkaâ plotʹ pred licom Gospoda! Ibo On podnimaetsâ ot svâtogo žiliŝa Svoego."],[3,1,"И показал он мне Иисуса, великого иерея, стоящего перед Ангелом Господним, и сатану, стоящего по правую руку его, чтобы противодействовать ему.","I pokazal on mne Iisusa, velikogo iereâ, stoâŝego pered Angelom Gospodnim, i satanu, stoâŝego po pravuû ruku ego, čtoby protivodejstvovatʹ emu."],[3,2,"И сказал Господь сатане: Господь да запретит тебе, сатана, да запретит тебе Господь, избравший Иерусалим! не головня ли он, исторгнутая из огня?","I skazal Gospodʹ satane: Gospodʹ da zapretit tebe, satana, da zapretit tebe Gospodʹ, izbravšij Ierusalim! ne golovnâ li on, istorgnutaâ iz ognâ?"],[3,3,"Иисус же одет был в запятнанные одежды и стоял перед Ангелом,","Iisus že odet byl v zapâtnannye odeždy i stoâl pered Angelom,"],[3,4,"который отвечал и сказал стоявшим перед ним так: снимите с него запятнанные одежды. А ему самому сказал: смотри, Я снял с тебя вину твою и облекаю тебя в одежды торжественные.","kotoryj otvečal i skazal stoâvšim pered nim tak: snimite s nego zapâtnannye odeždy. A emu samomu skazal: smotri, Â snâl s tebâ vinu tvoû i oblekaû tebâ v odeždy toržestvennye."],[3,5,"И сказал: возложите на голову его чистый кидар. И возложили чистый кидар на голову его и облекли его в одежду; Ангел же Господень стоял.","I skazal: vozložite na golovu ego čistyj kidar. I vozložili čistyj kidar na golovu ego i oblekli ego v odeždu; Angel že Gospodenʹ stoâl."],[3,6,"И засвидетельствовал Ангел Господень и сказал Иисусу:","I zasvidetelʹstvoval Angel Gospodenʹ i skazal Iisusu:"],[3,7,"так говорит Господь Саваоф: если ты будешь ходить по Моим путям и если будешь на страже Моей, то будешь судить дом Мой и наблюдать за дворами Моими. Я дам тебе ходить между сими, стоящими здесь.","tak govorit Gospodʹ Savaof: esli ty budešʹ hoditʹ po Moim putâm i esli budešʹ na straže Moej, to budešʹ suditʹ dom Moj i nablûdatʹ za dvorami Moimi. Â dam tebe hoditʹ meždu simi, stoâŝimi zdesʹ."],[3,8,"Выслушай же, Иисус, иерей великий, ты и собратия твои, сидящие перед тобою, мужи знаменательные: вот, Я привожу раба Моего, ОТРАСЛЬ.","Vyslušaj že, Iisus, ierej velikij, ty i sobratiâ tvoi, sidâŝie pered toboû, muži znamenatelʹnye: vot, Â privožu raba Moego, OTRASLʹ̱."],[3,9,"Ибо вот тот камень, который Я полагаю перед Иисусом; на этом одном камне семь очей; вот, Я вырежу на нем начертания его, говорит Господь Саваоф, и изглажу грех земли сей в один день.","Ibo vot tot kamenʹ, kotoryj Â polagaû pered Iisusom; na étom odnom kamne semʹ očej; vot, Â vyrežu na nem načertaniâ ego, govorit Gospodʹ Savaof, i izglažu greh zemli sej v odin denʹ."],[3,10,"В тот день, говорит Господь Саваоф, будете друг друга приглашать под виноград и под смоковницу.","V tot denʹ, govorit Gospodʹ Savaof, budete drug druga priglašatʹ pod vinograd i pod smokovnicu."],[4,1,"И возвратился тот Ангел, который говорил со мною, и пробудил меня, как пробуждают человека от сна его.","I vozvratilsâ tot Angel, kotoryj govoril so mnoû, i probudil menâ, kak probuždaût čeloveka ot sna ego."],[4,2,"И сказал он мне: что ты видишь? И отвечал я: вижу, вот светильник весь из золота, и чашечка для елея наверху его, и семь лампад на нем, и по семи трубочек у лампад, которые наверху его;","I skazal on mne: čto ty vidišʹ? I otvečal â: vižu, vot svetilʹnik vesʹ iz zolota, i čašečka dlâ eleâ naverhu ego, i semʹ lampad na nem, i po semi truboček u lampad, kotorye naverhu ego;"],[4,3,"и две маслины на нем, одна с правой стороны чашечки, другая с левой стороны ее.","i dve masliny na nem, odna s pravoj storony čašečki, drugaâ s levoj storony ee."],[4,4,"И отвечал я и сказал Ангелу, говорившему со мною: что это, господин мой?","I otvečal â i skazal Angelu, govorivšemu so mnoû: čto éto, gospodin moj?"],[4,5,"И Ангел, говоривший со мною, отвечал и сказал мне: ты не знаешь, что это? И сказал я: не знаю, господин мой.","I Angel, govorivšij so mnoû, otvečal i skazal mne: ty ne znaešʹ, čto éto? I skazal â: ne znaû, gospodin moj."],[4,6,"Тогда отвечал он и сказал мне так: это слово Господа к Зоровавелю, выражающее: не воинством и не силою, но Духом Моим, говорит Господь Саваоф.","Togda otvečal on i skazal mne tak: éto slovo Gospoda k Zorovavelû, vyražaûŝee: ne voinstvom i ne siloû, no Duhom Moim, govorit Gospodʹ Savaof."],[4,7,"Кто ты, великая гора, перед Зоровавелем? ты – равнина, и вынесет он краеугольный камень при шумных восклицаниях: «благодать, благодать на нем!»","Kto ty, velikaâ gora, pered Zorovavelem? ty – ravnina, i vyneset on kraeugolʹnyj kamenʹ pri šumnyh vosklicaniâh: «blagodatʹ, blagodatʹ na nem!»"],[4,8,"И было ко мне слово Господне:","I bylo ko mne slovo Gospodne:"],[4,9,"руки Зоровавеля положили основание дому сему; его руки и окончат его, и узнаешь, что Господь Саваоф послал Меня к вам.","ruki Zorovavelâ položili osnovanie domu semu; ego ruki i okončat ego, i uznaešʹ, čto Gospodʹ Savaof poslal Menâ k vam."],[4,10,"Ибо кто может считать день сей маловажным, когда радостно смотрят на строительный отвес в руках Зоровавеля те семь, – это очи Господа, которые объемлют взором всю землю?","Ibo kto možet sčitatʹ denʹ sej malovažnym, kogda radostno smotrât na stroitelʹnyj otves v rukah Zorovavelâ te semʹ, – éto oči Gospoda, kotorye obʺemlût vzorom vsû zemlû?"],[4,11,"Тогда отвечал я и сказал ему: что значат те две маслины с правой стороны светильника и с левой стороны его?","Togda otvečal â i skazal emu: čto značat te dve masliny s pravoj storony svetilʹnika i s levoj storony ego?"],[4,12,"Вторично стал я говорить и сказал ему: что значат две масличные ветви, которые через две золотые трубочки изливают из себя золото?","Vtorično stal â govoritʹ i skazal emu: čto značat dve masličnye vetvi, kotorye čerez dve zolotye trubočki izlivaût iz sebâ zoloto?"],[4,13,"И сказал он мне: ты не знаешь, что это? Я отвечал: не знаю, господин мой.","I skazal on mne: ty ne znaešʹ, čto éto? Â otvečal: ne znaû, gospodin moj."],[4,14,"И сказал он: это два помазанные елеем, предстоящие Господу всей земли.","I skazal on: éto dva pomazannye eleem, predstoâŝie Gospodu vsej zemli."],[5,1,"И опять поднял я глаза мои и увидел: вот летит свиток.","I opâtʹ podnâl â glaza moi i uvidel: vot letit svitok."],[5,2,"И сказал он мне: что видишь ты? Я отвечал: вижу летящий свиток; длина его двадцать локтей, а ширина его десять локтей.","I skazal on mne: čto vidišʹ ty? Â otvečal: vižu letâŝij svitok; dlina ego dvadcatʹ loktej, a širina ego desâtʹ loktej."],[5,3,"Он сказал мне: это проклятие, исходящее на лицо всей земли; ибо всякий, кто крадет, будет истреблен, как написано на одной стороне, и всякий, клянущийся ложно, истреблен будет, как написано на другой стороне.","On skazal mne: éto proklâtie, ishodâŝee na lico vsej zemli; ibo vsâkij, kto kradet, budet istreblen, kak napisano na odnoj storone, i vsâkij, klânuŝijsâ ložno, istreblen budet, kak napisano na drugoj storone."],[5,4,"Я навел его, говорит Господь Саваоф, и оно войдет в дом татя и в дом клянущегося Моим именем ложно, и пребудет в доме его, и истребит его, и дерева его, и камни его.","Â navel ego, govorit Gospodʹ Savaof, i ono vojdet v dom tatâ i v dom klânuŝegosâ Moim imenem ložno, i prebudet v dome ego, i istrebit ego, i dereva ego, i kamni ego."],[5,5,"И вышел Ангел, говоривший со мною, и сказал мне: подними еще глаза твои и посмотри, что это выходит?","I vyšel Angel, govorivšij so mnoû, i skazal mne: podnimi eŝe glaza tvoi i posmotri, čto éto vyhodit?"],[5,6,"Когда же я сказал: что это? Он отвечал: это выходит ефа, и сказал: это образ их по всей земле.","Kogda že â skazal: čto éto? On otvečal: éto vyhodit efa, i skazal: éto obraz ih po vsej zemle."],[5,7,"И вот, кусок свинца поднялся, и там сидела одна женщина посреди ефы.","I vot, kusok svinca podnâlsâ, i tam sidela odna ženŝina posredi efy."],[5,8,"И сказал он: эта женщина – само нечестие, и бросил ее в средину ефы, а на отверстие ее бросил свинцовый кусок.","I skazal on: éta ženŝina – samo nečestie, i brosil ee v sredinu efy, a na otverstie ee brosil svincovyj kusok."],[5,9,"И поднял я глаза мои и увидел: вот, появились две женщины, и ветер был в крыльях их, и крылья у них как крылья аиста; и подняли они ефу и понесли ее между землею и небом.","I podnâl â glaza moi i uvidel: vot, poâvilisʹ dve ženŝiny, i veter byl v krylʹâh ih, i krylʹâ u nih kak krylʹâ aista; i podnâli oni efu i ponesli ee meždu zemleû i nebom."],[5,10,"И сказал я Ангелу, говорившему со мною: куда несут они эту ефу?","I skazal â Angelu, govorivšemu so mnoû: kuda nesut oni étu efu?"],[5,11,"Тогда сказал он мне: чтобы устроить для нее дом в земле Сеннаар, и когда будет все приготовлено, то она поставится там на своей основе.","Togda skazal on mne: čtoby ustroitʹ dlâ nee dom v zemle Sennaar, i kogda budet vse prigotovleno, to ona postavitsâ tam na svoej osnove."],[6,1,"И опять поднял я глаза мои и вижу: вот, четыре колесницы выходят из ущелья между двумя горами; и горы те были горы медные.","I opâtʹ podnâl â glaza moi i vižu: vot, četyre kolesnicy vyhodât iz uŝelʹâ meždu dvumâ gorami; i gory te byli gory mednye."],[6,2,"В первой колеснице кони рыжие, а во второй колеснице кони вороные;","V pervoj kolesnice koni ryžie, a vo vtoroj kolesnice koni voronye;"],[6,3,"в третьей колеснице кони белые, а в четвертой колеснице кони пегие, сильные.","v tretʹej kolesnice koni belye, a v četvertoj kolesnice koni pegie, silʹnye."],[6,4,"И, начав речь, я сказал Ангелу, говорившему со мною: что это, господин мой?","I, načav rečʹ, â skazal Angelu, govorivšemu so mnoû: čto éto, gospodin moj?"],[6,5,"И отвечал Ангел и сказал мне: это выходят четыре духа небесных, которые предстоят пред Господом всей земли.","I otvečal Angel i skazal mne: éto vyhodât četyre duha nebesnyh, kotorye predstoât pred Gospodom vsej zemli."],[6,6,"Вороные кони там выходят к стране северной и белые идут за ними, а пегие идут к стране полуденной.","Voronye koni tam vyhodât k strane severnoj i belye idut za nimi, a pegie idut k strane poludennoj."],[6,7,"И сильные вышли и стремились идти, чтобы пройти землю; и он сказал: идите, пройдите землю, – и они прошли землю.","I silʹnye vyšli i stremilisʹ idti, čtoby projti zemlû; i on skazal: idite, projdite zemlû, – i oni prošli zemlû."],[6,8,"Тогда позвал он меня и сказал мне так: смотри, вышедшие в землю северную успокоили дух Мой на земле северной.","Togda pozval on menâ i skazal mne tak: smotri, vyšedšie v zemlû severnuû uspokoili duh Moj na zemle severnoj."],[6,9,"И было слово Господне ко мне:","I bylo slovo Gospodne ko mne:"],[6,10,"возьми у пришедших из плена, у Хелдая, у Товии и у Иедая, и пойди в тот самый день, пойди в дом Иосии, сына Софониева, куда они пришли из Вавилона,","vozʹmi u prišedših iz plena, u Heldaâ, u Tovii i u Iedaâ, i pojdi v tot samyj denʹ, pojdi v dom Iosii, syna Sofonieva, kuda oni prišli iz Vavilona,"],[6,11,"возьми у них серебро и золото и сделай венцы, и возложи на голову Иисуса, сына Иоседекова, иерея великого,","vozʹmi u nih serebro i zoloto i sdelaj vency, i vozloži na golovu Iisusa, syna Iosedekova, iereâ velikogo,"],[6,12,"и скажи ему: так говорит Господь Саваоф: вот Муж, – имя Ему ОТРАСЛЬ, Он произрастет из Своего корня и создаст храм Господень.","i skaži emu: tak govorit Gospodʹ Savaof: vot Muž, – imâ Emu OTRASLʹ̱, On proizrastet iz Svoego kornâ i sozdast hram Gospodenʹ."],[6,13,"Он создаст храм Господень и примет славу, и воссядет, и будет владычествовать на престоле Своем; будет и священником на престоле Своем, и совет мира будет между тем и другим.","On sozdast hram Gospodenʹ i primet slavu, i vossâdet, i budet vladyčestvovatʹ na prestole Svoem; budet i svâŝennikom na prestole Svoem, i sovet mira budet meždu tem i drugim."],[6,14,"А венцы те будут Хелему и Товии, Иедаю и Хену, сыну Софониеву, на память в храме Господнем.","A vency te budut Helemu i Tovii, Iedaû i Henu, synu Sofonievu, na pamâtʹ v hrame Gospodnem."],[6,15,"И издали придут, и примут участие в построении храма Господня, и вы узнаете, что Господь Саваоф послал меня к вам, и это будет, если вы усердно будете слушаться гласа Господа Бога вашего.","I izdali pridut, i primut učastie v postroenii hrama Gospodnâ, i vy uznaete, čto Gospodʹ Savaof poslal menâ k vam, i éto budet, esli vy userdno budete slušatʹsâ glasa Gospoda Boga vašego."],[7,1,"В четвертый год царя Дария было слово Господне к Захарии, в четвертый день девятого месяца, Хаслева,","V četvertyj god carâ Dariâ bylo slovo Gospodne k Zaharii, v četvertyj denʹ devâtogo mesâca, Hasleva,"],[7,2,"когда Вефиль послал Сарецера и Регем-Мелеха и спутников его помолиться пред лицом Господа","kogda Vefilʹ poslal Sarecera i Regem-Meleha i sputnikov ego pomolitʹsâ pred licom Gospoda"],[7,3,"и спросить у священников, которые в доме Господа Саваофа, и у пророков, говоря: «плакать ли мне в пятый месяц и поститься, как я делал это уже много лет?»","i sprositʹ u svâŝennikov, kotorye v dome Gospoda Savaofa, i u prorokov, govorâ: «plakatʹ li mne v pâtyj mesâc i postitʹsâ, kak â delal éto uže mnogo let?»"],[7,4,"И было ко мне слово Господа Саваофа:","I bylo ko mne slovo Gospoda Savaofa:"],[7,5,"скажи всему народу земли сей и священникам так: когда вы постились и плакали в пятом и седьмом месяце, притом уже семьдесят лет, для Меня ли вы постились? для Меня ли?","skaži vsemu narodu zemli sej i svâŝennikam tak: kogda vy postilisʹ i plakali v pâtom i sedʹmom mesâce, pritom uže semʹdesât let, dlâ Menâ li vy postilisʹ? dlâ Menâ li?"],[7,6,"И когда вы едите и когда пьете, не для себя ли вы едите, не для себя ли вы пьете?","I kogda vy edite i kogda pʹete, ne dlâ sebâ li vy edite, ne dlâ sebâ li vy pʹete?"],[7,7,"Не те же ли слова провозглашал Господь через прежних пророков, когда еще Иерусалим был населен и покоен, и города вокруг него, южная страна и низменность, были населены?","Ne te že li slova provozglašal Gospodʹ čerez prežnih prorokov, kogda eŝe Ierusalim byl naselen i pokoen, i goroda vokrug nego, ûžnaâ strana i nizmennostʹ, byli naseleny?"],[7,8,"И было слово Господне к Захарии:","I bylo slovo Gospodne k Zaharii:"],[7,9,"так говорил тогда Господь Саваоф: производите суд справедливый и оказывайте милость и сострадание каждый брату своему;","tak govoril togda Gospodʹ Savaof: proizvodite sud spravedlivyj i okazyvajte milostʹ i sostradanie každyj bratu svoemu;"],[7,10,"вдовы и сироты, пришельца и бедного не притесняйте и зла друг против друга не мыслите в сердце вашем.","vdovy i siroty, prišelʹca i bednogo ne pritesnâjte i zla drug protiv druga ne myslite v serdce vašem."],[7,11,"Но они не хотели внимать, отворотились от Меня, и уши свои отяготили, чтобы не слышать.","No oni ne hoteli vnimatʹ, otvorotilisʹ ot Menâ, i uši svoi otâgotili, čtoby ne slyšatʹ."],[7,12,"И сердце свое окаменили, чтобы не слышать закона и слов, которые посылал Господь Саваоф Духом Своим через прежних пророков; за то и постиг их великий гнев Господа Саваофа.","I serdce svoe okamenili, čtoby ne slyšatʹ zakona i slov, kotorye posylal Gospodʹ Savaof Duhom Svoim čerez prežnih prorokov; za to i postig ih velikij gnev Gospoda Savaofa."],[7,13,"И было: как Он взывал, а они не слушали, так и они взывали, а Я не слушал, говорит Господь Саваоф.","I bylo: kak On vzyval, a oni ne slušali, tak i oni vzyvali, a Â ne slušal, govorit Gospodʹ Savaof."],[7,14,"И Я развеял их по всем народам, которых они не знали, и земля сия опустела после них, так что никто не ходил по ней ни взад, ни вперед, и они сделали вожделенную страну пустынею.","I Â razveâl ih po vsem narodam, kotoryh oni ne znali, i zemlâ siâ opustela posle nih, tak čto nikto ne hodil po nej ni vzad, ni vpered, i oni sdelali voždelennuû stranu pustyneû."],[8,1,"И было слово Господа Саваофа:","I bylo slovo Gospoda Savaofa:"],[8,2,"так говорит Господь Саваоф: возревновал Я о Сионе ревностью великою, и с великим гневом возревновал Я о нем.","tak govorit Gospodʹ Savaof: vozrevnoval Â o Sione revnostʹû velikoû, i s velikim gnevom vozrevnoval Â o nem."],[8,3,"Так говорит Господь: обращусь Я к Сиону и буду жить в Иерусалиме, и будет называться Иерусалим городом истины, и гора Господа Саваофа – горою святыни.","Tak govorit Gospodʹ: obraŝusʹ Â k Sionu i budu žitʹ v Ierusalime, i budet nazyvatʹsâ Ierusalim gorodom istiny, i gora Gospoda Savaofa – goroû svâtyni."],[8,4,"Так говорит Господь Саваоф: опять старцы и старицы будут сидеть на улицах в Иерусалиме, каждый с посохом в руке, от множества дней.","Tak govorit Gospodʹ Savaof: opâtʹ starcy i staricy budut sidetʹ na ulicah v Ierusalime, každyj s posohom v ruke, ot množestva dnej."],[8,5,"И улицы города сего наполнятся отроками и отроковицами, играющими на улицах его.","I ulicy goroda sego napolnâtsâ otrokami i otrokovicami, igraûŝimi na ulicah ego."],[8,6,"Так говорит Господь Саваоф: если это в глазах оставшегося народа покажется дивным во дни сии, то неужели оно дивно и в Моих очах? говорит Господь Саваоф.","Tak govorit Gospodʹ Savaof: esli éto v glazah ostavšegosâ naroda pokažetsâ divnym vo dni sii, to neuželi ono divno i v Moih očah? govorit Gospodʹ Savaof."],[8,7,"Так говорит Господь Саваоф: вот, Я спасу народ Мой из страны востока и из страны захождения солнца;","Tak govorit Gospodʹ Savaof: vot, Â spasu narod Moj iz strany vostoka i iz strany zahoždeniâ solnca;"],[8,8,"и приведу их, и будут они жить в Иерусалиме, и будут Моим народом, и Я буду их Богом, в истине и правде.","i privedu ih, i budut oni žitʹ v Ierusalime, i budut Moim narodom, i Â budu ih Bogom, v istine i pravde."],[8,9,"Так говорит Господь Саваоф: укрепите руки ваши вы, слышащие ныне слова сии из уст пророков, бывших при основании дома Господа Саваофа, для создания храма.","Tak govorit Gospodʹ Savaof: ukrepite ruki vaši vy, slyšaŝie nyne slova sii iz ust prorokov, byvših pri osnovanii doma Gospoda Savaofa, dlâ sozdaniâ hrama."],[8,10,"Ибо прежде дней тех не было возмездия для человека, ни возмездия за труд животных; ни уходящему, ни приходящему не было покоя от врага; и попускал Я всякого человека враждовать против другого.","Ibo prežde dnej teh ne bylo vozmezdiâ dlâ čeloveka, ni vozmezdiâ za trud životnyh; ni uhodâŝemu, ni prihodâŝemu ne bylo pokoâ ot vraga; i popuskal Â vsâkogo čeloveka vraždovatʹ protiv drugogo."],[8,11,"А ныне для остатка этого народа Я не такой, как в прежние дни, говорит Господь Саваоф.","A nyne dlâ ostatka étogo naroda Â ne takoj, kak v prežnie dni, govorit Gospodʹ Savaof."],[8,12,"Ибо посев будет в мире; виноградная лоза даст плод свой, и земля даст произведения свои, и небеса будут давать росу свою, и все это Я отдам во владение оставшемуся народу сему.","Ibo posev budet v mire; vinogradnaâ loza dast plod svoj, i zemlâ dast proizvedeniâ svoi, i nebesa budut davatʹ rosu svoû, i vse éto Â otdam vo vladenie ostavšemusâ narodu semu."],[8,13,"И будет: как вы, дом Иудин и дом Израилев, были проклятием у народов, так Я спасу вас, и вы будете благословением; не бойтесь; да укрепятся руки ваши!","I budet: kak vy, dom Iudin i dom Izrailev, byli proklâtiem u narodov, tak Â spasu vas, i vy budete blagosloveniem; ne bojtesʹ; da ukrepâtsâ ruki vaši!"],[8,14,"Ибо так говорит Господь Саваоф; как Я определил наказать вас, когда отцы ваши прогневляли Меня, говорит Господь Саваоф, и не отменил,","Ibo tak govorit Gospodʹ Savaof; kak Â opredelil nakazatʹ vas, kogda otcy vaši prognevlâli Menâ, govorit Gospodʹ Savaof, i ne otmenil,"],[8,15,"так опять Я определил в эти дни соделать доброе Иерусалиму и дому Иудину; не бойтесь!","tak opâtʹ Â opredelil v éti dni sodelatʹ dobroe Ierusalimu i domu Iudinu; ne bojtesʹ!"],[8,16,"Вот дела, которые вы должны делать: говорите истину друг другу; по истине и миролюбно судите у ворот ваших.","Vot dela, kotorye vy dolžny delatʹ: govorite istinu drug drugu; po istine i mirolûbno sudite u vorot vaših."],[8,17,"Никто из вас да не мыслит в сердце своем зла против ближнего своего, и ложной клятвы не любите, ибо все это Я ненавижу, говорит Господь.","Nikto iz vas da ne myslit v serdce svoem zla protiv bližnego svoego, i ložnoj klâtvy ne lûbite, ibo vse éto Â nenavižu, govorit Gospodʹ."],[8,18,"И было ко мне слово Господа Саваофа:","I bylo ko mne slovo Gospoda Savaofa:"],[8,19,"так говорит Господь Саваоф: пост четвертого месяца и пост пятого, и пост седьмого, и пост десятого соделается для дома Иудина радостью и веселым торжеством; только любите истину и мир.","tak govorit Gospodʹ Savaof: post četvertogo mesâca i post pâtogo, i post sedʹmogo, i post desâtogo sodelaetsâ dlâ doma Iudina radostʹû i veselym toržestvom; tolʹko lûbite istinu i mir."],[8,20,"Так говорит Господь Саваоф: еще будут приходить народы и жители многих городов;","Tak govorit Gospodʹ Savaof: eŝe budut prihoditʹ narody i žiteli mnogih gorodov;"],[8,21,"и пойдут жители одного города к жителям другого и скажут: пойдем молиться лицу Господа и взыщем Господа Саваофа;и каждый скажет: пойду и я.","i pojdut žiteli odnogo goroda k žitelâm drugogo i skažut: pojdem molitʹsâ licu Gospoda i vzyŝem Gospoda Savaofa;i každyj skažet: pojdu i â."],[8,22,"И будут приходить многие племена и сильные народы, чтобы взыскать Господа Саваофа в Иерусалиме и помолиться лицу Господа.","I budut prihoditʹ mnogie plemena i silʹnye narody, čtoby vzyskatʹ Gospoda Savaofa v Ierusalime i pomolitʹsâ licu Gospoda."],[8,23,"Так говорит Господь Саваоф: будет в те дни, возьмутся десять человек из всех разноязычных народов, возьмутся за полу Иудея и будут говорить: мы пойдем с тобою, ибо мы слышали, что с вами Бог.","Tak govorit Gospodʹ Savaof: budet v te dni, vozʹmutsâ desâtʹ čelovek iz vseh raznoâzyčnyh narodov, vozʹmutsâ za polu Iudeâ i budut govoritʹ: my pojdem s toboû, ibo my slyšali, čto s vami Bog."],[9,1,"Пророческое слово Господа на землю Хадрах, и на Дамаске оно остановится, – ибо око Господа на всех людей, как и на все колена Израилевы, –","Proročeskoe slovo Gospoda na zemlû Hadrah, i na Damaske ono ostanovitsâ, – ibo oko Gospoda na vseh lûdej, kak i na vse kolena Izrailevy, –"],[9,2,"и на Емаф, смежный с ним, на Тир и Сидон, ибо он очень умудрился.","i na Emaf, smežnyj s nim, na Tir i Sidon, ibo on očenʹ umudrilsâ."],[9,3,"И устроил себе Тир крепость, накопил серебра, как пыли, и золота, как уличной грязи.","I ustroil sebe Tir krepostʹ, nakopil serebra, kak pyli, i zolota, kak uličnoj grâzi."],[9,4,"Вот, Господь сделает его бедным и поразит силу его в море, и сам он будет истреблен огнем.","Vot, Gospodʹ sdelaet ego bednym i porazit silu ego v more, i sam on budet istreblen ognem."],[9,5,"Увидит это Аскалон и ужаснется, и Газа, и вострепещет сильно, и Екрон; ибо посрамится надежда его: не станет царя в Газе, и Аскалон будет необитаем.","Uvidit éto Askalon i užasnetsâ, i Gaza, i vostrepeŝet silʹno, i Ekron; ibo posramitsâ nadežda ego: ne stanet carâ v Gaze, i Askalon budet neobitaem."],[9,6,"Чужое племя будет жить в Азоте, и Я уничтожу высокомерие Филистимлян.","Čužoe plemâ budet žitʹ v Azote, i Â uničtožu vysokomerie Filistimlân."],[9,7,"Исторгну кровь из уст его и мерзости его из зубов его, и он достанется Богу нашему, и будет как тысяченачальник в Иуде, и Екрон будет как Иевусей.","Istorgnu krovʹ iz ust ego i merzosti ego iz zubov ego, i on dostanetsâ Bogu našemu, i budet kak tysâčenačalʹnik v Iude, i Ekron budet kak Ievusej."],[9,8,"И Я расположу стан у дома Моего против войска, против проходящих вперед и назад, и не будет более проходить притеснитель, ибо ныне Моими очами Я буду взирать на это.","I Â raspoložu stan u doma Moego protiv vojska, protiv prohodâŝih vpered i nazad, i ne budet bolee prohoditʹ pritesnitelʹ, ibo nyne Moimi očami Â budu vziratʹ na éto."],[9,9,"Ликуй от радости, дщерь Сиона, торжествуй, дщерь Иерусалима: се Царь твой грядет к тебе, праведный и спасающий, кроткий, сидящий на ослице и на молодом осле, сыне подъяремной.","Likuj ot radosti, dŝerʹ Siona, toržestvuj, dŝerʹ Ierusalima: se Carʹ tvoj grâdet k tebe, pravednyj i spasaûŝij, krotkij, sidâŝij na oslice i na molodom osle, syne podʺâremnoj."],[9,10,"Тогда истреблю колесницы у Ефрема и коней в Иерусалиме, и сокрушен будет бранный лук; и Он возвестит мир народам, и владычество Его будет от моря до моря и от реки до концов земли.","Togda istreblû kolesnicy u Efrema i konej v Ierusalime, i sokrušen budet brannyj luk; i On vozvestit mir narodam, i vladyčestvo Ego budet ot morâ do morâ i ot reki do koncov zemli."],[9,11,"А что до тебя, ради крови завета твоего Я освобожу узников твоих изо рва, в котором нет воды.","A čto do tebâ, radi krovi zaveta tvoego Â osvobožu uznikov tvoih izo rva, v kotorom net vody."],[9,12,"Возвращайтесь на твердыню, вы, пленники надеющиеся! Что теперь возвещаю, воздам тебе вдвойне.","Vozvraŝajtesʹ na tverdynû, vy, plenniki nadeûŝiesâ! Čto teperʹ vozveŝaû, vozdam tebe vdvojne."],[9,13,"Ибо как лук Я натяну Себе Иуду и наполню лук Ефремом, и воздвигну сынов твоих, Сион, против сынов твоих, Иония, и сделаю тебя мечом ратоборца.","Ibo kak luk Â natânu Sebe Iudu i napolnû luk Efremom, i vozdvignu synov tvoih, Sion, protiv synov tvoih, Ioniâ, i sdelaû tebâ mečom ratoborca."],[9,14,"И явится над ними Господь, и, как молния, вылетит стрела Его, и возгремит Господь Бог трубою, и шествовать будет в бурях полуденных.","I âvitsâ nad nimi Gospodʹ, i, kak molniâ, vyletit strela Ego, i vozgremit Gospodʹ Bog truboû, i šestvovatʹ budet v burâh poludennyh."],[9,15,"Господь Саваоф будет защищать их, и они будут истреблять и попирать пращные камни, и будут пить и шуметь как бы от вина, и наполнятся как жертвенные чаши, как углы жертвенника.","Gospodʹ Savaof budet zaŝiŝatʹ ih, i oni budut istreblâtʹ i popiratʹ praŝnye kamni, i budut pitʹ i šumetʹ kak by ot vina, i napolnâtsâ kak žertvennye čaši, kak ugly žertvennika."],[9,16,"И спасет их Господь Бог их в тот день, как овец, народ Свой; ибо, подобно камням в венце, они воссияют на земле Его.","I spaset ih Gospodʹ Bog ih v tot denʹ, kak ovec, narod Svoj; ibo, podobno kamnâm v vence, oni vossiâût na zemle Ego."],[9,17,"О, как велика благость его и какая красота его! Хлеб одушевит язык у юношей и вино – у отроковиц!","O, kak velika blagostʹ ego i kakaâ krasota ego! Hleb oduševit âzyk u ûnošej i vino – u otrokovic!"],[10,1,"Просите у Господа дождя во время благопотребное; Господь блеснет молниею и даст вам обильный дождь, каждому злак на поле.","Prosite u Gospoda doždâ vo vremâ blagopotrebnoe; Gospodʹ blesnet molnieû i dast vam obilʹnyj doždʹ, každomu zlak na pole."],[10,2,"Ибо терафимы говорят пустое, и вещуны видят ложное и рассказывают сны лживые; они утешают пустотою; поэтому они бродят как овцы, бедствуют, потому что нет пастыря.","Ibo terafimy govorât pustoe, i veŝuny vidât ložnoe i rasskazyvaût sny lživye; oni utešaût pustotoû; poétomu oni brodât kak ovcy, bedstvuût, potomu čto net pastyrâ."],[10,3,"На пастырей воспылал гнев Мой, и козлов Я накажу; ибо посетит Господь Саваоф стадо Свое, дом Иудин, и поставит их, как славного коня Своего на брани.","Na pastyrej vospylal gnev Moj, i kozlov Â nakažu; ibo posetit Gospodʹ Savaof stado Svoe, dom Iudin, i postavit ih, kak slavnogo konâ Svoego na brani."],[10,4,"Из него будет краеугольный камень, из него – гвоздь, из него – лук для брани, из него произойдут все народоправители.","Iz nego budet kraeugolʹnyj kamenʹ, iz nego – gvozdʹ, iz nego – luk dlâ brani, iz nego proizojdut vse narodopraviteli."],[10,5,"И они будут как герои, попирающие врагов на войне, как уличную грязь, и сражаться, потому что Господь с ними, и посрамят всадников на конях.","I oni budut kak geroi, popiraûŝie vragov na vojne, kak uličnuû grâzʹ, i sražatʹsâ, potomu čto Gospodʹ s nimi, i posramât vsadnikov na konâh."],[10,6,"И укреплю дом Иудин, и спасу дом Иосифов, и возвращу их, потому что Я умилосердился над ними, и они будут, как бы Я не оставлял их: ибо Я – Господь Бог их и услышу их.","I ukreplû dom Iudin, i spasu dom Iosifov, i vozvraŝu ih, potomu čto Â umiloserdilsâ nad nimi, i oni budut, kak by Â ne ostavlâl ih: ibo Â – Gospodʹ Bog ih i uslyšu ih."],[10,7,"Как герой будет Ефрем; возвеселится сердце их, как от вина; и увидят это сыны их и возрадуются; в восторге будет сердце их о Господе.","Kak geroj budet Efrem; vozveselitsâ serdce ih, kak ot vina; i uvidât éto syny ih i vozraduûtsâ; v vostorge budet serdce ih o Gospode."],[10,8,"Я дам им знак и соберу их, потому что Я искупил их; они будут так же многочисленны, как прежде;","Â dam im znak i soberu ih, potomu čto Â iskupil ih; oni budut tak že mnogočislenny, kak prežde;"],[10,9,"и расселю их между народами, и в отдаленных странах они будут воспоминать обо Мне и будут жить с детьми своими, и возвратятся;","i rasselû ih meždu narodami, i v otdalennyh stranah oni budut vospominatʹ obo Mne i budut žitʹ s detʹmi svoimi, i vozvratâtsâ;"],[10,10,"и возвращу их из земли Египетской, и из Ассирии соберу их, и приведу их в землю Галаадскую и на Ливан, и недостанет места для них.","i vozvraŝu ih iz zemli Egipetskoj, i iz Assirii soberu ih, i privedu ih v zemlû Galaadskuû i na Livan, i nedostanet mesta dlâ nih."],[10,11,"И пройдет бедствие по морю и поразит волны морские, и иссякнут все глубины реки, и смирится гордость Ассура, и скипетр отнимется у Египта.","I projdet bedstvie po morû i porazit volny morskie, i issâknut vse glubiny reki, i smiritsâ gordostʹ Assura, i skipetr otnimetsâ u Egipta."],[10,12,"Укреплю их в Господе, и они будут ходить во имя Его, говорит Господь.","Ukreplû ih v Gospode, i oni budut hoditʹ vo imâ Ego, govorit Gospodʹ."],[11,1,"Отворяй, Ливан, ворота твои, и да пожрет огонь кедры твои.","Otvorâj, Livan, vorota tvoi, i da požret ogonʹ kedry tvoi."],[11,2,"Рыдай, кипарис, ибо упал кедр, ибо и величавые опустошены; рыдайте, дубы Васанские, ибо повалился непроходимый лес.","Rydaj, kiparis, ibo upal kedr, ibo i veličavye opustošeny; rydajte, duby Vasanskie, ibo povalilsâ neprohodimyj les."],[11,3,"Слышен голос рыдания пастухов, потому что опустошено приволье их; слышно рыкание молодых львов, потому что опустошена краса Иордана.","Slyšen golos rydaniâ pastuhov, potomu čto opustošeno privolʹe ih; slyšno rykanie molodyh lʹvov, potomu čto opustošena krasa Iordana."],[11,4,"Так говорит Господь Бог мой: паси овец, обреченных на заклание,","Tak govorit Gospodʹ Bog moj: pasi ovec, obrečennyh na zaklanie,"],[11,5,"которых купившие убивают ненаказанно, а продавшие говорят: «благословен Господь; я разбогател!», и пастухи их не жалеют о них.","kotoryh kupivšie ubivaût nenakazanno, a prodavšie govorât: «blagosloven Gospodʹ; â razbogatel!», i pastuhi ih ne žaleût o nih."],[11,6,"Ибо Я не буду более миловать жителей земли сей, говорит Господь; и вот, Я предам людей, каждого в руки ближнего его и в руки царя его, и они будут поражать землю, и Я не избавлю от рук их.","Ibo Â ne budu bolee milovatʹ žitelej zemli sej, govorit Gospodʹ; i vot, Â predam lûdej, každogo v ruki bližnego ego i v ruki carâ ego, i oni budut poražatʹ zemlû, i Â ne izbavlû ot ruk ih."],[11,7,"И буду пасти овец, обреченных на заклание, овец поистине бедных. И возьму Себе два жезла, и назову один – благоволением, другой – узами, и ими буду пасти овец.","I budu pasti ovec, obrečennyh na zaklanie, ovec poistine bednyh. I vozʹmu Sebe dva žezla, i nazovu odin – blagovoleniem, drugoj – uzami, i imi budu pasti ovec."],[11,8,"И истреблю трех из пастырей в один месяц; и отвратится душа Моя от них, как и их душа отвращается от Меня.","I istreblû treh iz pastyrej v odin mesâc; i otvratitsâ duša Moâ ot nih, kak i ih duša otvraŝaetsâ ot Menâ."],[11,9,"Тогда скажу: не буду пасти вас: умирающая – пусть умирает, и гибнущая – пусть гибнет, а остающиеся пусть едят плоть одна другой.","Togda skažu: ne budu pasti vas: umiraûŝaâ – pustʹ umiraet, i gibnuŝaâ – pustʹ gibnet, a ostaûŝiesâ pustʹ edât plotʹ odna drugoj."],[11,10,"И возьму жезл Мой – благоволения и переломлю его, чтобы уничтожить завет, который заключил Я со всеми народами.","I vozʹmu žezl Moj – blagovoleniâ i perelomlû ego, čtoby uničtožitʹ zavet, kotoryj zaklûčil Â so vsemi narodami."],[11,11,"И он уничтожен будет в тот день, и тогда узнают бедные из овец, ожидающие Меня, что это слово Господа.","I on uničtožen budet v tot denʹ, i togda uznaût bednye iz ovec, ožidaûŝie Menâ, čto éto slovo Gospoda."],[11,12,"И скажу им: если угодно вам, то дайте Мне плату Мою; если же нет, – не давайте; и они отвесят в уплату Мне тридцать сребреников.","I skažu im: esli ugodno vam, to dajte Mne platu Moû; esli že net, – ne davajte; i oni otvesât v uplatu Mne tridcatʹ srebrenikov."],[11,13,"И сказал мне Господь: брось их в церковное хранилище, – высокая цена, в какую они оценили Меня! И взял Я тридцать сребреников и бросил их в дом Господень для горшечника.","I skazal mne Gospodʹ: brosʹ ih v cerkovnoe hraniliŝe, – vysokaâ cena, v kakuû oni ocenili Menâ! I vzâl Â tridcatʹ srebrenikov i brosil ih v dom Gospodenʹ dlâ goršečnika."],[11,14,"И переломил Я другой жезл Мой – «узы», чтобы расторгнуть братство между Иудою и Израилем.","I perelomil Â drugoj žezl Moj – «uzy», čtoby rastorgnutʹ bratstvo meždu Iudoû i Izrailem."],[11,15,"И Господь сказал мне: еще возьми себе снаряд одного из глупых пастухов.","I Gospodʹ skazal mne: eŝe vozʹmi sebe snarâd odnogo iz glupyh pastuhov."],[11,16,"Ибо вот, Я поставлю на этой земле пастуха, который о погибающих не позаботится, потерявшихся не будет искать и больных не будет лечить, здоровых не будет кормить, а мясо тучных будет есть и копыта их оторвет.","Ibo vot, Â postavlû na étoj zemle pastuha, kotoryj o pogibaûŝih ne pozabotitsâ, poterâvšihsâ ne budet iskatʹ i bolʹnyh ne budet lečitʹ, zdorovyh ne budet kormitʹ, a mâso tučnyh budet estʹ i kopyta ih otorvet."],[11,17,"Горе негодному пастуху, оставляющему стадо! меч на руку его и на правый глаз его! рука его совершенно иссохнет, и правый глаз его совершенно потускнет.","Gore negodnomu pastuhu, ostavlâûŝemu stado! meč na ruku ego i na pravyj glaz ego! ruka ego soveršenno issohnet, i pravyj glaz ego soveršenno potusknet."],[12,1,"Пророческое слово Господа об Израиле. Господь, распростерший небо, основавший землю и образовавший дух человека внутри него, говорит:","Proročeskoe slovo Gospoda ob Izraile. Gospodʹ, rasprosteršij nebo, osnovavšij zemlû i obrazovavšij duh čeloveka vnutri nego, govorit:"],[12,2,"вот, Я сделаю Иерусалим чашею исступления для всех окрестных народов и также для Иуды во время осады Иерусалима.","vot, Â sdelaû Ierusalim čašeû isstupleniâ dlâ vseh okrestnyh narodov i takže dlâ Iudy vo vremâ osady Ierusalima."],[12,3,"И будет в тот день, сделаю Иерусалим тяжелым камнем для всех племен; все, которые будут поднимать его, надорвут себя, а соберутся против него все народы земли.","I budet v tot denʹ, sdelaû Ierusalim tâželym kamnem dlâ vseh plemen; vse, kotorye budut podnimatʹ ego, nadorvut sebâ, a soberutsâ protiv nego vse narody zemli."],[12,4,"В тот день, говорит Господь, Я поражу всякого коня бешенством и всадника его – безумием, а на дом Иудин отверзу очи Мои; всякого же коня у народов поражу слепотою.","V tot denʹ, govorit Gospodʹ, Â poražu vsâkogo konâ bešenstvom i vsadnika ego – bezumiem, a na dom Iudin otverzu oči Moi; vsâkogo že konâ u narodov poražu slepotoû."],[12,5,"И скажут князья Иудины в сердцах своих: сила моя – жители Иерусалима в Господе Саваофе, Боге их.","I skažut knâzʹâ Iudiny v serdcah svoih: sila moâ – žiteli Ierusalima v Gospode Savaofe, Boge ih."],[12,6,"В тот день Я сделаю князей Иудиных как жаровню с огнем между дровами и как горящий светильник среди снопов, и они истребят все окрестные народы, справа и слева, и снова населен будет Иерусалим на своем месте, в Иерусалиме.","V tot denʹ Â sdelaû knâzej Iudinyh kak žarovnû s ognem meždu drovami i kak gorâŝij svetilʹnik sredi snopov, i oni istrebât vse okrestnye narody, sprava i sleva, i snova naselen budet Ierusalim na svoem meste, v Ierusalime."],[12,7,"И спасет Господь сначала шатры Иуды, чтобы величие дома Давидова и величие жителей Иерусалима не возносилось над Иудою.","I spaset Gospodʹ snačala šatry Iudy, čtoby veličie doma Davidova i veličie žitelej Ierusalima ne voznosilosʹ nad Iudoû."],[12,8,"В тот день защищать будет Господь жителей Иерусалима, и самый слабый между ними в тот день будет как Давид, а дом Давида будет как Бог, как Ангел Господень перед ними.","V tot denʹ zaŝiŝatʹ budet Gospodʹ žitelej Ierusalima, i samyj slabyj meždu nimi v tot denʹ budet kak David, a dom Davida budet kak Bog, kak Angel Gospodenʹ pered nimi."],[12,9,"И будет в тот день, Я истреблю все народы, нападающие на Иерусалим.","I budet v tot denʹ, Â istreblû vse narody, napadaûŝie na Ierusalim."],[12,10,"А на дом Давида и на жителей Иерусалима изолью дух благодати и умиления, и они воззрят на Него, Которого пронзили, и будут рыдать о Нем, как рыдают об единородном сыне, и скорбеть, как скорбят о первенце.","A na dom Davida i na žitelej Ierusalima izolʹû duh blagodati i umileniâ, i oni vozzrât na Nego, Kotorogo pronzili, i budut rydatʹ o Nem, kak rydaût ob edinorodnom syne, i skorbetʹ, kak skorbât o pervence."],[12,11,"В тот день поднимется большой плач в Иерусалиме, как плач Гададриммона в долине Мегиддонской.","V tot denʹ podnimetsâ bolʹšoj plač v Ierusalime, kak plač Gadadrimmona v doline Megiddonskoj."],[12,12,"И будет рыдать земля, каждое племя особо: племя дома Давидова особо, и жены их особо; племя дома Нафанова особо, и жены их особо;","I budet rydatʹ zemlâ, každoe plemâ osobo: plemâ doma Davidova osobo, i ženy ih osobo; plemâ doma Nafanova osobo, i ženy ih osobo;"],[12,13,"племя дома Левиина особо, и жены их особо; племя Симеоново особо, и жены их особо.","plemâ doma Leviina osobo, i ženy ih osobo; plemâ Simeonovo osobo, i ženy ih osobo."],[12,14,"Все остальные племена – каждое племя особо, и жены их особо.","Vse ostalʹnye plemena – každoe plemâ osobo, i ženy ih osobo."],[13,1,"В тот день откроется источник дому Давидову и жителям Иерусалима для омытия греха и нечистоты.","V tot denʹ otkroetsâ istočnik domu Davidovu i žitelâm Ierusalima dlâ omytiâ greha i nečistoty."],[13,2,"И будет в тот день, говорит Господь Саваоф, Я истреблю имена идолов с этой земли, и они не будут более упоминаемы, равно как лжепророков и нечистого духа удалю с земли.","I budet v tot denʹ, govorit Gospodʹ Savaof, Â istreblû imena idolov s étoj zemli, i oni ne budut bolee upominaemy, ravno kak lžeprorokov i nečistogo duha udalû s zemli."],[13,3,"Тогда, если кто будет прорицать, то отец его и мать его, родившие его, скажут ему: тебе не должно жить, потому что ты ложь говоришь во имя Господа; и поразят его отец его и мать его, родившие его, когда он будет прорицать.","Togda, esli kto budet proricatʹ, to otec ego i matʹ ego, rodivšie ego, skažut emu: tebe ne dolžno žitʹ, potomu čto ty ložʹ govorišʹ vo imâ Gospoda; i porazât ego otec ego i matʹ ego, rodivšie ego, kogda on budet proricatʹ."],[13,4,"И будет в тот день, устыдятся такие прорицатели, каждый видения своего, когда будут прорицать, и не будут надевать на себя власяницы, чтобы обманывать.","I budet v tot denʹ, ustydâtsâ takie proricateli, každyj videniâ svoego, kogda budut proricatʹ, i ne budut nadevatʹ na sebâ vlasânicy, čtoby obmanyvatʹ."],[13,5,"И каждый скажет: я не пророк, я земледелец, потому что некто сделал меня рабом от детства моего.","I každyj skažet: â ne prorok, â zemledelec, potomu čto nekto sdelal menâ rabom ot detstva moego."],[13,6,"Ему скажут: отчего же на руках у тебя рубцы? И он ответит: оттого, что меня били в доме любящих меня.","Emu skažut: otčego že na rukah u tebâ rubcy? I on otvetit: ottogo, čto menâ bili v dome lûbâŝih menâ."],[13,7,"О, меч! поднимись на пастыря Моего и на ближнего Моего, говорит Господь Саваоф: порази пастыря, и рассеются овцы! И Я обращу руку Мою на малых.","O, meč! podnimisʹ na pastyrâ Moego i na bližnego Moego, govorit Gospodʹ Savaof: porazi pastyrâ, i rasseûtsâ ovcy! I Â obraŝu ruku Moû na malyh."],[13,8,"И будет на всей земле, говорит Господь, две части на ней будут истреблены, вымрут, а третья останется на ней.","I budet na vsej zemle, govorit Gospodʹ, dve časti na nej budut istrebleny, vymrut, a tretʹâ ostanetsâ na nej."],[13,9,"И введу эту третью часть в огонь, и расплавлю их, как плавят серебро, и очищу их, как очищают золото: они будут призывать имя Мое, и Я услышу их и скажу: «это Мой народ», и они скажут: «Господь – Бог мой!»","I vvedu étu tretʹû častʹ v ogonʹ, i rasplavlû ih, kak plavât serebro, i očiŝu ih, kak očiŝaût zoloto: oni budut prizyvatʹ imâ Moe, i Â uslyšu ih i skažu: «éto Moj narod», i oni skažut: «Gospodʹ – Bog moj!»"],[14,1,"Вот наступает день Господень, и разделят награбленное у тебя среди тебя.","Vot nastupaet denʹ Gospodenʹ, i razdelât nagrablennoe u tebâ sredi tebâ."],[14,2,"И соберу все народы на войну против Иерусалима, и взят будет город, и разграблены будут домы, и обесчещены будут жены, и половина города пойдет в плен; но остальной народ не будет истреблен из города.","I soberu vse narody na vojnu protiv Ierusalima, i vzât budet gorod, i razgrableny budut domy, i obesčeŝeny budut ženy, i polovina goroda pojdet v plen; no ostalʹnoj narod ne budet istreblen iz goroda."],[14,3,"Тогда выступит Господь и ополчится против этих народов, как ополчился в день брани.","Togda vystupit Gospodʹ i opolčitsâ protiv étih narodov, kak opolčilsâ v denʹ brani."],[14,4,"И станут ноги Его в тот день на горе Елеонской, которая перед лицом Иерусалима к востоку; и раздвоится гора Елеонская от востока к западу весьма большою долиною, и половина горы отойдет к северу, а половина ее – к югу.","I stanut nogi Ego v tot denʹ na gore Eleonskoj, kotoraâ pered licom Ierusalima k vostoku; i razdvoitsâ gora Eleonskaâ ot vostoka k zapadu vesʹma bolʹšoû dolinoû, i polovina gory otojdet k severu, a polovina ee – k ûgu."],[14,5,"И вы побежите в долину гор Моих, ибо долина гор будет простираться до Асила; и вы побежите, как бежали от землетрясения во дни Озии, царя Иудейского; и придет Господь Бог мой и все святые с Ним.","I vy pobežite v dolinu gor Moih, ibo dolina gor budet prostiratʹsâ do Asila; i vy pobežite, kak bežali ot zemletrâseniâ vo dni Ozii, carâ Iudejskogo; i pridet Gospodʹ Bog moj i vse svâtye s Nim."],[14,6,"И будет в тот день: не станет света, светила удалятся.","I budet v tot denʹ: ne stanet sveta, svetila udalâtsâ."],[14,7,"День этот будет единственный, ведомый только Господу: ни день, ни ночь; лишь в вечернее время явится свет.","Denʹ étot budet edinstvennyj, vedomyj tolʹko Gospodu: ni denʹ, ni nočʹ; lišʹ v večernee vremâ âvitsâ svet."],[14,8,"И будет в тот день, живые воды потекут из Иерусалима, половина их к морю восточному и половина их к морю западному: летом и зимой так будет.","I budet v tot denʹ, živye vody potekut iz Ierusalima, polovina ih k morû vostočnomu i polovina ih k morû zapadnomu: letom i zimoj tak budet."],[14,9,"И Господь будет Царем над всею землею; в тот день будет Господь един и имя Его едино.","I Gospodʹ budet Carem nad vseû zemleû; v tot denʹ budet Gospodʹ edin i imâ Ego edino."],[14,10,"Вся эта земля будет как равнина, от Гаваона до Реммона, на юг от Иерусалима, который высоко будет стоять на своем месте и населится от ворот Вениаминовых до места первых ворот, до угловых ворот, и от башни Анамеила до царских точил.","Vsâ éta zemlâ budet kak ravnina, ot Gavaona do Remmona, na ûg ot Ierusalima, kotoryj vysoko budet stoâtʹ na svoem meste i naselitsâ ot vorot Veniaminovyh do mesta pervyh vorot, do uglovyh vorot, i ot bašni Anameila do carskih točil."],[14,11,"И будут жить в нем, и проклятия не будет более, но будет стоять Иерусалим безопасно.","I budut žitʹ v nem, i proklâtiâ ne budet bolee, no budet stoâtʹ Ierusalim bezopasno."],[14,12,"И вот какое будет поражение, которым поразит Господь все народы, которые воевали против Иерусалима: у каждого исчахнет тело его, когда он еще стоит на своих ногах, и глаза у него истают в яминах своих, и язык его иссохнет во рту у него.","I vot kakoe budet poraženie, kotorym porazit Gospodʹ vse narody, kotorye voevali protiv Ierusalima: u každogo isčahnet telo ego, kogda on eŝe stoit na svoih nogah, i glaza u nego istaût v âminah svoih, i âzyk ego issohnet vo rtu u nego."],[14,13,"И будет в тот день: произойдет между ними великое смятение от Господа, так что один схватит руку другого, и поднимется рука его на руку ближнего его.","I budet v tot denʹ: proizojdet meždu nimi velikoe smâtenie ot Gospoda, tak čto odin shvatit ruku drugogo, i podnimetsâ ruka ego na ruku bližnego ego."],[14,14,"Но и сам Иуда будет воевать против Иерусалима, и собрано будет богатство всех окрестных народов: золото, серебро и одежды в великом множестве.","No i sam Iuda budet voevatʹ protiv Ierusalima, i sobrano budet bogatstvo vseh okrestnyh narodov: zoloto, serebro i odeždy v velikom množestve."],[14,15,"Будет такое же поражение и коней, и лошаков, и верблюдов, и ослов, и всякого скота, какой будет в станах у них.","Budet takoe že poraženie i konej, i lošakov, i verblûdov, i oslov, i vsâkogo skota, kakoj budet v stanah u nih."],[14,16,"Затем все остальные из всех народов, приходивших против Иерусалима, будут приходить из года в год для поклонения Царю, Господу Саваофу, и для празднования праздника кущей.","Zatem vse ostalʹnye iz vseh narodov, prihodivših protiv Ierusalima, budut prihoditʹ iz goda v god dlâ pokloneniâ Carû, Gospodu Savaofu, i dlâ prazdnovaniâ prazdnika kuŝej."],[14,17,"И будет: если какое из племен земных не пойдет в Иерусалим для поклонения Царю, Господу Саваофу, то не будет дождя у них.","I budet: esli kakoe iz plemen zemnyh ne pojdet v Ierusalim dlâ pokloneniâ Carû, Gospodu Savaofu, to ne budet doždâ u nih."],[14,18,"И если племя Египетское не поднимется в путь и не придет [сюда], то и у него не будет дождя и постигнет его поражение, каким поразит Господь народы, не приходящие праздновать праздника кущей.","I esli plemâ Egipetskoe ne podnimetsâ v putʹ i ne pridet [sûda], to i u nego ne budet doždâ i postignet ego poraženie, kakim porazit Gospodʹ narody, ne prihodâŝie prazdnovatʹ prazdnika kuŝej."],[14,19,"Вот что будет за грех Египта и за грех всех народов, которые не придут праздновать праздника кущей!","Vot čto budet za greh Egipta i za greh vseh narodov, kotorye ne pridut prazdnovatʹ prazdnika kuŝej!"],[14,20,"В то время даже на конских уборах будет начертано: «Святыня Господу», и котлы в доме Господнем будут как жертвенные чаши перед алтарем.","V to vremâ daže na konskih uborah budet načertano: «Svâtynâ Gospodu», i kotly v dome Gospodnem budut kak žertvennye čaši pered altarem."],[14,21,"И все котлы в Иерусалиме и Иудее будут святынею Господа Саваофа, и будут приходить все приносящие жертву и брать их и варить в них, и не будет более ни одного Хананея в доме Господа Саваофа в тот день.","I vse kotly v Ierusalime i Iudee budut svâtyneû Gospoda Savaofa, i budut prihoditʹ vse prinosâŝie žertvu i bratʹ ih i varitʹ v nih, i ne budet bolee ni odnogo Hananeâ v dome Gospoda Savaofa v tot denʹ."]],"cmn-cuv-hant":[[1,1,"大流士 王第二年八月，耶和華的話臨到 易多的孫子、 比利家的兒子先知 撒迦利亞，說：","dà liú shì wáng dì èr nián bā yuè， yé hé huá de huà lín dào yì duō de sūn zǐ, bǐ lì jiā de ér zǐ xiān zhī sā jiā lì yà， shuō："],[1,2,"「耶和華曾向你們列祖大大發怒。","‘yé hé huá céng xiàng nǐ men liè zǔ dà dà fā nù."],[1,3,"所以你要對 以色列人說，萬軍之耶和華如此說：你們要轉向我，我就轉向你們。這是萬軍之耶和華說的。","suǒ yǐ nǐ yào duì yǐ sè liè rén shuō， wàn jūn zhī yé hé huá rú cǐ shuō： nǐ men yào zhuǎn xiàng wǒ， wǒ jiù zhuǎn xiàng nǐ men. zhè shì wàn jūn zhī yé hé huá shuō de."],[1,4,"不要效法你們列祖。從前的先知呼叫他們說，萬軍之耶和華如此說：『你們要回頭離開你們的惡道惡行。』他們卻不聽，也不順從我。這是耶和華說的。","bù yào xiào fǎ nǐ men liè zǔ. cóng qián de xiān zhī hū jiào tā men shuō， wàn jūn zhī yé hé huá rú cǐ shuō：“nǐ men yào huí tóu lí kāi nǐ men de è dào è xíng.” tā men què bù tīng， yě bù shùn cóng wǒ. zhè shì yé hé huá shuō de."],[1,5,"你們的列祖在哪裏呢？那些先知能永遠存活嗎？","nǐ men de liè zǔ zài nǎ lǐ ne？ nà xiē xiān zhī néng yǒng yuǎn cún huó ma？"],[1,6,"只是我的言語和律例，就是所吩咐我僕人眾先知的，豈不臨到你們列祖嗎？他們就回頭，說：『萬軍之耶和華定意按我們的行動作為向我們怎樣行，他已照樣行了。』」","zhǐ shì wǒ de yán yǔ hé lǜ lì， jiù shì suǒ fēn fù wǒ pú rén zhòng xiān zhī de， qǐ bù lín dào nǐ men liè zǔ ma？ tā men jiù huí tóu， shuō：“wàn jūn zhī yé hé huá dìng yì àn wǒ men de xíng dòng zuò wèi xiàng wǒ men zěn yàng xíng， tā yǐ zhào yàng xíng le.”’"],[1,7,"大流士第二年十一月，就是細罷特月二十四日，耶和華的話臨到 易多的孫子、 比利家的兒子先知 撒迦利亞，說：","dà liú shì dì èr nián shí yī yuè， jiù shì xì bà tè yuè èr shí sì rì， yé hé huá de huà lín dào yì duō de sūn zǐ, bǐ lì jiā de ér zǐ xiān zhī sā jiā lì yà， shuō："],[1,8,"「我夜間觀看，見一人騎着紅馬，站在窪地番石榴樹中間。在他身後又有紅馬、黃馬，和白馬。」","‘wǒ yè jiān guān kàn， jiàn yī rén qí zhe hóng mǎ， zhàn zài wā de fān shí liú shù zhōng jiān. zài tā shēn hòu yòu yǒu hóng mǎ, huáng mǎ， hé bái mǎ.’"],[1,9,"我對與我說話的天使說：「主啊，這是甚麼意思？」他說：「我要指示你這是甚麼意思。」","wǒ duì yǔ wǒ shuō huà de tiān shǐ shuō：‘zhǔ a， zhè shì shèn me yì sī？’ tā shuō：‘wǒ yào zhǐ shì nǐ zhè shì shèn me yì sī.’"],[1,10,"那站在番石榴樹中間的人說：「這是奉耶和華差遣在遍地走來走去的。」","nà zhàn zài fān shí liú shù zhōng jiān de rén shuō：‘zhè shì fèng yé hé huá chà qiǎn zài biàn de zǒu lái zǒu qù de.’"],[1,11,"那些騎馬的對站在番石榴樹中間耶和華的使者說：「我們已在遍地走來走去，見全地都安息平靜。」","nà xiē qí mǎ de duì zhàn zài fān shí liú shù zhōng jiān yé hé huá de shǐ zhě shuō：‘wǒ men yǐ zài biàn de zǒu lái zǒu qù， jiàn quán de dōu ān xī píng jìng.’"],[1,12,"於是，耶和華的使者說：「萬軍之耶和華啊，你惱恨 耶路撒冷和 猶大的城邑已經七十年，你不施憐憫要到幾時呢？」","yú shì， yé hé huá de shǐ zhě shuō：‘wàn jūn zhī yé hé huá a， nǐ nǎo hèn yé lù sā lěng hé yóu dà de chéng yì yǐ jīng qī shí nián， nǐ bù shī lián mǐn yào dào jǐ shí ne？’"],[1,13,"耶和華就用美善的安慰話回答那與我說話的天使。","yé hé huá jiù yòng měi shàn de ān wèi huà huí dá nà yǔ wǒ shuō huà de tiān shǐ."],[1,14,"與我說話的天使對我說：「你要宣告說，萬軍之耶和華如此說：我為 耶路撒冷為 錫安，心裏極其火熱。","yǔ wǒ shuō huà de tiān shǐ duì wǒ shuō：‘nǐ yào xuān gào shuō， wàn jūn zhī yé hé huá rú cǐ shuō： wǒ wèi yé lù sā lěng wèi xī ān， xīn lǐ jí qí huǒ rè."],[1,15,"我甚惱怒那安逸的列國，因我從前稍微惱怒 我民，他們就加害過分。","wǒ shèn nǎo nù nà ān yì de liè guó， yīn wǒ cóng qián shāo wēi nǎo nù wǒ mín， tā men jiù jiā hài guò fēn."],[1,16,"所以耶和華如此說：現今我回到 耶路撒冷，仍施憐憫，我的殿必重建在其中，準繩必拉在 耶路撒冷之上。這是萬軍之耶和華說的。","suǒ yǐ yé hé huá rú cǐ shuō： xiàn jīn wǒ huí dào yé lù sā lěng， réng shī lián mǐn， wǒ de diàn bì zhòng jiàn zài qí zhōng， zhǔn shéng bì lā zài yé lù sā lěng zhī shàng. zhè shì wàn jūn zhī yé hé huá shuō de."],[1,17,"你要再宣告說，萬軍之耶和華如此說：我的城邑必再豐盛發達。耶和華必再安慰 錫安，揀選 耶路撒冷。」","nǐ yào zài xuān gào shuō， wàn jūn zhī yé hé huá rú cǐ shuō： wǒ de chéng yì bì zài fēng shèng fā dá. yé hé huá bì zài ān wèi xī ān， jiǎn xuǎn yé lù sā lěng.’"],[1,18,"我舉目觀看，見有四角。","wǒ jǔ mù guān kàn， jiàn yǒu sì jiǎo."],[1,19,"我就問與我說話的天使說：「這是甚麼意思？」他回答說：「這是打散 猶大、 以色列，和 耶路撒冷的角。」","wǒ jiù wèn yǔ wǒ shuō huà de tiān shǐ shuō：‘zhè shì shèn me yì sī？’ tā huí dá shuō：‘zhè shì dǎ sàn yóu dà, yǐ sè liè， hé yé lù sā lěng de jiǎo.’"],[1,20,"耶和華又指四個匠人給我看。","yé hé huá yòu zhǐ sì gè jiàng rén gěi wǒ kàn."],[1,21,"我說：「他們來做甚麼呢？」他說：「這是打散 猶大的角，使人不敢抬頭；但這些匠人來威嚇列國，打掉他們的角，就是舉起打散 猶大地的角。」","wǒ shuō：‘tā men lái zuò shèn me ne？’ tā shuō：‘zhè shì dǎ sàn yóu dà de jiǎo， shǐ rén bù gǎn tái tóu； dàn zhè xiē jiàng rén lái wēi xià liè guó， dǎ diào tā men de jiǎo， jiù shì jǔ qǐ dǎ sàn yóu dà de de jiǎo.’"],[2,1,"我又舉目觀看，見一人手拿準繩。","wǒ yòu jǔ mù guān kàn， jiàn yī rén shǒu ná zhǔn shéng."],[2,2,"我說：「你往哪裏去？」他對我說：「要去量 耶路撒冷，看有多寬多長。」","wǒ shuō：‘nǐ wǎng nǎ lǐ qù？’ tā duì wǒ shuō：‘yào qù liàng yé lù sā lěng， kàn yǒu duō kuān duō zhǎng.’"],[2,3,"與我說話的天使去的時候，又有一位天使迎着他來，","yǔ wǒ shuō huà de tiān shǐ qù de shí hòu， yòu yǒu yī wèi tiān shǐ yíng zhe tā lái，"],[2,4,"對他說：「你跑去告訴那少年人說， 耶路撒冷必有人居住，好像無城牆的鄉村，因為人民和牲畜甚多。","duì tā shuō：‘nǐ pǎo qù gào sù nà shǎo nián rén shuō， yé lù sā lěng bì yǒu rén jū zhù， hǎo xiàng wú chéng qiáng de xiāng cūn， yīn wèi rén mín hé shēng chù shèn duō."],[2,5,"耶和華說：我要作 耶路撒冷四圍的火城，並要作其中的榮耀。」","yé hé huá shuō： wǒ yào zuò yé lù sā lěng sì wéi de huǒ chéng， bìng yào zuò qí zhōng de róng yào.’"],[2,6,"耶和華說：「我從前分散你們在天的四方，現在你們要從北方之地逃回。這是耶和華說的。","yé hé huá shuō：‘wǒ cóng qián fēn sàn nǐ men zài tiān de sì fāng， xiàn zài nǐ men yào cóng běi fāng zhī de táo huí. zhè shì yé hé huá shuō de."],[2,7,"與 巴比倫人同住的 錫安民哪，應當逃脫。","yǔ bā bǐ lún rén tóng zhù de xī ān mín nǎ， yīng dāng táo tuō."],[2,8,"萬軍之耶和華說，在顯出榮耀之後，差遣我去 懲罰那擄掠你們的列國，摸你們的就是摸他眼中的瞳人。","wàn jūn zhī yé hé huá shuō， zài xiǎn chū róng yào zhī hòu， chà qiǎn wǒ qù chéng fá nà lǔ lüè nǐ men de liè guó， mō nǐ men de jiù shì mō tā yǎn zhōng de tóng rén."],[2,9,"看哪，我要向他們掄手，他們就必作服事他們之人的擄物，你們便知道萬軍之耶和華差遣我了。","kàn nǎ， wǒ yào xiàng tā men lūn shǒu， tā men jiù bì zuò fú shì tā men zhī rén de lǔ wù， nǐ men biàn zhī dào wàn jūn zhī yé hé huá chà qiǎn wǒ le."],[2,10,"錫安城啊，應當歡樂歌唱，因為我來要住在你中間。這是耶和華說的。」","xī ān chéng a， yīng dāng huān lè gē chàng， yīn wèi wǒ lái yào zhù zài nǐ zhōng jiān. zhè shì yé hé huá shuō de.’"],[2,11,"那時，必有許多國歸附耶和華，作他的子民。他要住在你中間，你就知道萬軍之耶和華差遣我到你那裏去了。","nà shí， bì yǒu xǔ duō guó guī fù yé hé huá， zuò tā de zǐ mín. tā yào zhù zài nǐ zhōng jiān， nǐ jiù zhī dào wàn jūn zhī yé hé huá chà qiǎn wǒ dào nǐ nà lǐ qù le."],[2,12,"耶和華必收回 猶大作他聖地的分，也必再揀選 耶路撒冷。","yé hé huá bì shōu huí yóu dà zuò tā shèng de de fēn， yě bì zài jiǎn xuǎn yé lù sā lěng."],[2,13,"凡有血氣的都當在耶和華面前靜默無聲；因為他興起，從聖所出來了。","fán yǒu xuè qì de dōu dāng zài yé hé huá miàn qián jìng mò wú shēng； yīn wèi tā xìng qǐ， cóng shèng suǒ chū lái le."],[3,1,"天使又指給我看：大祭司 約書亞站在耶和華的使者面前；撒但也站在 約書亞的右邊，與他作對。","tiān shǐ yòu zhǐ gěi wǒ kàn： dà jì sī yuē shū yà zhàn zài yé hé huá de shǐ zhě miàn qián； sā dàn yě zhàn zài yuē shū yà de yòu biān， yǔ tā zuò duì."],[3,2,"耶和華向撒但說：「撒但哪，耶和華責備你！就是揀選 耶路撒冷的耶和華責備你！這不是從火中抽出來的一根柴嗎？」","yé hé huá xiàng sā dàn shuō：‘sā dàn nǎ， yé hé huá zé bèi nǐ！ jiù shì jiǎn xuǎn yé lù sā lěng de yé hé huá zé bèi nǐ！ zhè bù shì cóng huǒ zhōng chōu chū lái de yī gēn chái ma？’"],[3,3,"約書亞穿着污穢的衣服站在使者面前。","yuē shū yà chuān zhe wū huì de yī fú zhàn zài shǐ zhě miàn qián."],[3,4,"使者吩咐站在面前的說：「你們要脫去他污穢的衣服」；又對 約書亞說：「我使你脫離罪孽，要給你穿上華美的衣服。」","shǐ zhě fēn fù zhàn zài miàn qián de shuō：‘nǐ men yào tuō qù tā wū huì de yī fú’； yòu duì yuē shū yà shuō：‘wǒ shǐ nǐ tuō lí zuì niè， yào gěi nǐ chuān shàng huá měi de yī fú.’"],[3,5,"我說：「要將潔淨的冠冕戴在他頭上。」他們就把潔淨的冠冕戴在他頭上，給他穿上 華美的衣服，耶和華的使者在旁邊站立。","wǒ shuō：‘yào jiāng jié jìng de guān miǎn dài zài tā tóu shàng.’ tā men jiù bǎ jié jìng de guān miǎn dài zài tā tóu shàng， gěi tā chuān shàng huá měi de yī fú， yé hé huá de shǐ zhě zài páng biān zhàn lì."],[3,6,"耶和華的使者告誡 約書亞說：","yé hé huá de shǐ zhě gào jiè yuē shū yà shuō："],[3,7,"「萬軍之耶和華如此說：你若遵行我的道，謹守我的命令，你就可以管理我的家，看守我的院宇；我也要使你在這些站立的人中間來往。","‘wàn jūn zhī yé hé huá rú cǐ shuō： nǐ ruò zūn xíng wǒ de dào， jǐn shǒu wǒ de mìng lìng， nǐ jiù kě yǐ guǎn lǐ wǒ de jiā， kàn shǒu wǒ de yuàn yǔ； wǒ yě yào shǐ nǐ zài zhè xiē zhàn lì de rén zhōng jiān lái wǎng."],[3,8,"大祭司 約書亞啊，你和坐在你面前的同伴都當聽。（他們是作預兆的。）我必使我僕人 大衛的苗裔發出。","dà jì sī yuē shū yà a， nǐ hé zuò zài nǐ miàn qián de tóng bàn dōu dāng tīng.（tā men shì zuò yù zhào de.） wǒ bì shǐ wǒ pú rén dà wèi de miáo yì fā chū."],[3,9,"看哪，我在 約書亞面前所立的石頭，在一塊石頭上有七眼。萬軍之耶和華說：我要親自雕刻這石頭，並要在一日之間除掉這地的罪孽。","kàn nǎ， wǒ zài yuē shū yà miàn qián suǒ lì de shí tóu， zài yī kuài shí tóu shàng yǒu qī yǎn. wàn jūn zhī yé hé huá shuō： wǒ yào qīn zì diāo kè zhè shí tóu， bìng yào zài yī rì zhī jiān chú diào zhè de de zuì niè."],[3,10,"當那日，你們各人要請鄰舍坐在葡萄樹和無花果樹下。這是萬軍之耶和華說的。」","dāng nà rì， nǐ men gè rén yào qǐng lín shě zuò zài pú táo shù hé wú huā guǒ shù xià. zhè shì wàn jūn zhī yé hé huá shuō de.’"],[4,1,"那與我說話的天使又來叫醒我，好像人睡覺被喚醒一樣。","nà yǔ wǒ shuō huà de tiān shǐ yòu lái jiào xǐng wǒ， hǎo xiàng rén shuì jué bèi huàn xǐng yī yàng."],[4,2,"他問我說：「你看見了甚麼？」我說：「我看見了一個純金的燈臺，頂上有燈盞，燈臺上有七盞燈，每盞有七個管子。","tā wèn wǒ shuō：‘nǐ kàn jiàn le shèn me？’ wǒ shuō：‘wǒ kàn jiàn le yī gè chún jīn de dēng tái， dǐng shàng yǒu dēng zhǎn， dēng tái shàng yǒu qī zhǎn dēng， měi zhǎn yǒu qī gè guǎn zǐ."],[4,3,"旁邊有兩棵橄欖樹，一棵在燈盞的右邊，一棵在燈盞的左邊。」","páng biān yǒu liǎng kē gǎn lǎn shù， yī kē zài dēng zhǎn de yòu biān， yī kē zài dēng zhǎn de zuǒ biān.’"],[4,4,"我問與我說話的天使說：「主啊，這是甚麼意思？」","wǒ wèn yǔ wǒ shuō huà de tiān shǐ shuō：‘zhǔ a， zhè shì shèn me yì sī？’"],[4,5,"與我說話的天使回答我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","yǔ wǒ shuō huà de tiān shǐ huí dá wǒ shuō：‘nǐ bù zhī dào zhè shì shèn me yì sī ma？’ wǒ shuō：‘zhǔ a， wǒ bù zhī dào.’"],[4,6,"他對我說：「這是耶和華指示 所羅巴伯的。萬軍之耶和華說：不是倚靠勢力，不是倚靠才能，乃是倚靠我的靈 方能成事。","tā duì wǒ shuō：‘zhè shì yé hé huá zhǐ shì suǒ luó bā bó de. wàn jūn zhī yé hé huá shuō： bù shì yǐ kào shì lì， bù shì yǐ kào cái néng， nǎi shì yǐ kào wǒ de líng fāng néng chéng shì."],[4,7,"大山哪，你算甚麼呢？在 所羅巴伯面前，你必成為平地。他必搬出一塊石頭，安在 殿頂上。人且大聲歡呼說：『願恩惠恩惠歸與這殿！』」","dà shān nǎ， nǐ suàn shèn me ne？ zài suǒ luó bā bó miàn qián， nǐ bì chéng wèi píng de. tā bì bān chū yī kuài shí tóu， ān zài diàn dǐng shàng. rén qiě dà shēng huān hū shuō：“yuàn ēn huì ēn huì guī yǔ zhè diàn！”’"],[4,8,"耶和華的話又臨到我說：","yé hé huá de huà yòu lín dào wǒ shuō："],[4,9,"「 所羅巴伯的手立了這殿的根基，他的手也必完成這工，你就知道萬軍之耶和華差遣我到你們這裏來了。","‘ suǒ luó bā bó de shǒu lì le zhè diàn de gēn jī， tā de shǒu yě bì wán chéng zhè gōng， nǐ jiù zhī dào wàn jūn zhī yé hé huá chà qiǎn wǒ dào nǐ men zhè lǐ lái le."],[4,10,"誰藐視這日的事為小呢？這七 眼乃是耶和華的眼睛，遍察全地，見 所羅巴伯手拿線鉈就歡喜。」","shuí miǎo shì zhè rì de shì wèi xiǎo ne？ zhè qī yǎn nǎi shì yé hé huá de yǎn jīng， biàn chá quán de， jiàn suǒ luó bā bó shǒu ná xiàn shī jiù huān xǐ.’"],[4,11,"我又問天使說：「這燈臺左右的兩棵橄欖樹是甚麼意思？」","wǒ yòu wèn tiān shǐ shuō：‘zhè dēng tái zuǒ yòu de liǎng kē gǎn lǎn shù shì shèn me yì sī？’"],[4,12,"我二次問他說：「這兩根橄欖枝在兩個流出金色 油的金嘴旁邊是甚麼意思？」","wǒ èr cì wèn tā shuō：‘zhè liǎng gēn gǎn lǎn zhī zài liǎng gè liú chū jīn sè yóu de jīn zuǐ páng biān shì shèn me yì sī？’"],[4,13,"他對我說：「你不知道這是甚麼意思嗎？」我說：「主啊，我不知道。」","tā duì wǒ shuō：‘nǐ bù zhī dào zhè shì shèn me yì sī ma？’ wǒ shuō：‘zhǔ a， wǒ bù zhī dào.’"],[4,14,"他說：「這是兩個受膏者站在普天下主的旁邊。」","tā shuō：‘zhè shì liǎng gè shòu gāo zhě zhàn zài pǔ tiān xià zhǔ de páng biān.’"],[5,1,"我又舉目觀看，見有一飛行的書卷。","wǒ yòu jǔ mù guān kàn， jiàn yǒu yī fēi xíng de shū juǎn."],[5,2,"他問我說：「你看見甚麼？」我回答說：「我看見一飛行的書卷，長二十肘，寬十肘。」","tā wèn wǒ shuō：‘nǐ kàn jiàn shèn me？’ wǒ huí dá shuō：‘wǒ kàn jiàn yī fēi xíng de shū juǎn， zhǎng èr shí zhǒu， kuān shí zhǒu.’"],[5,3,"他對我說：「這是發出行在遍地上的咒詛。凡偷竊的必按卷上這面的話除滅；凡起 假誓的必按卷上那面的話除滅。","tā duì wǒ shuō：‘zhè shì fā chū xíng zài biàn de shàng de zhòu zǔ. fán tōu qiè de bì àn juǎn shàng zhè miàn de huà chú miè； fán qǐ jiǎ shì de bì àn juǎn shàng nà miàn de huà chú miè."],[5,4,"萬軍之耶和華說：我必使這書卷出去，進入偷竊人的家和指我名起假誓人的家，必常在他家裏，連房屋帶木石都毀滅了。」","wàn jūn zhī yé hé huá shuō： wǒ bì shǐ zhè shū juǎn chū qù， jìn rù tōu qiè rén de jiā hé zhǐ wǒ míng qǐ jiǎ shì rén de jiā， bì cháng zài tā jiā lǐ， lián fáng wū dài mù shí dōu huǐ miè le.’"],[5,5,"與我說話的天使出來，對我說：「你要舉目觀看，見所出來的是甚麼？」","yǔ wǒ shuō huà de tiān shǐ chū lái， duì wǒ shuō：‘nǐ yào jǔ mù guān kàn， jiàn suǒ chū lái de shì shèn me？’"],[5,6,"我說：「這是甚麼呢？」他說：「這出來的是量器。」他又說：「這是惡人在遍地的形狀。」","wǒ shuō：‘zhè shì shèn me ne？’ tā shuō：‘zhè chū lái de shì liàng qì.’ tā yòu shuō：‘zhè shì è rén zài biàn de de xíng zhuàng.’"],[5,7,"（我見有一片圓鉛被舉起來。）這坐在量器中的是個婦人。","（wǒ jiàn yǒu yī piàn yuán qiān bèi jǔ qǐ lái.） zhè zuò zài liàng qì zhōng de shì gè fù rén."],[5,8,"天使說：「這是罪惡。」他就把婦人扔在量器中，將那片圓鉛扔在量器的口上。","tiān shǐ shuō：‘zhè shì zuì è.’ tā jiù bǎ fù rén rēng zài liàng qì zhōng， jiāng nà piàn yuán qiān rēng zài liàng qì de kǒu shàng."],[5,9,"我又舉目觀看，見有兩個婦人出來，在她們翅膀中有風， 飛得甚快，翅膀如同鸛鳥的翅膀。她們將量器抬起來，懸在天地中間。","wǒ yòu jǔ mù guān kàn， jiàn yǒu liǎng gè fù rén chū lái， zài tā men chì bǎng zhōng yǒu fēng， fēi dé shèn kuài， chì bǎng rú tóng guàn niǎo de chì bǎng. tā men jiāng liàng qì tái qǐ lái， xuán zài tiān de zhōng jiān."],[5,10,"我問與我說話的天使說：「她們要將量器抬到哪裏去呢？」","wǒ wèn yǔ wǒ shuō huà de tiān shǐ shuō：‘tā men yào jiāng liàng qì tái dào nǎ lǐ qù ne？’"],[5,11,"他對我說：「要往 示拿地去，為它蓋造房屋；等房屋齊備，就把它安置在自己的地方。」","tā duì wǒ shuō：‘yào wǎng shì ná de qù， wèi tā gài zào fáng wū； děng fáng wū qí bèi， jiù bǎ tā ān zhì zài zì jǐ de de fāng.’"],[6,1,"我又舉目觀看，見有四輛車從兩山中間出來；那山是銅山。","wǒ yòu jǔ mù guān kàn， jiàn yǒu sì liàng chē cóng liǎng shān zhōng jiān chū lái； nà shān shì tóng shān."],[6,2,"第一輛車套着紅馬，第二輛車套着黑馬。","dì yī liàng chē tào zhe hóng mǎ， dì èr liàng chē tào zhe hēi mǎ."],[6,3,"第三輛車套着白馬，第四輛車套着有斑點的壯馬。","dì sān liàng chē tào zhe bái mǎ， dì sì liàng chē tào zhe yǒu bān diǎn de zhuàng mǎ."],[6,4,"我就問與我說話的天使說：「主啊，這是甚麼意思？」","wǒ jiù wèn yǔ wǒ shuō huà de tiān shǐ shuō：‘zhǔ a， zhè shì shèn me yì sī？’"],[6,5,"天使回答我說：「這是天的四風，是從普天下的主面前出來的。」","tiān shǐ huí dá wǒ shuō：‘zhè shì tiān de sì fēng， shì cóng pǔ tiān xià de zhǔ miàn qián chū lái de.’"],[6,6,"套着黑馬的 車往北方去，白馬跟隨在後；有斑點的馬往南方去。","tào zhe hēi mǎ de chē wǎng běi fāng qù， bái mǎ gēn suí zài hòu； yǒu bān diǎn de mǎ wǎng nán fāng qù."],[6,7,"壯馬出來，要在遍地走來走去。天使說：「你們只管在遍地走來走去。」牠們就照樣行了。","zhuàng mǎ chū lái， yào zài biàn de zǒu lái zǒu qù. tiān shǐ shuō：‘nǐ men zhǐ guǎn zài biàn de zǒu lái zǒu qù.’ tā men jiù zhào yàng xíng le."],[6,8,"他又呼叫我說：「看哪，往北方去的已在北方安慰我的心。」","tā yòu hū jiào wǒ shuō：‘kàn nǎ， wǎng běi fāng qù de yǐ zài běi fāng ān wèi wǒ de xīn.’"],[6,9,"耶和華的話臨到我說：","yé hé huá de huà lín dào wǒ shuō："],[6,10,"「你要從被擄之人中取 黑玳、 多比雅、 耶大雅的 金銀。這三人是從 巴比倫來到 西番雅的兒子 約西亞的家裏。當日你要進他的家，","‘nǐ yào cóng bèi lǔ zhī rén zhōng qǔ hēi dài, duō bǐ yǎ, yé dà yǎ de jīn yín. zhè sān rén shì cóng bā bǐ lún lái dào xī fān yǎ de ér zǐ yuē xī yà de jiā lǐ. dāng rì nǐ yào jìn tā de jiā，"],[6,11,"取這金銀做冠冕，戴在 約撒答的兒子大祭司 約書亞的頭上，","qǔ zhè jīn yín zuò guān miǎn， dài zài yuē sā dá de ér zǐ dà jì sī yuē shū yà de tóu shàng，"],[6,12,"對他說，萬軍之耶和華如此說：看哪，那名稱為 大衛苗裔的，他要在本處長起來，並要建造耶和華的殿。","duì tā shuō， wàn jūn zhī yé hé huá rú cǐ shuō： kàn nǎ， nà míng chēng wèi dà wèi miáo yì de， tā yào zài běn chù zhǎng qǐ lái， bìng yào jiàn zào yé hé huá de diàn."],[6,13,"他要建造耶和華的殿，並擔負尊榮，坐在位上掌王權；又必在位上作祭司，使兩職之間籌定和平。","tā yào jiàn zào yé hé huá de diàn， bìng dān fù zūn róng， zuò zài wèi shàng zhǎng wáng quán； yòu bì zài wèi shàng zuò jì sī， shǐ liǎng zhí zhī jiān chóu dìng hé píng."],[6,14,"這冠冕要歸 希連、 多比雅、 耶大雅，和 西番雅的兒子 賢，放在耶和華的殿裏為記念。」","zhè guān miǎn yào guī xī lián, duō bǐ yǎ, yé dà yǎ， hé xī fān yǎ de ér zǐ xián， fàng zài yé hé huá de diàn lǐ wèi jì niàn.’"],[6,15,"遠方的人也要來建造耶和華的殿，你們就知道萬軍之耶和華差遣我到你們這裏來。你們若留意聽從耶和華－你們神的話， 這事必然成就。","yuǎn fāng de rén yě yào lái jiàn zào yé hé huá de diàn， nǐ men jiù zhī dào wàn jūn zhī yé hé huá chà qiǎn wǒ dào nǐ men zhè lǐ lái. nǐ men ruò liú yì tīng cóng yé hé huá－nǐ men shén de huà， zhè shì bì rán chéng jiù."],[7,1,"大流士王第四年九月，就是基斯流月初四日，耶和華的話臨到 撒迦利亞。","dà liú shì wáng dì sì nián jiǔ yuè， jiù shì jī sī liú yuè chū sì rì， yé hé huá de huà lín dào sā jiā lì yà."],[7,2,"那時 伯特利人已經打發 沙利色和 利堅米勒，並跟從他們的人，去懇求耶和華的恩，","nà shí bó tè lì rén yǐ jīng dǎ fā shā lì sè hé lì jiān mǐ lēi， bìng gēn cóng tā men de rén， qù kěn qiú yé hé huá de ēn，"],[7,3,"並問萬軍之耶和華殿中的祭司和先知說：「我歷年以來，在五月間哭泣齋戒，現在還當這樣行嗎？」","bìng wèn wàn jūn zhī yé hé huá diàn zhōng de jì sī hé xiān zhī shuō：‘wǒ lì nián yǐ lái， zài wǔ yuè jiān kū qì zhāi jiè， xiàn zài hái dāng zhè yàng xíng ma？’"],[7,4,"萬軍之耶和華的話就臨到我說：","wàn jūn zhī yé hé huá de huà jiù lín dào wǒ shuō："],[7,5,"「你要宣告國內的眾民和祭司，說：『你們這七十年，在五月、七月禁食悲哀，豈是絲毫向我禁食嗎？","‘nǐ yào xuān gào guó nèi de zhòng mín hé jì sī， shuō：“nǐ men zhè qī shí nián， zài wǔ yuè, qī yuè jìn shí bēi āi， qǐ shì sī háo xiàng wǒ jìn shí ma？"],[7,6,"你們吃喝，不是為自己吃，為自己喝嗎？","nǐ men chī hē， bù shì wèi zì jǐ chī， wèi zì jǐ hē ma？"],[7,7,"當 耶路撒冷和四圍的城邑有居民，正興盛，南地高原有人居住的時候，耶和華藉從前的先知所宣告的話，你們不 當聽嗎？』」","dāng yé lù sā lěng hé sì wéi de chéng yì yǒu jū mín， zhèng xìng shèng， nán de gāo yuán yǒu rén jū zhù de shí hòu， yé hé huá jí cóng qián de xiān zhī suǒ xuān gào de huà， nǐ men bù dāng tīng ma？”’"],[7,8,"耶和華的話又臨到 撒迦利亞說：","yé hé huá de huà yòu lín dào sā jiā lì yà shuō："],[7,9,"「萬軍之耶和華曾對 你們的列祖如此說：『要按至理判斷，各人以慈愛憐憫弟兄。","‘wàn jūn zhī yé hé huá céng duì nǐ men de liè zǔ rú cǐ shuō：“yào àn zhì lǐ pàn duàn， gè rén yǐ cí ài lián mǐn dì xiōng."],[7,10,"不可欺壓寡婦、孤兒、寄居的，和貧窮人。誰都不可心裏謀害弟兄。』」","bù kě qī yā guǎ fù, gū ér, jì jū de， hé pín qióng rén. shuí dōu bù kě xīn lǐ móu hài dì xiōng.”’"],[7,11,"他們卻不肯聽從，扭轉肩頭，塞耳不聽，","tā men què bù kěn tīng cóng， niǔ zhuǎn jiān tóu， sāi ěr bù tīng，"],[7,12,"使心硬如金鋼石，不聽律法和萬軍之耶和華用靈藉從前的先知所說的話。故此，萬軍之耶和華大發烈怒。","shǐ xīn yìng rú jīn gāng shí， bù tīng lǜ fǎ hé wàn jūn zhī yé hé huá yòng líng jí cóng qián de xiān zhī suǒ shuō de huà. gù cǐ， wàn jūn zhī yé hé huá dà fā liè nù."],[7,13,"萬軍之耶和華說：「我曾呼喚他們，他們不聽；將來他們呼求我，我也不聽！","wàn jūn zhī yé hé huá shuō：‘wǒ céng hū huàn tā men， tā men bù tīng； jiāng lái tā men hū qiú wǒ， wǒ yě bù tīng！"],[7,14,"我必以旋風吹散他們到素不認識的萬國中。這樣，他們的地就荒涼，甚至無人來往經過，因為他們使美好之地荒涼了。」","wǒ bì yǐ xuán fēng chuī sàn tā men dào sù bù rèn shí de wàn guó zhōng. zhè yàng， tā men de de jiù huāng liáng， shèn zhì wú rén lái wǎng jīng guò， yīn wèi tā men shǐ měi hǎo zhī de huāng liáng le.’"],[8,1,"萬軍之耶和華的話臨到我說：","wàn jūn zhī yé hé huá de huà lín dào wǒ shuō："],[8,2,"「萬軍之耶和華如此說：我為 錫安心裏極其火熱，我為她火熱，向 她的仇敵發烈怒。","‘wàn jūn zhī yé hé huá rú cǐ shuō： wǒ wèi xī ān xīn lǐ jí qí huǒ rè， wǒ wèi tā huǒ rè， xiàng tā de chóu dí fā liè nù."],[8,3,"耶和華如此說：我現在回到 錫安，要住在 耶路撒冷中。 耶路撒冷必稱為誠實的城，萬軍之耶和華的山必稱為聖山。","yé hé huá rú cǐ shuō： wǒ xiàn zài huí dào xī ān， yào zhù zài yé lù sā lěng zhōng. yé lù sā lěng bì chēng wèi chéng shí de chéng， wàn jūn zhī yé hé huá de shān bì chēng wèi shèng shān."],[8,4,"萬軍之耶和華如此說：將來必有年老的男女坐在 耶路撒冷街上，因為年紀老邁就手拿柺杖。","wàn jūn zhī yé hé huá rú cǐ shuō： jiāng lái bì yǒu nián lǎo de nán nǚ zuò zài yé lù sā lěng jiē shàng， yīn wèi nián jì lǎo mài jiù shǒu ná guǎi zhàng."],[8,5,"城中街上必滿有男孩女孩玩耍。","chéng zhōng jiē shàng bì mǎn yǒu nán hái nǚ hái wán shuǎ."],[8,6,"萬軍之耶和華如此說：到那日，這事在餘剩的民眼中看為希奇，在我眼中也看為希奇嗎？這是萬軍之耶和華說的。","wàn jūn zhī yé hé huá rú cǐ shuō： dào nà rì， zhè shì zài yú shèng de mín yǎn zhōng kàn wèi xī qí， zài wǒ yǎn zhōng yě kàn wèi xī qí ma？ zhè shì wàn jūn zhī yé hé huá shuō de."],[8,7,"萬軍之耶和華如此說：我要從東方從西方救回我的民。","wàn jūn zhī yé hé huá rú cǐ shuō： wǒ yào cóng dōng fāng cóng xī fāng jiù huí wǒ de mín."],[8,8,"我要領他們來，使他們住在 耶路撒冷中。他們要作我的子民，我要作他們的神，都憑誠實和公義。」","wǒ yào lǐng tā men lái， shǐ tā men zhù zài yé lù sā lěng zhōng. tā men yào zuò wǒ de zǐ mín， wǒ yào zuò tā men de shén， dōu píng chéng shí hé gōng yì.’"],[8,9,"萬軍之耶和華如此說：「當建造萬軍之耶和華的殿，立根基之日的先知所說的話，現在你們聽見，應當手裏強壯。","wàn jūn zhī yé hé huá rú cǐ shuō：‘dāng jiàn zào wàn jūn zhī yé hé huá de diàn， lì gēn jī zhī rì de xiān zhī suǒ shuō de huà， xiàn zài nǐ men tīng jiàn， yīng dāng shǒu lǐ qiáng zhuàng."],[8,10,"那日以先，人得不着雇價，牲畜也是如此；且因敵人的緣故，出入之人不得平安，乃因我使眾人互相攻擊。","nà rì yǐ xiān， rén dé bù zhe gù jià， shēng chù yě shì rú cǐ； qiě yīn dí rén de yuán gù， chū rù zhī rén bù dé píng ān， nǎi yīn wǒ shǐ zhòng rén hù xiāng gōng jī."],[8,11,"但如今，我待這餘剩的民必不像從前。這是萬軍之耶和華說的。","dàn rú jīn， wǒ dài zhè yú shèng de mín bì bù xiàng cóng qián. zhè shì wàn jūn zhī yé hé huá shuō de."],[8,12,"因為他們必平安撒種，葡萄樹必結果子，地土必有出產，天也必降甘露。我要使這餘剩的民享受這一切的福。","yīn wèi tā men bì píng ān sā zhǒng， pú táo shù bì jié guǒ zǐ， de tǔ bì yǒu chū chǎn， tiān yě bì jiàng gān lù. wǒ yào shǐ zhè yú shèng de mín xiǎng shòu zhè yī qiè de fú."],[8,13,"猶大家和 以色列家啊，你們從前在列國中怎樣成為可咒詛的；照樣，我要拯救你們，使人稱你們為有福的。你們不要懼怕，手要強壯。」","yóu dà jiā hé yǐ sè liè jiā a， nǐ men cóng qián zài liè guó zhōng zěn yàng chéng wèi kě zhòu zǔ de； zhào yàng， wǒ yào zhěng jiù nǐ men， shǐ rén chēng nǐ men wèi yǒu fú de. nǐ men bù yào jù pà， shǒu yào qiáng zhuàng.’"],[8,14,"萬軍之耶和華如此說：「你們列祖惹我發怒的時候，我怎樣定意降禍，並不後悔。","wàn jūn zhī yé hé huá rú cǐ shuō：‘nǐ men liè zǔ rě wǒ fā nù de shí hòu， wǒ zěn yàng dìng yì jiàng huò， bìng bù hòu huǐ."],[8,15,"現在我照樣定意施恩與 耶路撒冷和 猶大家，你們不要懼怕。","xiàn zài wǒ zhào yàng dìng yì shī ēn yǔ yé lù sā lěng hé yóu dà jiā， nǐ men bù yào jù pà."],[8,16,"你們所當行的是這樣：各人與鄰舍說話誠實，在城門口按至理判斷，使人和睦。","nǐ men suǒ dāng xíng de shì zhè yàng： gè rén yǔ lín shě shuō huà chéng shí， zài chéng mén kǒu àn zhì lǐ pàn duàn， shǐ rén hé mù."],[8,17,"誰都不可心裏謀害鄰舍，也不可喜愛起假誓，因為這些事都為我所恨惡。這是耶和華說的。」","shuí dōu bù kě xīn lǐ móu hài lín shě， yě bù kě xǐ ài qǐ jiǎ shì， yīn wèi zhè xiē shì dōu wèi wǒ suǒ hèn è. zhè shì yé hé huá shuō de.’"],[8,18,"萬軍之耶和華的話臨到我說：","wàn jūn zhī yé hé huá de huà lín dào wǒ shuō："],[8,19,"「萬軍之耶和華如此說：四月、五月禁食的日子，七月、十月禁食的日子，必變為 猶大家歡喜快樂的日子和歡樂的節期；所以你們要喜愛誠實與和平。」","‘wàn jūn zhī yé hé huá rú cǐ shuō： sì yuè, wǔ yuè jìn shí de rì zǐ， qī yuè, shí yuè jìn shí de rì zǐ， bì biàn wèi yóu dà jiā huān xǐ kuài lè de rì zǐ hé huān lè de jié qī； suǒ yǐ nǐ men yào xǐ ài chéng shí yǔ hé píng.’"],[8,20,"萬軍之耶和華如此說：「將來必有列國的人和多城的居民來到。","wàn jūn zhī yé hé huá rú cǐ shuō：‘jiāng lái bì yǒu liè guó de rén hé duō chéng de jū mín lái dào."],[8,21,"這城的居民必到那城，說：『我們要快去懇求耶和華的恩，尋求萬軍之耶和華；我也要去。』","zhè chéng de jū mín bì dào nà chéng， shuō：“wǒ men yào kuài qù kěn qiú yé hé huá de ēn， xún qiú wàn jūn zhī yé hé huá； wǒ yě yào qù.”"],[8,22,"必有列邦的人和強國的民來到 耶路撒冷尋求萬軍之耶和華，懇求耶和華的恩。","bì yǒu liè bāng de rén hé qiáng guó de mín lái dào yé lù sā lěng xún qiú wàn jūn zhī yé hé huá， kěn qiú yé hé huá de ēn."],[8,23,"萬軍之耶和華如此說：在那些日子，必有十個人從列國諸族中出來，拉住一個 猶大人的衣襟，說：『我們要與你們同去，因為我們聽見神與你們同在了。』」","wàn jūn zhī yé hé huá rú cǐ shuō： zài nà xiē rì zǐ， bì yǒu shí gè rén cóng liè guó zhū zú zhōng chū lái， lā zhù yī gè yóu dà rén de yī jīn， shuō：“wǒ men yào yǔ nǐ men tóng qù， yīn wèi wǒ men tīng jiàn shén yǔ nǐ men tóng zài le.”’"],[9,1,"耶和華的默示應驗在 哈得拉地 大馬士革 －世人和 以色列各支派的眼目都仰望耶和華－","yé hé huá de mò shì yīng yàn zài hā dé lā de dà mǎ shì gé －shì rén hé yǐ sè liè gè zhī pài de yǎn mù dōu yǎng wàng yé hé huá－"],[9,2,"和靠近的 哈馬，並 泰爾、 西頓； 因為這二城的人大有智慧。","hé kào jìn de hā mǎ， bìng tài ěr, xī dùn； yīn wèi zhè èr chéng de rén dà yǒu zhì huì."],[9,3,"泰爾為自己修築保障， 積蓄銀子如塵沙， 堆起精金如街上的泥土。","tài ěr wèi zì jǐ xiū zhú bǎo zhàng， jī xù yín zǐ rú chén shā， duī qǐ jīng jīn rú jiē shàng de ní tǔ."],[9,4,"主必趕出她， 打敗她海上的權利； 她必被火燒滅。","zhǔ bì gǎn chū tā， dǎ bài tā hǎi shàng de quán lì； tā bì bèi huǒ shāo miè."],[9,5,"亞實基倫看見必懼怕； 迦薩看見甚痛苦； 以革倫因失了盼望蒙羞。 迦薩必不再有君王； 亞實基倫也不再有居民。","yà shí jī lún kàn jiàn bì jù pà； jiā sà kàn jiàn shèn tòng kǔ； yǐ gé lún yīn shī le pàn wàng méng xiū. jiā sà bì bù zài yǒu jūn wáng； yà shí jī lún yě bù zài yǒu jū mín."],[9,6,"私生子必住在 亞實突； 我必除滅 非利士人的驕傲。","sī shēng zǐ bì zhù zài yà shí tū； wǒ bì chú miè fēi lì shì rén de jiāo ào."],[9,7,"我必除去他口中帶血之肉 和牙齒內可憎之物。 他必作為餘剩的人歸與我們的神， 必在 猶大像族長； 以革倫人必如 耶布斯人。","wǒ bì chú qù tā kǒu zhōng dài xuè zhī ròu hé yá chǐ nèi kě zēng zhī wù. tā bì zuò wèi yú shèng de rén guī yǔ wǒ men de shén， bì zài yóu dà xiàng zú zhǎng； yǐ gé lún rén bì rú yé bù sī rén."],[9,8,"我必在我家的四圍安營， 使敵軍不得任意往來， 暴虐的人也不再經過， 因為我親眼看顧 我的家。","wǒ bì zài wǒ jiā de sì wéi ān yíng， shǐ dí jūn bù dé rèn yì wǎng lái， bào nüè de rén yě bù zài jīng guò， yīn wèi wǒ qīn yǎn kàn gù wǒ de jiā."],[9,9,"錫安的民哪，應當大大喜樂； 耶路撒冷的民哪，應當歡呼。 看哪，你的王來到你這裏！ 他是公義的，並且施行拯救， 謙謙和和地騎着驢， 就是騎着驢的駒子。","xī ān de mín nǎ， yīng dāng dà dà xǐ lè； yé lù sā lěng de mín nǎ， yīng dāng huān hū. kàn nǎ， nǐ de wáng lái dào nǐ zhè lǐ！ tā shì gōng yì de， bìng qiě shī xíng zhěng jiù， qiān qiān hé hé de qí zhe lǘ， jiù shì qí zhe lǘ de jū zǐ."],[9,10,"我必除滅 以法蓮的戰車 和 耶路撒冷的戰馬； 爭戰的弓也必除滅。 他必向列國講和平； 他的權柄必從這海管到那海， 從大河管到地極。","wǒ bì chú miè yǐ fǎ lián de zhàn chē hé yé lù sā lěng de zhàn mǎ； zhēng zhàn de gōng yě bì chú miè. tā bì xiàng liè guó jiǎng hé píng； tā de quán bǐng bì cóng zhè hǎi guǎn dào nà hǎi， cóng dà hé guǎn dào de jí."],[9,11,"錫安哪，我因與你立約的血， 將你中間被擄而囚的人從無水的坑中釋放出來。","xī ān nǎ， wǒ yīn yǔ nǐ lì yuē de xuè， jiāng nǐ zhōng jiān bèi lǔ ér qiú de rén cóng wú shuǐ de kēng zhōng shì fàng chū lái."],[9,12,"你們被囚而有指望的人都要轉回保障。 我今日說明，我必加倍賜福給你們。","nǐ men bèi qiú ér yǒu zhǐ wàng de rén dōu yào zhuǎn huí bǎo zhàng. wǒ jīn rì shuō míng， wǒ bì jiā bèi cì fú gěi nǐ men."],[9,13,"我拿 猶大作上弦的弓； 我拿 以法蓮為張弓的箭。 錫安哪，我要激發你的眾子， 攻擊 希臘的眾子，使你如勇士的刀。","wǒ ná yóu dà zuò shàng xián de gōng； wǒ ná yǐ fǎ lián wèi zhāng gōng de jiàn. xī ān nǎ， wǒ yào jī fā nǐ de zhòng zǐ， gōng jī xī là de zhòng zǐ， shǐ nǐ rú yǒng shì de dāo."],[9,14,"耶和華必顯現在他們以上； 他的箭必射出像閃電。 主耶和華必吹角， 乘南方的旋風而行。","yé hé huá bì xiǎn xiàn zài tā men yǐ shàng； tā de jiàn bì shè chū xiàng shǎn diàn. zhǔ yé hé huá bì chuī jiǎo， chéng nán fāng de xuán fēng ér xíng."],[9,15,"萬軍之耶和華必保護他們； 他們必吞滅 仇敵，踐踏彈石。 他們必喝 血吶喊，猶如飲酒； 他們必像盛滿 血的碗， 又像壇的四角滿了 血。","wàn jūn zhī yé hé huá bì bǎo hù tā men； tā men bì tūn miè chóu dí， jiàn tà dàn shí. tā men bì hē xuè nà hǎn， yóu rú yǐn jiǔ； tā men bì xiàng shèng mǎn xuè de wǎn， yòu xiàng tán de sì jiǎo mǎn le xuè."],[9,16,"當那日，耶和華－他們的神 必看他的民如群羊，拯救他們； 因為 他們必像冠冕上的寶石， 高舉在他的地以上。","dāng nà rì， yé hé huá－tā men de shén bì kàn tā de mín rú qún yáng， zhěng jiù tā men； yīn wèi tā men bì xiàng guān miǎn shàng de bǎo shí， gāo jǔ zài tā de de yǐ shàng."],[9,17,"他的恩慈何等大！ 他的榮美何其盛！ 五穀健壯少男； 新酒培養處女。","tā de ēn cí hé děng dà！ tā de róng měi hé qí shèng！ wǔ gǔ jiàn zhuàng shǎo nán； xīn jiǔ péi yǎng chù nǚ."],[10,1,"當春雨的時候， 你們要向發閃電的耶和華求雨。 他必為眾人降下甘霖， 使田園生長菜蔬。","dāng chūn yǔ de shí hòu， nǐ men yào xiàng fā shǎn diàn de yé hé huá qiú yǔ. tā bì wèi zhòng rén jiàng xià gān lín， shǐ tián yuán shēng zhǎng cài shū."],[10,2,"因為，家神所言的是虛空； 卜士所見的是虛假； 做夢者所說的是假夢。 他們白白地安慰人， 所以眾人如羊流離， 因無牧人就受苦。","yīn wèi， jiā shén suǒ yán de shì xū kōng； bo shì suǒ jiàn de shì xū jiǎ； zuò mèng zhě suǒ shuō de shì jiǎ mèng. tā men bái bái de ān wèi rén， suǒ yǐ zhòng rén rú yáng liú lí， yīn wú mù rén jiù shòu kǔ."],[10,3,"我的怒氣向牧人發作； 我必懲罰公山羊； 因我－萬軍之耶和華 眷顧自己的羊群，就是 猶大家， 必使他們如駿馬在陣上。","wǒ de nù qì xiàng mù rén fā zuò； wǒ bì chéng fá gōng shān yáng； yīn wǒ－wàn jūn zhī yé hé huá juàn gù zì jǐ de yáng qún， jiù shì yóu dà jiā， bì shǐ tā men rú jùn mǎ zài zhèn shàng."],[10,4,"房角石、釘子、爭戰的弓， 和一切掌權的都從他而出。","fáng jiǎo shí, dīng zǐ, zhēng zhàn de gōng， hé yī qiè zhǎng quán de dōu cóng tā ér chū."],[10,5,"他們必如勇士在陣上 將 仇敵踐踏在街上的泥土中。 他們必爭戰，因為耶和華與他們同在； 騎馬的也必羞愧。","tā men bì rú yǒng shì zài zhèn shàng jiāng chóu dí jiàn tà zài jiē shàng de ní tǔ zhōng. tā men bì zhēng zhàn， yīn wèi yé hé huá yǔ tā men tóng zài； qí mǎ de yě bì xiū kuì."],[10,6,"我要堅固 猶大家，拯救 約瑟家， 要領他們歸回。 我要憐恤他們； 他們必像未曾棄絕的一樣， 都因我是耶和華－他們的神， 我必應允他們 的禱告。","wǒ yào jiān gù yóu dà jiā， zhěng jiù yuē sè jiā， yào lǐng tā men guī huí. wǒ yào lián xù tā men； tā men bì xiàng wèi céng qì jué de yī yàng， dōu yīn wǒ shì yé hé huá－tā men de shén， wǒ bì yīng yǔn tā men de dǎo gào."],[10,7,"以法蓮人必如勇士； 他們心中暢快如同喝酒； 他們的兒女必看見而快活； 他們的心必因耶和華喜樂。","yǐ fǎ lián rén bì rú yǒng shì； tā men xīn zhōng chàng kuài rú tóng hē jiǔ； tā men de ér nǚ bì kàn jiàn ér kuài huó； tā men de xīn bì yīn yé hé huá xǐ lè."],[10,8,"我要發嘶聲，聚集他們， 因我已經救贖他們。 他們的人數必加增， 如從前加增一樣。","wǒ yào fā sī shēng， jù jí tā men， yīn wǒ yǐ jīng jiù shú tā men. tā men de rén shù bì jiā zēng， rú cóng qián jiā zēng yī yàng."],[10,9,"我雖然播散他們在列國中， 他們必在遠方記念我。 他們與兒女都必存活，且得歸回。","wǒ suī rán bō sàn tā men zài liè guó zhōng， tā men bì zài yuǎn fāng jì niàn wǒ. tā men yǔ ér nǚ dōu bì cún huó， qiě dé guī huí."],[10,10,"我必再領他們出 埃及地， 招聚他們出 亞述， 領他們到 基列和 黎巴嫩； 這地尚且不夠他們居住。","wǒ bì zài lǐng tā men chū āi jí de， zhāo jù tā men chū yà shù， lǐng tā men dào jī liè hé lí bā nèn； zhè de shàng qiě bù gòu tā men jū zhù."],[10,11,"耶和華必經過苦海，擊打海浪， 使 尼羅河的深處都枯乾。 亞述的驕傲必致卑微； 埃及的權柄必然滅沒。","yé hé huá bì jīng guò kǔ hǎi， jī dǎ hǎi làng， shǐ ní luó hé de shēn chù dōu kū qián. yà shù de jiāo ào bì zhì bēi wēi； āi jí de quán bǐng bì rán miè méi."],[10,12,"我必使他們倚靠我，得以堅固； 一舉一動必奉我的名。 這是耶和華說的。","wǒ bì shǐ tā men yǐ kào wǒ， dé yǐ jiān gù； yī jǔ yī dòng bì fèng wǒ de míng. zhè shì yé hé huá shuō de."],[11,1,"黎巴嫩哪，開開你的門， 任火燒滅你的香柏樹。","lí bā nèn nǎ， kāi kāi nǐ de mén， rèn huǒ shāo miè nǐ de xiāng bǎi shù."],[11,2,"松樹啊，應當哀號； 因為香柏樹傾倒，佳美的樹毀壞。 巴珊的橡樹啊，應當哀號， 因為茂盛的樹林已經倒了。","sōng shù a， yīng dāng āi hào； yīn wèi xiāng bǎi shù qīng dào， jiā měi de shù huǐ huài. bā shān de xiàng shù a， yīng dāng āi hào， yīn wèi mào shèng de shù lín yǐ jīng dào le."],[11,3,"聽啊，有牧人哀號的聲音， 因他們榮華 的草場毀壞了。 有少壯獅子咆哮的聲音， 因 約旦河旁的叢林荒廢了。","tīng a， yǒu mù rén āi hào de shēng yīn， yīn tā men róng huá de cǎo chǎng huǐ huài le. yǒu shǎo zhuàng shī zǐ páo xiào de shēng yīn， yīn yuē dàn hé páng de cóng lín huāng fèi le."],[11,4,"耶和華－我的神如此說：「你－ 撒迦利亞要牧養這將宰的群羊。","yé hé huá－wǒ de shén rú cǐ shuō：‘nǐ－ sā jiā lì yà yào mù yǎng zhè jiāng zǎi de qún yáng."],[11,5,"買他們的宰了他們，以自己為無罪；賣他們的說：『耶和華是應當稱頌的，因我成為富足。』牧養他們的並不憐恤他們。","mǎi tā men de zǎi le tā men， yǐ zì jǐ wèi wú zuì； mài tā men de shuō：“yé hé huá shì yīng dāng chēng sòng de， yīn wǒ chéng wèi fù zú.” mù yǎng tā men de bìng bù lián xù tā men."],[11,6,"耶和華說：『我不再憐恤這地的居民，必將這民交給各人的鄰舍和他們王的手中。他們必毀滅這地，我也不救這民脫離他們的手。』」","yé hé huá shuō：“wǒ bù zài lián xù zhè de de jū mín， bì jiāng zhè mín jiāo gěi gè rén de lín shě hé tā men wáng de shǒu zhōng. tā men bì huǐ miè zhè de， wǒ yě bù jiù zhè mín tuō lí tā men de shǒu.”’"],[11,7,"於是，我牧養這將宰的群羊，就是群中最困苦的羊。我拿着兩根杖，一根我稱為「榮美」，一根我稱為「聯索」。這樣，我牧養了群羊。","yú shì， wǒ mù yǎng zhè jiāng zǎi de qún yáng， jiù shì qún zhōng zuì kùn kǔ de yáng. wǒ ná zhe liǎng gēn zhàng， yī gēn wǒ chēng wèi‘róng měi’， yī gēn wǒ chēng wèi‘lián suǒ’. zhè yàng， wǒ mù yǎng le qún yáng."],[11,8,"一月之內，我除滅三個牧人，因為我的心厭煩他們；他們的心也憎嫌我。","yī yuè zhī nèi， wǒ chú miè sān gè mù rén， yīn wèi wǒ de xīn yàn fán tā men； tā men de xīn yě zēng xián wǒ."],[11,9,"我就說：「我不牧養你們。要死的，由他死；要喪亡的，由他喪亡；餘剩的，由他們彼此相食。」","wǒ jiù shuō：‘wǒ bù mù yǎng nǐ men. yào sǐ de， yóu tā sǐ； yào sàng wáng de， yóu tā sàng wáng； yú shèng de， yóu tā men bǐ cǐ xiāng shí.’"],[11,10,"我折斷那稱為「榮美」的杖，表明我廢棄與萬民所立的約。","wǒ zhé duàn nà chēng wèi‘róng měi’ de zhàng， biǎo míng wǒ fèi qì yǔ wàn mín suǒ lì de yuē."],[11,11,"當日就廢棄了。這樣，那些仰望我的困苦羊就知道所說的是耶和華的話。","dāng rì jiù fèi qì le. zhè yàng， nà xiē yǎng wàng wǒ de kùn kǔ yáng jiù zhī dào suǒ shuō de shì yé hé huá de huà."],[11,12,"我對他們說：「你們若以為美，就給我工價。不然，就罷了！」於是他們給了三十塊錢作為我的工價。","wǒ duì tā men shuō：‘nǐ men ruò yǐ wèi měi， jiù gěi wǒ gōng jià. bù rán， jiù bà le！’ yú shì tā men gěi le sān shí kuài qián zuò wèi wǒ de gōng jià."],[11,13,"耶和華吩咐我說：「要把眾人所估定美好的價值丟給窯戶。」我便將這三十塊錢，在耶和華的殿中丟給窯戶了。","yé hé huá fēn fù wǒ shuō：‘yào bǎ zhòng rén suǒ gū dìng měi hǎo de jià zhí diū gěi yáo hù.’ wǒ biàn jiāng zhè sān shí kuài qián， zài yé hé huá de diàn zhōng diū gěi yáo hù le."],[11,14,"我又折斷稱為「聯索」的那根杖，表明我廢棄 猶大與 以色列弟兄的情誼。","wǒ yòu zhé duàn chēng wèi‘lián suǒ’ de nà gēn zhàng， biǎo míng wǒ fèi qì yóu dà yǔ yǐ sè liè dì xiōng de qíng yì."],[11,15,"耶和華又吩咐我說：「你再取愚昧牧人所用的器具，","yé hé huá yòu fēn fù wǒ shuō：‘nǐ zài qǔ yú mèi mù rén suǒ yòng de qì jù，"],[11,16,"因我要在這地興起一個牧人。他不看顧喪亡的，不尋找分散的，不醫治受傷的，也不牧養強壯的；卻要吃肥 羊的肉，撕裂牠的蹄子。","yīn wǒ yào zài zhè de xìng qǐ yī gè mù rén. tā bù kàn gù sàng wáng de， bù xún zhǎo fēn sàn de， bù yī zhì shòu shāng de， yě bù mù yǎng qiáng zhuàng de； què yào chī féi yáng de ròu， sī liè tā de tí zǐ."],[11,17,"無用的牧人丟棄羊群有禍了！ 刀必臨到他的膀臂和右眼上。 他的膀臂必全然枯乾； 他的右眼也必昏暗失明。」","wú yòng de mù rén diū qì yáng qún yǒu huò le！ dāo bì lín dào tā de bǎng bì hé yòu yǎn shàng. tā de bǎng bì bì quán rán kū qián； tā de yòu yǎn yě bì hūn àn shī míng.’"],[12,1,"耶和華論 以色列的默示。 鋪張諸天、建立地基、造人裏面之靈的耶和華說：","yé hé huá lùn yǐ sè liè de mò shì. pù zhāng zhū tiān, jiàn lì de jī, zào rén lǐ miàn zhī líng de yé hé huá shuō："],[12,2,"「我必使 耶路撒冷被圍困的時候，向四圍列國的民成為令人昏醉的杯；這默示也論到 猶大。","‘wǒ bì shǐ yé lù sā lěng bèi wéi kùn de shí hòu， xiàng sì wéi liè guó de mín chéng wèi lìng rén hūn zuì de bēi； zhè mò shì yě lùn dào yóu dà."],[12,3,"那日，我必使 耶路撒冷向聚集攻擊他的萬民當作一塊重石頭；凡舉起的必受重傷。","nà rì， wǒ bì shǐ yé lù sā lěng xiàng jù jí gōng jī tā de wàn mín dāng zuò yī kuài zhòng shí tóu； fán jǔ qǐ de bì shòu zhòng shāng."],[12,4,"耶和華說：到那日，我必使一切馬匹驚惶，使騎馬的顛狂。我必看顧 猶大家，使列國的一切馬匹瞎眼。","yé hé huá shuō： dào nà rì， wǒ bì shǐ yī qiè mǎ pǐ jīng huáng， shǐ qí mǎ de diān kuáng. wǒ bì kàn gù yóu dà jiā， shǐ liè guó de yī qiè mǎ pǐ xiā yǎn."],[12,5,"猶大的族長必心裏說：『 耶路撒冷的居民倚靠萬軍之耶和華－他們的神，就作我們的能力。』","yóu dà de zú zhǎng bì xīn lǐ shuō：“ yé lù sā lěng de jū mín yǐ kào wàn jūn zhī yé hé huá－tā men de shén， jiù zuò wǒ men de néng lì.”"],[12,6,"「那日，我必使 猶大的族長如火盆在木柴中，又如火把在禾捆裏；他們必左右燒滅四圍列國的民。 耶路撒冷人必仍住本處，就是 耶路撒冷。","‘nà rì， wǒ bì shǐ yóu dà de zú zhǎng rú huǒ pén zài mù chái zhōng， yòu rú huǒ bǎ zài hé kǔn lǐ； tā men bì zuǒ yòu shāo miè sì wéi liè guó de mín. yé lù sā lěng rén bì réng zhù běn chù， jiù shì yé lù sā lěng."],[12,7,"「耶和華必先拯救 猶大的帳棚，免得 大衛家的榮耀和 耶路撒冷居民的榮耀勝過 猶大。","‘yé hé huá bì xiān zhěng jiù yóu dà de zhàng péng， miǎn dé dà wèi jiā de róng yào hé yé lù sā lěng jū mín de róng yào shèng guò yóu dà."],[12,8,"那日，耶和華必保護 耶路撒冷的居民。他們中間軟弱的必如 大衛； 大衛的家必如神，如行在他們前面之耶和華的使者。","nà rì， yé hé huá bì bǎo hù yé lù sā lěng de jū mín. tā men zhōng jiān ruǎn ruò de bì rú dà wèi； dà wèi de jiā bì rú shén， rú xíng zài tā men qián miàn zhī yé hé huá de shǐ zhě."],[12,9,"那日，我必定意滅絕來攻擊 耶路撒冷各國的民。","nà rì， wǒ bì dìng yì miè jué lái gōng jī yé lù sā lěng gè guó de mín."],[12,10,"「我必將那施恩叫人懇求的靈，澆灌 大衛家和 耶路撒冷的居民。他們必仰望我，就是他們所扎的；必為我悲哀，如喪獨生子，又為我愁苦，如喪長子。","‘wǒ bì jiāng nà shī ēn jiào rén kěn qiú de líng， jiāo guàn dà wèi jiā hé yé lù sā lěng de jū mín. tā men bì yǎng wàng wǒ， jiù shì tā men suǒ zhā de； bì wèi wǒ bēi āi， rú sàng dú shēng zǐ， yòu wèi wǒ chóu kǔ， rú sàng zhǎng zǐ."],[12,11,"那日， 耶路撒冷必有大大的悲哀，如 米吉多平原之 哈達臨門的悲哀。","nà rì， yé lù sā lěng bì yǒu dà dà de bēi āi， rú mǐ jí duō píng yuán zhī hā dá lín mén de bēi āi."],[12,12,"境內一家一家地都必悲哀。 大衛家，男的獨在一處，女的獨在一處。 拿單家，男的獨在一處，女的獨在一處。","jìng nèi yī jiā yī jiā de dōu bì bēi āi. dà wèi jiā， nán de dú zài yī chù， nǚ de dú zài yī chù. ná dān jiā， nán de dú zài yī chù， nǚ de dú zài yī chù."],[12,13,"利未家，男的獨在一處，女的獨在一處。 示每家，男的獨在一處，女的獨在一處。","lì wèi jiā， nán de dú zài yī chù， nǚ de dú zài yī chù. shì měi jiā， nán de dú zài yī chù， nǚ de dú zài yī chù."],[12,14,"其餘的各家，男的獨在一處，女的獨在一處。","qí yú de gè jiā， nán de dú zài yī chù， nǚ de dú zài yī chù."],[13,1,"「那日，必給 大衛家和 耶路撒冷的居民開一個泉源，洗除罪惡與污穢。」","‘nà rì， bì gěi dà wèi jiā hé yé lù sā lěng de jū mín kāi yī gè quán yuán， xǐ chú zuì è yǔ wū huì.’"],[13,2,"萬軍之耶和華說：「那日，我必從地上除滅偶像的名，不再被人記念；也必使這地不再有 假先知與污穢的靈。","wàn jūn zhī yé hé huá shuō：‘nà rì， wǒ bì cóng de shàng chú miè ǒu xiàng de míng， bù zài bèi rén jì niàn； yě bì shǐ zhè de bù zài yǒu jiǎ xiān zhī yǔ wū huì de líng."],[13,3,"若再有人說預言，生他的父母必對他說：『你不得存活，因為你託耶和華的名說假預言。』生他的父母在他說預言的時候，要將他刺透。","ruò zài yǒu rén shuō yù yán， shēng tā de fù mǔ bì duì tā shuō：“nǐ bù dé cún huó， yīn wèi nǐ tuō yé hé huá de míng shuō jiǎ yù yán.” shēng tā de fù mǔ zài tā shuō yù yán de shí hòu， yào jiāng tā cì tòu."],[13,4,"那日，凡作先知說預言的必因他所論的異象羞愧，不再穿毛衣哄騙人。","nà rì， fán zuò xiān zhī shuō yù yán de bì yīn tā suǒ lùn de yì xiàng xiū kuì， bù zài chuān máo yī hōng piàn rén."],[13,5,"他必說：『我不是先知，我是耕地的；我從幼年作人的奴僕。』","tā bì shuō：“wǒ bù shì xiān zhī， wǒ shì gēng de de； wǒ cóng yòu nián zuò rén de nú pú.”"],[13,6,"必有人問他說：『你兩臂中間是甚麼傷呢？』他必回答說：『這是我在親友家中所受的傷。』」","bì yǒu rén wèn tā shuō：“nǐ liǎng bì zhōng jiān shì shèn me shāng ne？” tā bì huí dá shuō：“zhè shì wǒ zài qīn yǒu jiā zhōng suǒ shòu de shāng.”’"],[13,7,"萬軍之耶和華說： 刀劍哪，應當興起， 攻擊我的牧人和我的同伴。 擊打牧人，羊就分散； 我必反手加在微小者的身上。","wàn jūn zhī yé hé huá shuō： dāo jiàn nǎ， yīng dāng xìng qǐ， gōng jī wǒ de mù rén hé wǒ de tóng bàn. jī dǎ mù rén， yáng jiù fēn sàn； wǒ bì fǎn shǒu jiā zài wēi xiǎo zhě de shēn shàng."],[13,8,"耶和華說：這全地的人， 三分之二必剪除而死， 三分之一仍必存留。","yé hé huá shuō： zhè quán de de rén， sān fēn zhī èr bì jiǎn chú ér sǐ， sān fēn zhī yī réng bì cún liú."],[13,9,"我要使這三分之一經火， 熬煉他們，如熬煉銀子； 試煉他們，如試煉金子。 他們必求告我的名， 我必應允他們。 我要說：這是我的子民。 他們也要說：耶和華是我 們的神。","wǒ yào shǐ zhè sān fēn zhī yī jīng huǒ， áo liàn tā men， rú áo liàn yín zǐ； shì liàn tā men， rú shì liàn jīn zǐ. tā men bì qiú gào wǒ de míng， wǒ bì yīng yǔn tā men. wǒ yào shuō： zhè shì wǒ de zǐ mín. tā men yě yào shuō： yé hé huá shì wǒ men de shén."],[14,1,"耶和華的日子臨近，你的財物必被搶掠，在你中間分散。","yé hé huá de rì zǐ lín jìn， nǐ de cái wù bì bèi qiǎng lüè， zài nǐ zhōng jiān fēn sàn."],[14,2,"因為我必聚集萬國與 耶路撒冷爭戰，城必被攻取，房屋被搶奪，婦女被玷污，城中的民一半被擄去；剩下的民仍在城中，不致剪除。","yīn wèi wǒ bì jù jí wàn guó yǔ yé lù sā lěng zhēng zhàn， chéng bì bèi gōng qǔ， fáng wū bèi qiǎng duó， fù nǚ bèi diàn wū， chéng zhōng de mín yī bàn bèi lǔ qù； shèng xià de mín réng zài chéng zhōng， bù zhì jiǎn chú."],[14,3,"那時，耶和華必出去與那些國爭戰，好像從前爭戰一樣。","nà shí， yé hé huá bì chū qù yǔ nà xiē guó zhēng zhàn， hǎo xiàng cóng qián zhēng zhàn yī yàng."],[14,4,"那日，他的腳必站在 耶路撒冷前面朝東的 橄欖山上。這山必從中間分裂，自東至西成為極大的谷。山的一半向北挪移，一半向南挪移。","nà rì， tā de jiǎo bì zhàn zài yé lù sā lěng qián miàn cháo dōng de gǎn lǎn shān shàng. zhè shān bì cóng zhōng jiān fēn liè， zì dōng zhì xī chéng wèi jí dà de gǔ. shān de yī bàn xiàng běi nuó yí， yī bàn xiàng nán nuó yí."],[14,5,"你們要從我山的谷中逃跑，因為山谷必延到 亞薩。你們逃跑，必如 猶大王 烏西雅年間的人逃避大地震一樣。耶和華－我的神必降臨，有一切聖者同來。","nǐ men yào cóng wǒ shān de gǔ zhōng táo pǎo， yīn wèi shān gǔ bì yán dào yà sà. nǐ men táo pǎo， bì rú yóu dà wáng wū xī yǎ nián jiān de rén táo bì dà de zhèn yī yàng. yé hé huá－wǒ de shén bì jiàng lín， yǒu yī qiè shèng zhě tóng lái."],[14,6,"那日，必沒有光，三光必退縮。","nà rì， bì méi yǒu guāng， sān guāng bì tuì suō."],[14,7,"那日，必是耶和華所知道的，不是白晝，也不是黑夜，到了晚上才有光明。","nà rì， bì shì yé hé huá suǒ zhī dào de， bù shì bái zhòu， yě bù shì hēi yè， dào le wǎn shàng cái yǒu guāng míng."],[14,8,"那日，必有活水從 耶路撒冷出來，一半往東海流，一半往西海流；冬夏都是如此。","nà rì， bì yǒu huó shuǐ cóng yé lù sā lěng chū lái， yī bàn wǎng dōng hǎi liú， yī bàn wǎng xī hǎi liú； dōng xià dōu shì rú cǐ."],[14,9,"耶和華必作全地的王。那日耶和華必為獨一無二的，他的名也是獨一無二的。","yé hé huá bì zuò quán de de wáng. nà rì yé hé huá bì wèi dú yī wú èr de， tā de míng yě shì dú yī wú èr de."],[14,10,"全地，從 迦巴直到 耶路撒冷南方的 臨門，要變為 亞拉巴。 耶路撒冷必仍居高位，就是從 便雅憫門到第一門之處，又到 角門，並從 哈楠業樓，直到王的酒醡。","quán de， cóng jiā bā zhí dào yé lù sā lěng nán fāng de lín mén， yào biàn wèi yà lā bā. yé lù sā lěng bì réng jū gāo wèi， jiù shì cóng biàn yǎ mǐn mén dào dì yī mén zhī chù， yòu dào jiǎo mén， bìng cóng hā nán yè lóu， zhí dào wáng de jiǔ zhà."],[14,11,"人必住在其中，不再有咒詛。 耶路撒冷人必安然居住。","rén bì zhù zài qí zhōng， bù zài yǒu zhòu zǔ. yé lù sā lěng rén bì ān rán jū zhù."],[14,12,"耶和華用災殃攻擊那與 耶路撒冷爭戰的列國人，必是這樣：他們兩腳站立的時候，肉必消沒，眼在眶中乾癟，舌在口中潰爛。","yé hé huá yòng zāi yāng gōng jī nà yǔ yé lù sā lěng zhēng zhàn de liè guó rén， bì shì zhè yàng： tā men liǎng jiǎo zhàn lì de shí hòu， ròu bì xiāo méi， yǎn zài kuàng zhōng qián biě， shé zài kǒu zhōng kuì làn."],[14,13,"那日，耶和華必使他們大大擾亂。他們各人彼此揪住，舉手攻擊。","nà rì， yé hé huá bì shǐ tā men dà dà rǎo luàn. tā men gè rén bǐ cǐ jiū zhù， jǔ shǒu gōng jī."],[14,14,"猶大也必在 耶路撒冷爭戰。那時四圍各國的財物，就是許多金銀衣服，必被收聚。","yóu dà yě bì zài yé lù sā lěng zhēng zhàn. nà shí sì wéi gè guó de cái wù， jiù shì xǔ duō jīn yín yī fú， bì bèi shōu jù."],[14,15,"那臨到馬匹、騾子、駱駝、驢，和營中一切牲畜的災殃是與那災殃一般。","nà lín dào mǎ pǐ, luó zǐ, luò tuó, lǘ， hé yíng zhōng yī qiè shēng chù de zāi yāng shì yǔ nà zāi yāng yī bān."],[14,16,"所有來攻擊 耶路撒冷列國中剩下的人，必年年上來敬拜 大君王－萬軍之耶和華，並守住棚節。","suǒ yǒu lái gōng jī yé lù sā lěng liè guó zhōng shèng xià de rén， bì nián nián shàng lái jìng bài dà jūn wáng－wàn jūn zhī yé hé huá， bìng shǒu zhù péng jié."],[14,17,"地上 萬族中，凡不上 耶路撒冷敬拜 大君王－萬軍之耶和華的，必無雨降在他們的地上。","de shàng wàn zú zhōng， fán bù shàng yé lù sā lěng jìng bài dà jūn wáng－wàn jūn zhī yé hé huá de， bì wú yǔ jiàng zài tā men de de shàng."],[14,18,"埃及族若不上來， 雨也不降在他們的地上；凡不上來守住棚節的列國人，耶和華也必用這災攻擊他們。","āi jí zú ruò bù shàng lái， yǔ yě bù jiàng zài tā men de de shàng； fán bù shàng lái shǒu zhù péng jié de liè guó rén， yé hé huá yě bì yòng zhè zāi gōng jī tā men."],[14,19,"這就是 埃及的刑罰和那不上來守住棚節之列國的刑罰。","zhè jiù shì āi jí de xíng fá hé nà bù shàng lái shǒu zhù péng jié zhī liè guó de xíng fá."],[14,20,"當那日，馬的鈴鐺上必有「歸耶和華為聖」的這句話。耶和華殿內的鍋必如祭壇前的碗一樣。","dāng nà rì， mǎ de líng dāng shàng bì yǒu‘guī yé hé huá wèi shèng’ de zhè jù huà. yé hé huá diàn nèi de guō bì rú jì tán qián de wǎn yī yàng."],[14,21,"凡 耶路撒冷和 猶大的鍋都必歸萬軍之耶和華為聖。凡獻祭的都必來取這鍋，煮 肉在其中。當那日，在萬軍之耶和華的殿中必不再有 迦南人。","fán yé lù sā lěng hé yóu dà de guō dōu bì guī wàn jūn zhī yé hé huá wèi shèng. fán xiàn jì de dōu bì lái qǔ zhè guō， zhǔ ròu zài qí zhōng. dāng nà rì， zài wàn jūn zhī yé hé huá de diàn zhōng bì bù zài yǒu jiā nán rén."]],"arb-vandyck":[[1,1,"فِي ٱلشَّهْرِ ٱلثَّامِنِ فِي ٱلسَّنَةِ ٱلثَّانِيَةِ لِدَارِيُوسَ، كَانَتْ كَلِمَةُ ٱلرَّبِّ إِلَى زَكَرِيَّا بْنِ بَرَخِيَّا بْنِ عِدُّو ٱلنَّبِيِّ قَائِلًا:","fī ٱlsẖãh̊ri ٱltẖãạmini fī ٱlsãnaẗi ٱltẖãạnīaẗi lidārīūsa, kānat̊ kalimaẗu ٱlrãbĩ ại̹lay̱ zakarīãạ b̊ni barakẖīãạ b̊ni ʿidũw ٱlnãbīĩ qāyỉlaⁿạ:"],[1,2,"«قَدْ غَضِبَ ٱلرَّبُّ غَضَبًا عَلَى آبَائِكُمْ.","«qad̊ gẖaḍiba ٱlrãbũ gẖaḍabaⁿạ ʿalay̱ ậbāyỉkum̊."],[1,3,"فَقُلْ لَهُمْ: هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: ٱرْجِعُوا إِلَيَّ، يَقُولُ رَبُّ ٱلْجُنُودِ، فَأَرْجِعَ إِلَيْكُمْ، يَقُولُ رَبُّ ٱلْجُنُودِ.","faqul̊ lahum̊: hakadẖā qāla rabũ ٱl̊junūdi: ٱr̊jiʿūạ ại̹layã, yaqūlu rabũ ٱl̊junūdi, fāảr̊jiʿa ại̹laẙkum̊, yaqūlu rabũ ٱl̊junūdi."],[1,4,"لَا تَكُونُوا كَآبَائِكُمُ ٱلَّذِينَ نَادَاهُمُ ٱلْأَنْبِيَاءُ ٱلْأَوَّلُونَ قَائِلِينَ: هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: ٱرْجِعُوا عَنْ طُرُقِكُمُ ٱلشِّرِّيرَةِ وَعَنْ أَعْمَالِكُمُ ٱلشِّرِّيرَةِ. فَلَمْ يَسْمَعُوا وَلَمْ يُصْغُوا إِلَيَّ، يَقُولُ رَبُّ ٱلْجُنُودِ.","lā takūnūạ kā̂bāyỉkumu ٱlãdẖīna nādāhumu ٱl̊ạản̊bīāʾu ٱl̊ạảwãlūna qāyỉlīna: hakadẖā qāla rabũ ٱl̊junūdi: ٱr̊jiʿūạ ʿan̊ ṭuruqikumu ٱlsẖĩrĩyraẗi waʿan̊ ạảʿ̊mālikumu ٱlsẖĩrĩyraẗi. falam̊ yas̊maʿūạ walam̊ yuṣ̊gẖūạ ại̹layã, yaqūlu rabũ ٱl̊junūdi."],[1,5,"آبَاؤُكُمْ أَيْنَ هُمْ؟ وَٱلْأَنْبِيَاءُ هَلْ أَبَدًا يَحْيَوْنَ؟","ậbāwủkum̊ ạảẙna hum̊? waٱl̊ạản̊bīāʾu hal̊ ạảbadaⁿạ yaḥ̊yaẘna?"],[1,6,"وَلَكِنْ كَلَامِي وَفَرَائِضِي ٱلَّتِي أَوْصَيْتُ بِهَا عَبِيدِي ٱلْأَنْبِيَاءَ، أَفَلَمْ تُدْرِكْ آبَاءَكُمْ؟ فَرَجَعُوا وَقَالُوا: كَمَا قَصَدَ رَبُّ ٱلْجُنُودِ أَنْ يَصْنَعَ بِنَا كَطُرُقِنَا وَكَأَعْمَالِنَا، كَذَلِكَ فَعَلَ بِنَا».","walakin̊ kalāmī wafarāyỉḍī ٱlãtī ạảẘṣaẙtu bihā ʿabīdī ٱl̊ạản̊bīāʾa, ạảfalam̊ tud̊rik̊ ậbāʾakum̊? farajaʿūạ waqālūạ: kamā qaṣada rabũ ٱl̊junūdi ạản̊ yaṣ̊naʿa binā kaṭuruqinā wakāảʿ̊mālinā, kadẖalika faʿala binā»."],[1,7,"فِي ٱلْيَوْمِ ٱلرَّابِعِ وَٱلْعِشْرِينَ مِنَ ٱلشَّهْرِ ٱلْحَادِي عَشَرَ، هُوَ شَهْرُ شَبَاطَ. فِي ٱلسَّنَةِ ٱلثَّانِيَةِ لِدَارِيُوسَ، كَانَتْ كَلِمَةُ ٱلرَّبِّ إِلَى زَكَرِيَّا بْنِ بَرَخِيَّا بْنِ عِدُّو ٱلنَّبِيِّ قَائِلًا:","fī ٱl̊yaẘmi ٱlrãạbiʿi waٱl̊ʿisẖ̊rīna mina ٱlsẖãh̊ri ٱl̊ḥādī ʿasẖara, hūa sẖah̊ru sẖabāṭa. fī ٱlsãnaẗi ٱltẖãạnīaẗi lidārīūsa, kānat̊ kalimaẗu ٱlrãbĩ ại̹lay̱ zakarīãạ b̊ni barakẖīãạ b̊ni ʿidũw ٱlnãbīĩ qāyỉlaⁿạ:"],[1,8,"رَأَيْتُ فِي ٱللَّيْلِ وَإِذَا بِرَجُلٍ رَاكِبٍ عَلَى فَرَسٍ أَحْمَرَ، وَهُوَ وَاقِفٌ بَيْنَ ٱلْآسِ ٱلَّذِي فِي ٱلظِّلِّ، وَخَلْفَهُ خَيْلٌ حُمْرٌ وَشُقْرٌ وَشُهْبٌ.","rāảẙtu fī ٱllãẙli wāi̹dẖā birajuliⁿ rākibiⁿ ʿalay̱ farasiⁿ ạảḥ̊mara, wahūa wāqifuⁿ baẙna ٱl̊ậsi ٱlãdẖī fī ٱlẓĩlĩ, wakẖal̊fahu kẖaẙluⁿ ḥum̊ruⁿ wasẖuq̊ruⁿ wasẖuh̊buⁿ."],[1,9,"فَقُلْتُ: «يَا سَيِّدِي، مَا هَؤُلَاءِ؟» فَقَالَ لِي ٱلْمَلَاكُ ٱلَّذِي كَلَّمَنِي: «أَنَا أُرِيكَ مَا هَؤُلَاءِ».","faqul̊tu: «yā sayĩdī, mā hawủlāʾi?» faqāla lī ٱl̊malāku ٱlãdẖī kalãmanī: «ạảnā ạủrīka mā hawủlāʾi»."],[1,10,"فَأَجَابَ ٱلرَّجُلُ ٱلْوَاقِفُ بَيْنَ ٱلْآسِ وَقَالَ: «هَؤُلَاءِ هُمُ ٱلَّذِينَ أَرْسَلَهُمُ ٱلرَّبُّ لِلْجَوَلَانِ فِي ٱلْأَرْضِ».","fāảjāba ٱlrãjulu ٱl̊wāqifu baẙna ٱl̊ậsi waqāla: «hawủlāʾi humu ٱlãdẖīna ạảr̊salahumu ٱlrãbũ lil̊jawalāni fī ٱl̊ạảr̊ḍi»."],[1,11,"فَأَجَابُوا مَلَاكَ ٱلرَّبِّ ٱلْوَاقِفَ بَيْنَ ٱلْآسِ وَقَالُوا: «قَدْ جُلْنَا فِي ٱلْأَرْضِ وَإِذَا ٱلْأَرْضُ كُلُّهَا مُسْتَرِيحَةٌ وَسَاكِنَةٌ».","fāảjābūạ malāka ٱlrãbĩ ٱl̊wāqifa baẙna ٱl̊ậsi waqālūạ: «qad̊ jul̊nā fī ٱl̊ạảr̊ḍi wāi̹dẖā ٱl̊ạảr̊ḍu kulũhā mus̊tarīḥaẗuⁿ wasākinaẗuⁿ»."],[1,12,"فَأَجَابَ مَلَاكُ ٱلرَّبِّ وَقَالَ: «يَارَبَّ ٱلْجُنُودِ، إِلَى مَتَى أَنْتَ لَا تَرْحَمُ أُورُشَلِيمَ وَمُدُنَ يَهُوذَا ٱلَّتِي غَضِبْتَ عَلَيْهَا هَذِهِ ٱلسَّبْعِينَ سَنَةً؟»","fāảjāba malāku ٱlrãbĩ waqāla: «yārabã ٱl̊junūdi, ại̹lay̱ matay̱ ạản̊ta lā tar̊ḥamu ạủwrusẖalīma wamuduna yahūdẖā ٱlãtī gẖaḍib̊ta ʿalaẙhā hadẖihi ٱlsãb̊ʿīna sanaẗaⁿ?»"],[1,13,"فَأَجَابَ ٱلرَّبُّ ٱلْمَلَاكَ ٱلَّذِي كَلَّمَنِي بِكَلَامٍ طَيِّبٍ وَكَلَامِ تَعْزِيَةٍ.","fāảjāba ٱlrãbũ ٱl̊malāka ٱlãdẖī kalãmanī bikalāmiⁿ ṭayĩbiⁿ wakalāmi taʿ̊zīaẗiⁿ."],[1,14,"فَقَالَ لِي ٱلْمَلَاكُ ٱلَّذِي كَلَّمَنِي: «نَادِ قَائِلًا: هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: غِرْتُ عَلَى أُورُشَلِيمَ وَعَلَى صِهْيَوْنَ غَيْرَةً عَظِيمَةً.","faqāla lī ٱl̊malāku ٱlãdẖī kalãmanī: «nādi qāyỉlaⁿạ: hakadẖā qāla rabũ ٱl̊junūdi: gẖir̊tu ʿalay̱ ạủwrusẖalīma waʿalay̱ ṣih̊yaẘna gẖaẙraẗaⁿ ʿaẓīmaẗaⁿ."],[1,15,"وَأَنَا مُغْضِبٌ بِغَضَبٍ عَظِيمٍ عَلَى ٱلْأُمَمِ ٱلْمُطْمَئِنِّينَ. لِأَنِّي غَضِبْتُ قَلِيلًا وَهُمْ أَعَانُوا ٱلشَّرَّ.","wāảnā mugẖ̊ḍibuⁿ bigẖaḍabiⁿ ʿaẓīmiⁿ ʿalay̱ ٱl̊ạủmami ٱl̊muṭ̊mayỉnĩyna. liạảnĩy gẖaḍib̊tu qalīlaⁿạ wahum̊ ạảʿānūạ ٱlsẖãrã."],[1,16,"لِذَلِكَ هَكَذَا قَالَ ٱلرَّبُّ: قَدْ رَجَعْتُ إِلَى أُورُشَلِيمَ بِٱلْمَرَاحِمِ فَبَيْتِي يُبْنَى فِيهَا، يَقُولُ رَبُّ ٱلْجُنُودِ، وَيُمَدُّ ٱلْمِطْمَارُ عَلَى أُورُشَلِيمَ.","lidẖalika hakadẖā qāla ٱlrãbũ: qad̊ rajaʿ̊tu ại̹lay̱ ạủwrusẖalīma biٱl̊marāḥimi fabaẙtī yub̊nay̱ fīhā, yaqūlu rabũ ٱl̊junūdi, wayumadũ ٱl̊miṭ̊māru ʿalay̱ ạủwrusẖalīma."],[1,17,"نَادِ أَيْضًا وَقُلْ: هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: إِنَّ مُدُنِي تَفِيضُ بَعْدُ خَيْرًا، وَٱلرَّبُّ يُعَزِّي صِهْيَوْنَ بَعْدُ، وَيَخْتَارُ بَعْدُ أُورُشَلِيمَ».","nādi ạảẙḍaⁿạ waqul̊: hakadẖā qāla rabũ ٱl̊junūdi: ại̹nã mudunī tafīḍu baʿ̊du kẖaẙraⁿạ, waٱlrãbũ yuʿazĩy ṣih̊yaẘna baʿ̊du, wayakẖ̊tāru baʿ̊du ạủwrusẖalīma»."],[1,18,"فَرَفَعْتُ عَيْنَيَّ وَنَظَرْتُ وَإِذَا بِأَرْبَعَةِ قُرُونٍ.","farafaʿ̊tu ʿaẙnayã wanaẓar̊tu wāi̹dẖā biạảr̊baʿaẗi qurūniⁿ."],[1,19,"فَقُلْتُ لِلْمَلَاكِ ٱلَّذِي كَلَّمَنِي: «مَا هَذِهِ؟» فَقَالَ لِي: «هَذِهِ هِيَ ٱلْقُرُونُ ٱلَّتِي بَدَّدَتْ يَهُوذَا وَإِسْرَائِيلَ وَأُورُشَلِيمَ».","faqul̊tu lil̊malāki ٱlãdẖī kalãmanī: «mā hadẖihi?» faqāla lī: «hadẖihi hīa ٱl̊qurūnu ٱlãtī badãdat̊ yahūdẖā wāi̹s̊rāyỉyla wāủwrusẖalīma»."],[1,20,"فَأَرَانِي ٱلرَّبُّ أَرْبَعَةَ صُنَّاعٍ.","fāảrānī ٱlrãbũ ạảr̊baʿaẗa ṣunãạʿiⁿ."],[1,21,"فَقُلْتُ: «جَاءَ هَؤُلَاءِ، مَاذَا يَفْعَلُونَ؟» فَتَكَلَّمَ قَائِلًا: «هَذِهِ هِيَ ٱلْقُرُونُ ٱلَّتِي بَدَّدَتْ يَهُوذَا حَتَّى لَمْ يَرْفَعْ إِنْسَانٌ رَأْسَهُ. وَقَدْ جَاءَ هَؤُلَاءِ لِيُرْعِبُوهُمْ وَلِيَطْرُدُوا قُرُونَ ٱلْأُمَمِ ٱلرَّافِعِينَ قَرْنًا عَلَى أَرْضِ يَهُوذَا لِتَبْدِيدِهَا».","faqul̊tu: «jāʾa hawủlāʾi, mādẖā yaf̊ʿalūna?» fatakalãma qāyỉlaⁿạ: «hadẖihi hīa ٱl̊qurūnu ٱlãtī badãdat̊ yahūdẖā ḥatãy̱ lam̊ yar̊faʿ̊ ại̹n̊sānuⁿ rā̊̉sahu. waqad̊ jāʾa hawủlāʾi līur̊ʿibūhum̊ walīaṭ̊rudūạ qurūna ٱl̊ạủmami ٱlrãạfiʿīna qar̊naⁿạ ʿalay̱ ạảr̊ḍi yahūdẖā litab̊dīdihā»."],[2,1,"فَرَفَعْتُ عَيْنَيَّ وَنَظَرْتُ وَإِذَا رَجُلٌ وَبِيَدِهِ حَبْلُ قِيَاسٍ.","farafaʿ̊tu ʿaẙnayã wanaẓar̊tu wāi̹dẖā rajuluⁿ wabīadihi ḥab̊lu qīāsiⁿ."],[2,2,"فَقُلْتُ: «إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟» فَقَالَ لِي: «لِأَقِيسَ أُورُشَلِيمَ، لِأَرَى كَمْ عَرْضُهَا وَكَمْ طُولُهَا».","faqul̊tu: «ại̹lay̱ ạảẙna ạản̊ta dẖāhibuⁿ?» faqāla lī: «liạảqīsa ạủwrusẖalīma, liạảray̱ kam̊ ʿar̊ḍuhā wakam̊ ṭūluhā»."],[2,3,"وَإِذَا بِٱلْمَلَاكِ ٱلَّذِي كَلَّمَنِي قَدْ خَرَجَ، وَخَرَجَ مَلَاكٌ آخَرُ لِلِقَائِهِ.","wāi̹dẖā biٱl̊malāki ٱlãdẖī kalãmanī qad̊ kẖaraja, wakẖaraja malākuⁿ ậkẖaru liliqāyỉhi."],[2,4,"فَقَالَ لَهُ: «ٱجْرِ وَكَلِّمْ هَذَا ٱلْغُلَامَ قَائِلًا: كَٱلْأَعْرَاءِ تُسْكَنُ أُورُشَلِيمُ مِنْ كَثْرَةِ ٱلنَّاسِ وَٱلْبَهَائِمِ فِيهَا.","faqāla lahu: «ٱj̊ri wakalĩm̊ hadẖā ٱl̊gẖulāma qāyỉlaⁿạ: kaٱl̊ạảʿ̊rāʾi tus̊kanu ạủwrusẖalīmu min̊ katẖ̊raẗi ٱlnãạsi waٱl̊bahāyỉmi fīhā."],[2,5,"وَأَنَا، يَقُولُ ٱلرَّبُّ، أَكُونُ لَهَا سُورَ نَارٍ مِنْ حَوْلِهَا، وَأَكُونُ مَجْدًا فِي وَسَطِهَا.","wāảnā, yaqūlu ٱlrãbũ, ạảkūnu lahā sūra nāriⁿ min̊ ḥaẘlihā, wāảkūnu maj̊daⁿạ fī wasaṭihā."],[2,6,"«يَا يَا، ٱهْرُبُوا مِنْ أَرْضِ ٱلشِّمَالِ، يَقُولُ ٱلرَّبُّ. فَإِنِّي قَدْ فَرَّقْتُكُمْ كَرِيَاحِ ٱلسَّمَاءِ ٱلْأَرْبَعِ، يَقُولُ ٱلرَّبُّ.","«yā yā, ٱh̊rubūạ min̊ ạảr̊ḍi ٱlsẖĩmāli, yaqūlu ٱlrãbũ. fāi̹nĩy qad̊ farãq̊tukum̊ karīāḥi ٱlsãmāʾi ٱl̊ạảr̊baʿi, yaqūlu ٱlrãbũ."],[2,7,"تَنَجَّيْ يَا صِهْيَوْنُ ٱلسَّاكِنَةُ فِي بِنْتِ بَابِلَ،","tanajãẙ yā ṣih̊yaẘnu ٱlsãạkinaẗu fī bin̊ti bābila,"],[2,8,"لِأَنَّهُ هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: بَعْدَ ٱلْمَجْدِ أَرْسَلَنِي إِلَى ٱلْأُمَمِ ٱلَّذِينَ سَلَبُوكُمْ، لِأَنَّهُ مَنْ يَمَسُّكُمْ يَمَسُّ حَدَقَةَ عَيْنِهِ.","liạảnãhu hakadẖā qāla rabũ ٱl̊junūdi: baʿ̊da ٱl̊maj̊di ạảr̊salanī ại̹lay̱ ٱl̊ạủmami ٱlãdẖīna salabūkum̊, liạảnãhu man̊ yamasũkum̊ yamasũ ḥadaqaẗa ʿaẙnihi."],[2,9,"لِأَنِّي هَأَنَذَا أُحَرِّكُ يَدِي عَلَيْهِمْ فَيَكُونُونَ سَلَبًا لِعَبِيدِهِمْ. فَتَعْلَمُونَ أَنَّ رَبَّ ٱلْجُنُودِ قَدْ أَرْسَلَنِي.","liạảnĩy hāảnadẖā ạủḥarĩku yadī ʿalaẙhim̊ fayakūnūna salabaⁿạ liʿabīdihim̊. fataʿ̊lamūna ạảnã rabã ٱl̊junūdi qad̊ ạảr̊salanī."],[2,10,"«تَرَنَّمِي وَٱفْرَحِي يَا بِنْتَ صِهْيَوْنَ، لِأَنِّي هَأَنَذَا آتِي وَأَسْكُنُ فِي وَسَطِكِ، يَقُولُ ٱلرَّبُّ.","«taranãmī waٱf̊raḥī yā bin̊ta ṣih̊yaẘna, liạảnĩy hāảnadẖā ậtī wāảs̊kunu fī wasaṭiki, yaqūlu ٱlrãbũ."],[2,11,"فَيَتَّصِلُ أُمَمٌ كَثِيرَةٌ بِٱلرَّبِّ فِي ذَلِكَ ٱلْيَوْمِ، وَيَكُونُونَ لِي شَعْبًا فَأَسْكُنُ فِي وَسَطِكِ، فَتَعْلَمِينَ أَنَّ رَبَّ ٱلْجُنُودِ قَدْ أَرْسَلَنِي إِلَيْكِ.","fayatãṣilu ạủmamuⁿ katẖīraẗuⁿ biٱlrãbĩ fī dẖalika ٱl̊yaẘmi, wayakūnūna lī sẖaʿ̊baⁿạ fāảs̊kunu fī wasaṭiki, fataʿ̊lamīna ạảnã rabã ٱl̊junūdi qad̊ ạảr̊salanī ại̹laẙki."],[2,12,"وَٱلرَّبُّ يَرِثُ يَهُوذَا نَصِيبَهُ فِي ٱلْأَرْضِ ٱلْمُقَدَّسَةِ وَيَخْتَارُ أُورُشَلِيمَ بَعْدُ.","waٱlrãbũ yaritẖu yahūdẖā naṣībahu fī ٱl̊ạảr̊ḍi ٱl̊muqadãsaẗi wayakẖ̊tāru ạủwrusẖalīma baʿ̊du."],[2,13,"اُسْكُتُوا يَا كُلَّ ٱلْبَشَرِ قُدَّامَ ٱلرَّبِّ، لِأَنَّهُ قَدِ ٱسْتَيْقَظَ مِنْ مَسْكَنِ قُدْسِهِ».","ạus̊kutūạ yā kulã ٱl̊basẖari qudãạma ٱlrãbĩ, liạảnãhu qadi ٱs̊taẙqaẓa min̊ mas̊kani qud̊sihi»."],[3,1,"وَأَرَانِي يَهُوشَعَ ٱلْكَاهِنَ ٱلْعَظِيمَ قَائِمًا قُدَّامَ مَلَاكِ ٱلرَّبِّ، وَٱلشَّيْطَانُ قَائِمٌ عَنْ يَمِينِهِ لِيُقَاوِمَهُ.","wāảrānī yahūsẖaʿa ٱl̊kāhina ٱl̊ʿaẓīma qāyỉmaⁿạ qudãạma malāki ٱlrãbĩ, waٱlsẖãẙṭānu qāyỉmuⁿ ʿan̊ yamīnihi līuqāwimahu."],[3,2,"فَقَالَ ٱلرَّبُّ لِلشَّيْطَانِ: «لِيَنْتَهِرْكَ ٱلرَّبُّ يَا شَيْطَانُ! لِيَنْتَهِرْكَ ٱلرَّبُّ ٱلَّذِي ٱخْتَارَ أُورُشَلِيمَ! أَفَلَيْسَ هَذَا شُعْلَةً مُنْتَشَلَةً مِنَ ٱلنَّارِ؟».","faqāla ٱlrãbũ lilsẖãẙṭāni: «līan̊tahir̊ka ٱlrãbũ yā sẖaẙṭānu! līan̊tahir̊ka ٱlrãbũ ٱlãdẖī ٱkẖ̊tāra ạủwrusẖalīma! ạảfalaẙsa hadẖā sẖuʿ̊laẗaⁿ mun̊tasẖalaẗaⁿ mina ٱlnãạri?»."],[3,3,"وَكَانَ يَهُوشَعُ لَابِسًا ثِيَابًا قَذِرَةً وَوَاقِفًا قُدَّامَ ٱلْمَلَاكِ.","wakāna yahūsẖaʿu lābisaⁿạ tẖīābaⁿạ qadẖiraẗaⁿ wawāqifaⁿạ qudãạma ٱl̊malāki."],[3,4,"فَأَجَابَ وَكَلَّمَ ٱلْوَاقِفِينَ قُدَّامَهُ قَائِلًا: «ٱنْزِعُوا عَنْهُ ٱلثِّيَابَ ٱلْقَذِرَةَ». وَقَالَ لَهُ: «ٱنْظُرْ. قَدْ أَذْهَبْتُ عَنْكَ إِثْمَكَ، وَأُلْبِسُكَ ثِيَابًا مُزَخْرَفَةً».","fāảjāba wakalãma ٱl̊wāqifīna qudãạmahu qāyỉlaⁿạ: «ٱn̊ziʿūạ ʿan̊hu ٱltẖĩyāba ٱl̊qadẖiraẗa». waqāla lahu: «ٱn̊ẓur̊. qad̊ ạảdẖ̊hab̊tu ʿan̊ka ại̹tẖ̊maka, wāủl̊bisuka tẖīābaⁿạ muzakẖ̊rafaẗaⁿ»."],[3,5,"فَقُلْتُ: «لِيَضَعُوا عَلَى رَأْسِهِ عِمَامَةً طَاهِرَةً». فَوَضَعُوا عَلَى رَأْسِهِ ٱلْعِمَامَةَ ٱلطَّاهِرَةَ، وَأَلْبَسُوهُ ثِيَابًا وَمَلَاكُ ٱلرَّبِّ وَاقِفٌ.","faqul̊tu: «līaḍaʿūạ ʿalay̱ rā̊̉sihi ʿimāmaẗaⁿ ṭāhiraẗaⁿ». fawaḍaʿūạ ʿalay̱ rā̊̉sihi ٱl̊ʿimāmaẗa ٱlṭãạhiraẗa, wāảl̊basūhu tẖīābaⁿạ wamalāku ٱlrãbĩ wāqifuⁿ."],[3,6,"فَأَشْهَدَ مَلَاكُ ٱلرَّبِّ عَلَى يَهُوشَعَ قَائِلًا:","fāảsẖ̊hada malāku ٱlrãbĩ ʿalay̱ yahūsẖaʿa qāyỉlaⁿạ:"],[3,7,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: إِنْ سَلَكْتَ فِي طُرُقِي، وَإِنْ حَفِظْتَ شَعَائِرِي، فَأَنْتَ أَيْضًا تَدِينُ بَيْتِي، وَتُحَافِظُ أَيْضًا عَلَى دِيَارِي، وَأُعْطِيكَ مَسَالِكَ بَيْنَ هَؤُلَاءِ ٱلْوَاقِفِينَ.","«hakadẖā qāla rabũ ٱl̊junūdi: ại̹n̊ salak̊ta fī ṭuruqī, wāi̹n̊ ḥafiẓ̊ta sẖaʿāyỉrī, fāản̊ta ạảẙḍaⁿạ tadīnu baẙtī, watuḥāfiẓu ạảẙḍaⁿạ ʿalay̱ dīārī, wāủʿ̊ṭīka masālika baẙna hawủlāʾi ٱl̊wāqifīna."],[3,8,"فَٱسْمَعْ يَا يَهُوشَعُ ٱلْكَاهِنُ ٱلْعَظِيمُ أَنْتَ وَرُفَقَاؤُكَ ٱلْجَالِسُونَ أَمَامَكَ، لِأَنَّهُمْ رِجَالُ آيَةٍ، لِأَنِّي هَأَنَذَا آتِي بِعَبْدِي «ٱلْغُصْنِ».","faٱs̊maʿ̊ yā yahūsẖaʿu ٱl̊kāhinu ٱl̊ʿaẓīmu ạản̊ta warufaqāwủka ٱl̊jālisūna ạảmāmaka, liạảnãhum̊ rijālu ậyaẗiⁿ, liạảnĩy hāảnadẖā ậtī biʿab̊dī «ٱl̊gẖuṣ̊ni»."],[3,9,"فَهُوَذَا ٱلْحَجَرُ ٱلَّذِي وَضَعْتُهُ قُدَّامَ يَهُوشَعَ عَلَى حَجَرٍ وَاحِدٍ سَبْعُ أَعْيُنٍ. هَأَنَذَا نَاقِشٌ نَقْشَهُ، يَقُولُ رَبُّ ٱلْجُنُودِ، وَأُزِيلُ إِثْمَ تِلْكَ ٱلْأَرْضِ فِي يَوْمٍ وَاحِدٍ.","fahūadẖā ٱl̊ḥajaru ٱlãdẖī waḍaʿ̊tuhu qudãạma yahūsẖaʿa ʿalay̱ ḥajariⁿ wāḥidiⁿ sab̊ʿu ạảʿ̊yuniⁿ. hāảnadẖā nāqisẖuⁿ naq̊sẖahu, yaqūlu rabũ ٱl̊junūdi, wāủzīlu ại̹tẖ̊ma til̊ka ٱl̊ạảr̊ḍi fī yaẘmiⁿ wāḥidiⁿ."],[3,10,"فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ رَبُّ ٱلْجُنُودِ، يُنَادِي كُلُّ إِنْسَانٍ قَرِيبَهُ تَحْتَ ٱلْكَرْمَةِ وَتَحْتَ ٱلتِّينَةِ».","fī dẖalika ٱl̊yaẘmi, yaqūlu rabũ ٱl̊junūdi, yunādī kulũ ại̹n̊sāniⁿ qarībahu taḥ̊ta ٱl̊kar̊maẗi wataḥ̊ta ٱltĩynaẗi»."],[4,1,"فَرَجَعَ ٱلْمَلَاكُ ٱلَّذِي كَلَّمَنِي وَأَيْقَظَنِي كَرَجُلٍ أُوقِظَ مِنْ نَوْمِهِ.","farajaʿa ٱl̊malāku ٱlãdẖī kalãmanī wāảẙqaẓanī karajuliⁿ ạủwqiẓa min̊ naẘmihi."],[4,2,"وَقَالَ لِي: «مَاذَا تَرَى؟» فَقُلْتُ: «قَدْ نَظَرْتُ وَإِذَا بِمَنَارَةٍ كُلُّهَا ذَهَبٌ، وَكُوزُهَا عَلَى رَأْسِهَا، وَسَبْعَةُ سُرُجٍ عَلَيْهَا، وَسَبْعُ أَنَابِيبَ لِلسُّرْجِ ٱلَّتِي عَلَى رَأْسِهَا.","waqāla lī: «mādẖā taray̱?» faqul̊tu: «qad̊ naẓar̊tu wāi̹dẖā bimanāraẗiⁿ kulũhā dẖahabuⁿ, wakūzuhā ʿalay̱ rā̊̉sihā, wasab̊ʿaẗu surujiⁿ ʿalaẙhā, wasab̊ʿu ạảnābība lilsũr̊ji ٱlãtī ʿalay̱ rā̊̉sihā."],[4,3,"وَعِنْدَهَا زَيْتُونَتَانِ، إِحْدَاهُمَا عَنْ يَمِينِ ٱلْكُوزِ، وَٱلْأُخْرَى عَنْ يَسَارِهِ».","waʿin̊dahā zaẙtūnatāni, ại̹ḥ̊dāhumā ʿan̊ yamīni ٱl̊kūzi, waٱl̊ạủkẖ̊ray̱ ʿan̊ yasārihi»."],[4,4,"فَأَجَبْتُ وَقُلْتُ لِلْمَلَاكِ ٱلَّذِي كَلَّمَنِي قَائِلًا: «مَا هَذِهِ يَا سَيِّدِي؟»","fāảjab̊tu waqul̊tu lil̊malāki ٱlãdẖī kalãmanī qāyỉlaⁿạ: «mā hadẖihi yā sayĩdī?»"],[4,5,"فَأَجَابَ ٱلْمَلَاكُ ٱلَّذِي كَلَّمَنِي وَقَالَ لِي: «أَمَا تَعْلَمُ مَا هَذِهِ؟» فَقُلْتُ: «لَا يَا سَيِّدِي».","fāảjāba ٱl̊malāku ٱlãdẖī kalãmanī waqāla lī: «ạảmā taʿ̊lamu mā hadẖihi?» faqul̊tu: «lā yā sayĩdī»."],[4,6,"فَأَجَابَ وَكَلَّمَنِي قَائِلًا: «هَذِهِ كَلِمَةُ ٱلرَّبِّ إِلَى زَرُبَّابِلَ قَائِلًا: لَا بِٱلْقُدْرَةِ وَلَا بِٱلْقُوَّةِ، بَلْ بِرُوحِي قَالَ رَبُّ ٱلْجُنُودِ.","fāảjāba wakalãmanī qāyỉlaⁿạ: «hadẖihi kalimaẗu ٱlrãbĩ ại̹lay̱ zarubãạbila qāyỉlaⁿạ: lā biٱl̊qud̊raẗi walā biٱl̊qūãẗi, bal̊ birūḥī qāla rabũ ٱl̊junūdi."],[4,7,"مَنْ أَنْتَ أَيُّهَا ٱلْجَبَلُ ٱلْعَظِيمُ؟ أَمَامَ زَرُبَّابِلَ تَصِيرُ سَهْلًا! فَيُخْرِجُ حَجَرَ ٱلزَّاوِيَةِ بَيْنَ ٱلْهَاتِفِينَ: كَرَامَةً، كَرَامَةً لَهُ».","man̊ ạản̊ta ạảyũhā ٱl̊jabalu ٱl̊ʿaẓīmu? ạảmāma zarubãạbila taṣīru sah̊laⁿạ! fayukẖ̊riju ḥajara ٱlzãạwīaẗi baẙna ٱl̊hātifīna: karāmaẗaⁿ, karāmaẗaⁿ lahu»."],[4,8,"وَكَانَتْ إِلَيَّ كَلِمَةُ ٱلرَّبِّ قَائِلًا:","wakānat̊ ại̹layã kalimaẗu ٱlrãbĩ qāyỉlaⁿạ:"],[4,9,"«إِنَّ يَدَيْ زَرُبَّابِلَ قَدْ أَسَّسَتَا هَذَا ٱلْبَيْتَ، فَيَدَاهُ تُتَمِّمَانِهِ، فَتَعْلَمُ أَنَّ رَبَّ ٱلْجُنُودِ أَرْسَلَنِي إِلَيْكُمْ».","«ại̹nã yadaẙ zarubãạbila qad̊ ạảsãsatā hadẖā ٱl̊baẙta, fayadāhu tutamĩmānihi, fataʿ̊lamu ạảnã rabã ٱl̊junūdi ạảr̊salanī ại̹laẙkum̊»."],[4,10,"لِأَنَّهُ مَنِ ٱزْدَرَى بِيَوْمِ ٱلْأُمُورِ ٱلصَّغِيرَةِ. فَتَفْرَحُ أُولَئِكَ ٱلسَّبْعُ، وَيَرَوْنَ ٱلزِّيجَ بِيَدِ زَرُبَّابِلَ. إِنَّمَا هِيَ أَعْيُنُ ٱلرَّبِّ ٱلْجَائِلَةُ فِي ٱلْأَرْضِ كُلِّهَا.","liạảnãhu mani ٱz̊daray̱ bīaẘmi ٱl̊ạủmūri ٱlṣãgẖīraẗi. fataf̊raḥu ạủwlayỉka ٱlsãb̊ʿu, wayaraẘna ٱlzĩyja bīadi zarubãạbila. ại̹nãmā hīa ạảʿ̊yunu ٱlrãbĩ ٱl̊jāyỉlaẗu fī ٱl̊ạảr̊ḍi kulĩhā."],[4,11,"فَأَجَبْتُ وَقُلْتُ لَهُ: «مَا هَاتَانِ ٱلزَّيْتُونَتَانِ عَنْ يَمِينِ ٱلْمَنَارَةِ وَعَنْ يَسَارِهَا؟»","fāảjab̊tu waqul̊tu lahu: «mā hātāni ٱlzãẙtūnatāni ʿan̊ yamīni ٱl̊manāraẗi waʿan̊ yasārihā?»"],[4,12,"وَأَجَبْتُ ثَانِيَةً وَقُلْتُ لَهُ: «مَا فَرْعَا ٱلزَّيْتُونِ ٱللَّذَانِ بِجَانِبِ ٱلْأَنَابِيبِ مِنْ ذَهَبٍ، ٱلْمُفْرِغَانِ مِنْ أَنْفُسِهِمَا ٱلذَّهَبِيَّ؟»","wāảjab̊tu tẖānīaẗaⁿ waqul̊tu lahu: «mā far̊ʿā ٱlzãẙtūni ٱllãdẖāni bijānibi ٱl̊ạảnābībi min̊ dẖahabiⁿ, ٱl̊muf̊rigẖāni min̊ ạản̊fusihimā ٱldẖãhabīã?»"],[4,13,"فَأَجَابَنِي قَائِلًا: «أَمَا تَعْلَمُ مَا هَاتَانِ؟» فَقُلْتُ: «لَا يَا سَيِّدِي».","fāảjābanī qāyỉlaⁿạ: «ạảmā taʿ̊lamu mā hātāni?» faqul̊tu: «lā yā sayĩdī»."],[4,14,"فَقَالَ: «هَاتَانِ هُمَا ٱبْنَا ٱلزَّيْتِ ٱلْوَاقِفَانِ عِنْدَ سَيِّدِ ٱلْأَرْضِ كُلِّهَا».","faqāla: «hātāni humā ٱb̊nā ٱlzãẙti ٱl̊wāqifāni ʿin̊da sayĩdi ٱl̊ạảr̊ḍi kulĩhā»."],[5,1,"فَعُدْتُ وَرَفَعْتُ عَيْنَيَّ وَنَظَرْتُ وَإِذَا بِدَرْجٍ طَائِرٍ.","faʿud̊tu warafaʿ̊tu ʿaẙnayã wanaẓar̊tu wāi̹dẖā bidar̊jiⁿ ṭāyỉriⁿ."],[5,2,"فَقَالَ لِي: «مَاذَا تَرَى؟» فَقُلْتُ: «إِنِّي أَرَى دَرْجًا طَائِرًا، طُولُهُ عِشْرُونَ ذِرَاعًا، وَعَرْضُهُ عَشَرُ أَذْرُعٍ».","faqāla lī: «mādẖā taray̱?» faqul̊tu: «ại̹nĩy ạảray̱ dar̊jaⁿạ ṭāyỉraⁿạ, ṭūluhu ʿisẖ̊rūna dẖirāʿaⁿạ, waʿar̊ḍuhu ʿasẖaru ạảdẖ̊ruʿiⁿ»."],[5,3,"فَقَالَ لِي: «هَذِهِ هِيَ ٱللَّعْنَةُ ٱلْخَارِجَةُ عَلَى وَجْهِ كُلِّ ٱلْأَرْضِ. لِأَنَّ كُلَّ سَارِقٍ يُبَادُ مِنْ هُنَا بِحَسَبِهَا، وَكُلَّ حَالِفٍ يُبَادُ مِنْ هُنَاكَ بِحَسَبِهَا.","faqāla lī: «hadẖihi hīa ٱllãʿ̊naẗu ٱl̊kẖārijaẗu ʿalay̱ waj̊hi kulĩ ٱl̊ạảr̊ḍi. liạảnã kulã sāriqiⁿ yubādu min̊ hunā biḥasabihā, wakulã ḥālifiⁿ yubādu min̊ hunāka biḥasabihā."],[5,4,"إِنِّي أُخْرِجُهَا، يَقُولُ رَبُّ ٱلْجُنُودِ، فَتَدْخُلُ بَيْتَ ٱلسَّارِقِ وَبَيْتَ ٱلْحَالِفِ بِٱسْمِي زُورًا، وَتَبِيتُ فِي وَسَطِ بَيْتِهِ وَتُفْنِيهِ مَعَ خَشَبِهِ وَحِجَارَتِهِ».","ại̹nĩy ạủkẖ̊rijuhā, yaqūlu rabũ ٱl̊junūdi, fatad̊kẖulu baẙta ٱlsãạriqi wabaẙta ٱl̊ḥālifi biٱs̊mī zūraⁿạ, watabītu fī wasaṭi baẙtihi watuf̊nīhi maʿa kẖasẖabihi waḥijāratihi»."],[5,5,"ثُمَّ خَرَجَ ٱلْمَلَاكُ ٱلَّذِي كَلَّمَنِي وَقَالَ لِي: «ٱرْفَعْ عَيْنَيْكَ وَٱنْظُرْ مَا هَذَا ٱلْخَارِجُ».","tẖumã kẖaraja ٱl̊malāku ٱlãdẖī kalãmanī waqāla lī: «ٱr̊faʿ̊ ʿaẙnaẙka waٱn̊ẓur̊ mā hadẖā ٱl̊kẖāriju»."],[5,6,"فَقُلْتُ: «مَا هُوَ؟» فَقَالَ: «هَذِهِ هِيَ ٱلْإِيفَةُ ٱلْخَارِجَةُ». وَقَالَ: «هَذِهِ عَيْنُهُمْ فِي كُلِّ ٱلْأَرْضِ».","faqul̊tu: «mā hūa?» faqāla: «hadẖihi hīa ٱl̊ại̹yfaẗu ٱl̊kẖārijaẗu». waqāla: «hadẖihi ʿaẙnuhum̊ fī kulĩ ٱl̊ạảr̊ḍi»."],[5,7,"وَإِذَا بِوَزْنَةِ رَصَاصٍ رُفِعَتْ. وَكَانَتِ ٱمْرَأَةٌ جَالِسَةٌ فِي وَسَطِ ٱلْإِيفَةِ.","wāi̹dẖā biwaz̊naẗi raṣāṣiⁿ rufiʿat̊. wakānati ٱm̊rāảẗuⁿ jālisaẗuⁿ fī wasaṭi ٱl̊ại̹yfaẗi."],[5,8,"فَقَالَ: «هَذِهِ هِيَ ٱلشَّرُّ». فَطَرَحَهَا إِلَى وَسَطِ ٱلْإِيفَةِ، وَطَرَحَ ثِقْلَ ٱلرَّصَاصِ عَلَى فَمِهَا.","faqāla: «hadẖihi hīa ٱlsẖãrũ». faṭaraḥahā ại̹lay̱ wasaṭi ٱl̊ại̹yfaẗi, waṭaraḥa tẖiq̊la ٱlrãṣāṣi ʿalay̱ famihā."],[5,9,"وَرَفَعْتُ عَيْنَيَّ وَنَظَرْتُ وَإِذَا بِٱمْرَأَتَيْنِ خَرَجَتَا وَٱلرِّيحُ فِي أَجْنِحَتِهِمَا، وَلَهُمَا أَجْنِحَةٌ كَأَجْنِحَةِ ٱللَّقْلَقِ، فَرَفَعَتَا ٱلْإِيفَةَ بَيْنَ ٱلْأَرْضِ وَٱلسَّمَاءِ.","warafaʿ̊tu ʿaẙnayã wanaẓar̊tu wāi̹dẖā biٱm̊rāảtaẙni kẖarajatā waٱlrĩyḥu fī ạảj̊niḥatihimā, walahumā ạảj̊niḥaẗuⁿ kāảj̊niḥaẗi ٱllãq̊laqi, farafaʿatā ٱl̊ại̹yfaẗa baẙna ٱl̊ạảr̊ḍi waٱlsãmāʾi."],[5,10,"فَقُلْتُ لِلْمَلَاكِ ٱلَّذِي كَلَّمَنِي: «إِلَى أَيْنَ هُمَا ذَاهِبَتَانِ بِٱلْإِيفَةِ؟»","faqul̊tu lil̊malāki ٱlãdẖī kalãmanī: «ại̹lay̱ ạảẙna humā dẖāhibatāni biٱl̊ại̹yfaẗi?»"],[5,11,"فَقَالَ لِي: «لِتَبْنِيَا لَهَا بَيْتًا فِي أَرْضِ شِنْعَارَ. وَإِذَا تَهَيَّأَ تَقِرُّ هُنَاكَ عَلَى قَاعِدَتِهَا».","faqāla lī: «litab̊nīā lahā baẙtaⁿạ fī ạảr̊ḍi sẖin̊ʿāra. wāi̹dẖā tahayãạả taqirũ hunāka ʿalay̱ qāʿidatihā»."],[6,1,"فَعُدْتُ وَرَفَعْتُ عَيْنَيَّ وَنَظَرْتُ وَإِذَا بِأَرْبَعِ مَرْكَبَاتٍ خَارِجَاتٍ مِنْ بَيْنِ جَبَلَيْنِ، وَٱلْجَبَلَانِ جَبَلَا نُحَاسٍ.","faʿud̊tu warafaʿ̊tu ʿaẙnayã wanaẓar̊tu wāi̹dẖā biạảr̊baʿi mar̊kabātiⁿ kẖārijātiⁿ min̊ baẙni jabalaẙni, waٱl̊jabalāni jabalā nuḥāsiⁿ."],[6,2,"فِي ٱلْمَرْكَبَةِ ٱلْأُولَى خَيْلٌ حُمْرٌ، وَفِي ٱلْمَرْكَبَةِ ٱلثَّانِيَةِ خَيْلٌ دُهْمٌ،","fī ٱl̊mar̊kabaẗi ٱl̊ạủwlay̱ kẖaẙluⁿ ḥum̊ruⁿ, wafī ٱl̊mar̊kabaẗi ٱltẖãạnīaẗi kẖaẙluⁿ duh̊muⁿ,"],[6,3,"وَفِي ٱلْمَرْكَبَةِ ٱلثَّالِثَةِ خَيْلٌ شُهْبٌ، وَفِي ٱلْمَرْكَبَةِ ٱلرَّابِعَةِ خَيْلٌ مُنَمَّرَةٌ شُقْرٌ.","wafī ٱl̊mar̊kabaẗi ٱltẖãạlitẖaẗi kẖaẙluⁿ sẖuh̊buⁿ, wafī ٱl̊mar̊kabaẗi ٱlrãạbiʿaẗi kẖaẙluⁿ munamãraẗuⁿ sẖuq̊ruⁿ."],[6,4,"فَأَجَبْتُ وَقُلْتُ لِلْمَلَاكِ ٱلَّذِي كَلَّمَنِي: «مَا هَذِهِ يَا سَيِّدِي؟»","fāảjab̊tu waqul̊tu lil̊malāki ٱlãdẖī kalãmanī: «mā hadẖihi yā sayĩdī?»"],[6,5,"فَأَجَابَ ٱلْمَلَاكُ وَقَالَ لِي: «هَذِهِ هِيَ أَرْوَاحُ ٱلسَّمَاءِ ٱلْأَرْبَعُ خَارِجَةٌ مِنَ ٱلْوُقُوفِ لَدَى سَيِّدِ ٱلْأَرْضِ كُلِّهَا.","fāảjāba ٱl̊malāku waqāla lī: «hadẖihi hīa ạảr̊wāḥu ٱlsãmāʾi ٱl̊ạảr̊baʿu kẖārijaẗuⁿ mina ٱl̊wuqūfi laday̱ sayĩdi ٱl̊ạảr̊ḍi kulĩhā."],[6,6,"ٱلَّتِي فِيهَا ٱلْخَيْلُ ٱلدُّهْمُ تَخْرُجُ إِلَى أَرْضِ ٱلشِّمَالِ، وَٱلشُّهْبُ خَارِجَةٌ وَرَاءَهَا، وَٱلْمُنَمَّرَةُ تَخْرُجُ نَحْوَ أَرْضِ ٱلْجَنُوبِ».","ٱlãtī fīhā ٱl̊kẖaẙlu ٱldũh̊mu takẖ̊ruju ại̹lay̱ ạảr̊ḍi ٱlsẖĩmāli, waٱlsẖũh̊bu kẖārijaẗuⁿ warāʾahā, waٱl̊munamãraẗu takẖ̊ruju naḥ̊wa ạảr̊ḍi ٱl̊janūbi»."],[6,7,"أَمَّا ٱلشُّقْرُ فَخَرَجَتْ وَٱلْتَمَسَتْ أَنْ تَذْهَبَ لِتَتَمَشَّى فِي ٱلْأَرْضِ، فَقَالَ: «ٱذْهَبِي وَتَمَشَّيْ فِي ٱلْأَرْضِ». فَتَمَشَّتْ فِي ٱلْأَرْضِ.","ạảmãạ ٱlsẖũq̊ru fakẖarajat̊ waٱl̊tamasat̊ ạản̊ tadẖ̊haba litatamasẖãy̱ fī ٱl̊ạảr̊ḍi, faqāla: «ٱdẖ̊habī watamasẖãẙ fī ٱl̊ạảr̊ḍi». fatamasẖãt̊ fī ٱl̊ạảr̊ḍi."],[6,8,"فَصَرَخَ عَلَيَّ وَكَلَّمنِي قَائِلًا: «هُوَذَا ٱلْخَارِجُونَ إِلَى أَرْضِ ٱلشِّمَالِ قَدْ سَكَّنُوا رُوحِي فِي أَرْضِ ٱلشِّمَالِ».","faṣarakẖa ʿalayã wakalãmnī qāyỉlaⁿạ: «hūadẖā ٱl̊kẖārijūna ại̹lay̱ ạảr̊ḍi ٱlsẖĩmāli qad̊ sakãnūạ rūḥī fī ạảr̊ḍi ٱlsẖĩmāli»."],[6,9,"وَكَانَ إِلَيَّ كَلَامُ ٱلرَّبِّ قَائِلًا:","wakāna ại̹layã kalāmu ٱlrãbĩ qāyỉlaⁿạ:"],[6,10,"«خُذْ مِنْ أَهْلِ ٱلسَّبْيِ مِنْ حَلْدَايَ وَمِنْ طُوبِيَّا وَمِنْ يَدَعْيَا ٱلَّذِينَ جَاءُوا مِنْ بَابِلَ، وَتَعَالَ أَنْتَ فِي ذَلِكَ ٱلْيَوْمِ وَٱدْخُلْ إِلَى بَيْتِ يُوشِيَّا بْنِ صَفَنْيَا.","«kẖudẖ̊ min̊ ạảh̊li ٱlsãb̊yi min̊ ḥal̊dāya wamin̊ ṭūbīãạ wamin̊ yadaʿ̊yā ٱlãdẖīna jāʾūạ min̊ bābila, wataʿāla ạản̊ta fī dẖalika ٱl̊yaẘmi waٱd̊kẖul̊ ại̹lay̱ baẙti yūsẖīãạ b̊ni ṣafan̊yā."],[6,11,"ثُمَّ خُذْ فِضَّةً وَذَهَبًا وَٱعْمَلْ تِيجَانًا وَضَعْهَا عَلَى رَأْسِ يَهُوشَعَ بْنِ يَهُوصَادَقَ ٱلْكَاهِنِ ٱلْعَظِيمِ.","tẖumã kẖudẖ̊ fiḍãẗaⁿ wadẖahabaⁿạ waٱʿ̊mal̊ tījānaⁿạ waḍaʿ̊hā ʿalay̱ rā̊̉si yahūsẖaʿa b̊ni yahūṣādaqa ٱl̊kāhini ٱl̊ʿaẓīmi."],[6,12,"وَكَلِّمْهُ قَائِلًا: هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ قَائِلًا: هُوَذَا ٱلرَّجُلُ «ٱلْغُصْنُ» ٱسْمُهُ. وَمِنْ مَكَانِهِ يَنْبُتُ وَيَبْنِي هَيْكَلَ ٱلرَّبِّ.","wakalĩm̊hu qāyỉlaⁿạ: hakadẖā qāla rabũ ٱl̊junūdi qāyỉlaⁿạ: hūadẖā ٱlrãjulu «ٱl̊gẖuṣ̊nu» ٱs̊muhu. wamin̊ makānihi yan̊butu wayab̊nī haẙkala ٱlrãbĩ."],[6,13,"فَهُوَ يَبْنِي هَيْكَلَ ٱلرَّبِّ، وَهُوَ يَحْمِلُ ٱلْجَلَالَ وَيَجْلِسُ وَيَتَسَلَّطُ عَلَى كُرْسِيِّهِ، وَيَكُونُ كَاهِنًا عَلَى كُرْسِيِّهِ، وَتَكُونُ مَشُورَةُ ٱلسَّلَامِ بَيْنَهُمَا كِلَيْهِمَا.","fahūa yab̊nī haẙkala ٱlrãbĩ, wahūa yaḥ̊milu ٱl̊jalāla wayaj̊lisu wayatasalãṭu ʿalay̱ kur̊sīĩhi, wayakūnu kāhinaⁿạ ʿalay̱ kur̊sīĩhi, watakūnu masẖūraẗu ٱlsãlāmi baẙnahumā kilaẙhimā."],[6,14,"وَتَكُونُ ٱلتِّيجَانُ لِحَالِمَ وَلِطُوبِيَّا وَلِيَدَعْيَا وَلِحَيْنِ بْنِ صَفَنْيَا تَذْكَارًا فِي هَيْكَلِ ٱلرَّبِّ.","watakūnu ٱltĩyjānu liḥālima waliṭūbīãạ walīadaʿ̊yā waliḥaẙni b̊ni ṣafan̊yā tadẖ̊kāraⁿạ fī haẙkali ٱlrãbĩ."],[6,15,"وَٱلْبَعِيدُونَ يَأْتُونَ وَيَبْنُونَ فِي هَيْكَلِ ٱلرَّبِّ، فَتَعْلَمُونَ أَنَّ رَبَّ ٱلْجُنُودِ أَرْسَلَنِي إِلَيْكُمْ. وَيَكُونُ، إِذَا سَمِعْتُمْ سَمَعًا صَوْتَ ٱلرَّبِّ إِلَهِكُمْ».","waٱl̊baʿīdūna yā̊̉tūna wayab̊nūna fī haẙkali ٱlrãbĩ, fataʿ̊lamūna ạảnã rabã ٱl̊junūdi ạảr̊salanī ại̹laẙkum̊. wayakūnu, ại̹dẖā samiʿ̊tum̊ samaʿaⁿạ ṣaẘta ٱlrãbĩ ại̹lahikum̊»."],[7,1,"وَكَانَ فِي ٱلسَّنَةِ ٱلرَّابِعَةِ لِدَارِيُوسَ ٱلْمَلِكِ أَنَّ كَلَامَ ٱلرَّبِّ صَارَ إِلَى زَكَرِيَّا فِي ٱلرَّابِعِ مِنَ ٱلشَّهْرِ ٱلتَّاسِعِ فِي كِسْلُو.","wakāna fī ٱlsãnaẗi ٱlrãạbiʿaẗi lidārīūsa ٱl̊maliki ạảnã kalāma ٱlrãbĩ ṣāra ại̹lay̱ zakarīãạ fī ٱlrãạbiʿi mina ٱlsẖãh̊ri ٱltãạsiʿi fī kis̊lū."],[7,2,"لَمَّا أَرْسَلَ أَهْلُ بَيْتِ إِيلَ شَرَاصِرَ وَرَجَمَ مَلِكَ وَرِجَالَهُمْ لِيُصَلُّوا قُدَّامَ ٱلرَّبِّ،","lamãạ ạảr̊sala ạảh̊lu baẙti ại̹yla sẖarāṣira warajama malika warijālahum̊ līuṣalũwạ qudãạma ٱlrãbĩ,"],[7,3,"وَلِيُكَلِّمُوا ٱلْكَهَنَةَ ٱلَّذِينَ فِي بَيْتِ رَبِّ ٱلْجُنُودِ وَٱلْأَنْبِيَاءَ قَائِلِينَ: «أَأَبْكِي فِي ٱلشَّهْرِ ٱلْخَامِسِ مُنْفَصِلًا، كَمَا فَعَلْتُ كَمْ مِنَ ٱلسِّنِينَ هَذِهِ؟».","walīukalĩmūạ ٱl̊kahanaẗa ٱlãdẖīna fī baẙti rabĩ ٱl̊junūdi waٱl̊ạản̊bīāʾa qāyỉlīna: «ạảạảb̊kī fī ٱlsẖãh̊ri ٱl̊kẖāmisi mun̊faṣilaⁿạ, kamā faʿal̊tu kam̊ mina ٱlsĩnīna hadẖihi?»."],[7,4,"ثُمَّ صَارَ إِلَيَّ كَلَامُ رَبِّ ٱلْجُنُودِ قَائِلًا:","tẖumã ṣāra ại̹layã kalāmu rabĩ ٱl̊junūdi qāyỉlaⁿạ:"],[7,5,"«قُلْ لِجَمِيعِ شَعْبِ ٱلْأَرْضِ وَلِلْكَهَنَةِ قَائِلًا: لَمَّا صُمْتُمْ وَنُحْتُمْ فِي ٱلشَّهْرِ ٱلْخَامِسِ وَٱلشَّهْرِ ٱلسَّابِعِ، وَذَلِكَ هَذِهِ ٱلسَّبْعِينَ سَنَةً، فَهَلْ صُمْتُمْ صَوْمًا لِي أَنَا؟","«qul̊ lijamīʿi sẖaʿ̊bi ٱl̊ạảr̊ḍi walil̊kahanaẗi qāyỉlaⁿạ: lamãạ ṣum̊tum̊ wanuḥ̊tum̊ fī ٱlsẖãh̊ri ٱl̊kẖāmisi waٱlsẖãh̊ri ٱlsãạbiʿi, wadẖalika hadẖihi ٱlsãb̊ʿīna sanaẗaⁿ, fahal̊ ṣum̊tum̊ ṣaẘmaⁿạ lī ạảnā?"],[7,6,"وَلَمَّا أَكَلْتُمْ وَلَمَّا شَرِبْتُمْ، أَفَمَا كُنْتُمْ أَنْتُمُ ٱلْآكِلِينَ وَأَنْتُمُ ٱلشَّارِبِينَ؟","walamãạ ạảkal̊tum̊ walamãạ sẖarib̊tum̊, ạảfamā kun̊tum̊ ạản̊tumu ٱl̊ậkilīna wāản̊tumu ٱlsẖãạribīna?"],[7,7,"أَلَيْسَ هَذَا هُوَ ٱلْكَلَامُ ٱلَّذِي نَادَى بِهِ ٱلرَّبُّ عَنْ يَدِ ٱلْأَنْبِيَاءِ ٱلْأَوَّلِينَ، حِينَ كَانَتْ أُورُشَلِيمُ مَعْمُورَةً وَمُسْتَرِيحَةً، وَمُدُنُهَا حَوْلَهَا، وَٱلْجَنُوبُ وَٱلسَّهْلُ مَعْمُورَيْنِ؟».","ạảlaẙsa hadẖā hūa ٱl̊kalāmu ٱlãdẖī nāday̱ bihi ٱlrãbũ ʿan̊ yadi ٱl̊ạản̊bīāʾi ٱl̊ạảwãlīna, ḥīna kānat̊ ạủwrusẖalīmu maʿ̊mūraẗaⁿ wamus̊tarīḥaẗaⁿ, wamudunuhā ḥaẘlahā, waٱl̊janūbu waٱlsãh̊lu maʿ̊mūraẙni?»."],[7,8,"وَكَانَ كَلَامُ ٱلرَّبِّ إِلَى زَكَرِيَّا قَائِلًا:","wakāna kalāmu ٱlrãbĩ ại̹lay̱ zakarīãạ qāyỉlaⁿạ:"],[7,9,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ قَائِلًا: ٱقْضُوا قَضَاءَ ٱلْحَقِّ، وَٱعْمَلُوا إِحْسَانًا وَرَحْمَةً، كُلُّ إِنْسَانٍ مَعَ أَخِيهِ.","«hakadẖā qāla rabũ ٱl̊junūdi qāyỉlaⁿạ: ٱq̊ḍūạ qaḍāʾa ٱl̊ḥaqĩ, waٱʿ̊malūạ ại̹ḥ̊sānaⁿạ waraḥ̊maẗaⁿ, kulũ ại̹n̊sāniⁿ maʿa ạảkẖīhi."],[7,10,"وَلَا تَظْلِمُوا ٱلْأَرْمَلَةَ وَلَا ٱلْيَتِيمَ وَلَا ٱلْغَرِيبَ وَلَا ٱلْفَقِيرَ، وَلَا يُفَكِّرْ أَحَدٌ مِنْكُمْ شَرًّا عَلَى أَخِيهِ فِي قَلْبِكُمْ.","walā taẓ̊limūạ ٱl̊ạảr̊malaẗa walā ٱl̊yatīma walā ٱl̊gẖarība walā ٱl̊faqīra, walā yufakĩr̊ ạảḥaduⁿ min̊kum̊ sẖaraⁿ̃ạ ʿalay̱ ạảkẖīhi fī qal̊bikum̊."],[7,11,"فَأَبَوْا أَنْ يُصْغُوا وَأَعْطَوْا كَتِفًا مُعَانِدَةً، وَثَقَّلُوا آذَانَهُمْ عَنِ ٱلسَّمْعِ.","fāảbaẘạ ạản̊ yuṣ̊gẖūạ wāảʿ̊ṭaẘạ katifaⁿạ muʿānidaẗaⁿ, watẖaqãlūạ ậdẖānahum̊ ʿani ٱlsãm̊ʿi."],[7,12,"بَلْ جَعَلُوا قَلْبَهُمْ مَاسًا لِئَلَّا يَسْمَعُوا ٱلشَّرِيعَةَ وَٱلْكَلَامَ ٱلَّذِي أَرْسَلَهُ رَبُّ ٱلْجُنُودِ بِرُوحِهِ عَنْ يَدِ ٱلْأَنْبِيَاءِ ٱلْأَوَّلِينَ. فَجَاءَ غَضَبٌ عَظِيمٌ مِنْ عِنْدِ رَبِّ ٱلْجُنُودِ.","bal̊ jaʿalūạ qal̊bahum̊ māsaⁿạ līảlãạ yas̊maʿūạ ٱlsẖãrīʿaẗa waٱl̊kalāma ٱlãdẖī ạảr̊salahu rabũ ٱl̊junūdi birūḥihi ʿan̊ yadi ٱl̊ạản̊bīāʾi ٱl̊ạảwãlīna. fajāʾa gẖaḍabuⁿ ʿaẓīmuⁿ min̊ ʿin̊di rabĩ ٱl̊junūdi."],[7,13,"فَكَانَ كَمَا نَادَى هُوَ فَلَمْ يَسْمَعُوا، كَذَلِكَ يُنَادُونَ هُمْ فَلَا أَسْمَعُ، قَالَ رَبُّ ٱلْجُنُودِ.","fakāna kamā nāday̱ hūa falam̊ yas̊maʿūạ, kadẖalika yunādūna hum̊ falā ạảs̊maʿu, qāla rabũ ٱl̊junūdi."],[7,14,"وَأَعْصِفُهُمْ إِلَى كُلِّ ٱلْأُمَمِ ٱلَّذِينَ لَمْ يَعْرِفُوهُمْ. فَخَرِبَتِ ٱلْأَرْضُ وَرَاءَهُمْ، لَا ذَاهِبَ وَلَا آئِبَ. فَجَعَلُوا ٱلْأَرْضَ ٱلْبَهِجَةَ خَرَابًا».","wāảʿ̊ṣifuhum̊ ại̹lay̱ kulĩ ٱl̊ạủmami ٱlãdẖīna lam̊ yaʿ̊rifūhum̊. fakẖaribati ٱl̊ạảr̊ḍu warāʾahum̊, lā dẖāhiba walā ậyỉba. fajaʿalūạ ٱl̊ạảr̊ḍa ٱl̊bahijaẗa kẖarābaⁿạ»."],[8,1,"وَكَانَ كَلَامُ رَبِّ ٱلْجُنُودِ قَائِلًا:","wakāna kalāmu rabĩ ٱl̊junūdi qāyỉlaⁿạ:"],[8,2,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: غِرْتُ عَلَى صِهْيَوْنَ غَيْرَةً عَظِيمَةً، وَبِسَخَطٍ عَظِيمٍ غِرْتُ عَلَيْهَا.","«hakadẖā qāla rabũ ٱl̊junūdi: gẖir̊tu ʿalay̱ ṣih̊yaẘna gẖaẙraẗaⁿ ʿaẓīmaẗaⁿ, wabisakẖaṭiⁿ ʿaẓīmiⁿ gẖir̊tu ʿalaẙhā."],[8,3,"هَكَذَا قَالَ ٱلرَّبُّ: قَدْ رَجَعْتُ إِلَى صِهْيَوْنَ وَأَسْكُنُ فِي وَسَطِ أُورُشَلِيمَ، فَتُدْعَى أُورُشَلِيمُ مَدِينَةَ ٱلْحَقِّ، وَجَبَلُ رَبِّ ٱلْجُنُودِ ٱلْجَبَلَ ٱلْمُقَدَّسَ.","hakadẖā qāla ٱlrãbũ: qad̊ rajaʿ̊tu ại̹lay̱ ṣih̊yaẘna wāảs̊kunu fī wasaṭi ạủwrusẖalīma, fatud̊ʿay̱ ạủwrusẖalīmu madīnaẗa ٱl̊ḥaqĩ, wajabalu rabĩ ٱl̊junūdi ٱl̊jabala ٱl̊muqadãsa."],[8,4,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: سَيَجْلِسُ بَعْدُ ٱلشُّيُوخُ وَٱلشَّيْخَاتُ فِي أَسْوَاقِ أُورُشَلِيمَ، كُلُّ إِنْسَانٍ مِنْهُمْ عَصَاهُ بِيَدِهِ مِنْ كَثْرَةِ ٱلْأَيَّامِ.","«hakadẖā qāla rabũ ٱl̊junūdi: sayaj̊lisu baʿ̊du ٱlsẖũyūkẖu waٱlsẖãẙkẖātu fī ạảs̊wāqi ạủwrusẖalīma, kulũ ại̹n̊sāniⁿ min̊hum̊ ʿaṣāhu bīadihi min̊ katẖ̊raẗi ٱl̊ạảyãạmi."],[8,5,"وَتَمْتَلِئُ أَسْوَاقُ ٱلْمَدِينَةِ مِنَ ٱلصِّبْيَانِ وَٱلْبَنَاتِ لَاعِبِينَ فِي أَسْوَاقِهَا.","watam̊talīủ ạảs̊wāqu ٱl̊madīnaẗi mina ٱlṣĩb̊yāni waٱl̊banāti lāʿibīna fī ạảs̊wāqihā."],[8,6,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: إِنْ يَكُنْ ذَلِكَ عَجِيبًا فِي أَعْيُنِ بَقِيَّةِ هَذَا ٱلشَّعْبِ فِي هَذِهِ ٱلْأَيَّامِ، أَفَيَكُونُ أَيْضًا عَجِيبًا فِي عَيْنَيَّ؟ يَقُولُ رَبُّ ٱلْجُنُودِ.","«hakadẖā qāla rabũ ٱl̊junūdi: ại̹n̊ yakun̊ dẖalika ʿajībaⁿạ fī ạảʿ̊yuni baqīãẗi hadẖā ٱlsẖãʿ̊bi fī hadẖihi ٱl̊ạảyãạmi, ạảfayakūnu ạảẙḍaⁿạ ʿajībaⁿạ fī ʿaẙnayã? yaqūlu rabũ ٱl̊junūdi."],[8,7,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: هَأَنَذَا أُخَلِّصُ شَعْبِي مِنْ أَرْضِ ٱلْمَشْرِقِ وَمِنْ أَرْضِ مَغْرِبِ ٱلشَّمْسِ.","«hakadẖā qāla rabũ ٱl̊junūdi: hāảnadẖā ạủkẖalĩṣu sẖaʿ̊bī min̊ ạảr̊ḍi ٱl̊masẖ̊riqi wamin̊ ạảr̊ḍi magẖ̊ribi ٱlsẖãm̊si."],[8,8,"وَآتِي بِهِمْ فَيَسْكُنُونَ فِي وَسَطِ أُورُشَلِيمَ، وَيَكُونُونَ لِي شَعْبًا،وَأَنَا أَكُونُ لَهُمْ إِلَهًا بِٱلْحَقِّ وَٱلْبِرِّ.","wā̂tī bihim̊ fayas̊kunūna fī wasaṭi ạủwrusẖalīma, wayakūnūna lī sẖaʿ̊baⁿạ,wāảnā ạảkūnu lahum̊ ại̹lahaⁿạ biٱl̊ḥaqĩ waٱl̊birĩ."],[8,9,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: لِتَتَشَدَّدْ أَيْدِيكُمْ أَيُّهَا ٱلسَّامِعُونَ فِي هَذِهِ ٱلْأَيَّامِ هَذَا ٱلْكَلَامَ مِنْ أَفْوَاهِ ٱلْأَنْبِيَاءِ ٱلَّذِي كَانَ يَوْمَ أُسِّسَ بَيْتُ رَبِّ ٱلْجُنُودِ لِبِنَاءِ ٱلْهَيْكَلِ.","«hakadẖā qāla rabũ ٱl̊junūdi: litatasẖadãd̊ ạảẙdīkum̊ ạảyũhā ٱlsãạmiʿūna fī hadẖihi ٱl̊ạảyãạmi hadẖā ٱl̊kalāma min̊ ạảf̊wāhi ٱl̊ạản̊bīāʾi ٱlãdẖī kāna yaẘma ạủsĩsa baẙtu rabĩ ٱl̊junūdi libināʾi ٱl̊haẙkali."],[8,10,"لِأَنَّهُ قَبْلَ هَذِهِ ٱلْأَيَّامِ لَمْ تَكُنْ لِلْإِنْسَانِ أُجْرَةٌ وَلَا لِلْبَهِيمَةِ أُجْرَةٌ، وَلَا سَلَامٌ لِمَنْ خَرَجَ أَوْ دَخَلَ مِنْ قِبَلِ ٱلضِّيقِ. وَأَطْلَقْتُ كُلَّ إِنْسَانٍ، ٱلرَّجُلَ عَلَى قَرِيبِهِ.","liạảnãhu qab̊la hadẖihi ٱl̊ạảyãạmi lam̊ takun̊ lil̊ại̹n̊sāni ạủj̊raẗuⁿ walā lil̊bahīmaẗi ạủj̊raẗuⁿ, walā salāmuⁿ liman̊ kẖaraja ạảẘ dakẖala min̊ qibali ٱlḍĩyqi. wāảṭ̊laq̊tu kulã ại̹n̊sāniⁿ, ٱlrãjula ʿalay̱ qarībihi."],[8,11,"أَمَّا ٱلْآنَ فَلَا أَكُونُ أَنَا لِبَقِيَّةِ هَذَا ٱلشَّعْبِ كَمَا فِي ٱلْأَيَّامِ ٱلْأُولَى، يَقُولُ رَبُّ ٱلْجُنُودِ.","ạảmãạ ٱl̊ậna falā ạảkūnu ạảnā libaqīãẗi hadẖā ٱlsẖãʿ̊bi kamā fī ٱl̊ạảyãạmi ٱl̊ạủwlay̱, yaqūlu rabũ ٱl̊junūdi."],[8,12,"بَلْ زَرْعُ ٱلسَّلَامِ، ٱلْكَرْمُ يُعْطِي ثَمَرَهُ، وَٱلْأَرْضُ تُعْطِي غَلَّتَهَا، وَٱلسَّمَاوَاتُ تُعْطِي نَدَاهَا، وَأُمَلِّكُ بَقِيَّةَ هَذَا ٱلشَّعْبِ هَذِهِ كُلَّهَا.","bal̊ zar̊ʿu ٱlsãlāmi, ٱl̊kar̊mu yuʿ̊ṭī tẖamarahu, waٱl̊ạảr̊ḍu tuʿ̊ṭī gẖalãtahā, waٱlsãmāwātu tuʿ̊ṭī nadāhā, wāủmalĩku baqīãẗa hadẖā ٱlsẖãʿ̊bi hadẖihi kulãhā."],[8,13,"وَيَكُونُ كَمَا أَنَّكُمْ كُنْتُمْ لَعْنَةً بَيْنَ ٱلْأُمَمِ يَا بَيْتَ يَهُوذَا وَيَا بَيْتَ إِسْرَائِيلَ، كَذَلِكَ أُخَلِّصُكُمْ فَتَكُونُونَ بَرَكَةً فَلَا تَخَافُوا. لِتَتَشَدَّدْ أَيْدِيكُمْ.","wayakūnu kamā ạảnãkum̊ kun̊tum̊ laʿ̊naẗaⁿ baẙna ٱl̊ạủmami yā baẙta yahūdẖā wayā baẙta ại̹s̊rāyỉyla, kadẖalika ạủkẖalĩṣukum̊ fatakūnūna barakaẗaⁿ falā takẖāfūạ. litatasẖadãd̊ ạảẙdīkum̊."],[8,14,"«لِأَنَّهُ هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: كَمَا أَنِّي فَكَّرْتُ فِي أَنْ أُسِيءَ إِلَيْكُمْ حِينَ أَغْضَبَنِي آبَاؤُكُمْ، قَالَ رَبُّ ٱلْجُنُودِ، وَلَمْ أَنْدَمْ.","«liạảnãhu hakadẖā qāla rabũ ٱl̊junūdi: kamā ạảnĩy fakãr̊tu fī ạản̊ ạủsīʾa ại̹laẙkum̊ ḥīna ạảgẖ̊ḍabanī ậbāwủkum̊, qāla rabũ ٱl̊junūdi, walam̊ ạản̊dam̊."],[8,15,"هَكَذَا عُدْتُ وَفَكَّرْتُ فِي هَذِهِ ٱلْأَيَّامِ فِي أَنْ أُحْسِنَ إِلَى أُورُشَلِيمَ وَبَيْتِ يَهُوذَا. لَا تَخَافُوا.","hakadẖā ʿud̊tu wafakãr̊tu fī hadẖihi ٱl̊ạảyãạmi fī ạản̊ ạủḥ̊sina ại̹lay̱ ạủwrusẖalīma wabaẙti yahūdẖā. lā takẖāfūạ."],[8,16,"هَذِهِ هِيَ ٱلْأُمُورُ ٱلَّتِي تَفْعَلُونَهَا. لِيُكَلِّمْ كُلُّ إِنْسَانٍ قَرِيبَهُ بِٱلْحَقِّ. ٱقْضُوا بِٱلْحَقِّ وَقَضَاءِ ٱلسَّلَامِ فِي أَبْوَابِكُمْ.","hadẖihi hīa ٱl̊ạủmūru ٱlãtī taf̊ʿalūnahā. līukalĩm̊ kulũ ại̹n̊sāniⁿ qarībahu biٱl̊ḥaqĩ. ٱq̊ḍūạ biٱl̊ḥaqĩ waqaḍāʾi ٱlsãlāmi fī ạảb̊wābikum̊."],[8,17,"وَلَا يُفَكِّرَنَّ أَحَدٌ فِي ٱلسُّوءِ عَلَى قَرِيبِهِ فِي قُلُوبِكُمْ. وَلَا تُحِبُّوا يَمِينَ ٱلزُّورِ. لِأَنَّ هَذِهِ جَمِيعَهَا أَكْرَهُهَا، يَقُولُ ٱلرَّبُّ».","walā yufakĩranã ạảḥaduⁿ fī ٱlsũwʾi ʿalay̱ qarībihi fī qulūbikum̊. walā tuḥibũwạ yamīna ٱlzũwri. liạảnã hadẖihi jamīʿahā ạảk̊rahuhā, yaqūlu ٱlrãbũ»."],[8,18,"وَكَانَ إِلَيَّ كَلَامُ رَبِّ ٱلْجُنُودِ قَائِلًا:","wakāna ại̹layã kalāmu rabĩ ٱl̊junūdi qāyỉlaⁿạ:"],[8,19,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: إِنَّ صَوْمَ ٱلشَّهْرِ ٱلرَّابِعِ وَصَوْمَ ٱلْخَامِسِ وَصَوْمَ ٱلسَّابِعِ وَصَوْمَ ٱلْعَاشِرِ يَكُونُ لِبَيْتِ يَهُوذَا ٱبْتِهَاجًا وَفَرَحًا وَأَعْيَادًا طَيِّبَةً. فَأَحِبُّوا ٱلْحَقَّ وَٱلسَّلَامَ.","«hakadẖā qāla rabũ ٱl̊junūdi: ại̹nã ṣaẘma ٱlsẖãh̊ri ٱlrãạbiʿi waṣaẘma ٱl̊kẖāmisi waṣaẘma ٱlsãạbiʿi waṣaẘma ٱl̊ʿāsẖiri yakūnu libaẙti yahūdẖā ٱb̊tihājaⁿạ wafaraḥaⁿạ wāảʿ̊yādaⁿạ ṭayĩbaẗaⁿ. fāảḥibũwạ ٱl̊ḥaqã waٱlsãlāma."],[8,20,"هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: سَيَأْتِي شُعُوبٌ بَعْدُ، وَسُكَّانُ مُدُنٍ كَثِيرَةٍ.","hakadẖā qāla rabũ ٱl̊junūdi: sayā̊̉tī sẖuʿūbuⁿ baʿ̊du, wasukãạnu muduniⁿ katẖīraẗiⁿ."],[8,21,"وَسُكَّانُ وَاحِدَةٍ يَسِيرُونَ إِلَى أُخْرَى قَائِلِينَ: لِنَذْهَبْ ذَهَابًا لِنَتَرَضَّى وَجْهَ ٱلرَّبِّ وَنَطْلُبَ رَبَّ ٱلْجُنُودِ. أَنَا أَيْضًا أَذْهَبُ.","wasukãạnu wāḥidaẗiⁿ yasīrūna ại̹lay̱ ạủkẖ̊ray̱ qāyỉlīna: linadẖ̊hab̊ dẖahābaⁿạ linataraḍãy̱ waj̊ha ٱlrãbĩ wanaṭ̊luba rabã ٱl̊junūdi. ạảnā ạảẙḍaⁿạ ạảdẖ̊habu."],[8,22,"فَتَأْتِي شُعُوبٌ كَثِيرَةٌ وَأُمَمٌ قَوِيَّةٌ لِيَطْلُبُوا رَبَّ ٱلْجُنُودِ فِي أُورُشَلِيمَ، وَلْيَتَرَضَّوْا وَجْهَ ٱلرَّبِّ.","fatā̊̉tī sẖuʿūbuⁿ katẖīraẗuⁿ wāủmamuⁿ qawīãẗuⁿ līaṭ̊lubūạ rabã ٱl̊junūdi fī ạủwrusẖalīma, wal̊yataraḍãẘạ waj̊ha ٱlrãbĩ."],[8,23,"«هَكَذَا قَالَ رَبُّ ٱلْجُنُودِ: فِي تِلْكَ ٱلْأَيَّامِ يُمْسِكُ عَشَرَةُ رِجَالٍ مِنْ جَمِيعِ أَلْسِنَةِ ٱلْأُمَمِ يَتَمَسَّكُونَ بِذَيْلِ رَجُلٍ يَهُودِيٍّ قَائِلِينَ: نَذْهَبُ مَعَكُمْ لِأَنَّنَا سَمِعْنَا أَنَّ ٱللهَ مَعَكُمْ».","«hakadẖā qāla rabũ ٱl̊junūdi: fī til̊ka ٱl̊ạảyãạmi yum̊siku ʿasẖaraẗu rijāliⁿ min̊ jamīʿi ạảl̊sinaẗi ٱl̊ạủmami yatamasãkūna bidẖaẙli rajuliⁿ yahūdīiⁿ̃ qāyỉlīna: nadẖ̊habu maʿakum̊ liạảnãnā samiʿ̊nā ạảnã ٱllha maʿakum̊»."],[9,1,"وَحْيُ كَلِمَةِ ٱلرَّبِّ فِي أَرْضِ حَدْرَاخَ وَدِمَشْقَ مَحَلُّهُ. لِأَنَّ لِلرَّبِّ عَيْنَ ٱلْإِنْسَانِ وَكُلَّ أَسْبَاطِ إِسْرَائِيلَ.","waḥ̊yu kalimaẗi ٱlrãbĩ fī ạảr̊ḍi ḥad̊rākẖa wadimasẖ̊qa maḥalũhu. liạảnã lilrãbĩ ʿaẙna ٱl̊ại̹n̊sāni wakulã ạảs̊bāṭi ại̹s̊rāyỉyla."],[9,2,"وَحَمَاةُ أَيْضًا تُتَاخِمُهَا، وَصُورُ وَصَيْدُونُ وَإِنْ تَكُنْ حَكِيمَةً جِدًّا.","waḥamāẗu ạảẙḍaⁿạ tutākẖimuhā, waṣūru waṣaẙdūnu wāi̹n̊ takun̊ ḥakīmaẗaⁿ jidaⁿ̃ạ."],[9,3,"وَقَدْ بَنَتْ صُورُ حِصْنًا لِنَفْسِهَا، وَكَوَّمَتِ ٱلْفِضَّةَ كَٱلتُّرَابِ وَٱلذَّهَبَ كَطِينِ ٱلْأَسْوَاقِ.","waqad̊ banat̊ ṣūru ḥiṣ̊naⁿạ linaf̊sihā, wakawãmati ٱl̊fiḍãẗa kaٱltũrābi waٱldẖãhaba kaṭīni ٱl̊ạảs̊wāqi."],[9,4,"هُوَذَا ٱلسَّيِّدُ يَمْتَلِكُهَا وَيَضْرِبُ فِي ٱلْبَحْرِ قُوَّتَهَا، وَهِيَ تُؤْكَلُ بِٱلنَّارِ.","hūadẖā ٱlsãyĩdu yam̊talikuhā wayaḍ̊ribu fī ٱl̊baḥ̊ri qūãtahā, wahīa tū̊̉kalu biٱlnãạri."],[9,5,"تَرَى أَشْقَلُونُ فَتَخَافُ، وَغَزَّةُ فَتَتَوَجَّعُ جِدًّا، وَعَقْرُونُ. لِأَنَّهُ يُخْزِيهَا ٱنْتِظَارُهَا، وَٱلْمَلِكُ يَبِيدُ مِنْ غَزَّةَ، وَأَشْقَلُونُ لَا تُسْكَنُ.","taray̱ ạảsẖ̊qalūnu fatakẖāfu, wagẖazãẗu fatatawajãʿu jidaⁿ̃ạ, waʿaq̊rūnu. liạảnãhu yukẖ̊zīhā ٱn̊tiẓāruhā, waٱl̊maliku yabīdu min̊ gẖazãẗa, wāảsẖ̊qalūnu lā tus̊kanu."],[9,6,"وَيَسْكُنُ فِي أَشْدُودَ زَنِيمٌ، وَأَقْطَعُ كِبْرِيَاءَ ٱلْفِلِسْطِينِيِّينَ.","wayas̊kunu fī ạảsẖ̊dūda zanīmuⁿ, wāảq̊ṭaʿu kib̊rīāʾa ٱl̊filis̊ṭīnīĩyna."],[9,7,"وَأَنْزِعُ دِمَاءَهُ مِنْ فَمِهِ، وَرِجْسَهُ مِنْ بَيْنِ أَسْنَانِهِ، فَيَبْقَى هُوَ أَيْضًا لِإِلَهِنَا، وَيَكُونُ كَأَمِيرٍ فِي يَهُوذَا، وَعَقْرُونُ كَيَبُوسِيٍّ.","wāản̊ziʿu dimāʾahu min̊ famihi, warij̊sahu min̊ baẙni ạảs̊nānihi, fayab̊qay̱ hūa ạảẙḍaⁿạ liại̹lahinā, wayakūnu kāảmīriⁿ fī yahūdẖā, waʿaq̊rūnu kayabūsīiⁿ̃."],[9,8,"وَأَحُلُّ حَوْلَ بَيْتِي بِسَبَبِ ٱلْجَيْشِ ٱلذَّاهِبِ وَٱلْآئِبِ، فَلَا يَعْبُرُ عَلَيْهِمْ بَعْدُ جَابِي ٱلْجِزْيَةِ. فَإِنِّي ٱلْآنَ رَأَيْتُ بِعَيْنَيَّ.","wāảḥulũ ḥaẘla baẙtī bisababi ٱl̊jaẙsẖi ٱldẖãạhibi waٱl̊ậyỉbi, falā yaʿ̊buru ʿalaẙhim̊ baʿ̊du jābī ٱl̊jiz̊yaẗi. fāi̹nĩy ٱl̊ậna rāảẙtu biʿaẙnayã."],[9,9,"اِبْتَهِجِي جِدًّا يَا ٱبْنَةَ صِهْيَوْنَ، ٱهْتِفِي يَا بِنْتَ أُورُشَلِيمَ. هُوَذَا مَلِكُكِ يَأْتِي إِلَيْكِ. هُوَ عَادِلٌ وَمَنْصُورٌ وَدِيعٌ، وَرَاكِبٌ عَلَى حِمَارٍ وَعَلَى جَحْشٍ ٱبْنِ أَتَانٍ.","ạib̊tahijī jidaⁿ̃ạ yā ٱb̊naẗa ṣih̊yaẘna, ٱh̊tifī yā bin̊ta ạủwrusẖalīma. hūadẖā malikuki yā̊̉tī ại̹laẙki. hūa ʿādiluⁿ waman̊ṣūruⁿ wadīʿuⁿ, warākibuⁿ ʿalay̱ ḥimāriⁿ waʿalay̱ jaḥ̊sẖiⁿ ٱb̊ni ạảtāniⁿ."],[9,10,"وَأَقْطَعُ ٱلْمَرْكَبَةَ مِنْ أَفْرَايِمَ وَٱلْفَرَسَ مِنْ أُورُشَلِيمَ وَتُقْطَعُ قَوْسُ ٱلْحَرْبِ. وَيَتَكَلَّمُ بِٱلسَّلَامِ لِلْأُمَمِ، وَسُلْطَانُهُ مِنَ ٱلْبَحْرِ إِلَى ٱلْبَحْرِ، وَمِنَ ٱلنَّهْرِ إِلَى أَقَاصِي ٱلْأَرْضِ.","wāảq̊ṭaʿu ٱl̊mar̊kabaẗa min̊ ạảf̊rāyima waٱl̊farasa min̊ ạủwrusẖalīma watuq̊ṭaʿu qaẘsu ٱl̊ḥar̊bi. wayatakalãmu biٱlsãlāmi lil̊ạủmami, wasul̊ṭānuhu mina ٱl̊baḥ̊ri ại̹lay̱ ٱl̊baḥ̊ri, wamina ٱlnãh̊ri ại̹lay̱ ạảqāṣī ٱl̊ạảr̊ḍi."],[9,11,"وَأَنْتِ أَيْضًا فَإِنِّي بِدَمِ عَهْدِكِ قَدْ أَطْلَقْتُ أَسْرَاكِ مِنَ ٱلْجُبِّ ٱلَّذِي لَيْسَ فِيهِ مَاءٌ.","wāản̊ti ạảẙḍaⁿạ fāi̹nĩy bidami ʿah̊diki qad̊ ạảṭ̊laq̊tu ạảs̊rāki mina ٱl̊jubĩ ٱlãdẖī laẙsa fīhi māʾuⁿ."],[9,12,"ٱرْجِعُوا إِلَى ٱلْحِصْنِ يَا أَسْرَى ٱلرَّجَاءِ. ٱلْيَوْمَ أَيْضًا أُصَرِّحُ أَنِّي أَرُدُّ عَلَيْكِ ضِعْفَيْنِ.","ٱr̊jiʿūạ ại̹lay̱ ٱl̊ḥiṣ̊ni yā ạảs̊ray̱ ٱlrãjāʾi. ٱl̊yaẘma ạảẙḍaⁿạ ạủṣarĩḥu ạảnĩy ạảrudũ ʿalaẙki ḍiʿ̊faẙni."],[9,13,"لِأَنِّي أَوْتَرْتُ يَهُوذَا لِنَفْسِي، وَمَلَأْتُ ٱلْقَوْسَ أَفْرَايِمَ، وَأَنْهَضْتُ أَبْنَاءَكِ يَا صِهْيَوْنُ عَلَى بَنِيكِ يَا يَاوَانُ، وَجَعَلْتُكِ كَسَيْفِ جَبَّارٍ.","liạảnĩy ạảẘtar̊tu yahūdẖā linaf̊sī, wamalā̊̉tu ٱl̊qaẘsa ạảf̊rāyima, wāản̊haḍ̊tu ạảb̊nāʾaki yā ṣih̊yaẘnu ʿalay̱ banīki yā yāwānu, wajaʿal̊tuki kasaẙfi jabãạriⁿ."],[9,14,"وَيُرَى ٱلرَّبُّ فَوْقَهُمْ، وَسَهْمُهُ يَخْرُجُ كَٱلْبَرْقِ، وَٱلسَّيِّدُ ٱلرَّبُّ يَنْفُخُ فِي ٱلْبُوقِ وَيَسِيرُ فِي زَوَابِعِ ٱلْجَنُوبِ.","wayuray̱ ٱlrãbũ faẘqahum̊, wasah̊muhu yakẖ̊ruju kaٱl̊bar̊qi, waٱlsãyĩdu ٱlrãbũ yan̊fukẖu fī ٱl̊būqi wayasīru fī zawābiʿi ٱl̊janūbi."],[9,15,"رَبُّ ٱلْجُنُودِ يُحَامِي عَنْهُمْ فَيَأْكُلُونَ وَيَدُوسُونَ حِجَارَةَ ٱلْمِقْلَاعِ، وَيَشْرَبُونَ وَيَضُجُّونَ كَمَا مِنَ ٱلْخَمْرِ، وَيَمْتَلِئُونَ كَٱلْمَنْضَحِ وَكَزَوَايَا ٱلْمَذْبَحِ.","rabũ ٱl̊junūdi yuḥāmī ʿan̊hum̊ fayā̊̉kulūna wayadūsūna ḥijāraẗa ٱl̊miq̊lāʿi, wayasẖ̊rabūna wayaḍujũwna kamā mina ٱl̊kẖam̊ri, wayam̊talīủwna kaٱl̊man̊ḍaḥi wakazawāyā ٱl̊madẖ̊baḥi."],[9,16,"وَيُخَلِّصُهُمُ ٱلرَّبُّ إِلَهُهُمْ فِي ذَلِكَ ٱلْيَوْمِ. كَقَطِيعٍ شَعْبَهُ، بَلْ كَحِجَارَةِ ٱلتَّاجِ مَرْفُوعَةً عَلَى أَرْضِهِ.","wayukẖalĩṣuhumu ٱlrãbũ ại̹lahuhum̊ fī dẖalika ٱl̊yaẘmi. kaqaṭīʿiⁿ sẖaʿ̊bahu, bal̊ kaḥijāraẗi ٱltãạji mar̊fūʿaẗaⁿ ʿalay̱ ạảr̊ḍihi."],[9,17,"مَا أَجْوَدَهُ وَمَا أَجْمَلَهُ! اَلْحِنْطَةُ تُنْمِي ٱلْفِتْيَانَ، وَٱلْمِسْطَارُ ٱلْعَذَارَى.","mā ạảj̊wadahu wamā ạảj̊malahu! ạal̊ḥin̊ṭaẗu tun̊mī ٱl̊fit̊yāna, waٱl̊mis̊ṭāru ٱl̊ʿadẖāray̱."],[10,1,"اُطْلُبُوا مِنَ ٱلرَّبِّ ٱلْمَطَرَ فِي أَوَانِ ٱلْمَطَرِ ٱلْمُتَأَخِّرِ، فَيَصْنَعَ ٱلرَّبُّ بُرُوقًا وَيُعْطِيَهُمْ مَطَرَ ٱلْوَبْلِ. لِكُلِّ إِنْسَانٍ عُشْبًا فِي ٱلْحَقْلِ.","ạuṭ̊lubūạ mina ٱlrãbĩ ٱl̊maṭara fī ạảwāni ٱl̊maṭari ٱl̊mutāảkẖĩri, fayaṣ̊naʿa ٱlrãbũ burūqaⁿạ wayuʿ̊ṭīahum̊ maṭara ٱl̊wab̊li. likulĩ ại̹n̊sāniⁿ ʿusẖ̊baⁿạ fī ٱl̊ḥaq̊li."],[10,2,"لِأَنَّ ٱلتَّرَافِيمَ قَدْ تَكَلَّمُوا بِٱلْبَاطِلِ، وَٱلْعَرَّافُونَ رَأَوْا ٱلْكَذِبَ وَأَخْبَرُوا بِأَحْلَامِ كَذِبٍ. يُعَزُّونَ بِٱلْبَاطِلِ. لِذَلِكَ رَحَلُوا كَغَنَمٍ. ذَلُّوا إِذْ لَيْسَ رَاعٍ.","liạảnã ٱltãrāfīma qad̊ takalãmūạ biٱl̊bāṭili, waٱl̊ʿarãạfūna rāảẘạ ٱl̊kadẖiba wāảkẖ̊barūạ biạảḥ̊lāmi kadẖibiⁿ. yuʿazũwna biٱl̊bāṭili. lidẖalika raḥalūạ kagẖanamiⁿ. dẖalũwạ ại̹dẖ̊ laẙsa rāʿiⁿ."],[10,3,"«عَلَى ٱلرُّعَاةِ ٱشْتَعَلَ غَضَبِي فَعَاقَبْتُ ٱلْأَعْتِدَةَ، لِأَنَّ رَبَّ ٱلْجُنُودِ قَدْ تَعَهَّدَ قَطِيعَهُ بَيْتَ يَهُوذَا، وَجَعَلَهُمْ كَفَرَسِ جَلَالِهِ فِي ٱلْقِتَالِ.","«ʿalay̱ ٱlrũʿāẗi ٱsẖ̊taʿala gẖaḍabī faʿāqab̊tu ٱl̊ạảʿ̊tidaẗa, liạảnã rabã ٱl̊junūdi qad̊ taʿahãda qaṭīʿahu baẙta yahūdẖā, wajaʿalahum̊ kafarasi jalālihi fī ٱl̊qitāli."],[10,4,"مِنْهُ ٱلزَّاوِيَةُ. مِنْهُ ٱلْوَتَدُ. مِنْهُ قَوْسُ ٱلْقِتَالِ. مِنْهُ يَخْرُجُ كُلُّ ظَالِمٍ جَمِيعًا.","min̊hu ٱlzãạwīaẗu. min̊hu ٱl̊watadu. min̊hu qaẘsu ٱl̊qitāli. min̊hu yakẖ̊ruju kulũ ẓālimiⁿ jamīʿaⁿạ."],[10,5,"وَيَكُونُونَ كَٱلْجَبَابِرَةِ ٱلدَّائِسِينَ طِينَ ٱلْأَسْوَاقِ فِي ٱلْقِتَالِ، وَيُحَارِبُونَ لِأَنَّ ٱلرَّبَّ مَعَهُمْ، وَٱلرَّاكِبُونَ ٱلْخَيْلَ يَخْزَوْنَ.","wayakūnūna kaٱl̊jabābiraẗi ٱldãạyỉsīna ṭīna ٱl̊ạảs̊wāqi fī ٱl̊qitāli, wayuḥāribūna liạảnã ٱlrãbã maʿahum̊, waٱlrãạkibūna ٱl̊kẖaẙla yakẖ̊zaẘna."],[10,6,"وَأُقَوِّي بَيْتَ يَهُوذَا، وَأُخَلِّصُ بَيْتَ يُوسُفَ وَأُرَجِّعُهُمْ، لِأَنِّي قَدْ رَحِمْتُهُمْ. وَيَكُونُونَ كَأَنِّي لَمْ أَرْفُضْهُمْ، لِأَنِّي أَنَا ٱلرَّبُّ إِلَهُهُمْ فَأُجِيبُهُمْ.","wāủqawĩy baẙta yahūdẖā, wāủkẖalĩṣu baẙta yūsufa wāủrajĩʿuhum̊, liạảnĩy qad̊ raḥim̊tuhum̊. wayakūnūna kāảnĩy lam̊ ạảr̊fuḍ̊hum̊, liạảnĩy ạảnā ٱlrãbũ ại̹lahuhum̊ fāủjībuhum̊."],[10,7,"وَيَكُونُ أَفْرَايِمُ كَجَبَّارٍ، وَيَفْرَحُ قَلْبُهُمْ كَأَنَّهُ بِٱلْخَمْرِ، وَيَنْظُرُ بَنُوهُمْ فَيَفْرَحُونَ وَيَبْتَهِجُ قَلْبُهُمْ بِٱلرَّبِّ.","wayakūnu ạảf̊rāyimu kajabãạriⁿ, wayaf̊raḥu qal̊buhum̊ kāảnãhu biٱl̊kẖam̊ri, wayan̊ẓuru banūhum̊ fayaf̊raḥūna wayab̊tahiju qal̊buhum̊ biٱlrãbĩ."],[10,8,"أَصْفِرُ لَهُمْ وَأَجْمَعُهُمْ لِأَنِّي قَدْ فَدَيْتُهُمْ، وَيَكْثُرُونَ كَمَا كَثُرُوا.","ạảṣ̊firu lahum̊ wāảj̊maʿuhum̊ liạảnĩy qad̊ fadaẙtuhum̊, wayak̊tẖurūna kamā katẖurūạ."],[10,9,"وَأَزْرَعُهُمْ بَيْنَ ٱلشُّعُوبِ فَيَذْكُرُونَنِي فِي ٱلْأَرَاضِي ٱلْبَعِيدَةِ، وَيَحْيَوْنَ مَعَ بَنِيهِمْ وَيَرْجِعُونَ.","wāảz̊raʿuhum̊ baẙna ٱlsẖũʿūbi fayadẖ̊kurūnanī fī ٱl̊ạảrāḍī ٱl̊baʿīdaẗi, wayaḥ̊yaẘna maʿa banīhim̊ wayar̊jiʿūna."],[10,10,"وَأُرْجِعُهُمْ مِنْ أَرْضِ مِصْرَ، وَأَجْمَعُهُمْ مِنْ أَشُّورَ، وَآتِي بِهِمْ إِلَى أَرْضِ جِلْعَادَ وَلُبْنَانَ، وَلَا يُوجَدُ لَهُمْ مَكَانٌ.","wāủr̊jiʿuhum̊ min̊ ạảr̊ḍi miṣ̊ra, wāảj̊maʿuhum̊ min̊ ạảsẖũwra, wā̂tī bihim̊ ại̹lay̱ ạảr̊ḍi jil̊ʿāda walub̊nāna, walā yūjadu lahum̊ makānuⁿ."],[10,11,"وَيَعْبُرُ فِي بَحْرِ ٱلضِّيقِ، وَيَضْرِبُ ٱللُّجَجَ فِي ٱلْبَحْرِ، وَتَجِفُّ كُلُّ أَعْمَاقِ ٱلنَّهْرِ، وَتُخْفَضُ كِبْرِيَاءُ أَشُّورَ، وَيَزُولُ قَضِيبُ مِصْرَ.","wayaʿ̊buru fī baḥ̊ri ٱlḍĩyqi, wayaḍ̊ribu ٱllũjaja fī ٱl̊baḥ̊ri, watajifũ kulũ ạảʿ̊māqi ٱlnãh̊ri, watukẖ̊faḍu kib̊rīāʾu ạảsẖũwra, wayazūlu qaḍību miṣ̊ra."],[10,12,"وَأُقَوِّيهِمْ بِٱلرَّبِّ، فَيَسْلُكُونَ بِٱسْمِهِ، يَقُولُ ٱلرَّبُّ».","wāủqawĩyhim̊ biٱlrãbĩ, fayas̊lukūna biٱs̊mihi, yaqūlu ٱlrãbũ»."],[11,1,"اِفْتَحْ أَبْوَابَكَ يَا لُبْنَانُ، فَتَأْكُلَ ٱلنَّارُ أَرْزَكَ.","ạif̊taḥ̊ ạảb̊wābaka yā lub̊nānu, fatā̊̉kula ٱlnãạru ạảr̊zaka."],[11,2,"وَلْوِلْ يَا سَرْوُ، لِأَنَّ ٱلْأَرْزَ سَقَطَ، لِأَنَّ ٱلْأَعِزَّاءَ قَدْ خَرِبُوا. وَلْوِلْ يَا بَلُّوطَ بَاشَانَ، لِأَنَّ ٱلْوَعْرَ ٱلْمَنِيعَ قَدْ هَبَطَ.","wal̊wil̊ yā sar̊wu, liạảnã ٱl̊ạảr̊za saqaṭa, liạảnã ٱl̊ạảʿizãạʾa qad̊ kẖaribūạ. wal̊wil̊ yā balũwṭa bāsẖāna, liạảnã ٱl̊waʿ̊ra ٱl̊manīʿa qad̊ habaṭa."],[11,3,"صَوْتُ وَلْوَلَةِ ٱلرُّعَاةِ، لِأَنَّ فَخْرَهُمْ خَرِبَ. صَوْتُ زَمْجَرَةِ ٱلْأَشْبَالِ، لِأَنَّ كِبْرِيَاءَ ٱلْأُرْدُنِّ خَرِبَتْ.","ṣaẘtu wal̊walaẗi ٱlrũʿāẗi, liạảnã fakẖ̊rahum̊ kẖariba. ṣaẘtu zam̊jaraẗi ٱl̊ạảsẖ̊bāli, liạảnã kib̊rīāʾa ٱl̊ạủr̊dunĩ kẖaribat̊."],[11,4,"هَكَذَا قَالَ ٱلرَّبُّ إِلَهِي: «ٱرْعَ غَنَمَ ٱلذَّبْحِ","hakadẖā qāla ٱlrãbũ ại̹lahī: «ٱr̊ʿa gẖanama ٱldẖãb̊ḥi"],[11,5,"ٱلَّذِينَ يَذْبَحُهُمْ مَالِكُوهُمْ وَلَا يَأْثَمُونَ، وَبَائِعُوهُمْ يَقُولُونَ: مُبَارَكٌ ٱلرَّبُّ! قَدِ ٱسْتَغْنَيْتُ. وَرُعَاتُهُمْ لَا يُشْفِقُونَ عَلَيْهِمْ.","ٱlãdẖīna yadẖ̊baḥuhum̊ mālikūhum̊ walā yā̊̉tẖamūna, wabāyỉʿūhum̊ yaqūlūna: mubārakuⁿ ٱlrãbũ! qadi ٱs̊tagẖ̊naẙtu. waruʿātuhum̊ lā yusẖ̊fiqūna ʿalaẙhim̊."],[11,6,"لِأَنِّي لَا أُشْفِقُ بَعْدُ عَلَى سُكَّانِ ٱلْأَرْضِ، يَقُولُ ٱلرَّبُّ، بَلْ هَأَنَذَا مُسَلِّمٌ ٱلْإِنْسَانَ، كُلَّ رَجُلٍ لِيَدِ قَرِيبِهِ وَلِيَدِ مَلِكِهِ، فَيَضْرِبُونَ ٱلْأَرْضَ وَلَا أُنْقِذُ مِنْ يَدِهِمْ».","liạảnĩy lā ạủsẖ̊fiqu baʿ̊du ʿalay̱ sukãạni ٱl̊ạảr̊ḍi, yaqūlu ٱlrãbũ, bal̊ hāảnadẖā musalĩmuⁿ ٱl̊ại̹n̊sāna, kulã rajuliⁿ līadi qarībihi walīadi malikihi, fayaḍ̊ribūna ٱl̊ạảr̊ḍa walā ạủn̊qidẖu min̊ yadihim̊»."],[11,7,"فَرَعَيْتُ غَنَمَ ٱلذَّبْحِ. لَكِنَّهُمْ أَذَلُّ ٱلْغَنَمِ. وَأَخَذْتُ لِنَفْسِي عَصَوَيْنِ، فَسَمَّيْتُ ٱلْوَاحِدَةَ «نِعْمَةَ» وَسَمَّيْتُ ٱلْأُخْرَى «حِبَالًا» وَرَعَيْتُ ٱلْغَنَمَ.","faraʿaẙtu gẖanama ٱldẖãb̊ḥi. lakinãhum̊ ạảdẖalũ ٱl̊gẖanami. wāảkẖadẖ̊tu linaf̊sī ʿaṣawaẙni, fasamãẙtu ٱl̊wāḥidaẗa «niʿ̊maẗa» wasamãẙtu ٱl̊ạủkẖ̊ray̱ «ḥibālaⁿạ» waraʿaẙtu ٱl̊gẖanama."],[11,8,"وَأَبَدْتُ ٱلرُّعَاةَ ٱلثَّلَاثَةَ فِي شَهْرٍ وَاحِدٍ، وَضَاقَتْ نَفْسِي بِهِمْ، وَكَرِهَتْنِي أَيْضًا نَفْسُهُمْ.","wāảbad̊tu ٱlrũʿāẗa ٱltẖãlātẖaẗa fī sẖah̊riⁿ wāḥidiⁿ, waḍāqat̊ naf̊sī bihim̊, wakarihat̊nī ạảẙḍaⁿạ naf̊suhum̊."],[11,9,"فَقُلْتُ: «لَا أَرْعَاكُمْ. مَنْ يَمُتْ فَلْيَمُتْ، وَمَنْ يُبَدْ فَلْيُبَدْ. وَٱلْبَقِيَّةُ فَلْيَأْكُلْ بَعْضُهَا لَحْمَ بَعْضٍ!».","faqul̊tu: «lā ạảr̊ʿākum̊. man̊ yamut̊ fal̊yamut̊, waman̊ yubad̊ fal̊yubad̊. waٱl̊baqīãẗu fal̊yā̊̉kul̊ baʿ̊ḍuhā laḥ̊ma baʿ̊ḍiⁿ!»."],[11,10,"فَأَخَذْتُ عَصَايَ «نِعْمَةَ» وَقَصَفْتُهَا لِأَنْقُضَ عَهْدِي ٱلَّذِي قَطَعْتُهُ مَعَ كُلِّ ٱلْأَسْبَاطِ.","fāảkẖadẖ̊tu ʿaṣāya «niʿ̊maẗa» waqaṣaf̊tuhā liạản̊quḍa ʿah̊dī ٱlãdẖī qaṭaʿ̊tuhu maʿa kulĩ ٱl̊ạảs̊bāṭi."],[11,11,"فَنُقِضَ فِي ذَلِكَ ٱلْيَوْمِ. وَهَكَذَا عَلِمَ أَذَلُّ ٱلْغَنَمِ ٱلْمُنْتَظِرُونَ لِي أَنَّهَا كَلِمَةُ ٱلرَّبِّ.","fanuqiḍa fī dẖalika ٱl̊yaẘmi. wahakadẖā ʿalima ạảdẖalũ ٱl̊gẖanami ٱl̊mun̊taẓirūna lī ạảnãhā kalimaẗu ٱlrãbĩ."],[11,12,"فَقُلْتُ لَهُمْ: «إِنْ حَسُنَ فِي أَعْيُنِكُمْ فَأَعْطُونِي أُجْرَتِي وَإِلَّا فَٱمْتَنِعُوا». فَوَزَنُوا أُجْرَتِي ثَلَاثِينَ مِنَ ٱلْفِضَّةِ.","faqul̊tu lahum̊: «ại̹n̊ ḥasuna fī ạảʿ̊yunikum̊ fāảʿ̊ṭūnī ạủj̊ratī wāi̹lãạ faٱm̊taniʿūạ». fawazanūạ ạủj̊ratī tẖalātẖīna mina ٱl̊fiḍãẗi."],[11,13,"فَقَالَ لِي ٱلرَّبُّ: «أَلْقِهَا إِلَى ٱلْفَخَّارِيِّ، ٱلثَّمَنَ ٱلْكَرِيمَ ٱلَّذِي ثَمَّنُونِي بِهِ». فَأَخَذْتُ ٱلثَّلَاثِينَ مِنَ ٱلْفِضَّةِ وَأَلْقَيْتُهَا إِلَى ٱلْفَخَّارِيِّ فِي بَيْتِ ٱلرَّبِّ.","faqāla lī ٱlrãbũ: «ạảl̊qihā ại̹lay̱ ٱl̊fakẖãạrīĩ, ٱltẖãmana ٱl̊karīma ٱlãdẖī tẖamãnūnī bihi». fāảkẖadẖ̊tu ٱltẖãlātẖīna mina ٱl̊fiḍãẗi wāảl̊qaẙtuhā ại̹lay̱ ٱl̊fakẖãạrīĩ fī baẙti ٱlrãbĩ."],[11,14,"ثُمَّ قَصَفْتُ عَصَايَ ٱلْأُخْرَى «حِبَالًا» لِأَنْقُضَ ٱلْإِخَاءَ بَيْنَ يَهُوذَا وَإِسْرَائِيلَ.","tẖumã qaṣaf̊tu ʿaṣāya ٱl̊ạủkẖ̊ray̱ «ḥibālaⁿạ» liạản̊quḍa ٱl̊ại̹kẖāʾa baẙna yahūdẖā wāi̹s̊rāyỉyla."],[11,15,"فَقَالَ لِي ٱلرَّبُّ: «خُذْ لِنَفْسِكَ بَعْدُ أَدَوَاتِ رَاعٍ أَحْمَقَ،","faqāla lī ٱlrãbũ: «kẖudẖ̊ linaf̊sika baʿ̊du ạảdawāti rāʿiⁿ ạảḥ̊maqa,"],[11,16,"لِأَنِّي هَأَنَذَا مُقِيمٌ رَاعِيًا فِي ٱلْأَرْضِ لَا يَفْتَقِدُ ٱلْمُنْقَطِعِينَ، وَلَا يَطْلُبُ ٱلْمُنْسَاقَ، وَلَا يَجْبُرُ ٱلْمُنْكَسِرَ، وَلَا يُرَبِّي ٱلْقَائِمَ. وَلَكِنْ يَأْكُلُ لَحْمَ ٱلسِّمَانِ وَيَنْزِعُ أَظْلَافَهَا».","liạảnĩy hāảnadẖā muqīmuⁿ rāʿīaⁿạ fī ٱl̊ạảr̊ḍi lā yaf̊taqidu ٱl̊mun̊qaṭiʿīna, walā yaṭ̊lubu ٱl̊mun̊sāqa, walā yaj̊buru ٱl̊mun̊kasira, walā yurabĩy ٱl̊qāyỉma. walakin̊ yā̊̉kulu laḥ̊ma ٱlsĩmāni wayan̊ziʿu ạảẓ̊lāfahā»."],[11,17,"وَيْلٌ لِلرَّاعِي ٱلْبَاطِلِ ٱلتَّارِكِ ٱلْغَنَمِ! اَلسَّيْفُ عَلَى ذِرَاعِهِ وَعَلَى عَيْنِهِ ٱلْيُمْنَى. ذِرَاعُهُ تَيْبَسُ يَبْسًا، وَعَيْنُهُ ٱلْيُمْنَى تَكِلُّ كُلُولًا!","waẙluⁿ lilrãạʿī ٱl̊bāṭili ٱltãạriki ٱl̊gẖanami! ạalsãẙfu ʿalay̱ dẖirāʿihi waʿalay̱ ʿaẙnihi ٱl̊yum̊nay̱. dẖirāʿuhu taẙbasu yab̊saⁿạ, waʿaẙnuhu ٱl̊yum̊nay̱ takilũ kulūlaⁿạ!"],[12,1,"وَحْيُ كَلَامِ ٱلرَّبِّ عَلَى إِسْرَائِيلَ. يَقُولُ ٱلرَّبُّ بَاسِطُ ٱلسَّمَاوَاتِ وَمُؤَسِّسُ ٱلْأَرْضِ وَجَابِلُ رُوحِ ٱلْإِنْسَانِ فِي دَاخِلِهِ:","waḥ̊yu kalāmi ٱlrãbĩ ʿalay̱ ại̹s̊rāyỉyla. yaqūlu ٱlrãbũ bāsiṭu ٱlsãmāwāti wamūảsĩsu ٱl̊ạảr̊ḍi wajābilu rūḥi ٱl̊ại̹n̊sāni fī dākẖilihi:"],[12,2,"«هَأَنَذَا أَجْعَلُ أُورُشَلِيمَ كَأْسَ تَرَنُّحٍ لِجَمِيعِ ٱلشُّعُوبِ حَوْلَهَا، وَأَيْضًا عَلَى يَهُوذَا تَكُونُ فِي حِصَارِ أُورُشَلِيمَ.","«hāảnadẖā ạảj̊ʿalu ạủwrusẖalīma kā̊̉sa taranũḥiⁿ lijamīʿi ٱlsẖũʿūbi ḥaẘlahā, wāảẙḍaⁿạ ʿalay̱ yahūdẖā takūnu fī ḥiṣāri ạủwrusẖalīma."],[12,3,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنِّي أَجْعَلُ أُورُشَلِيمَ حَجَرًا مِشْوَالًا لِجَمِيعِ ٱلشُّعُوبِ، وَكُلُّ ٱلَّذِينَ يَشِيلُونَهُ يَنْشَقُّونَ شَقًّا. وَيَجْتَمِعُ عَلَيْهَا كُلُّ أُمَمِ ٱلْأَرْضِ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnĩy ạảj̊ʿalu ạủwrusẖalīma ḥajaraⁿạ misẖ̊wālaⁿạ lijamīʿi ٱlsẖũʿūbi, wakulũ ٱlãdẖīna yasẖīlūnahu yan̊sẖaqũwna sẖaqaⁿ̃ạ. wayaj̊tamiʿu ʿalaẙhā kulũ ạủmami ٱl̊ạảr̊ḍi."],[12,4,"فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَضْرِبُ كُلَّ فَرَسٍ بِٱلْحَيْرَةِ وَرَاكِبَهُ بِٱلْجُنُونِ. وَأَفْتَحُ عَيْنَيَّ عَلَى بَيْتِ يَهُوذَا، وَأَضْرِبُ كُلَّ خَيْلِ ٱلشُّعُوبِ بِٱلْعَمَى.","fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảḍ̊ribu kulã farasiⁿ biٱl̊ḥaẙraẗi warākibahu biٱl̊junūni. wāảf̊taḥu ʿaẙnayã ʿalay̱ baẙti yahūdẖā, wāảḍ̊ribu kulã kẖaẙli ٱlsẖũʿūbi biٱl̊ʿamay̱."],[12,5,"فَتَقُولُ أُمَرَاءُ يَهُوذَا فِي قَلْبِهِمْ: إِنَّ سُكَّانَ أُورُشَلِيمَ قُوَّةٌ لِي بِرَبِّ ٱلْجُنُودِ إِلَهِهِمْ.","fataqūlu ạủmarāʾu yahūdẖā fī qal̊bihim̊: ại̹nã sukãạna ạủwrusẖalīma qūãẗuⁿ lī birabĩ ٱl̊junūdi ại̹lahihim̊."],[12,6,"فِي ذَلِكَ ٱلْيَوْمِ أَجْعَلُ أُمَرَاءَ يَهُوذَا كَمِصْبَاحِ نَارٍ بَيْنَ ٱلْحَطَبِ، وَكَمِشْعَلِ نَارٍ بَيْنَ ٱلْحُزَمِ. فَيَأْكُلُونَ كُلَّ ٱلشُّعُوبِ حَوْلَهُمْ عَنِ ٱلْيَمِينِ وَعَنِ ٱلْيَسَارِ، فَتَثْبُتُ أُورُشَلِيمُ أَيْضًا فِي مَكَانِهَا بِأُورُشَلِيمَ.","fī dẖalika ٱl̊yaẘmi ạảj̊ʿalu ạủmarāʾa yahūdẖā kamiṣ̊bāḥi nāriⁿ baẙna ٱl̊ḥaṭabi, wakamisẖ̊ʿali nāriⁿ baẙna ٱl̊ḥuzami. fayā̊̉kulūna kulã ٱlsẖũʿūbi ḥaẘlahum̊ ʿani ٱl̊yamīni waʿani ٱl̊yasāri, fatatẖ̊butu ạủwrusẖalīmu ạảẙḍaⁿạ fī makānihā biạủwrusẖalīma."],[12,7,"وَيُخَلِّصُ ٱلرَّبُّ خِيَامَ يَهُوذَا أَوَّلًا لِكَيْلَا يَتَعَاظَمَ ٱفْتِخَارُ بَيْتِ دَاوُدَ وَٱفْتِخَارُ سُكَّانِ أُورُشَلِيمَ عَلَى يَهُوذَا.","wayukẖalĩṣu ٱlrãbũ kẖīāma yahūdẖā ạảwãlaⁿạ likaẙlā yataʿāẓama ٱf̊tikẖāru baẙti dāwuda waٱf̊tikẖāru sukãạni ạủwrusẖalīma ʿalay̱ yahūdẖā."],[12,8,"فِي ذَلِكَ ٱلْيَوْمِ يَسْتُرُ ٱلرَّبُّ سُكَّانَ أُورُشَلِيمَ، فَيَكُونُ ٱلْعَاثِرُ مِنْهُمْ فِي ذَلِكَ ٱلْيَوْمِ مِثْلَ دَاوُدَ، وَبَيْتُ دَاوُدَ مِثْلَ ٱللهِ، مِثْلَ مَلَاكِ ٱلرَّبِّ أَمَامَهُمْ.","fī dẖalika ٱl̊yaẘmi yas̊turu ٱlrãbũ sukãạna ạủwrusẖalīma, fayakūnu ٱl̊ʿātẖiru min̊hum̊ fī dẖalika ٱl̊yaẘmi mitẖ̊la dāwuda, wabaẙtu dāwuda mitẖ̊la ٱllhi, mitẖ̊la malāki ٱlrãbĩ ạảmāmahum̊."],[12,9,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنِّي أَلْتَمِسُ هَلَاكَ كُلِّ ٱلْأُمَمِ ٱلْآتِينَ عَلَى أُورُشَلِيمَ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnĩy ạảl̊tamisu halāka kulĩ ٱl̊ạủmami ٱl̊ậtīna ʿalay̱ ạủwrusẖalīma."],[12,10,"«وَأُفِيضُ عَلَى بَيْتِ دَاوُدَ وَعَلَى سُكَّانِ أُورُشَلِيمَ رُوحَ ٱلنِّعْمَةِ وَٱلتَّضَرُّعَاتِ، فَيَنْظُرُونَ إِلَيَّ، ٱلَّذِي طَعَنُوهُ، وَيَنُوحُونَ عَلَيْهِ كَنَائِحٍ عَلَى وَحِيدٍ لَهُ، وَيَكُونُونَ فِي مَرَارَةٍ عَلَيْهِ كَمَنْ هُوَ فِي مَرَارَةٍ عَلَى بِكْرِهِ.","«wāủfīḍu ʿalay̱ baẙti dāwuda waʿalay̱ sukãạni ạủwrusẖalīma rūḥa ٱlnĩʿ̊maẗi waٱltãḍarũʿāti, fayan̊ẓurūna ại̹layã, ٱlãdẖī ṭaʿanūhu, wayanūḥūna ʿalaẙhi kanāyỉḥiⁿ ʿalay̱ waḥīdiⁿ lahu, wayakūnūna fī marāraẗiⁿ ʿalaẙhi kaman̊ hūa fī marāraẗiⁿ ʿalay̱ bik̊rihi."],[12,11,"فِي ذَلِكَ ٱلْيَوْمِ يَعْظُمُ ٱلنَّوْحُ فِي أُورُشَلِيمَ كَنَوْحِ هَدَدْرِمُّونَ فِي بُقْعَةِ مَجِدُّونَ.","fī dẖalika ٱl̊yaẘmi yaʿ̊ẓumu ٱlnãẘḥu fī ạủwrusẖalīma kanaẘḥi hadad̊rimũwna fī buq̊ʿaẗi majidũwna."],[12,12,"وَتَنُوحُ ٱلْأَرْضُ عَشَائِرَ عَشَائِرَ عَلَى حِدَتِهَا: عَشِيرَةُ بَيْتِ دَاوُدَ عَلَى حِدَتِهَا، وَنِسَاؤُهُمْ عَلَى حِدَتِهِنَّ. عَشِيرَةُ بَيْتِ نَاثَانَ عَلَى حِدَتِهَا، وَنِسَاؤُهُمْ عَلَى حِدَتِهِنَّ.","watanūḥu ٱl̊ạảr̊ḍu ʿasẖāyỉra ʿasẖāyỉra ʿalay̱ ḥidatihā: ʿasẖīraẗu baẙti dāwuda ʿalay̱ ḥidatihā, wanisāwủhum̊ ʿalay̱ ḥidatihinã. ʿasẖīraẗu baẙti nātẖāna ʿalay̱ ḥidatihā, wanisāwủhum̊ ʿalay̱ ḥidatihinã."],[12,13,"عَشِيرَةُ بَيْتِ لَاوِي عَلَى حِدَتِهَا، وَنِسَاؤُهُمْ عَلَى حِدَتِهِنَّ. عَشِيرَةُ شَمْعِي عَلَى حِدَتِهَا، وَنِسَاؤُهُمْ عَلَى حِدَتِهِنَّ.","ʿasẖīraẗu baẙti lāwī ʿalay̱ ḥidatihā, wanisāwủhum̊ ʿalay̱ ḥidatihinã. ʿasẖīraẗu sẖam̊ʿī ʿalay̱ ḥidatihā, wanisāwủhum̊ ʿalay̱ ḥidatihinã."],[12,14,"كُلُّ ٱلْعَشَائِرِ ٱلْبَاقِيَةِ عَشِيرَةٌ عَشِيرَةٌ عَلَى حِدَتِهَا، وَنِسَاؤُهُمْ عَلَى حِدَتِهِنَّ.","kulũ ٱl̊ʿasẖāyỉri ٱl̊bāqīaẗi ʿasẖīraẗuⁿ ʿasẖīraẗuⁿ ʿalay̱ ḥidatihā, wanisāwủhum̊ ʿalay̱ ḥidatihinã."],[13,1,"«فِي ذَلِكَ ٱلْيَوْمِ يَكُونُ يَنْبُوعٌ مَفْتُوحًا لِبَيْتِ دَاوُدَ وَلِسُكَّانِ أُورُشَلِيمَ لِلْخَطِيَّةِ وَلِلْنَجَاسَةِ.","«fī dẖalika ٱl̊yaẘmi yakūnu yan̊būʿuⁿ maf̊tūḥaⁿạ libaẙti dāwuda walisukãạni ạủwrusẖalīma lil̊kẖaṭīãẗi walil̊najāsaẗi."],[13,2,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ رَبُّ ٱلْجُنُودِ، أَنِّي أَقْطَعُ أَسْمَاءَ ٱلْأَصْنَامِ مِنَ ٱلْأَرْضِ فَلَا تُذْكَرُ بَعْدُ، وَأُزِيلُ ٱلْأَنْبِيَاءَ أَيْضًا وَٱلرُّوحَ ٱلنَّجِسَ مِنَ ٱلْأَرْضِ.","wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu rabũ ٱl̊junūdi, ạảnĩy ạảq̊ṭaʿu ạảs̊māʾa ٱl̊ạảṣ̊nāmi mina ٱl̊ạảr̊ḍi falā tudẖ̊karu baʿ̊du, wāủzīlu ٱl̊ạản̊bīāʾa ạảẙḍaⁿạ waٱlrũwḥa ٱlnãjisa mina ٱl̊ạảr̊ḍi."],[13,3,"وَيَكُونُ إِذَا تَنَبَّأَ أَحَدٌ بَعْدُ أَنَّ أَبَاهُ وَأُمَّهُ، وَالِدَيْهِ، يَقُولَانِ لَهُ: لَا تَعِيشُ لِأَنَّكَ تَكَلَّمْتَ بِٱلْكَذِبِ بِٱسْمِ ٱلرَّبِّ. فَيَطْعَنُهُ أَبُوهُ وَأُمُّهُ، وَالِدَاهُ، عِنْدَمَا يَتَنَبَّأُ.","wayakūnu ại̹dẖā tanabãạả ạảḥaduⁿ baʿ̊du ạảnã ạảbāhu wāủmãhu, wālidaẙhi, yaqūlāni lahu: lā taʿīsẖu liạảnãka takalãm̊ta biٱl̊kadẖibi biٱs̊mi ٱlrãbĩ. fayaṭ̊ʿanuhu ạảbūhu wāủmũhu, wālidāhu, ʿin̊damā yatanabãạủ."],[13,4,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنَّ ٱلْأَنْبِيَاءَ يَخْزَوْنَ كُلُّ وَاحِدٍ مِنْ رُؤْيَاهُ إِذَا تَنَبَّأَ، وَلَا يَلْبَسُونَ ثَوْبَ شَعْرٍ لِأَجْلِ ٱلْغِشِّ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnã ٱl̊ạản̊bīāʾa yakẖ̊zaẘna kulũ wāḥidiⁿ min̊ rū̊̉yāhu ại̹dẖā tanabãạả, walā yal̊basūna tẖaẘba sẖaʿ̊riⁿ liạảj̊li ٱl̊gẖisẖĩ."],[13,5,"بَلْ يَقُولُ: لَسْتُ أَنَا نَبِيًّا. أَنَا إِنْسَانٌ فَالِحُ ٱلْأَرْضِ، لِأَنَّ إِنْسَانًا ٱقْتَنَانِي مِنْ صِبَايَ.","bal̊ yaqūlu: las̊tu ạảnā nabīaⁿ̃ạ. ạảnā ại̹n̊sānuⁿ fāliḥu ٱl̊ạảr̊ḍi, liạảnã ại̹n̊sānaⁿạ ٱq̊tanānī min̊ ṣibāya."],[13,6,"فَيَقُولُ لَهُ: مَا هَذِهِ ٱلْجُرُوحُ فِي يَدَيْكَ؟ فَيَقُولُ: هِيَ ٱلَّتِي جُرِحْتُ بِهَا فِي بَيْتِ أَحِبَّائِي.","fayaqūlu lahu: mā hadẖihi ٱl̊jurūḥu fī yadaẙka? fayaqūlu: hīa ٱlãtī juriḥ̊tu bihā fī baẙti ạảḥibãạyỉy."],[13,7,"«اِسْتَيْقِظْ يَا سَيْفُ عَلَى رَاعِيَّ، وَعَلَى رَجُلِ رِفْقَتِي، يَقُولُ رَبُّ ٱلْجُنُودِ. اِضْرِبِ ٱلرَّاعِيَ فَتَتَشَتَّتَ ٱلْغَنَمُ، وَأَرُدُّ يَدِي عَلَى ٱلصِّغَارِ.","«ạis̊taẙqiẓ̊ yā saẙfu ʿalay̱ rāʿīã, waʿalay̱ rajuli rif̊qatī, yaqūlu rabũ ٱl̊junūdi. ạiḍ̊ribi ٱlrãạʿīa fatatasẖatãta ٱl̊gẖanamu, wāảrudũ yadī ʿalay̱ ٱlṣĩgẖāri."],[13,8,"وَيَكُونُ فِي كُلِّ ٱلْأَرْضِ، يَقُولُ ٱلرَّبُّ، أَنَّ ثُلْثَيْنِ مِنْهَا يُقْطَعَانِ وَيَمُوتَانِ، وَٱلثُّلْثَ يَبْقَى فِيهَا.","wayakūnu fī kulĩ ٱl̊ạảr̊ḍi, yaqūlu ٱlrãbũ, ạảnã tẖul̊tẖaẙni min̊hā yuq̊ṭaʿāni wayamūtāni, waٱltẖũl̊tẖa yab̊qay̱ fīhā."],[13,9,"وَأُدْخِلُ ٱلثُّلْثَ فِي ٱلنَّارِ، وَأَمْحَصُهُمْ كَمَحْصِ ٱلْفِضَّةِ، وَأَمْتَحِنُهُمُ ٱمْتِحَانَ ٱلذَّهَبِ. هُوَ يَدْعُو بِٱسْمِي وَأَنَا أُجِيبُهُ. أَقُولُ: هُوَ شَعْبِي، وَهُوَ يَقُولُ: ٱلرَّبُّ إِلَهِي».","wāủd̊kẖilu ٱltẖũl̊tẖa fī ٱlnãạri, wāảm̊ḥaṣuhum̊ kamaḥ̊ṣi ٱl̊fiḍãẗi, wāảm̊taḥinuhumu ٱm̊tiḥāna ٱldẖãhabi. hūa yad̊ʿū biٱs̊mī wāảnā ạủjībuhu. ạảqūlu: hūa sẖaʿ̊bī, wahūa yaqūlu: ٱlrãbũ ại̹lahī»."],[14,1,"هُوَذَا يَوْمٌ لِلرَّبِّ يَأْتِي فَيُقْسَمُ سَلَبُكِ فِي وَسَطِكِ.","hūadẖā yaẘmuⁿ lilrãbĩ yā̊̉tī fayuq̊samu salabuki fī wasaṭiki."],[14,2,"وَأَجْمَعُ كُلَّ ٱلْأُمَمِ عَلَى أُورُشَلِيمَ لِلْمُحَارَبَةِ، فَتُؤْخَذُ ٱلْمَدِينَةُ، وَتُنْهَبُ ٱلْبُيُوتُ، وَتُفْضَحُ ٱلنِّسَاءُ، وَيَخْرُجُ نِصْفُ ٱلْمَدِينَةِ إِلَى ٱلسَّبْيِ، وَبَقِيَّةُ ٱلشَّعْبِ لَا تُقْطَعُ مِنَ ٱلْمَدِينَةِ.","wāảj̊maʿu kulã ٱl̊ạủmami ʿalay̱ ạủwrusẖalīma lil̊muḥārabaẗi, fatū̊̉kẖadẖu ٱl̊madīnaẗu, watun̊habu ٱl̊buyūtu, watuf̊ḍaḥu ٱlnĩsāʾu, wayakẖ̊ruju niṣ̊fu ٱl̊madīnaẗi ại̹lay̱ ٱlsãb̊yi, wabaqīãẗu ٱlsẖãʿ̊bi lā tuq̊ṭaʿu mina ٱl̊madīnaẗi."],[14,3,"فَيَخْرُجُ ٱلرَّبُّ وَيُحَارِبُ تِلْكَ ٱلْأُمَمَ كَمَا فِي يَوْمِ حَرْبِهِ، يَوْمَ ٱلْقِتَالِ.","fayakẖ̊ruju ٱlrãbũ wayuḥāribu til̊ka ٱl̊ạủmama kamā fī yaẘmi ḥar̊bihi, yaẘma ٱl̊qitāli."],[14,4,"وَتَقِفُ قَدَمَاهُ فِي ذَلِكَ ٱلْيَوْمِ عَلَى جَبَلِ ٱلزَّيْتُونِ ٱلَّذِي قُدَّامَ أُورُشَلِيمَ مِنَ ٱلشَّرْقِ، فَيَنْشَقُّ جَبَلُ ٱلزَّيْتُونِ مِنْ وَسَطِهِ نَحْوَ ٱلشَّرْقِ وَنَحْوَ ٱلْغَرْبِ وَادِيًا عَظِيمًا جِدًّا، وَيَنْتَقِلُ نِصْفُ ٱلْجَبَلِ نَحْوَ ٱلشِّمَالِ، وَنِصْفُهُ نَحْوَ ٱلْجَنُوبِ.","wataqifu qadamāhu fī dẖalika ٱl̊yaẘmi ʿalay̱ jabali ٱlzãẙtūni ٱlãdẖī qudãạma ạủwrusẖalīma mina ٱlsẖãr̊qi, fayan̊sẖaqũ jabalu ٱlzãẙtūni min̊ wasaṭihi naḥ̊wa ٱlsẖãr̊qi wanaḥ̊wa ٱl̊gẖar̊bi wādīaⁿạ ʿaẓīmaⁿạ jidaⁿ̃ạ, wayan̊taqilu niṣ̊fu ٱl̊jabali naḥ̊wa ٱlsẖĩmāli, waniṣ̊fuhu naḥ̊wa ٱl̊janūbi."],[14,5,"وَتَهْرُبُونَ فِي جِوَاءِ جِبَالِي، لِأَنَّ جِوَاءَ ٱلْجِبَالِ يَصِلُ إِلَى آصَلَ. وَتَهْرُبُونَ كَمَا هَرَبْتُمْ مِنَ ٱلزَّلْزَلَةِ فِي أَيَّامِ عُزِّيَّا مَلِكِ يَهُوذَا. وَيَأْتِي ٱلرَّبُّ إِلَهِي وَجَمِيعُ ٱلْقِدِّيسِينَ مَعَكَ.","watah̊rubūna fī jiwāʾi jibālī, liạảnã jiwāʾa ٱl̊jibāli yaṣilu ại̹lay̱ ậṣala. watah̊rubūna kamā harab̊tum̊ mina ٱlzãl̊zalaẗi fī ạảyãạmi ʿuzĩyãạ maliki yahūdẖā. wayā̊̉tī ٱlrãbũ ại̹lahī wajamīʿu ٱl̊qidĩysīna maʿaka."],[14,6,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنَّهُ لَا يَكُونُ نُورٌ. ٱلْدَّرَارِي تَنْقَبِضُ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnãhu lā yakūnu nūruⁿ. ٱl̊dãrārī tan̊qabiḍu."],[14,7,"وَيَكُونُ يَوْمٌ وَاحِدٌ مَعْرُوفٌ لِلرَّبِّ. لَا نَهَارَ وَلَا لَيْلَ، بَلْ يَحْدُثُ أَنَّهُ فِي وَقْتِ ٱلْمَسَاءِ يَكُونُ نُورٌ.","wayakūnu yaẘmuⁿ wāḥiduⁿ maʿ̊rūfuⁿ lilrãbĩ. lā nahāra walā laẙla, bal̊ yaḥ̊dutẖu ạảnãhu fī waq̊ti ٱl̊masāʾi yakūnu nūruⁿ."],[14,8,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنَّ مِيَاهًا حَيَّةً تَخْرُجُ مِنْ أُورُشَلِيمَ نِصْفُهَا إِلَى ٱلْبَحْرِ ٱلشَّرْقِيِّ، وَنِصْفُهَا إِلَى ٱلْبَحْرِ ٱلْغَرْبِيِّ. فِي ٱلصَّيْفِ وَفِي ٱلْخَرِيفِ تَكُونُ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnã mīāhaⁿạ ḥayãẗaⁿ takẖ̊ruju min̊ ạủwrusẖalīma niṣ̊fuhā ại̹lay̱ ٱl̊baḥ̊ri ٱlsẖãr̊qīĩ, waniṣ̊fuhā ại̹lay̱ ٱl̊baḥ̊ri ٱl̊gẖar̊bīĩ. fī ٱlṣãẙfi wafī ٱl̊kẖarīfi takūnu."],[14,9,"وَيَكُونُ ٱلرَّبُّ مَلِكًا عَلَى كُلِّ ٱلْأَرْضِ. فِي ذَلِكَ ٱلْيَوْمِ يَكُونُ ٱلرَّبُّ وَحْدَهُ وَٱسْمُهُ وَحْدَهُ.","wayakūnu ٱlrãbũ malikaⁿạ ʿalay̱ kulĩ ٱl̊ạảr̊ḍi. fī dẖalika ٱl̊yaẘmi yakūnu ٱlrãbũ waḥ̊dahu waٱs̊muhu waḥ̊dahu."],[14,10,"وَتَتَحَوَّلُ ٱلْأَرْضُ كُلُّهَا كَٱلْعَرَبَةِ مِنْ جَبْعَ إِلَى رِمُّونَ جَنُوبَ أُورُشَلِيمَ. وَتَرْتَفِعُ وَتُعْمَرُ فِي مَكَانِهَا، مِنْ بَابِ بَنْيَامِينَ إِلَى مَكَانِ ٱلْبَابِ ٱلْأَوَّلِ، إِلَى بَابِ ٱلزَّوَايَا، وَمِنْ بُرْجِ حَنَنْئِيلَ إِلَى مَعَاصِرِ ٱلْمَلِكِ.","watataḥawãlu ٱl̊ạảr̊ḍu kulũhā kaٱl̊ʿarabaẗi min̊ jab̊ʿa ại̹lay̱ rimũwna janūba ạủwrusẖalīma. watar̊tafiʿu watuʿ̊maru fī makānihā, min̊ bābi ban̊yāmīna ại̹lay̱ makāni ٱl̊bābi ٱl̊ạảwãli, ại̹lay̱ bābi ٱlzãwāyā, wamin̊ bur̊ji ḥanan̊yỉyla ại̹lay̱ maʿāṣiri ٱl̊maliki."],[14,11,"فَيَسْكُنُونَ فِيهَا وَلَا يَكُونُ بَعْدُ لَعْنٌ. فَتُعْمَرُ أُورُشَلِيمُ بِٱلْأَمْنِ.","fayas̊kunūna fīhā walā yakūnu baʿ̊du laʿ̊nuⁿ. fatuʿ̊maru ạủwrusẖalīmu biٱl̊ạảm̊ni."],[14,12,"وَهَذِهِ تَكُونُ ٱلضَّرْبَةُ ٱلَّتِي يَضْرِبُ بِهَا ٱلرَّبُّ كُلَّ ٱلشُّعُوبِ ٱلَّذِينَ تَجَنَّدُوا عَلَى أُورُشَلِيمَ. لَحْمُهُمْ يَذُوبُ وَهُمْ وَاقِفُونَ عَلَى أَقْدَامِهِمْ، وَعُيُونُهُمْ تَذُوبُ فِي أَوْقَابِهَا، وَلِسَانُهُمْ يَذُوبُ فِي فَمِهِمْ.","wahadẖihi takūnu ٱlḍãr̊baẗu ٱlãtī yaḍ̊ribu bihā ٱlrãbũ kulã ٱlsẖũʿūbi ٱlãdẖīna tajanãdūạ ʿalay̱ ạủwrusẖalīma. laḥ̊muhum̊ yadẖūbu wahum̊ wāqifūna ʿalay̱ ạảq̊dāmihim̊, waʿuyūnuhum̊ tadẖūbu fī ạảẘqābihā, walisānuhum̊ yadẖūbu fī famihim̊."],[14,13,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ أَنَّ ٱضْطِرَابًا عَظِيمًا مِنَ ٱلرَّبِّ يَحْدُثُ فِيهِمْ، فَيُمْسِكُ ٱلرَّجُلُ بِيَدِ قَرِيبِهِ وَتَعْلُو يَدُهُ عَلَى يَدِ قَرِيبِهِ.","wayakūnu fī dẖalika ٱl̊yaẘmi ạảnã ٱḍ̊ṭirābaⁿạ ʿaẓīmaⁿạ mina ٱlrãbĩ yaḥ̊dutẖu fīhim̊, fayum̊siku ٱlrãjulu bīadi qarībihi wataʿ̊lū yaduhu ʿalay̱ yadi qarībihi."],[14,14,"وَيَهُوذَا أَيْضًا تُحَارِبُ أُورُشَلِيمَ، وَتُجْمَعُ ثَرْوَةُ كُلِّ ٱلْأُمَمِ مِنْ حَوْلِهَا: ذَهَبٌ وَفِضَّةٌ وَمَلَابِسُ كَثِيرَةٌ جِدًّا.","wayahūdẖā ạảẙḍaⁿạ tuḥāribu ạủwrusẖalīma, watuj̊maʿu tẖar̊waẗu kulĩ ٱl̊ạủmami min̊ ḥaẘlihā: dẖahabuⁿ wafiḍãẗuⁿ wamalābisu katẖīraẗuⁿ jidaⁿ̃ạ."],[14,15,"وَكَذَا تَكُونُ ضَرْبَةُ ٱلْخَيْلِ وَٱلْبِغَالِ وَٱلْجِمَالِ وَٱلْحَمِيرِ وَكُلِّ ٱلْبَهَائِمِ ٱلَّتِي تَكُونُ فِي هَذِهِ ٱلْمَحَالِّ. كَهَذِهِ ٱلضَّرْبَةِ.","wakadẖā takūnu ḍar̊baẗu ٱl̊kẖaẙli waٱl̊bigẖāli waٱl̊jimāli waٱl̊ḥamīri wakulĩ ٱl̊bahāyỉmi ٱlãtī takūnu fī hadẖihi ٱl̊maḥālĩ. kahadẖihi ٱlḍãr̊baẗi."],[14,16,"وَيَكُونُ أَنَّ كُلَّ ٱلْبَاقِي مِنْ جَمِيعِ ٱلْأُمَمِ ٱلَّذِينَ جَاءُوا عَلَى أُورُشَلِيمَ، يَصْعَدُونَ مِنْ سَنَةٍ إِلَى سَنَةٍ لِيَسْجُدُوا لِلْمَلِكِ رَبِّ ٱلْجُنُودِ وَلِيُعَيِّدُوا عِيدَ ٱلْمَظَالِّ.","wayakūnu ạảnã kulã ٱl̊bāqī min̊ jamīʿi ٱl̊ạủmami ٱlãdẖīna jāʾūạ ʿalay̱ ạủwrusẖalīma, yaṣ̊ʿadūna min̊ sanaẗiⁿ ại̹lay̱ sanaẗiⁿ līas̊judūạ lil̊maliki rabĩ ٱl̊junūdi walīuʿayĩdūạ ʿīda ٱl̊maẓālĩ."],[14,17,"وَيَكُونُ أَنَّ كُلَّ مَنْ لَا يَصْعَدُ مِنْ قَبَائِلِ ٱلْأَرْضِ إِلَى أُورُشَلِيمَ لِيَسْجُدَ لِلْمَلِكِ رَبِّ ٱلْجُنُودِ، لَا يَكُونُ عَلَيْهِمْ مَطَرٌ.","wayakūnu ạảnã kulã man̊ lā yaṣ̊ʿadu min̊ qabāyỉli ٱl̊ạảr̊ḍi ại̹lay̱ ạủwrusẖalīma līas̊juda lil̊maliki rabĩ ٱl̊junūdi, lā yakūnu ʿalaẙhim̊ maṭaruⁿ."],[14,18,"وَإِنْ لَا تَصْعَدْ وَلَا تَأْتِ قَبِيلَةُ مِصْرَ وَلَا مَطَرٌ عَلَيْهَا، تَكُنْ عَلَيْهَا ٱلضَّرْبَةُ ٱلَّتِي يَضْرِبُ بِهَا ٱلرَّبُّ ٱلْأُمَمَ ٱلَّذِينَ لَا يَصْعَدُونَ لِيُعَيِّدُوا عِيدَ ٱلْمَظَالِّ.","wāi̹n̊ lā taṣ̊ʿad̊ walā tā̊̉ti qabīlaẗu miṣ̊ra walā maṭaruⁿ ʿalaẙhā, takun̊ ʿalaẙhā ٱlḍãr̊baẗu ٱlãtī yaḍ̊ribu bihā ٱlrãbũ ٱl̊ạủmama ٱlãdẖīna lā yaṣ̊ʿadūna līuʿayĩdūạ ʿīda ٱl̊maẓālĩ."],[14,19,"هَذَا يَكُونُ قِصَاصُ مِصْرَ وَقِصَاصُ كُلِّ ٱلْأُمَمِ ٱلَّذِينَ لَا يَصْعَدُونَ لِيُعَيِّدُوا عِيدَ ٱلْمَظَالِّ.","hadẖā yakūnu qiṣāṣu miṣ̊ra waqiṣāṣu kulĩ ٱl̊ạủmami ٱlãdẖīna lā yaṣ̊ʿadūna līuʿayĩdūạ ʿīda ٱl̊maẓālĩ."],[14,20,"فِي ذَلِكَ ٱلْيَوْمِ يَكُونُ عَلَى أَجْرَاسِ ٱلْخَيْلِ: «قُدْسٌ لِلرَّبِّ». وَٱلْقُدُورُ فِي بَيْتِ ٱلرَّبِّ تَكُونُ كَٱلْمَنَاضِحِ أَمَامَ ٱلْمَذْبَحِ.","fī dẖalika ٱl̊yaẘmi yakūnu ʿalay̱ ạảj̊rāsi ٱl̊kẖaẙli: «qud̊suⁿ lilrãbĩ». waٱl̊qudūru fī baẙti ٱlrãbĩ takūnu kaٱl̊manāḍiḥi ạảmāma ٱl̊madẖ̊baḥi."],[14,21,"وَكُلُّ قِدْرٍ فِي أُورُشَلِيمَ وَفِي يَهُوذَا تَكُونُ قُدْسًا لِرَبِّ ٱلْجُنُودِ، وَكُلُّ ٱلذَّابِحِينَ يَأْتُونَ وَيَأْخُذُونَ مِنْهَا وَيَطْبُخُونَ فِيهَا. وَفِي ذَلِكَ ٱلْيَوْمِ لَا يَكُونُ بَعْدُ كَنْعَانِيٌّ فِي بَيْتِ رَبِّ ٱلْجُنُودِ.","wakulũ qid̊riⁿ fī ạủwrusẖalīma wafī yahūdẖā takūnu qud̊saⁿạ lirabĩ ٱl̊junūdi, wakulũ ٱldẖãạbiḥīna yā̊̉tūna wayā̊̉kẖudẖūna min̊hā wayaṭ̊bukẖūna fīhā. wafī dẖalika ٱl̊yaẘmi lā yakūnu baʿ̊du kan̊ʿānīuⁿ̃ fī baẙti rabĩ ٱl̊junūdi."]],"bis-obbr":[[1,1,"Nao long namba tu yia we King* Darias i king blong Pesia, long namba eit manis* blong yia ya, Hae God i givim tok blong hem long Profet Sekaraea. Profet ya, papa blong hem Berekia, mo bubu blong hem Ido. Hem i talem long hem","Nao long namba tu yia we King* Darias i king blong Pesia, long namba eit manis* blong yia ya, Hae God i givim tok blong hem long Profet Sekaraea. Profet ya, papa blong hem Berekia, mo bubu blong hem Ido. Hem i talem long hem"],[1,2,"blong i go talemaot long ol man, we hem i talem se, “Mi mi Hae God, mi gat olgeta paoa. Mo mi talem long yufala, se bifo ol olfala blong yufala oli mekem mi mi kros tumas.","blong i go talemaot long ol man, we hem i talem se, “Mi mi Hae God, mi gat olgeta paoa. Mo mi talem long yufala, se bifo ol olfala blong yufala oli mekem mi mi kros tumas."],[1,3,"Be naoia, mi talem long yufala, se yufala i mas tanem tingting blong yufala from ol sin blong yufala, yufala i kambak long mi, nao mi bambae mi kambak, mi stap wetem yufala bakegen.","Be naoia, mi talem long yufala, se yufala i mas tanem tingting blong yufala from ol sin blong yufala, yufala i kambak long mi, nao mi bambae mi kambak, mi stap wetem yufala bakegen."],[1,4,"Bambae yufala i no tekem fasin ya blong ol bubu blong yufala bifo. Bifo, ol profet oli bin givim tok blong mi long olgeta, oli talem long olgeta, se oli mas tanem tingting blong olgeta from ol sin blong olgeta, mo oli mas kambak long mi bakegen. Be long taem ya, oli no harem tok blong mi, mo oli no obei long mi tu.","Bambae yufala i no tekem fasin ya blong ol bubu blong yufala bifo. Bifo, ol profet oli bin givim tok blong mi long olgeta, oli talem long olgeta, se oli mas tanem tingting blong olgeta from ol sin blong olgeta, mo oli mas kambak long mi bakegen. Be long taem ya, oli no harem tok blong mi, mo oli no obei long mi tu."],[1,5,"Be ol profet ya, mo ol bubu ya blong yufala bifo, naoia oli ded evriwan finis, i no moa gat wan i stap.","Be ol profet ya, mo ol bubu ya blong yufala bifo, naoia oli ded evriwan finis, i no moa gat wan i stap."],[1,6,"Ol profet ya oli man blong wok blong mi bifo, mo mi givim tok blong mi long olgeta, blong oli go talemaot long ol bubu ya blong yufala, mo blong oli blokem olgeta blong oli no moa mekem ol rabis fasin. Be olgeta ya oli no glad long ol profet ya, nao oli kasem panis from. Be biaen, oli tanem tingting blong olgeta from ol rabis fasin ya blong olgeta, nao oli talem se, ‘Hae God i gat olgeta paoa, mo i stret nomo we hem i givim panis ya long yumi from ol rabis fasin blong yumi. Ol samting ya we hem i mekem plan blong hem finis se bambae i mas kamtru, oli kamtru finis olsem we hem i talem.’ ”","Ol profet ya oli man blong wok blong mi bifo, mo mi givim tok blong mi long olgeta, blong oli go talemaot long ol bubu ya blong yufala, mo blong oli blokem olgeta blong oli no moa mekem ol rabis fasin. Be olgeta ya oli no glad long ol profet ya, nao oli kasem panis from. Be biaen, oli tanem tingting blong olgeta from ol rabis fasin ya blong olgeta, nao oli talem se, ‘Hae God i gat olgeta paoa, mo i stret nomo we hem i givim panis ya long yumi from ol rabis fasin blong yumi. Ol samting ya we hem i mekem plan blong hem finis se bambae i mas kamtru, oli kamtru finis olsem we hem i talem.’ ”"],[1,7,"Nao Profet Sekaraea i talem se, “Long namba tu yia we King Darias i king blong Pesia, long manis* ya Sebat,* we i namba leven manis, long namba twanti fo dei blong hem, long naet, mi luk wan vison* we Hae God i givim tok blong hem long mi.","Nao Profet Sekaraea i talem se, “Long namba tu yia we King Darias i king blong Pesia, long manis* ya Sebat,* we i namba leven manis, long namba twanti fo dei blong hem, long naet, mi luk wan vison* we Hae God i givim tok blong hem long mi."],[1,8,"Long vison ya, mi luk wan enjel blong hem i stap sidaon long wan hos we i red, mo hos ya i stap stanap long wan krik, long medel blong ol smosmol tri we nem blong hem metel.* Mo mi luk sam narafala hos tu oli stap stanap biaen long red hos ya. Wan i red, mo wan, kala blong hem i olsem asis faea, mo wan i waet.","Long vison ya, mi luk wan enjel blong hem i stap sidaon long wan hos we i red, mo hos ya i stap stanap long wan krik, long medel blong ol smosmol tri we nem blong hem metel.* Mo mi luk sam narafala hos tu oli stap stanap biaen long red hos ya. Wan i red, mo wan, kala blong hem i olsem asis faea, mo wan i waet."],[1,9,"Nao mi askem long enjel ya se, ‘?Masta,* ol hos ya oli minim wanem ya?’ “Mo hem i talem se, ‘Bambae mi soemaot long yu mining blong olgeta.","Nao mi askem long enjel ya se, ‘?Masta,* ol hos ya oli minim wanem ya?’ “Mo hem i talem se, ‘Bambae mi soemaot long yu mining blong olgeta."],[1,10,"Hae God i bin sanem ol hos ya blong oli go luklukgud long olgeta ples long wol.’","Hae God i bin sanem ol hos ya blong oli go luklukgud long olgeta ples long wol.’"],[1,11,"“Nao ol man we oli stap sidaon long ol hos ya oli talem long enjel ya se, ‘Mifala i go finis long olgeta ples long wol ya, mo mifala i luk we wol ya i stap kwaet, ol man blong hem oli no moa gat paoa.’","“Nao ol man we oli stap sidaon long ol hos ya oli talem long enjel ya se, ‘Mifala i go finis long olgeta ples long wol ya, mo mifala i luk we wol ya i stap kwaet, ol man blong hem oli no moa gat paoa.’"],[1,12,"“Nao enjel ya i talem se, ‘Hae God, yu yu gat olgeta paoa. Seventi yia nao we yu yu stap kros long taon ya Jerusalem,* mo long ol narafala taon long Juda.* ?Kros blong yu bambae i stap gogo kasem wetaem? ?Wetaem bambae yu soemaot we yu gat sore long olgeta?’","“Nao enjel ya i talem se, ‘Hae God, yu yu gat olgeta paoa. Seventi yia nao we yu yu stap kros long taon ya Jerusalem,* mo long ol narafala taon long Juda.* ?Kros blong yu bambae i stap gogo kasem wetaem? ?Wetaem bambae yu soemaot we yu gat sore long olgeta?’"],[1,13,"“Nao Hae God i givim wan gudfala ansa long enjel ya blong leftemap tingting blong hem.","“Nao Hae God i givim wan gudfala ansa long enjel ya blong leftemap tingting blong hem."],[1,14,"Nao enjel ya i talem long mi, blong mi talemaot we Hae God i talem se, ‘Jerusalem ya i taon blong mi, mo i tabu, mo mi mi laekem tumas. Oltaem, tingting blong mi i stap long hem.","Nao enjel ya i talem long mi, blong mi talemaot we Hae God i talem se, ‘Jerusalem ya i taon blong mi, mo i tabu, mo mi mi laekem tumas. Oltaem, tingting blong mi i stap long hem."],[1,15,"Mi mi kros tumas long ol narafala kantri ya we oli stap tingbaot olgeta nomo, mo oli praod tumas. Taem mi mi no moa kros long ol man blong mi, ol man blong ol kantri ya oli mekem i nogud moa long olgeta.","Mi mi kros tumas long ol narafala kantri ya we oli stap tingbaot olgeta nomo, mo oli praod tumas. Taem mi mi no moa kros long ol man blong mi, ol man blong ol kantri ya oli mekem i nogud moa long olgeta."],[1,16,"Nao from samting ya, mi kambak bakegen long Jerusalem, blong soemaot long ol man blong hem we mi mi gat sore long olgeta. Nao bambae oli wokemgud haos* ya blong mi bakegen, mo oli wokemgud taon ya tu.’","Nao from samting ya, mi kambak bakegen long Jerusalem, blong soemaot long ol man blong hem we mi mi gat sore long olgeta. Nao bambae oli wokemgud haos* ya blong mi bakegen, mo oli wokemgud taon ya tu.’"],[1,17,"“Mo enjel ya i talem long mi, blong mi go talemaot we Hae God i talem se, ‘Mi mi Hae God, mi gat olgeta paoa, mo ol taon blong mi bambae oli kam gud bakegen. Bambae mi givhan long Jerusalem bakegen, mo bambae mi talemaot se taon ya i blong mi.’ ”","“Mo enjel ya i talem long mi, blong mi go talemaot we Hae God i talem se, ‘Mi mi Hae God, mi gat olgeta paoa, mo ol taon blong mi bambae oli kam gud bakegen. Bambae mi givhan long Jerusalem bakegen, mo bambae mi talemaot se taon ya i blong mi.’ ”"],[1,18,"Mo bakegen, Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk fo hon blong buluk.","Mo bakegen, Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk fo hon blong buluk."],[1,19,"Nao mi askem long enjel ya we i stap toktok wetem mi se, ‘?Ol fo hon ya oli minim wanem?’ “Nao hem i talem se, ‘Hemia ol narafala kantri we oli gat paoa, nao oli ronemaot ol man Juda,* mo ol man Isrel,* mo ol man long taon ya Jerusalem.*’","Nao mi askem long enjel ya we i stap toktok wetem mi se, ‘?Ol fo hon ya oli minim wanem?’ “Nao hem i talem se, ‘Hemia ol narafala kantri we oli gat paoa, nao oli ronemaot ol man Juda,* mo ol man Isrel,* mo ol man long taon ya Jerusalem.*’"],[1,20,"“Mo bakegen, Hae God i soemaot long mi fo blaksmit* we oli stap holem fo bigbigfala hama.","“Mo bakegen, Hae God i soemaot long mi fo blaksmit* we oli stap holem fo bigbigfala hama."],[1,21,"Nao mi askem long enjel ya se, ‘?Ol man ya, oli kam blong mekem wanem?’ “Nao hem i talem se, ‘Oli kam blong mekem ol narafala kantri ya oli fraet, mo blong spolemgud olgeta, from we ol man blong ol kantri ya oli flatemgud ol man Juda, oli ronemaot olgeta oli go wanwan.’ ”","Nao mi askem long enjel ya se, ‘?Ol man ya, oli kam blong mekem wanem?’ “Nao hem i talem se, ‘Oli kam blong mekem ol narafala kantri ya oli fraet, mo blong spolemgud olgeta, from we ol man blong ol kantri ya oli flatemgud ol man Juda, oli ronemaot olgeta oli go wanwan.’ ”"],[2,1,"Mo bakegen Profet Sekaraea i talem se, “Nao mi luk wan vison* bakegen, mo long vison ya mi luk we wan man i stap holem teplaen.","Mo bakegen Profet Sekaraea i talem se, “Nao mi luk wan vison* bakegen, mo long vison ya mi luk we wan man i stap holem teplaen."],[2,2,"Nao mi askem long hem se, ‘?Yu stap go wea ya?’ “Mo hem i talem long mi se, ‘Mi wantem go makem saes blong taon ya Jerusalem.* Mi wantem faenemaot longfala blong hem, mo bigfala blong hem.’","Nao mi askem long hem se, ‘?Yu stap go wea ya?’ “Mo hem i talem long mi se, ‘Mi wantem go makem saes blong taon ya Jerusalem.* Mi wantem faenemaot longfala blong hem, mo bigfala blong hem.’"],[2,3,"“Nao mi luk wan narafala enjel i stap kam, mo enjel ya we i bin toktok wetem mi i go blong mitim hem.","“Nao mi luk wan narafala enjel i stap kam, mo enjel ya we i bin toktok wetem mi i go blong mitim hem."],[2,4,"Nao enjel ya we i jes kamtru, i talem long narawan ya se, ‘Yu resis, yu go talem long man ya we i stap holem teplaen ya se, “Jerusalem bambae i fulap long plante man mo plante anamol tu. Ples ya bambae i bigwan we i bigwan, bambae i no moa naf blong putum stonwol i goraon long hem.","Nao enjel ya we i jes kamtru, i talem long narawan ya se, ‘Yu resis, yu go talem long man ya we i stap holem teplaen ya se, “Jerusalem bambae i fulap long plante man mo plante anamol tu. Ples ya bambae i bigwan we i bigwan, bambae i no moa naf blong putum stonwol i goraon long hem."],[2,5,"Hae God i promes* finis, se hem nomo bambae i olsem faea we i laet i goraon long hem, olsem stonwol blong blokemgud taon ya. Hem bambae i stap wetem olgeta insaed long taon ya, mo bambae oli stap gud long medel blong bigfala laet ya blong hem.” ’ ”","Hae God i promes* finis, se hem nomo bambae i olsem faea we i laet i goraon long hem, olsem stonwol blong blokemgud taon ya. Hem bambae i stap wetem olgeta insaed long taon ya, mo bambae oli stap gud long medel blong bigfala laet ya blong hem.” ’ ”"],[2,6,"Mo bakegen, Profet Sekaraea i talemaot we Hae God i talem long ol man blong hem se, “Olgeta. Mi mi bin ronemaot yufala i go long evri ples. Be naoia, yufala we i stap wok slef* long Babilonia, yufala i aot long ples ya, yufala i kambak long Jerusalem* bakegen.","Mo bakegen, Profet Sekaraea i talemaot we Hae God i talem long ol man blong hem se, “Olgeta. Mi mi bin ronemaot yufala i go long evri ples. Be naoia, yufala we i stap wok slef* long Babilonia, yufala i aot long ples ya, yufala i kambak long Jerusalem* bakegen.",7],[2,8,"Taem wan man i kilim yufala, i olsem we man ya i kilim ae blong mi stret.” Mo profet i talem se, “Hae God i gat olgeta paoa, mo hem i sanem mi blong mi karem tok blong hem i go long ol kantri ya we oli bin tektekemaot olting blong yumi,","Taem wan man i kilim yufala, i olsem we man ya i kilim ae blong mi stret.” Mo profet i talem se, “Hae God i gat olgeta paoa, mo hem i sanem mi blong mi karem tok blong hem i go long ol kantri ya we oli bin tektekemaot olting blong yumi,"],[2,9,"mi talemaot long olgeta we hem i talem se, ‘Mi nomo bambae mi faet agens long yufala. Olgeta ya we bifo oli man blong wok blong yufala, bambae oli kam tektekemaot olting blong yufala.’ “Ol man Jerusalem. Taem ol samting ya oli kamtru, bambae yufala i save nao se Hae God i gat olgeta paoa, mo hem i bin sanem mi.","mi talemaot long olgeta we hem i talem se, ‘Mi nomo bambae mi faet agens long yufala. Olgeta ya we bifo oli man blong wok blong yufala, bambae oli kam tektekemaot olting blong yufala.’ “Ol man Jerusalem. Taem ol samting ya oli kamtru, bambae yufala i save nao se Hae God i gat olgeta paoa, mo hem i bin sanem mi."],[2,10,"“Hem i talem se, ‘Ol man Jerusalem. Yufala i mas glad, yufala i singsing. Bambae mi kam, mi mekem ples blong mi wetem yufala.’","“Hem i talem se, ‘Ol man Jerusalem. Yufala i mas glad, yufala i singsing. Bambae mi kam, mi mekem ples blong mi wetem yufala.’"],[2,11,"“Long taem ya, plante man blong ol naranarafala kantri bambae oli kam long Hae God, oli kam man blong hem. Hem bambae i kam stap wetem yumi, mo bambae yufala i save se hem nao i sanem mi, blong mi kam talemaot tok ya long yufala.","“Long taem ya, plante man blong ol naranarafala kantri bambae oli kam long Hae God, oli kam man blong hem. Hem bambae i kam stap wetem yumi, mo bambae yufala i save se hem nao i sanem mi, blong mi kam talemaot tok ya long yufala."],[2,12,"Distrik ya Juda* bambae i kam wan spesel ples blong Hae God long tabu kantri blong hem. Mo Jerusalem bambae i kam wan taon we hem i jusumaot se i blong hem, blong i stap long hem.","Distrik ya Juda* bambae i kam wan spesel ples blong Hae God long tabu kantri blong hem. Mo Jerusalem bambae i kam wan taon we hem i jusumaot se i blong hem, blong i stap long hem."],[2,13,"“Yumi evriwan i mas stap kwaet long fes blong Hae God, from we naoia, hem i aot long tabu ples blong hem, i stap kam blong stap wetem yumi.”","“Yumi evriwan i mas stap kwaet long fes blong Hae God, from we naoia, hem i aot long tabu ples blong hem, i stap kam blong stap wetem yumi.”"],[3,1,"Mo Profet Sekaraea i talem se, “Nao mi luk wan vison* bakegen we Hae God i soemaot long mi. Long vison ya, mi luk Hae Pris* ya Josua i stap stanap long fes blong enjel blong Hae God. Mo Setan tu i stap stanap long ples ya, long raet saed blong hae pris, i stap rere blong talemaot sam poen agens long hem.","Mo Profet Sekaraea i talem se, “Nao mi luk wan vison* bakegen we Hae God i soemaot long mi. Long vison ya, mi luk Hae Pris* ya Josua i stap stanap long fes blong enjel blong Hae God. Mo Setan tu i stap stanap long ples ya, long raet saed blong hae pris, i stap rere blong talemaot sam poen agens long hem."],[3,2,"Nao enjel blong Hae God i talem long Setan* se, ‘Setan. Hae God bambae i jajem yu se yu mas ded. Hem i laekem Jerusalem* ya tumas. Hem nao bambae i jajem yu se yu mas ded. Man ya hem i olsem wan stik we i stap insaed long faea, be wan man i tekemaot kwiktaem, nao i no bon.’","Nao enjel blong Hae God i talem long Setan* se, ‘Setan. Hae God bambae i jajem yu se yu mas ded. Hem i laekem Jerusalem* ya tumas. Hem nao bambae i jajem yu se yu mas ded. Man ya hem i olsem wan stik we i stap insaed long faea, be wan man i tekemaot kwiktaem, nao i no bon.’"],[3,3,"“Hae pris ya i stap stanap, mo klos blong hem i doti we i doti.","“Hae pris ya i stap stanap, mo klos blong hem i doti we i doti."],[3,4,"Nao enjel ya i talem long ol enjel we oli stap stanap long fes blong hem se, ‘Yufala i tekemaot rabis klos ya i gowe long hem.’ Nao hem i talem long hae pris se, ‘Mi mi tekemaot ol sin blong yu finis. Naoia bambae mi givim niufala klos long yu, blong yu yu werem.’","Nao enjel ya i talem long ol enjel we oli stap stanap long fes blong hem se, ‘Yufala i tekemaot rabis klos ya i gowe long hem.’ Nao hem i talem long hae pris se, ‘Mi mi tekemaot ol sin blong yu finis. Naoia bambae mi givim niufala klos long yu, blong yu yu werem.’"],[3,5,"“Mo hem i talem se, ‘Yufala i tekem wan niufala kaliko, yufala i putum i goraon long hed blong hem.’ Mo olgeta ya oli mekem olsem, mo oli tekem ol niufala klos oli putum long hae pris, mo enjel ya blong Hae God i stap stanap wetem olgeta.","“Mo hem i talem se, ‘Yufala i tekem wan niufala kaliko, yufala i putum i goraon long hed blong hem.’ Mo olgeta ya oli mekem olsem, mo oli tekem ol niufala klos oli putum long hae pris, mo enjel ya blong Hae God i stap stanap wetem olgeta."],[3,6,"“Nao enjel ya i talemaot long hae pris","“Nao enjel ya i talemaot long hae pris"],[3,7,"we Hae God we i gat olgeta paoa i talem se, ‘Sipos yu obei long ol Loa* blong mi, mo yu mekem ol samting we mi mi bin givim long yu blong mekem, bambae mi save letem long yu blong yu lukaot long haos* blong mi, mo long olgeta yad blong hem. Mo yu bambae yu gat raet blong kam stanap long fes blong mi, nao bambae mi stap ansa long ol prea blong yu, olsem we mi stap harem ol prea blong ol enjel ya we oli stap oltaem long fes blong mi.","we Hae God we i gat olgeta paoa i talem se, ‘Sipos yu obei long ol Loa* blong mi, mo yu mekem ol samting we mi mi bin givim long yu blong mekem, bambae mi save letem long yu blong yu lukaot long haos* blong mi, mo long olgeta yad blong hem. Mo yu bambae yu gat raet blong kam stanap long fes blong mi, nao bambae mi stap ansa long ol prea blong yu, olsem we mi stap harem ol prea blong ol enjel ya we oli stap oltaem long fes blong mi."],[3,8,"Josua, yu yu hae pris, mo yu mas lesin gud long mi. Mo yufala ol pris we yufala i stap wok aninit long hem, yufala tu i mas lesin gud long mi. Yufala evriwan ya i olsem pija blong ol gudgudfala samting we bambae oli kamtru. Bambae mi mi soemaot man ya blong wok blong mi long yufala, we nem blong hem, “Han Blong Tri”.","Josua, yu yu hae pris, mo yu mas lesin gud long mi. Mo yufala ol pris we yufala i stap wok aninit long hem, yufala tu i mas lesin gud long mi. Yufala evriwan ya i olsem pija blong ol gudgudfala samting we bambae oli kamtru. Bambae mi mi soemaot man ya blong wok blong mi long yufala, we nem blong hem, “Han Blong Tri”."],[3,9,"Mi mi putum wan ston finis i stap daon long fes blong hae pris. Ston ya i gat seven saed blong hem, mo bambae mi raetem wan tok long hem, nao long wan dei nomo, mi bambae mi tekemaot olgeta sin blong ol man blong kantri ya.","Mi mi putum wan ston finis i stap daon long fes blong hae pris. Ston ya i gat seven saed blong hem, mo bambae mi raetem wan tok long hem, nao long wan dei nomo, mi bambae mi tekemaot olgeta sin blong ol man blong kantri ya."],[3,10,"Taem dei ya i kamtru, bambae yufala wanwan i save singaot ol fren blong yufala oli kam sidaon wetem yufala aninit long ol figtri* blong yufala, mo ol grep* blong yufala, we yufala evriwan i glad, yufala i stap gud, yufala i gat pis.’ ”","Taem dei ya i kamtru, bambae yufala wanwan i save singaot ol fren blong yufala oli kam sidaon wetem yufala aninit long ol figtri* blong yufala, mo ol grep* blong yufala, we yufala evriwan i glad, yufala i stap gud, yufala i gat pis.’ ”"],[4,1,"Nao Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk enjel ya bakegen we i bin toktok wetem mi. Hem i kam holem mi, i seksekem mi, olsem we i wantem wekemap mi.","Nao Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk enjel ya bakegen we i bin toktok wetem mi. Hem i kam holem mi, i seksekem mi, olsem we i wantem wekemap mi."],[4,2,"Nao hem i askem long mi se, ‘?Wanem samting ya we yu yu luk?’ “Mo mi talem long hem se, ‘Mi mi luk wan ples blong putum laet ya. Oli wokem long gol, mo antap long hem i gat wan ples blong putum oel, mo i gat seven laet. Olgeta wanwan i gat seven ples blong putum wik.","Nao hem i askem long mi se, ‘?Wanem samting ya we yu yu luk?’ “Mo mi talem long hem se, ‘Mi mi luk wan ples blong putum laet ya. Oli wokem long gol, mo antap long hem i gat wan ples blong putum oel, mo i gat seven laet. Olgeta wanwan i gat seven ples blong putum wik."],[4,3,"Mo i gat tu olif,* wan i stanap long raetsaed blong ples ya blong putum laet, mo narawan long lefsaed.’","Mo i gat tu olif,* wan i stanap long raetsaed blong ples ya blong putum laet, mo narawan long lefsaed.’"],[4,4,"Nao mi askem long enjel ya se, ‘Masta,* ol samting ya oli saen blong wanem ya?’","Nao mi askem long enjel ya se, ‘Masta,* ol samting ya oli saen blong wanem ya?’"],[4,5,"“Nao hem i talem long mi se, ‘?Olsem wanem? ?Yu yu no save?’ “Mo mi talem long hem se, ‘No, masta, mi no save ya.’","“Nao hem i talem long mi se, ‘?Olsem wanem? ?Yu yu no save?’ “Mo mi talem long hem se, ‘No, masta, mi no save ya.’"],[4,10,"b “Nao enjel ya i talem long mi se, ‘Seven ples ya blong putum laet, i olsem seven ae blong Hae God, we i save lukluk olgeta ples long wol ya wantaem.’\na Naoia tingting blong olgeta i foldaon from we wok ya i gohed sloslo nomo. Be bambae oli luk we Serubabel nao bambae i putum las ston blong finisimgud haos ya, mo taem oli luk olsem, bambae oli glad tumas from.’ ”","b “Nao enjel ya i talem long mi se, ‘Seven ples ya blong putum laet, i olsem seven ae blong Hae God, we i save lukluk olgeta ples long wol ya wantaem.’\na Naoia tingting blong olgeta i foldaon from we wok ya i gohed sloslo nomo. Be bambae oli luk we Serubabel nao bambae i putum las ston blong finisimgud haos ya, mo taem oli luk olsem, bambae oli glad tumas from.’ ”",null,2],[4,11,"“Nao mi askem long hem se, ‘?Be wanem mining blong tufala olif ya we tufala i stap stanap long tufala saed blong hem.","“Nao mi askem long hem se, ‘?Be wanem mining blong tufala olif ya we tufala i stap stanap long tufala saed blong hem."],[4,12,"Mo i gat tu paep we oli wokem tufala long gol we olifoel* i stap ron i kamaot long tufala. ?Wanem mining blong tufala han blong olif ya we i stap long saed blong tufala paep ya?’","Mo i gat tu paep we oli wokem tufala long gol we olifoel* i stap ron i kamaot long tufala. ?Wanem mining blong tufala han blong olif ya we i stap long saed blong tufala paep ya?’"],[4,13,"“Nao hem i talem long mi se, ‘?Olsem wanem? ?Yu yu no save?’ “Mo mi talem long hem se, ‘Masta, mi no save.’","“Nao hem i talem long mi se, ‘?Olsem wanem? ?Yu yu no save?’ “Mo mi talem long hem se, ‘Masta, mi no save.’"],[4,14,"“Nao hem i talem se, ‘God i Masta blong olgeta ples long wol ya, mo tufala samting ya, hemia tufala man we hem i jusumaot tufala, i kafsaedem oel i go long hed blong tufala, blong tufala i stap mekem wok blong hem.’ ”","“Nao hem i talem se, ‘God i Masta blong olgeta ples long wol ya, mo tufala samting ya, hemia tufala man we hem i jusumaot tufala, i kafsaedem oel i go long hed blong tufala, blong tufala i stap mekem wok blong hem.’ ”"],[4,6,"Mo Profet Sekaraea i talem se, “Nao enjel ya i talem long mi blong mi go luk Serubabel, mi talemaot we Hae God i talem long hem se, ‘Serubabel. Mi mi Hae God, mi gat olgeta paoa, mo mi talem long yu, se bambae yu yu win, be i no long paoa blong ol soldia blong yu, mo i no long paoa blong yu. Bambae yu win long paoa blong Spirit blong mi nomo.","Mo Profet Sekaraea i talem se, “Nao enjel ya i talem long mi blong mi go luk Serubabel, mi talemaot we Hae God i talem long hem se, ‘Serubabel. Mi mi Hae God, mi gat olgeta paoa, mo mi talem long yu, se bambae yu yu win, be i no long paoa blong ol soldia blong yu, mo i no long paoa blong yu. Bambae yu win long paoa blong Spirit blong mi nomo."],[4,7,"I nating we tumas samting i stap blokem yu olsem bigfala hil, be samting ya bambae i lus nomo long fes blong yu. Yu bambae yu wokem haos* blong mi bakegen, mo taem yu putum las ston blong hem, olgeta man bambae oli save singaot bigwan wantaem se, “!I gud tumas! !I gud tumas!” ’","I nating we tumas samting i stap blokem yu olsem bigfala hil, be samting ya bambae i lus nomo long fes blong yu. Yu bambae yu wokem haos* blong mi bakegen, mo taem yu putum las ston blong hem, olgeta man bambae oli save singaot bigwan wantaem se, “!I gud tumas! !I gud tumas!” ’"],[4,8,"“Nao Hae God i talem wan tok blong hem bakegen long mi se,","“Nao Hae God i talem wan tok blong hem bakegen long mi se,"],[4,9,"‘Serubabel i statem fandesen blong haos ya, mo hem nao bambae i wok long hem gogo i finisim. Taem hem i mekem olsem, ol man blong mi bambae oli save se mi nomo mi sanem yu yu go talemaot ol tok ya long olgeta.","‘Serubabel i statem fandesen blong haos ya, mo hem nao bambae i wok long hem gogo i finisim. Taem hem i mekem olsem, ol man blong mi bambae oli save se mi nomo mi sanem yu yu go talemaot ol tok ya long olgeta."],[5,1,"Mo Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk wan buk* i stap flae i kam.","Mo Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk wan buk* i stap flae i kam."],[5,2,"Nao enjel ya we i bin toktok wetem mi, i askem long mi se, ‘?Yu stap lukluk wanem ya?’ “Mo mi talem long hem se, ‘Mi mi luk wan buk ya, i stap flae i kam. Longfala blong hem i kasem naen meta, mo bigfala blong hem i kasem fo meta.’","Nao enjel ya we i bin toktok wetem mi, i askem long mi se, ‘?Yu stap lukluk wanem ya?’ “Mo mi talem long hem se, ‘Mi mi luk wan buk ya, i stap flae i kam. Longfala blong hem i kasem naen meta, mo bigfala blong hem i kasem fo meta.’"],[5,3,"“Nao hem i talem long mi se, ‘Buk ya i gat ol toktok i stap long hem, we i blong singaot* trabol i kam long olgeta ples long kantri ya. Long wan saed blong hem, i gat ol tok we i talem se God bambae i ronemaot ol man blong stil oli gowe long ples ya. Mo long narasaed i gat ol tok we i talemaot se hem i agensem olgeta man we oli mekem strong promes blong talem trutok, be oli giaman nomo, nao from samting ya, hem bambae i ronemaot olgeta ya tu oli gowe long ples ya.","“Nao hem i talem long mi se, ‘Buk ya i gat ol toktok i stap long hem, we i blong singaot* trabol i kam long olgeta ples long kantri ya. Long wan saed blong hem, i gat ol tok we i talem se God bambae i ronemaot ol man blong stil oli gowe long ples ya. Mo long narasaed i gat ol tok we i talemaot se hem i agensem olgeta man we oli mekem strong promes blong talem trutok, be oli giaman nomo, nao from samting ya, hem bambae i ronemaot olgeta ya tu oli gowe long ples ya."],[5,4,"Hae God i gat olgeta paoa, mo hem i talem se hem bambae i letem trabol i kam kasem olgeta man ya blong stil, mo i kasem olgeta we oli stap talem strong promes long nem blong hem, be oli stap giaman nomo. Trabol ya bambae i spolem olgeta haos blong olgeta, gogo ol haos ya oli kam nogud olgeta.’ ”","Hae God i gat olgeta paoa, mo hem i talem se hem bambae i letem trabol i kam kasem olgeta man ya blong stil, mo i kasem olgeta we oli stap talem strong promes long nem blong hem, be oli stap giaman nomo. Trabol ya bambae i spolem olgeta haos blong olgeta, gogo ol haos ya oli kam nogud olgeta.’ ”"],[5,5,"Nao Profet Sekaraea i talem se, “Mi mi luk wan vison* bakegen, mo long vison ya mi luk we enjel ya i kamtru long mi bakegen, i talem long mi se, ‘!Ei! !Yu luk! I gat wan samting bakegen ya i stap kam!’","Nao Profet Sekaraea i talem se, “Mi mi luk wan vison* bakegen, mo long vison ya mi luk we enjel ya i kamtru long mi bakegen, i talem long mi se, ‘!Ei! !Yu luk! I gat wan samting bakegen ya i stap kam!’"],[5,6,"“Mo mi askem long hem se, ‘?Wanem samting ya?’ “Hem i talem long mi se, ‘Wan bigfala basket ya i stap kam. Hemia i saen blong ol sin blong olgeta ples long kantri ya.’ ”","“Mo mi askem long hem se, ‘?Wanem samting ya?’ “Hem i talem long mi se, ‘Wan bigfala basket ya i stap kam. Hemia i saen blong ol sin blong olgeta ples long kantri ya.’ ”"],[5,7,"“Nao mi luk we basket ya i gat lid blong hem we oli wokem long led. Mo taem mi stap lukluk yet, mi luk we lid blong hem i open. Nao mi luk we i gat wan woman i stap sidaon insaed.","“Nao mi luk we basket ya i gat lid blong hem we oli wokem long led. Mo taem mi stap lukluk yet, mi luk we lid blong hem i open. Nao mi luk we i gat wan woman i stap sidaon insaed."],[5,8,"Mo enjel ya i talem se, ‘Woman ya i saen blong olgeta rabis fasin.’ Nao hem i pusumdaon woman ya i go insaed long basket ya, nao i satem bakegen.","Mo enjel ya i talem se, ‘Woman ya i saen blong olgeta rabis fasin.’ Nao hem i pusumdaon woman ya i go insaed long basket ya, nao i satem bakegen."],[5,9,"Taem mi stap lukluk i go antap, mi luk tu narafala woman we tufala i gat wing blong tufala. Wing blong tufala i strong we i strong, olsem wing blong pijin ya stok.* Tufala i flae i kam, nao tufala i karem basket ya, tufala i flae i go wetem.","Taem mi stap lukluk i go antap, mi luk tu narafala woman we tufala i gat wing blong tufala. Wing blong tufala i strong we i strong, olsem wing blong pijin ya stok.* Tufala i flae i kam, nao tufala i karem basket ya, tufala i flae i go wetem."],[5,10,"“Nao mi askem long enjel ya se, ‘?Tufala i karem basket ya i go wea ya?’","“Nao mi askem long enjel ya se, ‘?Tufala i karem basket ya i go wea ya?’"],[5,11,"“Mo hem i talem se, ‘Tufala i karem i go long Babilonia Long ples ya bambae oli wokem wan haos blong hem, mo taem haos ya i finis, bambae oli putum basket ya insaed, blong ol man ples ya oli kam bodaon long hem, blong mekem wosip long hem.’ ”","“Mo hem i talem se, ‘Tufala i karem i go long Babilonia Long ples ya bambae oli wokem wan haos blong hem, mo taem haos ya i finis, bambae oli putum basket ya insaed, blong ol man ples ya oli kam bodaon long hem, blong mekem wosip long hem.’ ”"],[6,1,"Mo Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk fo kat i kamaot long medel blong tu hil, be tufala hil ya, bras nomo.","Mo Profet Sekaraea i talem se, “Nao mi mi luk wan vison* bakegen, mo long vison ya mi luk fo kat i kamaot long medel blong tu hil, be tufala hil ya, bras nomo."],[6,2,"Mi luk we fas kat, tu red hos i pulum, mo seken kat, tu blak hos i pulum.","Mi luk we fas kat, tu red hos i pulum, mo seken kat, tu blak hos i pulum."],[6,3,"Mo namba tri kat, tu waet hos i pulum, mo las kat, tu hos i pulum we kala blong tufala i olsem asis faea.","Mo namba tri kat, tu waet hos i pulum, mo las kat, tu hos i pulum we kala blong tufala i olsem asis faea."],[6,4,"Nao mi askem long enjel ya we i stap toktok wetem mi se, ‘?Masta,* ol kat ya oli minim wanem ya?’","Nao mi askem long enjel ya we i stap toktok wetem mi se, ‘?Masta,* ol kat ya oli minim wanem ya?’"],[6,5,"“Mo hem i talem se, ‘Mining blong hem, hemia ol fo win we oli stap mekem wok blong Hae God we i Masta blong olgeta ples long wol ya. Mo olgeta oli jes aot long fes blong hem oli kam.","“Mo hem i talem se, ‘Mining blong hem, hemia ol fo win we oli stap mekem wok blong Hae God we i Masta blong olgeta ples long wol ya. Mo olgeta oli jes aot long fes blong hem oli kam."],[6,6,"Kat ya we tufala blak hos i pulum, bambae i go long Babilonia long not, mo hemia we tufala waet hos i pulum, bambae i go long saed i go long wes. Mo hemia we tufala hos blong hem, we kala blong tufala i olsem asis faea, bambae i go long kantri ya long saot.’","Kat ya we tufala blak hos i pulum, bambae i go long Babilonia long not, mo hemia we tufala waet hos i pulum, bambae i go long saed i go long wes. Mo hemia we tufala hos blong hem, we kala blong tufala i olsem asis faea, bambae i go long kantri ya long saot.’"],[6,7,"Taem tufala hos ya i pulum kat ya i kam, mi luk olsem we tufala i no wantem wet, tufala i wantem hareap blong go luklukgud olgeta ples long wol ya. Nao enjel ya i talem long tufala se, ‘Naoia yutufala i save go luklukgud olgeta ples long wol ya.’ Nao tufala i girap, tufala i go.","Taem tufala hos ya i pulum kat ya i kam, mi luk olsem we tufala i no wantem wet, tufala i wantem hareap blong go luklukgud olgeta ples long wol ya. Nao enjel ya i talem long tufala se, ‘Naoia yutufala i save go luklukgud olgeta ples long wol ya.’ Nao tufala i girap, tufala i go."],[6,8,"Nao enjel ya i singaot i kam long mi, i talem se, ‘Naoia, from we tufala blak hos ya i go long Babilonia long not, kros blong Hae God i godaon.’ ”","Nao enjel ya i singaot i kam long mi, i talem se, ‘Naoia, from we tufala blak hos ya i go long Babilonia long not, kros blong Hae God i godaon.’ ”"],[6,9,"Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,","Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,"],[6,10,"“Yu tekem ol presen ya we Heldae mo Tobia mo Jedaea trifala i givim long yu, yu go kwiktaem long haos blong Josaea we papa blong hem Sefanaea. Trifala ya i jes kambak long Babilonia, ples ya we yufala i bin stap wok slef* long hem.","“Yu tekem ol presen ya we Heldae mo Tobia mo Jedaea trifala i givim long yu, yu go kwiktaem long haos blong Josaea we papa blong hem Sefanaea. Trifala ya i jes kambak long Babilonia, ples ya we yufala i bin stap wok slef* long hem."],[6,11,"Nao yu tekem ol silva mo gol we trifala ya i bin givim long yu, mo yu wokem wan spesel hat long hem. Taem yu wokem finis, yu go putum long hed blong Hae Pris* ya Josua, we papa blong hem Jehosadak.","Nao yu tekem ol silva mo gol we trifala ya i bin givim long yu, mo yu wokem wan spesel hat long hem. Taem yu wokem finis, yu go putum long hed blong Hae Pris* ya Josua, we papa blong hem Jehosadak."],[6,12,"Mo yu talem long hem we mi Hae God mi gat olgeta paoa, mo mi talem se, ‘Man ya we nem blong hem “Han blong Tri”, hem bambae i kam bigwan, i kam strong. Man ya nao bambae i stanemap haos blong mi bakegen, mo ol man bambae oli ona gud long hem olsem we hem i king. Mo taem hem i stap rulum ol man blong hem, oltaem wan pris bambae i stap stanap long saed blong hem. Mo oltaem, bambae tufala i stap wok wanples, tufala i gat pis, mo tufala i gat wan tingting nomo.","Mo yu talem long hem we mi Hae God mi gat olgeta paoa, mo mi talem se, ‘Man ya we nem blong hem “Han blong Tri”, hem bambae i kam bigwan, i kam strong. Man ya nao bambae i stanemap haos blong mi bakegen, mo ol man bambae oli ona gud long hem olsem we hem i king. Mo taem hem i stap rulum ol man blong hem, oltaem wan pris bambae i stap stanap long saed blong hem. Mo oltaem, bambae tufala i stap wok wanples, tufala i gat pis, mo tufala i gat wan tingting nomo.",13],[6,14,"Flas hat ya bambae i stap oltaem long haos* blong Hae God, mo bambae i wan memori blong ona long Heldae, mo Tobia, mo Jedaea mo Josaea.’ ”","Flas hat ya bambae i stap oltaem long haos* blong Hae God, mo bambae i wan memori blong ona long Heldae, mo Tobia, mo Jedaea mo Josaea.’ ”"],[6,15,"Nao Profet Sekaraea i talem se, “Haos ya blong Hae God, ol man we oli stap longwe, bambae oli kam givhan blong stanemap bakegen. Mo taem haos ya i finis, bambae yufala i save se Hae God we i gat olgeta paoa, hem nao i sanem mi mi kam blong givim tok blong hem long yufala. Hem i God blong yumi, mo sipos yufala i obei long ol tok blong hem, olgeta samting ya bambae i kamtru olsem.”","Nao Profet Sekaraea i talem se, “Haos ya blong Hae God, ol man we oli stap longwe, bambae oli kam givhan blong stanemap bakegen. Mo taem haos ya i finis, bambae yufala i save se Hae God we i gat olgeta paoa, hem nao i sanem mi mi kam blong givim tok blong hem long yufala. Hem i God blong yumi, mo sipos yufala i obei long ol tok blong hem, olgeta samting ya bambae i kamtru olsem.”"],[7,1,"Nao Profet Sekaraea i talem se, “Long namba fo yia we King Darias i king long Pesia, long manis ya Kislef* we i namba naen manis,* long namba fo dei blong hem, Hae God i givim tok blong hem long mi blong mi go talemaot.","Nao Profet Sekaraea i talem se, “Long namba fo yia we King Darias i king long Pesia, long manis ya Kislef* we i namba naen manis,* long namba fo dei blong hem, Hae God i givim tok blong hem long mi blong mi go talemaot."],[7,2,"“Hae God i gat olgeta paoa, mo long taem ya, ol man Betel oli bin sanem Sareja mo Regemelek mo ol man blong tufala i go long haos* blong hem, blong oli go prea long hem blong i blesem olgeta.","“Hae God i gat olgeta paoa, mo long taem ya, ol man Betel oli bin sanem Sareja mo Regemelek mo ol man blong tufala i go long haos* blong hem, blong oli go prea long hem blong i blesem olgeta."],[7,3,"Mo oli go blong askem kwestin long ol pris* mo long ol profet long ples ya. Oli talem se, ‘?Fasin ya we yumi stap holem i kam longtaem finis, we long namba faef manis, yumi stap livim kakae, yumi stap krae from haos ya, bambae yumi stap holem fasin ya yet, no yumi lego?’","Mo oli go blong askem kwestin long ol pris* mo long ol profet long ples ya. Oli talem se, ‘?Fasin ya we yumi stap holem i kam longtaem finis, we long namba faef manis, yumi stap livim kakae, yumi stap krae from haos ya, bambae yumi stap holem fasin ya yet, no yumi lego?’"],[7,4,"“Nao Hae God i givim wan tok long mi from bisnes ya.","“Nao Hae God i givim wan tok long mi from bisnes ya."],[7,5,"Hem i talem long mi blong mi go talemaot long ol pris, mo long ol man blong kantri ya se, ‘Long seventi yia we oli pas finis, oltaem long namba faef manis, mo bakegen long namba seven manis blong ol yia ya, yufala i stap livim kakae blong yufala, mo yufala i stap krae from haos blong mi, be long ol samting ya, yufala i no ona long mi nating.","Hem i talem long mi blong mi go talemaot long ol pris, mo long ol man blong kantri ya se, ‘Long seventi yia we oli pas finis, oltaem long namba faef manis, mo bakegen long namba seven manis blong ol yia ya, yufala i stap livim kakae blong yufala, mo yufala i stap krae from haos blong mi, be long ol samting ya, yufala i no ona long mi nating."],[7,6,"Mo taem yufala i stap kakae mo yufala i stap dring, be yufala i mekem, blong yufala nomo i harem gud.’ ”","Mo taem yufala i stap kakae mo yufala i stap dring, be yufala i mekem, blong yufala nomo i harem gud.’ ”"],[7,7,"Mo Profet Sekaraea i talem se, “Hemia sem tok ya we Hae God i bin talemaot long ol profet bifo, taem Jerusalem* ya i stap gud, i fulap long ol gudgudfala samting, mo i gat plante man oli stap insaed long taon ya, mo long ol narafala taon we oli stap raonabaot long hem. Mo long taem ya, i gat plante man tu oli stap long saot, mo long botom blong ol hil long saed i go long wes.”","Mo Profet Sekaraea i talem se, “Hemia sem tok ya we Hae God i bin talemaot long ol profet bifo, taem Jerusalem* ya i stap gud, i fulap long ol gudgudfala samting, mo i gat plante man oli stap insaed long taon ya, mo long ol narafala taon we oli stap raonabaot long hem. Mo long taem ya, i gat plante man tu oli stap long saot, mo long botom blong ol hil long saed i go long wes.”"],[7,8,"Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,","Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,"],[7,9,"“Mi mi Hae God, mo mi gat olgeta paoa. Bifo, mi mi bin givim tok blong mi long ol man blong mi, mi talem se, ‘Ol laen* blong Isrel.* Yufala i mas soemaot stret fasin blong jajem man, mo yufala i mas kaen, yufala i mas gat sore long ol narafala man.","“Mi mi Hae God, mo mi gat olgeta paoa. Bifo, mi mi bin givim tok blong mi long ol man blong mi, mi talem se, ‘Ol laen* blong Isrel.* Yufala i mas soemaot stret fasin blong jajem man, mo yufala i mas kaen, yufala i mas gat sore long ol narafala man."],[7,10,"Yufala i no mas mekem i strong tumas long ol wido, mo long ol pikinini we papa blong olgeta i ded, mo long ol strenja we oli stap wetem yufala. Yufala i mas givhan long ol puaman, mo yufala i no mas mekem plan blong spolem narafala man.’","Yufala i no mas mekem i strong tumas long ol wido, mo long ol pikinini we papa blong olgeta i ded, mo long ol strenja we oli stap wetem yufala. Yufala i mas givhan long ol puaman, mo yufala i no mas mekem plan blong spolem narafala man.’"],[7,11,"“Be ol man blong mi oli mekem stronghed, oli no laekem nating blong lesin long tok blong mi. Oli blokemgud sora blong olgeta,","“Be ol man blong mi oli mekem stronghed, oli no laekem nating blong lesin long tok blong mi. Oli blokemgud sora blong olgeta,"],[7,12,"oli mekem tingting blong olgeta i kam strong olsem ston. Nao mi mi kros tumas long olgeta, from we oli no wantem nating blong obei long ol tok ya we Spirit blong mi i bin talemaot long ol profet bifo.","oli mekem tingting blong olgeta i kam strong olsem ston. Nao mi mi kros tumas long olgeta, from we oli no wantem nating blong obei long ol tok ya we Spirit blong mi i bin talemaot long ol profet bifo."],[7,13,"Taem we oli prea long mi, mi mi no ansa long olgeta, from we taem mi mi tok, oli no obei nating long tok ya blong mi.","Taem we oli prea long mi, mi mi no ansa long olgeta, from we taem mi mi tok, oli no obei nating long tok ya blong mi."],[7,14,"Nao from we oli mekem olsem, mi mi kam olsem hariken, mi ronemaot olgeta oli go stap long ol narafala kantri. Nao gudfala graon ya we oli stap long hem fastaem, hem i stap nating, i no moa gat man i stap long hem.”","Nao from we oli mekem olsem, mi mi kam olsem hariken, mi ronemaot olgeta oli go stap long ol narafala kantri. Nao gudfala graon ya we oli stap long hem fastaem, hem i stap nating, i no moa gat man i stap long hem.”"],[8,1,"Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,","Nao Profet Sekaraea i talemaot we Hae God i talem long hem se,"],[8,2,"“Mi mi Hae God, mi gat olgeta paoa. I stat bifo olgeta kam kasem tede, oltaem, mi wantem tumas blong givhan long Jerusalem,* from we mi mi lavem ol man blong hem. From samting ya, mi mi kros tumas long ol enemi blong hem we oli stap spolem hem.","“Mi mi Hae God, mi gat olgeta paoa. I stat bifo olgeta kam kasem tede, oltaem, mi wantem tumas blong givhan long Jerusalem,* from we mi mi lavem ol man blong hem. From samting ya, mi mi kros tumas long ol enemi blong hem we oli stap spolem hem."],[8,3,"Mi bambae mi gobak long Jerusalem, tabu taon ya blong mi, nao mi stap long ples ya. Mo ol man bambae oli save talem se, ‘Taon ya, hem i wan taon we ol man blong hem, tingting blong olgeta i stap strong oltaem long Hae God.’ Mo bambae oli save talem tu se, ‘Hae God i gat olgeta paoa, mo hil ya blong hem i wan tabu hil.*’","Mi bambae mi gobak long Jerusalem, tabu taon ya blong mi, nao mi stap long ples ya. Mo ol man bambae oli save talem se, ‘Taon ya, hem i wan taon we ol man blong hem, tingting blong olgeta i stap strong oltaem long Hae God.’ Mo bambae oli save talem tu se, ‘Hae God i gat olgeta paoa, mo hil ya blong hem i wan tabu hil.*’"],[8,4,"Nao ol man mo ol woman we oli stap yusum wokingstik, from we oli olfala tumas, bambae oli save kam sidaon bakegen long ol open ples blong taon ya, we ol man oli stap mit long hem.","Nao ol man mo ol woman we oli stap yusum wokingstik, from we oli olfala tumas, bambae oli save kam sidaon bakegen long ol open ples blong taon ya, we ol man oli stap mit long hem."],[8,5,"Mo taon ya bambae i fulap bakegen long ol pikinini we bambae oli stap olbaot long ol rod blong hem, oli stap pleplei.","Mo taon ya bambae i fulap bakegen long ol pikinini we bambae oli stap olbaot long ol rod blong hem, oli stap pleplei."],[8,6,"“Olgeta ya we oli kambak, oli no plante, mo oli ting se samting ya i strong tumas, i no save kamtru. Be mi mi Hae God, mi gat olgeta paoa, mo i no gat wan samting nating we i strong tumas we mi no save mekem.","“Olgeta ya we oli kambak, oli no plante, mo oli ting se samting ya i strong tumas, i no save kamtru. Be mi mi Hae God, mi gat olgeta paoa, mo i no gat wan samting nating we i strong tumas we mi no save mekem."],[8,7,"Long weples we ol enemi oli tekemaot ol man blong mi i go long hem, be bambae mi tekem olgeta oli kambak bakegen.","Long weples we ol enemi oli tekemaot ol man blong mi i go long hem, be bambae mi tekem olgeta oli kambak bakegen."],[8,8,"Olgeta we oli stap long is, mo olgeta we oli stap long wes, mi bambae mi tekem olgeta i kambak long Jerusalem bakegen. Bambae oli man blong mi, mo mi bambae mi God blong olgeta. Mo mi bambae mi rulum olgeta oltaem nomo long stret fasin.”","Olgeta we oli stap long is, mo olgeta we oli stap long wes, mi bambae mi tekem olgeta i kambak long Jerusalem bakegen. Bambae oli man blong mi, mo mi bambae mi God blong olgeta. Mo mi bambae mi rulum olgeta oltaem nomo long stret fasin.”"],[8,9,"Nao Profet Sekaraea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Tingting blong yufala i mas strong. Naoia bambae mi talemaot long yufala sem tok ya we mi bin talem long ol profet, long taem ya we ol man oli putum fandesen blong haos* blong mi bakegen.","Nao Profet Sekaraea i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* Tingting blong yufala i mas strong. Naoia bambae mi talemaot long yufala sem tok ya we mi bin talem long ol profet, long taem ya we ol man oli putum fandesen blong haos* blong mi bakegen."],[8,10,"Bifo, long taem ya we ol man oli no gat mane nating blong pem man no anamol blong mekem wok blong olgeta, ol enemi blong olgeta oli mekem i strong tumas long olgeta. Long taem ya, mi mekem ol man oli stap kilkilim olgeta bakegen.","Bifo, long taem ya we ol man oli no gat mane nating blong pem man no anamol blong mekem wok blong olgeta, ol enemi blong olgeta oli mekem i strong tumas long olgeta. Long taem ya, mi mekem ol man oli stap kilkilim olgeta bakegen."],[8,11,"Be naoia, yufala we i laef i stap long taon ya, mi bambae mi mekem i gud long yufala.","Be naoia, yufala we i laef i stap long taon ya, mi bambae mi mekem i gud long yufala."],[8,12,"Taem yufala i go blong planem garen blong yufala, bambae ol enemi oli no save kam spolem yufala. Ol grep* blong yufala bambae oli karem plante frut, mo ol kakae we yufala i planem bambae oli karem plante kakae, from we bambae i gat ren blong mekem ol samting ya i gru gud. Mi bambae mi givim ol gudgudfala samting ya i go long yufala.","Taem yufala i go blong planem garen blong yufala, bambae ol enemi oli no save kam spolem yufala. Ol grep* blong yufala bambae oli karem plante frut, mo ol kakae we yufala i planem bambae oli karem plante kakae, from we bambae i gat ren blong mekem ol samting ya i gru gud. Mi bambae mi givim ol gudgudfala samting ya i go long yufala."],[8,13,"Ol man Juda,* mo ol man Isrel. Bifo ol strenja oli stap yusum nem blong yufala blong singaot* trabol i kam long narafala man. Oli stap talem se, ‘Bigfala trabol ya bambae i kasem yufala olsem we bifo i kam kasem ol man Juda, mo ol man Isrel.’ Be mi bambae mi sevem yufala, nao taem ol strenja ya oli luk olsem, bambae oli save talem se, ‘Olgeta. God bambae i blesem yufala olsem we hem i blesem ol man Juda mo ol man Isrel.’ Nao from samting ya, bambae yufala i no fraet, tingting blong yufala i mas strong oltaem.","Ol man Juda,* mo ol man Isrel. Bifo ol strenja oli stap yusum nem blong yufala blong singaot* trabol i kam long narafala man. Oli stap talem se, ‘Bigfala trabol ya bambae i kasem yufala olsem we bifo i kam kasem ol man Juda, mo ol man Isrel.’ Be mi bambae mi sevem yufala, nao taem ol strenja ya oli luk olsem, bambae oli save talem se, ‘Olgeta. God bambae i blesem yufala olsem we hem i blesem ol man Juda mo ol man Isrel.’ Nao from samting ya, bambae yufala i no fraet, tingting blong yufala i mas strong oltaem."],[8,14,"“Bifo, taem ol bubu blong yufala oli mekem mi mi kros, mi mekem plan blong letem trabol i kam kasem olgeta, mo mi no jenisim tingting blong mi nating, mi gohed, mi mekem samting ya i kamtru.","“Bifo, taem ol bubu blong yufala oli mekem mi mi kros, mi mekem plan blong letem trabol i kam kasem olgeta, mo mi no jenisim tingting blong mi nating, mi gohed, mi mekem samting ya i kamtru."],[8,15,"Be yufala i no fraet. Naoia mi mi mekem plan finis, blong mi blesem Jerusalem mo Juda.","Be yufala i no fraet. Naoia mi mi mekem plan finis, blong mi blesem Jerusalem mo Juda."],[8,16,"Mo ol samting we yufala i mas mekem i olsem. Yufala i mas talem trutok long ol narafala man, mo taem yufala i jajem man, yufala i mas jajem hem long stret fasin we i save mekem man i gat pis.","Mo ol samting we yufala i mas mekem i olsem. Yufala i mas talem trutok long ol narafala man, mo taem yufala i jajem man, yufala i mas jajem hem long stret fasin we i save mekem man i gat pis."],[8,17,"Bambae yufala i no mas mekem plan blong spolem narafala man. Mo bambae yufala i no mekem ol giaman toktok, we yufala i stap mekem strong promes se tok ya i tru. Fasin we man i giaman, mo we man i jajem man long fasin we i no stret, mo we man i faet, mi mi no laekem nating ol fasin ya.”","Bambae yufala i no mas mekem plan blong spolem narafala man. Mo bambae yufala i no mekem ol giaman toktok, we yufala i stap mekem strong promes se tok ya i tru. Fasin we man i giaman, mo we man i jajem man long fasin we i no stret, mo we man i faet, mi mi no laekem nating ol fasin ya.”"],[8,18,"Nao profet i talem se, “Hae God i gat olgeta paoa, mo hem i givim tok blong hem long mi, blong mi talemaot long yufala.","Nao profet i talem se, “Hae God i gat olgeta paoa, mo hem i givim tok blong hem long mi, blong mi talemaot long yufala."],[8,19,"Hem i talem se, ‘Ol man Juda. Bifo, yufala i stap livim kakae long namba fo manis,* mo long namba faef manis, mo bakegen long namba seven manis, mo long namba ten manis, be naoia, fasin ya bambae i mas finis. Ol manis ya bambae oli kam manis blong mekem lafet, blong yufala i glad yufala i harem gud. Nao from samting ya, yufala i mas laekem ol trutok mo pis.","Hem i talem se, ‘Ol man Juda. Bifo, yufala i stap livim kakae long namba fo manis,* mo long namba faef manis, mo bakegen long namba seven manis, mo long namba ten manis, be naoia, fasin ya bambae i mas finis. Ol manis ya bambae oli kam manis blong mekem lafet, blong yufala i glad yufala i harem gud. Nao from samting ya, yufala i mas laekem ol trutok mo pis."],[8,20,"“ ‘I gat taem i stap kam we ol man blong plante taon bambae oli kam long Jerusalem.","“ ‘I gat taem i stap kam we ol man blong plante taon bambae oli kam long Jerusalem."],[8,21,"Long taem ya, bambae ol man blong wan taon oli save talem long ol man blong narafala taon se, “Hae God i gat olgeta paoa, mo naoia mifala i go blong mekem wosip long hem, mifala i go prea long hem, blong hem i blesem mifala. I gud yufala i kam wetem mifala, nao yumi go.”","Long taem ya, bambae ol man blong wan taon oli save talem long ol man blong narafala taon se, “Hae God i gat olgeta paoa, mo naoia mifala i go blong mekem wosip long hem, mifala i go prea long hem, blong hem i blesem mifala. I gud yufala i kam wetem mifala, nao yumi go.”"],[8,22,"Mi mi gat olgeta paoa, mo bambae i gat plante man blong ol narafala kantri we oli gat paoa, mo ol haeman oli kam long Jerusalem blong mekem wosip long mi. Mo bambae oli prea long mi blong mi blesem olgeta.","Mi mi gat olgeta paoa, mo bambae i gat plante man blong ol narafala kantri we oli gat paoa, mo ol haeman oli kam long Jerusalem blong mekem wosip long mi. Mo bambae oli prea long mi blong mi blesem olgeta."],[8,23,"Long dei ya, bambae i gat ten man we oli strenja, we lanwis blong olgeta i naranarafala, bambae oli kam luk wan laen blong Isrel, oli talem long hem se, “Mifala i wantem kam fren blong yufala, from we mifala i harem nius se God i stap givhan long yufala.” ’ ”","Long dei ya, bambae i gat ten man we oli strenja, we lanwis blong olgeta i naranarafala, bambae oli kam luk wan laen blong Isrel, oli talem long hem se, “Mifala i wantem kam fren blong yufala, from we mifala i harem nius se God i stap givhan long yufala.” ’ ”"],[9,1,"Nao Hae God i givim tok blong hem long Profet Sekaraea, mo profet i talemaot we hem i talem se, “Mi mi makemaot finis panis we ol man blong kantri ya Hadrak, mo ol man blong taon ya Damaskes we i kaptel blong Siria bambae oli kasem, from we i no ol laen* blong Isrel* nomo we oli stap long han blong mi, ol man Damaskes tu, oli stap long han blong mi.","Nao Hae God i givim tok blong hem long Profet Sekaraea, mo profet i talemaot we hem i talem se, “Mi mi makemaot finis panis we ol man blong kantri ya Hadrak, mo ol man blong taon ya Damaskes we i kaptel blong Siria bambae oli kasem, from we i no ol laen* blong Isrel* nomo we oli stap long han blong mi, ol man Damaskes tu, oli stap long han blong mi."],[9,2,"Mo i gat taon ya Hamat, we mak blong hem i stat long Hadrak, mo tufala taon ya Taea mo Saedon, nating we ol man blong tufala oli waes tumas, be trifala taon ya tu i stap long han blong mi, mo bambae oli mas kasem panis.","Mo i gat taon ya Hamat, we mak blong hem i stat long Hadrak, mo tufala taon ya Taea mo Saedon, nating we ol man blong tufala oli waes tumas, be trifala taon ya tu i stap long han blong mi, mo bambae oli mas kasem panis."],[9,3,"Bifo, ol man Taea oli bin wokem bigfala stonwol i goraon long taon blong olgeta, mo oli hivimap fulap silva mo gol long ples blong olgeta, we i plante we plante olsem doti nomo.","Bifo, ol man Taea oli bin wokem bigfala stonwol i goraon long taon blong olgeta, mo oli hivimap fulap silva mo gol long ples blong olgeta, we i plante we plante olsem doti nomo."],[9,4,"Be mi mi Masta* blong olgeta ples long wol ya, mo bambae mi tekemaot olgeta samting ya evriwan i gowe long ples ya. Bambae mi sakemaot olgeta i go long solwota, mo bambae mi bonem taon ya blong olgeta.","Be mi mi Masta* blong olgeta ples long wol ya, mo bambae mi tekemaot olgeta samting ya evriwan i gowe long ples ya. Bambae mi sakemaot olgeta i go long solwota, mo bambae mi bonem taon ya blong olgeta."],[9,5,"“Taem olgeta blong Askelon oli luk samting ya, bambae oli fraet gud long hem. Mo olgeta blong Gasa bambae oli harem nogud tumas from. Olgeta blong Ekron tu bambae oli harem nogud, tingting blong olgeta bambae i go olbaot. Gasa bambae i lusum king blong hem, mo Askelon bambae i stap nating nomo, i no moa gat man long hem.","“Taem olgeta blong Askelon oli luk samting ya, bambae oli fraet gud long hem. Mo olgeta blong Gasa bambae oli harem nogud tumas from. Olgeta blong Ekron tu bambae oli harem nogud, tingting blong olgeta bambae i go olbaot. Gasa bambae i lusum king blong hem, mo Askelon bambae i stap nating nomo, i no moa gat man long hem."],[9,6,"Ol man blong ol naranarafala kantri bambae oli kam stap wanples long Asdod, oli mekem ples blong olgeta long ples ya. Ol man Filistia ya oli stap praod tumas, be mi bambae mi mekem tingting blong olgeta i stap daon.","Ol man blong ol naranarafala kantri bambae oli kam stap wanples long Asdod, oli mekem ples blong olgeta long ples ya. Ol man Filistia ya oli stap praod tumas, be mi bambae mi mekem tingting blong olgeta i stap daon."],[9,7,"Bambae oli no moa save kakae mit we i gat blad long hem, mo ol kakae ya we Loa* i talem se i tabu blong kakae. Olgeta we oli stap laef, bambae oli joen long ol man blong mi blong oli kam man blong mi. Mo bambae oli olsem ol laen blong Juda.* Ol man Ekron, bambae oli kam man blong mi, olsem we ol man Jebus oli kam man blong mi finis.","Bambae oli no moa save kakae mit we i gat blad long hem, mo ol kakae ya we Loa* i talem se i tabu blong kakae. Olgeta we oli stap laef, bambae oli joen long ol man blong mi blong oli kam man blong mi. Mo bambae oli olsem ol laen blong Juda.* Ol man Ekron, bambae oli kam man blong mi, olsem we ol man Jebus oli kam man blong mi finis."],[9,8,"Mi bambae mi blokemgud kantri blong mi, blong ol soldia blong ol narafala kantri oli no save kam pas long ples ya. Bambae mi no save letem blong ol enemi oli kam rulum ol man blong mi, from we mi luk finis ol rabis fasin we oli mekem long olgeta.”","Mi bambae mi blokemgud kantri blong mi, blong ol soldia blong ol narafala kantri oli no save kam pas long ples ya. Bambae mi no save letem blong ol enemi oli kam rulum ol man blong mi, from we mi luk finis ol rabis fasin we oli mekem long olgeta.”"],[9,9,"Nao Profet Sekaraea i talemaot we Hae God i talem se, “!Ol man Saeon*! Yufala i mas harem gud, yufala i glad. !Ol man Jerusalem*! I gud yufala i glad we yufala i singsingaot from. !Yufala i luk! King blong yufala i stap kam long yufala. Hem i win finis, mo i glad tumas from we hem i winim ol enemi blong hem. Be tingting blong hem i stap daon, nao i stap raed long wan dongki. Hem i stap raed long wan dongki we i yangfala nomo.","Nao Profet Sekaraea i talemaot we Hae God i talem se, “!Ol man Saeon*! Yufala i mas harem gud, yufala i glad. !Ol man Jerusalem*! I gud yufala i glad we yufala i singsingaot from. !Yufala i luk! King blong yufala i stap kam long yufala. Hem i win finis, mo i glad tumas from we hem i winim ol enemi blong hem. Be tingting blong hem i stap daon, nao i stap raed long wan dongki. Hem i stap raed long wan dongki we i yangfala nomo."],[9,10,"Mi bambae mi tekemaot ol kat blong faet i gowe long Isrel* long not. Mo bambae mi tekemaot ol hos blong faet i gowe long Jerusalem. Ol bonara blong olgeta we oli stap yusum long taem blong faet, mi bambae mi spolem evriwan. King ya blong yufala bambae i mekem pis wetem ol narafala kantri, mo bambae hem i king long olgeta ples, i stat long solwota long is, i go kasem solwota long wes, i stat long Yufretes Reva long not, i go kasem en blong wol.”","Mi bambae mi tekemaot ol kat blong faet i gowe long Isrel* long not. Mo bambae mi tekemaot ol hos blong faet i gowe long Jerusalem. Ol bonara blong olgeta we oli stap yusum long taem blong faet, mi bambae mi spolem evriwan. King ya blong yufala bambae i mekem pis wetem ol narafala kantri, mo bambae hem i king long olgeta ples, i stat long solwota long is, i go kasem solwota long wes, i stat long Yufretes Reva long not, i go kasem en blong wol.”"],[9,11,"Nao Profet Sekaraea i talemaot we Hae God i talem se, “Mi mi mekem promes* finis wetem yufala, mo blad blong sakrefaes i ron blong mekem promes ya i stanap strong. Nao from samting ya, mi bambae mi tekemaot yufala long ples ya we yufala i stap wok slef* long hem, we i olsem hol we i no gat wota long hem, mi letem yufala i gofri.","Nao Profet Sekaraea i talemaot we Hae God i talem se, “Mi mi mekem promes* finis wetem yufala, mo blad blong sakrefaes i ron blong mekem promes ya i stanap strong. Nao from samting ya, mi bambae mi tekemaot yufala long ples ya we yufala i stap wok slef* long hem, we i olsem hol we i no gat wota long hem, mi letem yufala i gofri."],[9,12,"Yufala we i stap wok slef we tingting blong yufala i stap strong long mi, i gud yufala i kambak long sefples blong yufala bakegen. Fastaem yufala i stap harem nogud tumas long plante samting. Be naoia, mi mi talem stret long yufala, se bambae mi blesem yufala moa i winim we mi stap blesem yufala fastaem. Bambae mi givim ol gudgudfala samting long yufala.","Yufala we i stap wok slef we tingting blong yufala i stap strong long mi, i gud yufala i kambak long sefples blong yufala bakegen. Fastaem yufala i stap harem nogud tumas long plante samting. Be naoia, mi mi talem stret long yufala, se bambae mi blesem yufala moa i winim we mi stap blesem yufala fastaem. Bambae mi givim ol gudgudfala samting long yufala."],[9,13,"Ol man Juda.* Bambae mi yusum yufala olsem bonara blong mi. Ol man Isrel.* Bambae mi mekem yufala olsem ol ara blong mi. Mo yufala ol man Saeon,* bambae mi yusum yufala, olsem naef blong faet blong mi, blong kilim ol man Gris.”","Ol man Juda.* Bambae mi yusum yufala olsem bonara blong mi. Ol man Isrel.* Bambae mi mekem yufala olsem ol ara blong mi. Mo yufala ol man Saeon,* bambae mi yusum yufala, olsem naef blong faet blong mi, blong kilim ol man Gris.”"],[9,14,"Mo Profet Sekaraea i talem se, “Hae God bambae i kamtru long ol man blong hem, mo hem i sut long ara blong hem we bambae i laet olsem laetning. Hem i Masta* blong yumi, mo bambae i blu long bigfala pupu blong hem. Taem hem i wokbaot i kam, bambae bigfala waelwin i aot long saot, i karem hem i kam.","Mo Profet Sekaraea i talem se, “Hae God bambae i kamtru long ol man blong hem, mo hem i sut long ara blong hem we bambae i laet olsem laetning. Hem i Masta* blong yumi, mo bambae i blu long bigfala pupu blong hem. Taem hem i wokbaot i kam, bambae bigfala waelwin i aot long saot, i karem hem i kam."],[9,15,"Hae God i gat olgeta paoa. Hem bambae i blokemgud ol man blong hem, mo i kilim olgeta enemi blong olgeta. Taem oli go blong faet, bambae oli singsingaot olsem ol man we oli drong. Bambae oli kilim ol enemi blong olgeta we blad blong olgeta bambae i ron olsem blad blong anamol we man i kilim blong mekem sakrefaes, nao i putum long wan besin, // i kafsaedem i go long olta.","Hae God i gat olgeta paoa. Hem bambae i blokemgud ol man blong hem, mo i kilim olgeta enemi blong olgeta. Taem oli go blong faet, bambae oli singsingaot olsem ol man we oli drong. Bambae oli kilim ol enemi blong olgeta we blad blong olgeta bambae i ron olsem blad blong anamol we man i kilim blong mekem sakrefaes, nao i putum long wan besin, // i kafsaedem i go long olta."],[9,16,"Taem dei ya i kamtru, Hae God bambae i blokemgud ol man blong hem, olsem we man blong lukaot long sipsip i stap lukaot gud long ol sipsip blong hem, blong wan samting i no save spolem olgeta. Long kantri ya blong hem bambae olgeta ya oli saen olsem ol flas ston long hat blong king.","Taem dei ya i kamtru, Hae God bambae i blokemgud ol man blong hem, olsem we man blong lukaot long sipsip i stap lukaot gud long ol sipsip blong hem, blong wan samting i no save spolem olgeta. Long kantri ya blong hem bambae olgeta ya oli saen olsem ol flas ston long hat blong king."],[9,17,"Ples ya bambae i gud tumas, ol kakae blong hem mo ol waen blong hem, bambae i mekem ol yangfala blong ples ya oli fatfat gud oli strong.”","Ples ya bambae i gud tumas, ol kakae blong hem mo ol waen blong hem, bambae i mekem ol yangfala blong ples ya oli fatfat gud oli strong.”"],[10,1,"Nao Profet Sekaraea i talem se, “Yufala i mas askem long Hae God blong i sanem ren i kam long yufala long stret taem blong hem, blong mekem ol garen blong yufala i gru gud. Oltaem, hem nomo i stap mekem klaod blong ren, blong i ren bigwan, no blong i ren smosmol.","Nao Profet Sekaraea i talem se, “Yufala i mas askem long Hae God blong i sanem ren i kam long yufala long stret taem blong hem, blong mekem ol garen blong yufala i gru gud. Oltaem, hem nomo i stap mekem klaod blong ren, blong i ren bigwan, no blong i ren smosmol."],[10,2,"Be ol man we oli stap askem long ol aedol, mo long ol kleva we oli stap talemaot ol samting we bambae i kamtru long fiuja, blong oli mekem ol samting olsem long yufala, ansa we oli stap givim, i krangke mo i no tru nating. Olgeta we oli stap talemaot mining blong ol drim, oli stap giaman nomo long yufala. Ol samting we oli talem i no givhan nating long yufala. Nao from samting ya, yufala i stap go olbaot olsem sipsip we i lus long bus. Yufala i stap trabol olbaot from we i no gat man blong lidim yufala.”","Be ol man we oli stap askem long ol aedol, mo long ol kleva we oli stap talemaot ol samting we bambae i kamtru long fiuja, blong oli mekem ol samting olsem long yufala, ansa we oli stap givim, i krangke mo i no tru nating. Olgeta we oli stap talemaot mining blong ol drim, oli stap giaman nomo long yufala. Ol samting we oli talem i no givhan nating long yufala. Nao from samting ya, yufala i stap go olbaot olsem sipsip we i lus long bus. Yufala i stap trabol olbaot from we i no gat man blong lidim yufala.”"],[10,3,"Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi gat olgeta paoa, mo mi kros tumas long ol lida blong ol narafala kantri we oli stap rulum ol man blong mi. Bambae mi mas panisim olgeta. Ol man Juda* ya oli man blong mi, mo mi mas lukaot gud long olgeta. Bambae mi mekem olgeta oli kam olsem ol strong hos blong faet blong mi.","Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi gat olgeta paoa, mo mi kros tumas long ol lida blong ol narafala kantri we oli stap rulum ol man blong mi. Bambae mi mas panisim olgeta. Ol man Juda* ya oli man blong mi, mo mi mas lukaot gud long olgeta. Bambae mi mekem olgeta oli kam olsem ol strong hos blong faet blong mi."],[10,4,"Bambae mi jusumaot wan man long laen* blong Juda blong i king blong ol man blong mi, mo hem bambae i stanap strong blong lidim olgeta, mo bambae i komanda blong olgeta, mo olgeta lida blong ol man blong mi bambae oli kamaot long laen ya.","Bambae mi jusumaot wan man long laen* blong Juda blong i king blong ol man blong mi, mo hem bambae i stanap strong blong lidim olgeta, mo bambae i komanda blong olgeta, mo olgeta lida blong ol man blong mi bambae oli kamaot long laen ya."],[10,5,"Ol man Juda bambae oli win, olsem ol soldia we oli winim ol enemi blong olgeta, nao oli purumpurumbut long olgeta long sofmad. Bambae oli faet, nao oli winim ol enemi blong olgeta we oli man blong ron long hos. Bambae oli win olsem, from we mi Hae God, mi stap givhan long olgeta.","Ol man Juda bambae oli win, olsem ol soldia we oli winim ol enemi blong olgeta, nao oli purumpurumbut long olgeta long sofmad. Bambae oli faet, nao oli winim ol enemi blong olgeta we oli man blong ron long hos. Bambae oli win olsem, from we mi Hae God, mi stap givhan long olgeta."],[10,6,"“Mi bambae mi mekem ol man Juda oli strong, mo bambae mi tekemaot ol man Isrel* long han blong ol enemi blong olgeta. Mi bambae mi gat sore long olgeta, mi tekem olgeta evriwan oli kambak long stret ples blong olgeta bakegen. Bambae oli stap gud long ples blong olgeta, olsem we mi mi no bin lego olgeta samtaem. Mi mi Hae God, mi God blong olgeta, mo taem oli prea long mi, mi bambae mi harem prea blong olgeta.","“Mi bambae mi mekem ol man Juda oli strong, mo bambae mi tekemaot ol man Isrel* long han blong ol enemi blong olgeta. Mi bambae mi gat sore long olgeta, mi tekem olgeta evriwan oli kambak long stret ples blong olgeta bakegen. Bambae oli stap gud long ples blong olgeta, olsem we mi mi no bin lego olgeta samtaem. Mi mi Hae God, mi God blong olgeta, mo taem oli prea long mi, mi bambae mi harem prea blong olgeta."],[10,7,"Ol man Isrel ya bambae oli strong olsem ol soldia, oltaem bambae oli glad, oli harem gud, olsem man we i dring waen. Ol laen we oli kamaot biaen long olgeta, oltaem bambae oli stap tingbaot taem ya we ol bubu blong olgeta oli win long faet, mo bambae oli harem gud, from we mi mi mekem olsem long olgeta.","Ol man Isrel ya bambae oli strong olsem ol soldia, oltaem bambae oli glad, oli harem gud, olsem man we i dring waen. Ol laen we oli kamaot biaen long olgeta, oltaem bambae oli stap tingbaot taem ya we ol bubu blong olgeta oli win long faet, mo bambae oli harem gud, from we mi mi mekem olsem long olgeta."],[10,8,"Mi bambae mi singaot ol man blong mi, mi tekem olgeta i kam wanples. Bambae mi sevem olgeta, mo mi mekem olgeta oli kam plante we plante, olsem bifo.","Mi bambae mi singaot ol man blong mi, mi tekem olgeta i kam wanples. Bambae mi sevem olgeta, mo mi mekem olgeta oli kam plante we plante, olsem bifo."],[10,9,"Nating we mi mekem olgeta oli go stap olbaot long ol narafala kantri, be bambae oli save tingbaot mi bakegen. Nao olgeta evriwan wetem ol pikinini blong olgeta, bambae oli kambak long stret ples blong olgeta bakegen.","Nating we mi mekem olgeta oli go stap olbaot long ol narafala kantri, be bambae oli save tingbaot mi bakegen. Nao olgeta evriwan wetem ol pikinini blong olgeta, bambae oli kambak long stret ples blong olgeta bakegen."],[10,10,"Olgeta we oli stap long Ijip mo long Asiria, bambae mi tekem olgeta oli kambak long kantri blong olgeta bakegen. Mo bambae mi mekem olgeta oli stap long Gilead mo long Lebanon tu, nao olgeta ples long kantri ya bambae i fulap gud long olgeta.","Olgeta we oli stap long Ijip mo long Asiria, bambae mi tekem olgeta oli kambak long kantri blong olgeta bakegen. Mo bambae mi mekem olgeta oli stap long Gilead mo long Lebanon tu, nao olgeta ples long kantri ya bambae i fulap gud long olgeta."],[10,11,"Taem bigfala trabol i kasem olgeta, olsem ol bigbigfala wef blong solwota, be mi bambae mi blokem trabol ya, mo bambae mi mekem Nael Reva i drae olgeta. Ijip bambae i lusum paoa blong hem, mo ol man Asiria ya we oli stap praod tumas, bambae mi mekem olgeta oli sem.","Taem bigfala trabol i kasem olgeta, olsem ol bigbigfala wef blong solwota, be mi bambae mi blokem trabol ya, mo bambae mi mekem Nael Reva i drae olgeta. Ijip bambae i lusum paoa blong hem, mo ol man Asiria ya we oli stap praod tumas, bambae mi mekem olgeta oli sem."],[10,12,"Mi bambae mi mekem ol man blong mi oli kam strong, nao bambae oli save obei long mi, mo bambae oli mekem wosip long mi. Mi mi Hae God, mo hemia tok blong mi.”","Mi bambae mi mekem ol man blong mi oli kam strong, nao bambae oli save obei long mi, mo bambae oli mekem wosip long mi. Mi mi Hae God, mo hemia tok blong mi.”"],[11,1,"Mo Profet Sekaraea i talem se, “Lebanon. Yu mas openem ol doa blong yu, blong faea i kam bonem ol tri ya sida* we i stap long yu.","Mo Profet Sekaraea i talem se, “Lebanon. Yu mas openem ol doa blong yu, blong faea i kam bonem ol tri ya sida* we i stap long yu."],[11,2,"Ol paentri.* Yufala i mas krae bigwan from ol sida ya we oli folfoldaon finis. Ol gudgudfala tri ya, faea i kakae olgeta evriwan finis. Ol oktri* blong Basan. Yufala tu i mas krae bigwan, from we ol bigbigfala tri long bus, ol man oli katemdaon evriwan finis.","Ol paentri.* Yufala i mas krae bigwan from ol sida ya we oli folfoldaon finis. Ol gudgudfala tri ya, faea i kakae olgeta evriwan finis. Ol oktri* blong Basan. Yufala tu i mas krae bigwan, from we ol bigbigfala tri long bus, ol man oli katemdaon evriwan finis."],[11,3,"Ol lida blong kantri ya oli krae tumas, oli harem nogud from we ol gudgudfala samting blong olgeta oli lus evriwan finis. Ol laeon tu oli stap krae, from we bigfala bus ya klosap long Jodan Reva, we i ples blong olgeta, ol man oli spolem evriwan finis.”","Ol lida blong kantri ya oli krae tumas, oli harem nogud from we ol gudgudfala samting blong olgeta oli lus evriwan finis. Ol laeon tu oli stap krae, from we bigfala bus ya klosap long Jodan Reva, we i ples blong olgeta, ol man oli spolem evriwan finis.”"],[11,4,"Nao Profet Sekaraea i talem se, “Hae God i God blong mi, mo hem i talem long mi se, ‘Yu mas kam olsem man blong lukaot long sipsip, blong lukaot gud long ol sipsip ya we ol man oli makemaot olgeta blong kakae.","Nao Profet Sekaraea i talem se, “Hae God i God blong mi, mo hem i talem long mi se, ‘Yu mas kam olsem man blong lukaot long sipsip, blong lukaot gud long ol sipsip ya we ol man oli makemaot olgeta blong kakae."],[11,5,"Ol man we oli stap pem ol sipsip we oli blong karem pikinini, oli stap go kilim olgeta be oli no kasem panis from. Mo olgeta we oli stap salem ol sipsip ya, oli stap talem se, “!O, naoia yumi kam rijman! !Yumi mas presem God from!” Mo ol man blong lukaot long ol sipsip ya, olgeta tu oli no gat sore long olgeta.’","Ol man we oli stap pem ol sipsip we oli blong karem pikinini, oli stap go kilim olgeta be oli no kasem panis from. Mo olgeta we oli stap salem ol sipsip ya, oli stap talem se, “!O, naoia yumi kam rijman! !Yumi mas presem God from!” Mo ol man blong lukaot long ol sipsip ya, olgeta tu oli no gat sore long olgeta.’"],[11,6,"(“Hae God i talem se, ‘Bambae mi mi no moa gat sore long ol man blong wol ya. Bambae mi mekem ol man oli foldaon wanwan long han blong ol king blong olgeta. Nao bambae mi mekem we olgeta ya oli flatemgud olgeta ples long wol ya. Mo bambae mi no save tekemaot ol man ya bakegen long han blong olgeta.’ ”)","(“Hae God i talem se, ‘Bambae mi mi no moa gat sore long ol man blong wol ya. Bambae mi mekem ol man oli foldaon wanwan long han blong ol king blong olgeta. Nao bambae mi mekem we olgeta ya oli flatemgud olgeta ples long wol ya. Mo bambae mi no save tekemaot ol man ya bakegen long han blong olgeta.’ ”)"],[11,7,"Nao profet i talem se, “Nao mi mi mekem olsem we Hae God i talem long mi. Mi go luk olgeta ya we oli stap pem ol sipsip, mo oli stap salem olgeta, blong oli pem mi, blong mi go lukaot long ol sipsip ya blong olgeta, we oli makemaot olgeta blong kakae. Nao mi holem tu stik blong lukaot long sipsip, wan mi putum nem blong hem se, ‘Givhan long Gladhat’, mo narawan mi putum nem blong hem se, ‘Joen Wanples’, mo mi stap lukaot gud long olgeta.","Nao profet i talem se, “Nao mi mi mekem olsem we Hae God i talem long mi. Mi go luk olgeta ya we oli stap pem ol sipsip, mo oli stap salem olgeta, blong oli pem mi, blong mi go lukaot long ol sipsip ya blong olgeta, we oli makemaot olgeta blong kakae. Nao mi holem tu stik blong lukaot long sipsip, wan mi putum nem blong hem se, ‘Givhan long Gladhat’, mo narawan mi putum nem blong hem se, ‘Joen Wanples’, mo mi stap lukaot gud long olgeta."],[11,8,"I gat tri narafala man blong lukaot long sipsip we mifala i wok wanples, be trifala i no laekem mi nating, trifala i stap agens long mi. Nao mi no moa gat sore long trifala, mo long wan manis nomo mi mi sakemaot trifala.","I gat tri narafala man blong lukaot long sipsip we mifala i wok wanples, be trifala i no laekem mi nating, trifala i stap agens long mi. Nao mi no moa gat sore long trifala, mo long wan manis nomo mi mi sakemaot trifala."],[11,9,"Nao mi talem long ol sipsip ya blong mi se, ‘Bambae mi no moa save lukaot long yufala bakegen. Yufala we i blong ded, mi mas letem yufala i go ded, mo yufala we i blong ol man oli kilim yufala i ded, oli mas kilim yufala. Mo yufala ya we i blong stap, bambae yufala nomo i stap kilkilim yufala gogo yufala i ded evriwan.’","Nao mi talem long ol sipsip ya blong mi se, ‘Bambae mi no moa save lukaot long yufala bakegen. Yufala we i blong ded, mi mas letem yufala i go ded, mo yufala we i blong ol man oli kilim yufala i ded, oli mas kilim yufala. Mo yufala ya we i blong stap, bambae yufala nomo i stap kilkilim yufala gogo yufala i ded evriwan.’"],[11,10,"Nao mi tekem stik ya we nem blong hem ‘Givhan long Gladhat’, mi brekem blong soemaot we promes* we Hae God i mekem wetem olgeta kantri, naoia i finis.","Nao mi tekem stik ya we nem blong hem ‘Givhan long Gladhat’, mi brekem blong soemaot we promes* we Hae God i mekem wetem olgeta kantri, naoia i finis."],[11,11,"Nao long sem dei ya nomo, promes ya i finis olgeta. Taem mi stap mekem ol samting ya, olgeta we oli stap pem ol sipsip ya, mo olgeta we oli stap salem, oli stap lukluk mi, mo oli save we Hae God i toktok long olgeta long ol samting ya we mi mi stap mekem.","Nao long sem dei ya nomo, promes ya i finis olgeta. Taem mi stap mekem ol samting ya, olgeta we oli stap pem ol sipsip ya, mo olgeta we oli stap salem, oli stap lukluk mi, mo oli save we Hae God i toktok long olgeta long ol samting ya we mi mi stap mekem."],[11,12,"Mo mi talem long olgeta se, ‘Sipos yufala i wantem, mi mi wantem se yufala i pem mi, be sipos yufala i no wantem, yufala i holem pei blong mi i stap fastaem.’ Nao olgeta oli skelem toti sekel silva we i olsem fiftin taosen vatu 0, oli givim long mi blong pem mi.","Mo mi talem long olgeta se, ‘Sipos yufala i wantem, mi mi wantem se yufala i pem mi, be sipos yufala i no wantem, yufala i holem pei blong mi i stap fastaem.’ Nao olgeta oli skelem toti sekel silva we i olsem fiftin taosen vatu 0, oli givim long mi blong pem mi."],[11,13,"“Nao Hae God i talem long mi se, ‘Yu go putum mane ya long ples blong mane long haos* blong mi.’ Nao mi luk we pei blong mi i no kasem stret mak blong hem nating, be mi tekem mane ya, mi go putum long ples blong mane long haos blong God, olsem we hem i talem.","“Nao Hae God i talem long mi se, ‘Yu go putum mane ya long ples blong mane long haos* blong mi.’ Nao mi luk we pei blong mi i no kasem stret mak blong hem nating, be mi tekem mane ya, mi go putum long ples blong mane long haos blong God, olsem we hem i talem."],[11,14,"Nao mi girap, mi brekem narafala stik ya we nem blong hem ‘Joen Wanples’, blong soemaot we tufala kantri ya Juda* mo Isrel,* tufala i seraot.”","Nao mi girap, mi brekem narafala stik ya we nem blong hem ‘Joen Wanples’, blong soemaot we tufala kantri ya Juda* mo Isrel,* tufala i seraot.”"],[11,15,"Nao Profet Sekaraea i talemaot we Hae God i talem long hem bakegen se, “Naoia mi mi wantem blong yu yu mekem olsem we yu yu man blong lukaot long sipsip, be fasin blong yu bambae i nogud.","Nao Profet Sekaraea i talemaot we Hae God i talem long hem bakegen se, “Naoia mi mi wantem blong yu yu mekem olsem we yu yu man blong lukaot long sipsip, be fasin blong yu bambae i nogud."],[11,16,"Samting ya bambae i soemaot we mi bambae mi putum wan man blong i lukaot long ol sipsip blong mi. Be man ya bambae i no save givhan nating long olgeta ya we bambae oli stap long trabol we klosap oli ded from, mo bambae hem i no save lukaot olgeta we oli lus, mo i no save givhan long olgeta we oli gat so. Mo olgeta we oli strong, oli stap gud, bambae hem i no save tekem olgeta i go long gudfala gras blong oli kakae. Bambae hem i girap, i stap kilim olgeta we oli fatfat gud, nao i kakae olgeta we i finisimgud.","Samting ya bambae i soemaot we mi bambae mi putum wan man blong i lukaot long ol sipsip blong mi. Be man ya bambae i no save givhan nating long olgeta ya we bambae oli stap long trabol we klosap oli ded from, mo bambae hem i no save lukaot olgeta we oli lus, mo i no save givhan long olgeta we oli gat so. Mo olgeta we oli strong, oli stap gud, bambae hem i no save tekem olgeta i go long gudfala gras blong oli kakae. Bambae hem i girap, i stap kilim olgeta we oli fatfat gud, nao i kakae olgeta we i finisimgud."],[11,17,"Man blong lukaot long sipsip we fasin blong hem i nogud olsem, nao i lego ol sipsip blong hem, hem bambae i mas kasem panis. Long taem blong faet, bambae hem i lusum olgeta paoa blong hem. Han blong hem bambae i kam nogud, mo raet ae blong hem bambae i kam blaen.”","Man blong lukaot long sipsip we fasin blong hem i nogud olsem, nao i lego ol sipsip blong hem, hem bambae i mas kasem panis. Long taem blong faet, bambae hem i lusum olgeta paoa blong hem. Han blong hem bambae i kam nogud, mo raet ae blong hem bambae i kam blaen.”"],[12,1,"Nao Profet Sekaraea i talem se, “Hae God i mekem skae mo wol ya, mo hem i givim laef blong hem long man. Hem i talem se,","Nao Profet Sekaraea i talem se, “Hae God i mekem skae mo wol ya, mo hem i givim laef blong hem long man. Hem i talem se,"],[12,2,"‘Mi bambae mi mekem taon ya Jerusalem* i olsem kap we waen i fulap long hem, nao ol narafala kantri we oli stap raonabaot long hem bambae oli dring long hem. Nao biaen, bambae oli stap wokbaot olsem man we i drong. Mo taem oli kam blong raonem Jerusalem blong faet agens long hem, bambae oli raonem ol narafala taon tu long Juda,* blong faet agens long olgeta.","‘Mi bambae mi mekem taon ya Jerusalem* i olsem kap we waen i fulap long hem, nao ol narafala kantri we oli stap raonabaot long hem bambae oli dring long hem. Nao biaen, bambae oli stap wokbaot olsem man we i drong. Mo taem oli kam blong raonem Jerusalem blong faet agens long hem, bambae oli raonem ol narafala taon tu long Juda,* blong faet agens long olgeta."],[12,3,"Be taem dei ya i kamtru, bambae mi mekem Jerusalem i kam olsem wan hevi ston we sipos wan kantri i wantem muvum, kantri ya bambae i harem nogud tumas from. Olgeta kantri long wol ya bambae oli save joen wanples blong kam faet agens long Jerusalem.","Be taem dei ya i kamtru, bambae mi mekem Jerusalem i kam olsem wan hevi ston we sipos wan kantri i wantem muvum, kantri ya bambae i harem nogud tumas from. Olgeta kantri long wol ya bambae oli save joen wanples blong kam faet agens long Jerusalem."],[12,4,"Be long taem ya, mi bambae mi mekem ol hos blong olgeta oli fraet we oli lusum hed, mo ol man we oli ron long ol hos ya, bambae hed blong olgeta i krangke. Be mi bambae mi lukaot gud long ol man Juda, blong ol enemi oli no save spolem olgeta. Ol enemi ya blong olgeta, mi bambae mi mekem ol hos blong olgeta oli blaen.","Be long taem ya, mi bambae mi mekem ol hos blong olgeta oli fraet we oli lusum hed, mo ol man we oli ron long ol hos ya, bambae hed blong olgeta i krangke. Be mi bambae mi lukaot gud long ol man Juda, blong ol enemi oli no save spolem olgeta. Ol enemi ya blong olgeta, mi bambae mi mekem ol hos blong olgeta oli blaen."],[12,5,"Nao taem ol laen* blong Juda oli luk samting ya, bambae oli save talem se, “Hae God i gat olgeta paoa, mo hem nomo i stap mekem ol man blong hem we oli stap long Jerusalem oli kam strong olsem.”","Nao taem ol laen* blong Juda oli luk samting ya, bambae oli save talem se, “Hae God i gat olgeta paoa, mo hem nomo i stap mekem ol man blong hem we oli stap long Jerusalem oli kam strong olsem.”"],[12,6,"“ ‘Long taem ya, bambae mi mekem ol laen ya blong Juda oli strong olsem faea we i kakae bigfala bus, no i olsem faea we i kakae ol wit* we kakae blong hem i rere finis. Mo bambae oli spolem olgeta kantri we oli stap raonabaot long olgeta. Be ol man Jerusalem bambae oli stap gud nomo insaed long taon ya blong olgeta.","“ ‘Long taem ya, bambae mi mekem ol laen ya blong Juda oli strong olsem faea we i kakae bigfala bus, no i olsem faea we i kakae ol wit* we kakae blong hem i rere finis. Mo bambae oli spolem olgeta kantri we oli stap raonabaot long olgeta. Be ol man Jerusalem bambae oli stap gud nomo insaed long taon ya blong olgeta."],[12,7,"“ ‘Mi mi Hae God, mo bambae mi mekem ol soldia blong Juda oli win fastaem, nao biaen, bambae mi mekem ol laen blong Deved, mo ol man Jerusalem oli win. Bambae mi mekem olsem, blong bambae ol man Jerusalem oli no save talem se oli strong moa winim ol narafala man Juda.","“ ‘Mi mi Hae God, mo bambae mi mekem ol soldia blong Juda oli win fastaem, nao biaen, bambae mi mekem ol laen blong Deved, mo ol man Jerusalem oli win. Bambae mi mekem olsem, blong bambae ol man Jerusalem oli no save talem se oli strong moa winim ol narafala man Juda."],[12,8,"Long taem ya, mi bambae mi lukaot gud long olgeta we oli stap long Jerusalem. Nating we sam long olgeta oli no gat paoa nating, be bambae mi mekem olgeta oli kam strong olsem King Deved bifo. Olgeta we oli kamaot biaen long hem bambae oli lidim ol man, olsem we enjel blong mi i stap mekem, no olsem we mi mi stap mekem.","Long taem ya, mi bambae mi lukaot gud long olgeta we oli stap long Jerusalem. Nating we sam long olgeta oli no gat paoa nating, be bambae mi mekem olgeta oli kam strong olsem King Deved bifo. Olgeta we oli kamaot biaen long hem bambae oli lidim ol man, olsem we enjel blong mi i stap mekem, no olsem we mi mi stap mekem."],[12,9,"Long taem ya ol man blong ol narafala kantri we oli wantem faet agens long Jerusalem, mi bambae mi kilim olgeta evriwan oli ded.’ ”","Long taem ya ol man blong ol narafala kantri we oli wantem faet agens long Jerusalem, mi bambae mi kilim olgeta evriwan oli ded.’ ”"],[12,10,"Nao Profet Sekaraea i talemaot we Hae God i talem se, “Bambae mi mekem ol laen blong King Deved, mo olgeta long Jerusalem* oli fulap long ol gudfala tingting. Hemia tingting ya we man i gat sore long narafala man, mo tingting we man i save prea oltaem. Olgeta ya bambae oli luk man ya we olgeta nomo oli sperem hem, mo bambae oli krae from hem, olsem man we i krae from pikinini blong hem we i wan nomo we hem i gat. Bambae oli krae we oli krae, olsem we man i krae from fasbon pikinini blong hem we i lus.","Nao Profet Sekaraea i talemaot we Hae God i talem se, “Bambae mi mekem ol laen blong King Deved, mo olgeta long Jerusalem* oli fulap long ol gudfala tingting. Hemia tingting ya we man i gat sore long narafala man, mo tingting we man i save prea oltaem. Olgeta ya bambae oli luk man ya we olgeta nomo oli sperem hem, mo bambae oli krae from hem, olsem man we i krae from pikinini blong hem we i wan nomo we hem i gat. Bambae oli krae we oli krae, olsem we man i krae from fasbon pikinini blong hem we i lus."],[12,11,"Long taem ya, ol man bambae oli krae tumas from Jerusalem, olsem we bifo, ol man oli krae from god ya Hadadrimon, long levelples ya long Megido.","Long taem ya, ol man bambae oli krae tumas from Jerusalem, olsem we bifo, ol man oli krae from god ya Hadadrimon, long levelples ya long Megido."],[12,12,"Olgeta famle long kantri ya, olgeta wanwan bambae oli krae long ol haos blong olgeta. Ol laen blong King Deved, mo ol laen blong Natan, mo ol laen blong Livae,* mo ol laen blong Simei, mo olgeta narafala famle tu, bambae oli krae long ol haos blong olgeta. Ol man bambae oli krae long narafala ples, mo ol woman long narafala ples.”","Olgeta famle long kantri ya, olgeta wanwan bambae oli krae long ol haos blong olgeta. Ol laen blong King Deved, mo ol laen blong Natan, mo ol laen blong Livae,* mo ol laen blong Simei, mo olgeta narafala famle tu, bambae oli krae long ol haos blong olgeta. Ol man bambae oli krae long narafala ples, mo ol woman long narafala ples.”",14],[13,1,"Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi gat olgeta paoa, mo long taem ya, mi bambae mi mekem wan springwota i ron, blong mekem ol laen blong King Deved wetem ol narafala man long Jerusalem oli klin, from we bifo oli stap mekem sin, mo oli stap mekem wosip long ol aedol.","Nao profet i talemaot we Hae God i talem se, “Mi mi Hae God, mi gat olgeta paoa, mo long taem ya, mi bambae mi mekem wan springwota i ron, blong mekem ol laen blong King Deved wetem ol narafala man long Jerusalem oli klin, from we bifo oli stap mekem sin, mo oli stap mekem wosip long ol aedol."],[13,2,"Long taem ya, mi bambae mi tekemaot ol nem blong ol aedol i gowe long tingting blong olgeta man long kantri ya, blong bambae man i no moa save tingbaot olgeta bakegen. Man we i stap talem se hem i profet, mi bambae mi sakemaot hem, mo bambae mi mekem we ol man oli no moa wantem mekem wosip long ol aedol.","Long taem ya, mi bambae mi tekemaot ol nem blong ol aedol i gowe long tingting blong olgeta man long kantri ya, blong bambae man i no moa save tingbaot olgeta bakegen. Man we i stap talem se hem i profet, mi bambae mi sakemaot hem, mo bambae mi mekem we ol man oli no moa wantem mekem wosip long ol aedol."],[13,3,"Be sipos wan giaman profet i stap gohed blong talemaot tok blong hem, papa mo mama blong hem bambae tufala i talem long hem se, ‘Yu yu mas ded, from we yu stap talem se yu yu wan profet, be yu stap giaman nomo.’ Long sem taem we hem i stap toktok, papa mo mama blong hem, bambae tufala i stikim hem i ded.","Be sipos wan giaman profet i stap gohed blong talemaot tok blong hem, papa mo mama blong hem bambae tufala i talem long hem se, ‘Yu yu mas ded, from we yu stap talem se yu yu wan profet, be yu stap giaman nomo.’ Long sem taem we hem i stap toktok, papa mo mama blong hem, bambae tufala i stikim hem i ded."],[13,4,"Taem dei ya i kamtru, olgeta profet evriwan bambae oli sem from ol vison* we oli luk. Bambae i no moa gat wan long olgeta i save werem klos blong profet, blong giaman long ol man, se hem i profet.","Taem dei ya i kamtru, olgeta profet evriwan bambae oli sem from ol vison* we oli luk. Bambae i no moa gat wan long olgeta i save werem klos blong profet, blong giaman long ol man, se hem i profet."],[13,5,"Man we fastaem i profet, long taem ya bambae hem i girap, i talem se, ‘Mi mi no wan profet, mi wan fama ya, mo hemia i wok blong mi oltaem long laef blong mi.’","Man we fastaem i profet, long taem ya bambae hem i girap, i talem se, ‘Mi mi no wan profet, mi wan fama ya, mo hemia i wok blong mi oltaem long laef blong mi.’"],[13,6,"Nao sipos wan man i askem long hem se, ‘?Be ol mak blong ol so ya long jes blong yu, wanem i mekem olgeta?’ bambae hem i giaman se, ‘Ol mak ya, mi kasem long haos blong ol fren blong mi.’ ”","Nao sipos wan man i askem long hem se, ‘?Be ol mak blong ol so ya long jes blong yu, wanem i mekem olgeta?’ bambae hem i giaman se, ‘Ol mak ya, mi kasem long haos blong ol fren blong mi.’ ”"],[13,7,"Nao Profet Sekaraea i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Naef blong faet. Yu girap, yu kilim man blong lukaot long sipsip blong mi, we hem i stap mekem wok blong mi. Yu kilim hem, nao ol sipsip ya bambae oli go wanwan. Mi bambae mi faet agens long ol man blong mi,","Nao Profet Sekaraea i talem se, “Hae God i gat olgeta paoa, mo hem i talem se, ‘Naef blong faet. Yu girap, yu kilim man blong lukaot long sipsip blong mi, we hem i stap mekem wok blong mi. Yu kilim hem, nao ol sipsip ya bambae oli go wanwan. Mi bambae mi faet agens long ol man blong mi,"],[13,8,"nao olbaot long kantri ya, sipos i gat tri man, bambae tu i ded, wan i stap, tu i ded, wan i stap.","nao olbaot long kantri ya, sipos i gat tri man, bambae tu i ded, wan i stap, tu i ded, wan i stap."],[13,9,"Nao olgeta ya we oli stap we oli no ded, mi bambae mi mekem olgeta oli klin, olsem we man i bonem silva blong mekem i klin. Bambae mi mekem i strong long olgeta olsem we man i bonem gol blong tekemaot doti blong hem. Nao biaen, sipos olgeta oli prea long mi, bambae mi save harem olgeta. Mo mi bambae mi save singaot olgeta, se oli man blong mi, mo bambae olgeta oli talemaot se, ‘Hae God i God blong mifala.’ ”","Nao olgeta ya we oli stap we oli no ded, mi bambae mi mekem olgeta oli klin, olsem we man i bonem silva blong mekem i klin. Bambae mi mekem i strong long olgeta olsem we man i bonem gol blong tekemaot doti blong hem. Nao biaen, sipos olgeta oli prea long mi, bambae mi save harem olgeta. Mo mi bambae mi save singaot olgeta, se oli man blong mi, mo bambae olgeta oli talemaot se, ‘Hae God i God blong mifala.’ ”"],[14,1,"Nao Profet Sekaraea i talem long ol laen* blong Isrel* se, “Olgeta. Dei blong Hae God i stap kam klosap we hem bambae i jajem olgeta man. Long taem ya, hem bambae i tekem ol man blong ol narafala kantri oli kam wanples long Jerusalem,* nao i letem olgeta oli mekem faet agens long yufala. Bambae oli winim yufala, oli holem taon ya, nao oli go insaed long ol haos blong yufala, oli tekemaot olting blong yufala, mo bambae oli seraot ol samting ya stret long fes blong yufala. Mo bambae oli fosem ol woman blong yufala blong slip wetem olgeta, mo bambae oli tekemaot haf blong ol man mo woman oli go stap wok slef* long ol kantri blong olgeta, be narahaf bambae oli stap nomo long taon ya.","Nao Profet Sekaraea i talem long ol laen* blong Isrel* se, “Olgeta. Dei blong Hae God i stap kam klosap we hem bambae i jajem olgeta man. Long taem ya, hem bambae i tekem ol man blong ol narafala kantri oli kam wanples long Jerusalem,* nao i letem olgeta oli mekem faet agens long yufala. Bambae oli winim yufala, oli holem taon ya, nao oli go insaed long ol haos blong yufala, oli tekemaot olting blong yufala, mo bambae oli seraot ol samting ya stret long fes blong yufala. Mo bambae oli fosem ol woman blong yufala blong slip wetem olgeta, mo bambae oli tekemaot haf blong ol man mo woman oli go stap wok slef* long ol kantri blong olgeta, be narahaf bambae oli stap nomo long taon ya.",2],[14,3,"Nao Hae God bambae i go faet agens long ol kantri ya long fasin blong hem we i stap mekem long taem blong faet.","Nao Hae God bambae i go faet agens long ol kantri ya long fasin blong hem we i stap mekem long taem blong faet."],[14,4,"Long dei ya, bambae hem i stanap long Hil blong ol tri ya Olif afsaed long Jerusalem, long saed i go long is, nao bambae hil ya i split long medel. Haf bambae i muv i go long not, mo narahaf bambae i muv i go long saot, mo bigfala levelples bambae i stap long medel, we bambae i stat long is i go kasem long wes.","Long dei ya, bambae hem i stanap long Hil blong ol tri ya Olif afsaed long Jerusalem, long saed i go long is, nao bambae hil ya i split long medel. Haf bambae i muv i go long not, mo narahaf bambae i muv i go long saot, mo bigfala levelples bambae i stap long medel, we bambae i stat long is i go kasem long wes."],[14,5,"Nao bambae yufala i pas long levelples ya, yufala i ronwe i go kasem narasaed. Bambae yufala i ronwe olsem we ol bubu blong yufala bifo oli bin ronwe, long taem ya we graon i seksek bigwan, long taem blong King Usia, we i king blong Juda* bifo. Long taem ya nao, Hae God we i God blong yumi, hem bambae i kamtru wetem ol tabu man blong hem.”","Nao bambae yufala i pas long levelples ya, yufala i ronwe i go kasem narasaed. Bambae yufala i ronwe olsem we ol bubu blong yufala bifo oli bin ronwe, long taem ya we graon i seksek bigwan, long taem blong King Usia, we i king blong Juda* bifo. Long taem ya nao, Hae God we i God blong yumi, hem bambae i kamtru wetem ol tabu man blong hem.”"],[14,6,"Mo Profet Sekaraea i talem se, “Taem dei ya i kamtru, bambae ples i no moa kolkol, mo bambae i no moa save kolkol we i kolkol tumas.","Mo Profet Sekaraea i talem se, “Taem dei ya i kamtru, bambae ples i no moa kolkol, mo bambae i no moa save kolkol we i kolkol tumas."],[14,7,"Bambae i delaet olwe nomo, bambae i no moa save tudak. Dei blong ol samting ya, i no gat man i save, Hae God nomo i save.","Bambae i delaet olwe nomo, bambae i no moa save tudak. Dei blong ol samting ya, i no gat man i save, Hae God nomo i save."],[14,8,"“Taem dei ya i kamtru, bambae gudfala wota i aot long Jerusalem* i ron i go. Haf blong hem bambae i ron i godaon long Ded Si,* mo narahaf bambae i ron i go long Mediterenian Si. Wota ya bambae i ron olwe, neva bambae i kam drae samtaem.","“Taem dei ya i kamtru, bambae gudfala wota i aot long Jerusalem* i ron i go. Haf blong hem bambae i ron i godaon long Ded Si,* mo narahaf bambae i ron i go long Mediterenian Si. Wota ya bambae i ron olwe, neva bambae i kam drae samtaem."],[14,9,"Long taem ya nao, Hae God bambae i kam King blong olgeta man long wol ya, mo olgeta evriwan bambae oli stap mekem wosip long hem we hem nomo i God, mo olgeta man bambae oli singaot hem long wan nem nomo.","Long taem ya nao, Hae God bambae i kam King blong olgeta man long wol ya, mo olgeta evriwan bambae oli stap mekem wosip long hem we hem nomo i God, mo olgeta man bambae oli singaot hem long wan nem nomo."],[14,10,"“Nao olgeta ples, i stat long Geba long not i go kasem Rimon long saot, bambae i kam level. Mo taon ya Jerusalem bambae i stanap long hil hem wan, olsem wan wajhaos.* Taon ya bambae i bigwan, we bambae i stat long doa* blong bigfala stonwol blong taon ya we nem blong hem “Doa blong Benjamin”, i go kasem “Doa long Kona”, long ples ya we bifo i gat olfala doa long hem. Mo bambae i stat long wajhaos ya blong Hananehel, i go kasem ples blong mekem waen blong king.","“Nao olgeta ples, i stat long Geba long not i go kasem Rimon long saot, bambae i kam level. Mo taon ya Jerusalem bambae i stanap long hil hem wan, olsem wan wajhaos.* Taon ya bambae i bigwan, we bambae i stat long doa* blong bigfala stonwol blong taon ya we nem blong hem “Doa blong Benjamin”, i go kasem “Doa long Kona”, long ples ya we bifo i gat olfala doa long hem. Mo bambae i stat long wajhaos ya blong Hananehel, i go kasem ples blong mekem waen blong king."],[14,11,"Nao ol man blong ples ya bambae oli stap gud oltaem. Bambae i no moa gat wan samting blong oli fraet long hem se bambae i kam spolem olgeta.","Nao ol man blong ples ya bambae oli stap gud oltaem. Bambae i no moa gat wan samting blong oli fraet long hem se bambae i kam spolem olgeta."],[14,12,"“Olgeta man blong ol narafala kantri we oli bin mekem faet agens long Jerusalem, Hae God bambae i letem wan rabis sik i kam kasem olgeta. Taem oli stap laef yet, be ol bodi blong olgeta bambae i roten i sting. Ol ae blong olgeta mo tang blong olgeta bambae i roten tu.","“Olgeta man blong ol narafala kantri we oli bin mekem faet agens long Jerusalem, Hae God bambae i letem wan rabis sik i kam kasem olgeta. Taem oli stap laef yet, be ol bodi blong olgeta bambae i roten i sting. Ol ae blong olgeta mo tang blong olgeta bambae i roten tu."],[14,13,"“Long taem ya, Hae God bambae i mekem olgeta oli fraet, oli lusum hed. Nao sipos wan man i sidaon wetem narafala man we i fren blong hem nomo, man ya bambae i girap i holem fren ya blong hem, nao i kilim hem i ded.","“Long taem ya, Hae God bambae i mekem olgeta oli fraet, oli lusum hed. Nao sipos wan man i sidaon wetem narafala man we i fren blong hem nomo, man ya bambae i girap i holem fren ya blong hem, nao i kilim hem i ded."],[14,14,"Mo ol man Juda* bambae oli faet long ol enemi ya blong olgeta, blong blokemgud Jerusalem. Nao ol gudgudfala samting ya, ol gol mo ol silva, mo ol klos we i plante we plante, we i blong ol man ya blong ol narafala kantri we oli stap raonabaot long Jerusalem, ol man Juda bambae oli kam karemaot evriwan i blong olgeta.","Mo ol man Juda* bambae oli faet long ol enemi ya blong olgeta, blong blokemgud Jerusalem. Nao ol gudgudfala samting ya, ol gol mo ol silva, mo ol klos we i plante we plante, we i blong ol man ya blong ol narafala kantri we oli stap raonabaot long Jerusalem, ol man Juda bambae oli kam karemaot evriwan i blong olgeta."],[14,15,"“Mo semkaen sik ya, bambae i kasem ol hos wetem ol hafkas* dongki blong olgeta, mo ol kamel, mo ol dongki, mo ol narafala anamol blong olgeta, we oli stap long ol ples we ol enemi ya oli putumap ol haos tapolen blong olgeta long hem.”","“Mo semkaen sik ya, bambae i kasem ol hos wetem ol hafkas* dongki blong olgeta, mo ol kamel, mo ol dongki, mo ol narafala anamol blong olgeta, we oli stap long ol ples we ol enemi ya oli putumap ol haos tapolen blong olgeta long hem.”"],[14,16,"Nao Profet Sekaraea i talem se, “Hae God i gat olgeta paoa, mo hem i King blong olgeta man. Nao ol man blong ol narafala kantri we oli stap laef yet, long evri yia, bambae oli stap kam long Jerusalem* blong mekem wosip long hem. Mo bambae oli stap mekem Lafet* blong ol Wansaed Haos long ples ya.","Nao Profet Sekaraea i talem se, “Hae God i gat olgeta paoa, mo hem i King blong olgeta man. Nao ol man blong ol narafala kantri we oli stap laef yet, long evri yia, bambae oli stap kam long Jerusalem* blong mekem wosip long hem. Mo bambae oli stap mekem Lafet* blong ol Wansaed Haos long ples ya."],[14,17,"Sipos ol man blong wan kantri oli no wantem kam long Jerusalem blong mekem wosip long Hae God, bambae hem i no moa save sanem ren i kam long kantri blong olgeta.","Sipos ol man blong wan kantri oli no wantem kam long Jerusalem blong mekem wosip long Hae God, bambae hem i no moa save sanem ren i kam long kantri blong olgeta."],[14,18,"Mo sipos ol man Ijip oli no wantem kam blong mekem Lafet blong ol Wansaed Haos, sik ya we bambae Hae God i letem i kasem ol narafala kantri we oli no wantem kam long lafet ya, bambae i kasem olgeta tu.","Mo sipos ol man Ijip oli no wantem kam blong mekem Lafet blong ol Wansaed Haos, sik ya we bambae Hae God i letem i kasem ol narafala kantri we oli no wantem kam long lafet ya, bambae i kasem olgeta tu."],[14,19,"Panis ya nao, bambae i kasem ol man Ijip, mo ol man blong ol narafala kantri we oli no wantem kam blong mekem lafet ya.","Panis ya nao, bambae i kasem ol man Ijip, mo ol man blong ol narafala kantri we oli no wantem kam blong mekem lafet ya."],[14,20,"“Long taem ya, ol bel we oli fasem i stap hang long ol strap blong ol hos, be bambae ol man oli save raetem tok ya long olgeta, se ‘Bel ya i tabu, i blong Hae God’. Mo ol sospen we oli stap long haos* blong Hae God, be bambae oli kam tabu, stret olsem ol besin ya we oli stap klosap long olta.","“Long taem ya, ol bel we oli fasem i stap hang long ol strap blong ol hos, be bambae ol man oli save raetem tok ya long olgeta, se ‘Bel ya i tabu, i blong Hae God’. Mo ol sospen we oli stap long haos* blong Hae God, be bambae oli kam tabu, stret olsem ol besin ya we oli stap klosap long olta."],[14,21,"Mo olgeta sospen blong ol man Jerusalem mo blong ol narafala man Juda,* bambae oli tabu, oli blong Hae God. Ol man bambae oli save yusum olgeta long taem blong mekem wosip, blong kukum ol mit blong ol sakrefaes. Hae God i gat olgeta paoa, mo long taem ya, ol bisnesman bambae oli no moa save mekem bisnes bakegen long haos ya blong hem.”","Mo olgeta sospen blong ol man Jerusalem mo blong ol narafala man Juda,* bambae oli tabu, oli blong Hae God. Ol man bambae oli save yusum olgeta long taem blong mekem wosip, blong kukum ol mit blong ol sakrefaes. Hae God i gat olgeta paoa, mo long taem ya, ol bisnesman bambae oli no moa save mekem bisnes bakegen long haos ya blong hem.”"]]}};